INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (35, E'A35', E'1', E'adaptive-sub-sovereign-topology', E'SUB-SOVEREIGN:created-only-when-parent-duty-needs-separate-control; CATALOG:active sub-sovereign parent and child map per complete parent reallocation A89+C50+A96+A100; RULE:each active sub-sovereign has exactly one parent and manages modules+assigns+coordinates+collects evidence only; STARTUP:startup-sub-sovereign under runtime-sovereign; DECISION-CHILDREN:policy-architecture+health-maintenance-test+data-governance+priority-capability+change-acceptance; SYNCHRONIZATION-CHILDREN:resource-dependency-sync+dependency-sync+channel-contract-sync+release-update-sync+runtime-state-sync+repair-backup-sync+cleanup-retention-sync+learning-evidence-sync+automatic-log-sync; PERMISSION-CHILDREN:language-review+directory+identity-group structural assignments; SPECIALIZED-SOVEREIGN:may-operate-without-sub-sovereign-when-one-bounded-domain; RETIRED:legacy-undifferentiated-runtime+resource/data/integration/language-review/third-party-sub-sovereigns-after-promotion-hold-no-active-authority\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:unnecessary-sub-sovereign+duplicate-control-owner+multiple-parents+direct-execution+information-layer-bypass', E'');
