INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (148, E'B10', E'2', E'module-fine-grained-decomposition', E'EACH-MODULE:decompose-into-owned-submodules; REQUIRED-LAYERS:presentation+channel-api+application-use-case+domain-business+service+repository-data-access+integration-adapter+execution-worker; EACH-SUBMODULE:single-responsibility+single-owner+explicit-input-output+declared-dependencies; SHARING:contracts-and-neutral-infrastructure-only; BUSINESS-LOGIC:remains-with-module-owner\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:monolithic-module+duplicate-responsibility+multiple-owners+implicit-dependency+cross-module-private-import+shared-layer-business-logic+presentation-direct-data-or-execution-access', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (149, E'B11', E'2', E'execution-layer-internal-tiering', E'EXECUTION-LAYER-TIERS:dispatch-intake>authorization-and-governance-gate>task-planning>specialized-executor>result-verification>state-event-audit-publication; CONTROL:sub-sovereign; WORK:specialized-module-executor; VERIFY:independent-from-work-step; RESULT:returned-through-information-layer; FAILURE:maintenance-path-only', E'FORBID:tier-skip+executor-self-authorize+executor-self-dispatch+work-step-self-verify+direct-ui-to-executor+cross-module-executor-substitution+unrecorded-result', E'');
