INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (153, E'B15', E'2', E'cryptography-and-key-lifecycle', E'DATA-AT-REST:AES-256-GCM-or-ChaCha20-Poly1305; SIGNATURE:Ed25519; HASH:SHA-256-minimum; KEY-GENERATION:CSPRNG; ROTATION:encryption<=90-days+signing<=365-days; REVOCATION:immediate-on-compromise; DESTRUCTION:verified; PRIVATE-KEY:never-in-codex', E'FORBID:deprecated-algorithm+hardcoded-secret+plaintext-private-key+reuse-after-revocation', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (154, E'B16', E'2', E'resource-quota', E'QUOTA-ENVELOPE:every module/component declares minimum+default+maximum memory+disk+CPU+GPU/VRAM+threads+processes+connections+queue+model-residency+latency budget; C++23 resource-governor is sole system-administrator regulator and adjusts admission+priority+affinity+working-set inside envelopes; capability owners adjust internal batch/pool/cache/concurrency only inside delegated bounds; PRIORITY:governance-basis>core-runtime>active-user-work>background-maintenance; EXHAUSTION:shed/defer/deny new low-priority work+preserve in-flight and completed state+release idle+audit; RECOVERY:hysteresis+stability window+automatic restoration; ADAPTIVE-OBJECTIVE:high-performance+high-execution-speed+low-resource-consumption jointly optimized; METRICS:throughput+latency-p50/p95/p99+CPU+RAM+GPU/VRAM+disk/IO+process/thread-count+startup/shutdown; ACCEPTANCE:no single-metric gain may regress another required metric,correctness,quality,security,stability,authority or hard deadline beyond its registered budget; DECISION:only Pareto-nondominated or policy-weighted improvement with complete before/after evidence may activate; otherwise rollback or fail-closed', E'FORBID:unbounded-allocation+ceiling-raise-by-adaptation+second-governor+Python-resource-loop+silent-truncation+background-starvation+throttle-protected-governance/inflight-work+FORBID:single-metric-optimization+performance-by-resource-overuse+resource-saving-by-latency/throughput-regression+speed-by-skipping-correctness/security/governance+claim-without-before/after-evidence', E'');
