INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (156, E'B18', E'2', E'adaptive-sovereign-responsibility-map', E'STARTUP:[startup-gates,dependency-start,readiness-handoff]; DECISION:[system-policy,priority-delegation,change-acceptance]; SYSTEM-RUNTIME:[runtime-lifecycle,continuity,state-sync]; MAINTENANCE:[health-monitor,health-preservation,system-maintenance]; PERMISSION:unchanged; LEARNING:[error-classification,outcome-learning,automation-candidates]; PROGRAMMING:[code-analysis,versioned-planning,tool-dispatch-and-verification]; RESOURCE:[state,allocation,release]; DATA:[integrity,lifecycle,reconciliation]; INTEGRATION:[channel-topology,message-routing,cross-module-contract]; THIRD-PARTY:[inventory-version,license-security,update-decision]; LANGUAGE-REVIEW:[conformance,migration,generated-code-review]\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:duty-overbreadth+duty-overlap+self-authorization+direct-ungoverned-execution+cross-sovereign-takeover', E'');
