INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (315, E'C2', E'3', E'system-responsibility', E'GIT:version+history; POSTGRESQL:central-structured-official-data+shared-transport+audit; POSTGRESQL-PGVECTOR:canonical-semantic-vector-authority; RUST-VECTOR-ENGINE:rebuildable-derived-semantic-index; RAG:hybrid+code+agentic+memory; LLM:understand-reason-operate; OWNERSHIP:local-governed', E'FORBID:role-substitution/alternate embedded database-as-central-official-or-shared-audit/local-vector-as-canonical-semantic-index/unreconciled-fallback+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'');
