INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (321, E'C8', E'3', E'directory-write', E'DIRECTORY-WRITE:permission-sovereign-decision; EXEC:governed-executor; STORE:data-governance-sub-sovereign-declared; BASIS:codex+explicit-authorization DIRECTORY-STORAGE:every directory managed by permission-core is persisted in the registered local PostgreSQL authority only; PostgreSQL is the sole current structured storage and transaction boundary for directory entries,relationships,lifecycle and write receipts; alternate embedded database,file,cache,mirror or module-private state cannot be directory authority or write fallback.', E'FORBID:direct-mutation-by-permission-sovereign/unauthorized-directory-write+permission-core-directory-outside-PostgreSQL+alternate embedded database-or-file-as-directory-authority+directory-write-fallback-outside-PostgreSQL+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'');
