INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (323, E'C10', E'3', E'rag-architecture', E'RAG-ARCH:hybrid-rag+code-rag+agentic-rag+memory-rag; HYBRID-RAG:dense+sparse+semantic-fusion; CODE-RAG:code-snippet+ast+dependency-graph-retrieval; AGENTIC-RAG:multi-step-retrieve+reason+adapt; MEMORY-RAG:session+long-term+episodic-memory; SHARED-INDEX:rust-vector-engine(local-owned); OWNERSHIP:local-owned; HOSTING:local-only; BASIS:codex\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:non-formal-rag-substitution; FORBID:external-or-cloud-hosting-of-rag; FORBID:replace-hybrid-architecture; FORBID:omit-any-of-four-sub-architectures', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (324, E'C11', E'3', E'git-operation-tiers', E'GIT-OPS:READ=status/log/diff/show/blame/ls-files/cat-file/rev-parse/for-each-ref/config-get direct read-only; AUTOMATED-WRITE:add-path-scoped+commit+fetch+branch-create+switch+merge+rebase-local+cherry-pick+revert+worktree-lifecycle+fast-forward-push only through GitRepository.run and sole coordinator; HIGH-RISK:force-push+ref-delete+history-rewrite+destructive-reset+prune+clean remain denied unless an explicit Codex provision authorizes the exact operation; CONFIRMATION:normal governed automation requires no interactive confirmation; ENFORCEMENT:single-entry+hook+policy+audit\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:raw-Git-write+second-Git-entry+interactive-confirmation-dependency-for-normal-automation+force-push+ref-delete+history-rewrite+destructive-reset+whole-index-foreign-stage+enforcement-bypass', E'');
