INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (335, E'C22', E'3', E'multi-worker-automatic-git-delivery', E'FULL-AUTOMATION:each worker uses own worktree+branch+index; GitAutomationService detects stable path-scoped changes,stages only tracked allowlist paths,commits locally and enqueues immutable commit; SOLE-COORDINATOR:workspace_sync integrates queued commits into main,runs governance audit,fast-forwards clean worktrees,verifies central/main equality and pushes origin/main; CONFLICT:generated registered artifacts regenerate automatically;single-owner content resolves from current canonical owner when policy+base+target prove one result;ambiguous,multi-owner or unverifiable conflict is quarantined without data loss and retried only after authoritative state changes; FAILURE:retain commits+typed report+bounded retry; REMOTE:main-only', E'FORBID:worker-push+second-coordinator+manual-confirmation-on-normal-path+force-push+ref-delete+history-rewrite+dirty-sync+audit-bypass+moving-branch-merge+unverifiable-conflict-choice+untracked-artifact-auto-add', E'');
