INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (337, E'C24', E'3', E'automatic-system-health-preservation', E'HEALTH-STATES:healthy|degraded|recovering|critical|unknown; DIMENSIONS:governance-integrity+process-survival+runtime-readiness+dependency-readiness+information-channel-continuity+data-integrity+resource-headroom+security-signals+clock-validity+backup-recoverability; EACH-COMPONENT-HEALTH-CONTRACT:owner+typed-signals+sampling-or-event-source+thresholds+staleness-limit+dependency-map+severity+recovery-objective; MONITOR:continuous-events+bounded-active-probes+debounce+hysteresis+trend-detection; HEALTH-OWNER:decision-sovereign classifies health+health-maintenance-test-sub-sovereign preserves+coordinates-maintenance; PREVENTION:capacity-headroom+dependency-renewal+stale-state-reconciliation+bounded-housekeeping+verified-update-readiness; AUTOMATIC-PRESERVATION:signal>information-layer>maintenance-classification>decision>permission-validation>runtime-dispatch-or-release-update-sync-sub-sovereign-dispatch>governed-executor>independent-verification>stability-window>information-layer-status+audit>星澄-card-and-active-ui; RECOVERY-POLICY:idempotent+bounded-attempts+backoff+circuit-breaker+rollback-or-quarantine+preserve-user-work; SUCCESS:all-required-signals-current+thresholds-satisfied+independent-verification+declared-stability-window; FAILURE:critical-or-unknown+fail-closed-for-affected-capability+retain-evidence+user-notification+learning-outcome\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:component-self-authorized-repair+maintenance-owning-non-health-decision+direct-mutation+information-layer-bypass+single-signal-healthy-claim+stale-signal-as-current+infinite-retry+retry-storm+repair-without-decision-proof+success-before-verification+hidden-degradation+health-score-without-dimension-evidence+automatic-codex-or-permission-change', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (338, E'C25', E'3', E'single-codex-with-星澄-only-Chinese-exception', E'SOLE-AUTHORITY:the current local PostgreSQL gptbridge_codex at governance-codex://official is the one and only Governance Codex authority;NO-FILE-AUTHORITY:no SQL dump,database file,JSON,cache,export,backup,search projection,architecture document or generated artifact is a Codex authority or parallel Codex;ONLY-MIRROR-EXCEPTION:exactly five synchronized read-only governance_codex.zh-TW.part files may exist as one non-authoritative Chinese language mirror;MIRROR-RIGHTS:adjudication-none+execution-none+import-none+write-none+authority-none;CONFLICT:PostgreSQL current effective law always prevails;FAILURE:missing,stale,mixed-version or damaged Chinese parts become unavailable and never create a fallback authority;PROHIBITION:no other Codex mirror or machine Codex copy may be retained', E'FORBID:parallel-codex-authority+file-codex-authority+SQL-dump-mirror+database-file-mirror+JSON-mirror+backup-as-authority+mirror-fallback+non-Chinese-codex-mirror', E'星澄-only Chinese read exception; no authority or permission-review requirement; official-entry identity scope session and audit remain mandatory');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (339, E'C26', E'3', E'frontend-backend-connection-fault-tolerance', E'SCOPE:main-system+every-independent-tool frontend/backend; OWNER:information-layer-connection-controller-only; STATE-MACHINE:idle>connecting>authenticating>synchronizing>connected>degraded>reconnecting>repairing>failed; TRANSITION:typed+monotonic+generation-id+reason+timestamp+attempt-count; SESSION:authenticated+authorized+contract-versioned+generation-fenced+single-active-per-client-route; LIVENESS:bidirectional-heartbeat+deadline+miss-threshold+transport-close+protocol-error+backend-generation-change; DETECTION:any-liveness-failure-immediately-invalidates-ready-and-blocks-state-changing-commands; RECONNECT:automatic-single-flight+cancel-prior-attempt+bounded-exponential-backoff+jitter+rate-limit+maximum-attempt-window+fresh-session-token+fresh-generation; RESYNC:resubscribe+send-last-acknowledged-event-cursor+backend-gap-check+authoritative-full-snapshot-on-gap-or-generation-change+monotonic-event-replay-with-idempotency-key+client-ack; READY-GATE:transport+authentication+authorization+contract-compatible+subscription+snapshot-current+cursor-contiguous+required-runtime-health; COMMANDS:connected-ready-generation-only+request-id+idempotency-key+acknowledged-result; OFFLINE/DEGRADED/REPAIRING:fail-closed+no-implicit-queue+no-stale-replay; REPAIR-ESCALATION:reconnect-budget-exhausted>information-layer-signal>maintenance-health-classification>decision>permission>system-runtime-or-programming>governed-executor>independent-verification>fresh-reconnect; UI:all-connection-state+reason+attempt+last-success+repair-state published-in-real-time-through-information-layer; RECOVERY-SUCCESS:new-generation-ready+stable-heartbeat-window+snapshot-and-cursor-verified; COVERAGE:same-contract-for-development+production+hot-reload+post-repair\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:frontend-owned-WebSocket+direct-backend-connection+multiple-reconnect-loops+concurrent-session-generations+socket-open-as-ready+fixed-delay-retry+unbounded-retry+retry-storm+reuse-expired-session+command-while-not-ready+silent-command-buffer+out-of-order-event-apply+cursor-gap-ignore+stale-snapshot-as-current+UI-manual-refresh-dependency+repair-success-before-stability-window+hidden-failed-state+information-layer-bypass', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (340, E'C27', E'3', E'universal-information-layer-connection-exclusivity', E'CONNECTION-DEFINITION:any-cross-process+cross-thread-message-channel+cross-layer+cross-module+cross-owner+frontend-backend+sovereign-sub-sovereign+module-executor+network+loopback+LAN+internet+WebSocket+HTTP/HTTPS+TCP/UDP+IPC+pipe+queue+event-bus+callback-bus+database+PostgreSQL+SQLite-cross-owner+Rust-Vector-Engine+RAG+Ollama+model-runtime+filesystem-cross-owner+repository+broker+tool+service+child-process-control+health-probe+administration+provisioning+startup+repair+test-or-script communication/session/request/read/write/control/status/event/data-transfer; SOLE-OWNER:information-layer; REQUIRED-ROUTE:authenticated-requester>registered-information-layer-entry>authorization+type+contract+scope+rate+observability+audit-gates>information-layer-owned-transport-adapter>authorized-destination>typed-result-via-information-layer; PHYSICAL-CONNECTION:may-be-opened-only-by-information-layer-owned-adapter-on-behalf-of-approved-request+adapter-has-no-domain-decision; CREDENTIALS+TOKENS+PORTS+CONNECTION-POOLS+SESSIONS+RETRY+TIMEOUT+HEARTBEAT+BACKPRESSURE+RECONNECT:information-layer-custody; CALLER:request-only+no-transport-handle; DESTINATION:reply-only-through-originating-information-route; FAILURE:fail-closed+typed-error+audit+health-signal; COVERAGE:runtime+development+maintenance+migration+packaging+diagnostics+tests+one-off-scripts; INTERNAL-NON-CONNECTION:pure-in-process-function-call-inside-one-owner-and-one-layer-without-I/O/message/session/transport-handle remains-owner-internal; CURRENT-NORMALIZATION:C116 controls;SQLite is retired with zero active consumers;every affirmative SQLite use,fallback,reconciliation,authority or runtime clause in this provision is void and historical-only', E'FORBID:direct-socket+direct-HTTP+direct-WebSocket+direct-database-driver+direct-model-endpoint+direct-cross-owner-file-read/write+direct-subprocess-control-channel+private-IPC+private-event-bus+implicit-callback-channel+unregistered-queue+transport-library-in-domain-or-presentation-code+caller-owned-connection-pool+credential-forwarding+destination-direct-reply+startup/provisioning/admin/health/test/script-bypass+temporary-debug-connection+fallback-direct-link+information-layer-domain-business-logic+information-layer-authorization-self-grant+FORBID:SQLite-active-consumer+SQLite-runtime-write+SQLite-fallback+SQLite-reconciliation', E'No cross-boundary connection exception; only owner-internal pure calls that create no I/O message session or transport handle are outside the connection definition');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (341, E'C28', E'3', E'third-party-sovereign-optimized-responsibility', E'DEPENDENCY-AUTHORITY:automation-core automatically updates registered dependency versions but cannot admit a new dependency identity/source/runtime without current explicit permission artifact. ADMISSION:request declares purpose+owner+consumers+alternatives+direct/transitive graph+source+exact candidate+license+security+privilege/network/data/resource footprint; permission-core allow/deny precedes any fetch/install/lock/execute. UPDATE:registered identity follows 14-day normal rule or verified emergency exception and all gates;every package download uses exactly Visual Studio Installer or Winget;language package managers (including Bun) never perform a network download and use only vendored or already-registered artifacts;a package neither channel can provide requires an explicit permission artifact;Python and Node.js are forbidden:no download,install,execution,residency or final effective state. RETIREMENT:consumer cutover+stability+zero active consumer+zero lock/manifest/runtime reference+data/config migration+bounded rollback retention+purge receipt; terminal PURGED means no binary,package,cache,environment,model artifact or executable reference remains. INVENTORY:current+rollback-only+retirement state machine machine-readable.; UPDATE-DETECTION:every-24-hours+immediate-governed-security-advisory-event; RETIREMENT-TAG:mandatory from SUPERSEDED through PURGE_READY and binds dependency-id+old-version+successor-version+state+reason+zero-consumer-progress+rollback-deadline+scheduled-purge-at\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:unapproved-new-package+implicit-transitive-admission+package-manager-auto-add+language-manager-network-download+package-list-addition-without-explicit-permission+unapproved-source/repository+download-before-admission+retired-version-active-consumer+indefinite-old-version-retention+purged-artifact-reference+deletion-before-proven-cutover+missing-or-stale-retirement-tag+update-detection-interval-not-24-hours', E'A dependency without an upstream signature may be considered only when its exact bytes are content-addressed, independently provenance-verified, reproducibly acquired from an approved source, sandbox-tested, explicitly risk-accepted, and bounded to a noncritical scope');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (342, E'C29', E'3', E'local-code-and-third-party-dependency-boundary', E'BOUNDARY:local authored code remains authority;third-party dependencies are exact pinned immutable artifacts. NEW-ADMISSION:explicit permission required for every new identity,source,introduced transitive dependency and package-list addition; no permission means no network fetch,installation,manifest/lock change or execution;package download channels are exactly Visual Studio Installer and Winget;language package managers (including Bun) never perform a network download and use only vendored or already-registered artifacts except under an explicitly permitted exception;Python and Node.js are forbidden without exception. EXISTING-UPDATE:D28/C28 automated timing and gates. RETIREMENT:replace consumers+remove lock/manifest reference+verify zero runtime load+retain at most one prior version during bounded rollback window+automatic purge after expiry; purge removes installed files,caches,staging remnants and rebuildable artifacts while retaining only audit/receipt metadata.; UPDATE-DETECTION:every-24-hours+immediate-governed-security-advisory-event; RETIREMENT-TAG:mandatory from SUPERSEDED through PURGE_READY and binds dependency-id+old-version+successor-version+state+reason+zero-consumer-progress+rollback-deadline+scheduled-purge-at\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:unmanaged/unapproved-dependency+implicit-download+dependency-confusion+floating-version+runtime-self-install+package-postinstall-unreviewed-execution+old-binary/cache-after-purge+multiple-rollback-generations+third-party-as-authority+missing-or-stale-retirement-tag+update-detection-interval-not-24-hours', E'Operating-system components may use OS-attested identity and servicing provenance when byte-level pinning is unavailable; exact platform version and capability scope remain required');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (343, E'C30', E'3', E'global-timestamp-propagation', E'SCOPE:all-main-system+independent-tools+sovereigns+sub-sovereigns+information-layer+executors+frontend/backend+PostgreSQL+PostgreSQL-pgvector+Rust-derived-index-metadata+RAG+model-operations+files-cross-owner+Git-operations+commands+requests+responses+events+state+data-mutations+decisions+permission-proofs+execution-proofs+health+repair+learning+audit+errors+retries+checkpoints+backups+releases+versions+UI-projections; REQUIRED-FIELDS:event-or-record-id+occurred-at-utc-RFC3339+recorded-at-utc-RFC3339+timezone-IANA+local-display-time-RFC3339-with-offset+monotonic-sequence+clock-source+clock-status+origin-generation+correlation-id; AUTHORITY:occurred-at assigned-once-by-origin-owner+recorded-at assigned-once-by-authoritative-store/ledger; PROPAGATION:information-layer validates-format/drift/generation+preserves-original-times+adds-hop-received/sent timestamps without-overwrite; STORAGE:PostgreSQL=timestamptz-UTC+sequence+canonical-vector-metadata,Rust-derived-index=UTC-string+source-record-id/revision,JSON/API=RFC3339-UTC+explicit-timezone,UI=localized-display-derived-from-UTC+shows-staleness; PRECISION:minimum-millisecond+preserve-higher-source-precision; ORDER:origin-monotonic-sequence+causal-parent+authoritative-revision determine-order+wall-clock-never-sole-order; CLOCK:D20 authenticated-source+max-drift-5-seconds; DRIFT/UNKNOWN-CLOCK:mark-untrusted+block-expiry/security/release/order-sensitive mutation+permit-redacted-diagnostic-only; REPLAY:retain-original-occurred-at/sequence+new-delivery-time-separated; MIGRATION:legacy-record-without-time remains-legacy-unknown+must-not-fabricate; RETENTION/TZ-CHANGE/DST:never-change-stored-UTC+render-current-or-recorded-zone-explicitly; UI-SYNC:D31 includes-commit-time/event-time/render-time/ack-time and calculates-lag; AUDIT:append-only timestamp evidence+clock corrections as-new-events', E'FORBID:missing-timestamp-on-new-record+naive-local-time+timezone-abbreviation-only+server-receipt-time-replacing-origin-time+timestamp-overwrite/backdate/future-date beyond-tolerance+fabricated-legacy-time+wall-clock-only-order+cross-generation-sequence reuse+UI-generated-authoritative-time+database-default-time-as-origin-when-origin-known+silent-clock-drift+timestamp-stripping at-channel/serialization/indexing/export+different-module-private-time-format+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'Pure ephemeral arithmetic within one synchronous function requires no timestamp until it becomes state, output, event, decision, evidence, log, metric, cache entry, or cross-boundary value');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (344, E'C31', E'3', E'absolute-gptbridge-code-root-containment', E'CANONICAL-CODE-ROOT:DIR[DIR_PROJECT_ROOT]; SCOPE:all-GPTBridge-owned/authored/copied/generated/transformed/downloaded/vendored/patched/extracted/staged/executable project source+scripts+modules+packages+plugins+extensions+hooks+launchers+workers+migrations+code-templates+embedded-code+build-inputs+runtime-loaded-code+hot-update/hot-reload artifacts+test-code+repair-code+AI/programming-tool output+Git-worktrees/object-database/index/hooks; LOCATION-RULE:every-in-scope path after absolute-normalization+case-folding+drive-resolution+environment-expansion+short-name-resolution+symlink/junction/mount/reparse-target-resolution must-equal-root or be-strict-descendant-of-root; ROOT-BOUNDARY:path-component boundary not-string-prefix; DIRECTORY-AUTHORITY:permission-sovereign registers-all-approved-code-directories under-root only; PROGRAMMING:release-update-sync-sub-sovereign may-plan/dispatch changes only-to-registered-descendants; EXECUTION:runtime-sovereign validates executable/module/script/working-directory/import/search/plugin/temp-generated-code paths before-dispatch; INFORMATION-LAYER:rejects cross-root code transfer/write/extract/load/execute requests+publishes typed-denial; GIT:main-repository+.git+all-worktrees+shared-object-database+hooks must-reside-within-root+external-worktree-path forbidden; GENERATION:temporary/generated/build/package/cache/coverage/test/recovery/repair code stored only-in-approved-root descendants+atomic-promote-within-same-boundary; IMPORT/PATH:PYTHONPATH/NODE_PATH/PATH/plugin/module-resolution cannot introduce GPTBridge project code from outside-root; ARCHIVE:pre-scan+canonicalize-each-entry+reject-absolute/parent-traversal/reparse/hardlink escape before-extract; HOT-UPDATE/REPAIR:source+staging+rollback+active-release all-inside-root and D28/D29 identity rules still-apply; AUDIT:operation+actor+requested-path+resolved-path+root+decision+content-hash+timestamp+correlation-id without-secret; CHECKPOINTS:startup+code-change+tool-call+Git-operation+dependency-install+generation+build+test+package+hot-update+repair+runtime-load; FAILURE:any-unresolved/ambiguous/nonexistent-parent/reparse-loop/case-alias/device-path/network-path/outside-root=>fail-closed+no-create/write/copy/move/load/import/execute+report-to-user; EXISTING-OUTSIDE-CODE:quarantine-reference+do-not-load+move requires-explicit-governed migration that first validates-destination-inside-root and never-deletes-source-until-hash-verified; THIRD-PARTY-BOUNDARY:operating-system executables and externally-installed immutable third-party runtimes are-not-GPTBridge-project-code and may-be-invoked only-by-exact-approved-identity through-C28 governed-executor+cannot receive/store/generate/modify GPTBridge code outside-root; DATA:non-code user data governed-separately+must-never-contain executable-project-code to-evade-boundary\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:any-project-code-outside-DIR[DIR_PROJECT_ROOT]+DIR[DIR_GIT_WORKTREES] or-other-sibling-worktree+user-profile/Desktop/Documents/Downloads/AppData+ProgramData+Windows/System/other-drive/UNC/network/share/cloud-sync/temp as-project-code-root+symlink/junction/reparse/mount/hardlink escape+path-prefix-confusion+relative-traversal+8.3-alias/device-path escape+environment-variable redirection+external-Git-worktree/object-store/hook+outside-root-clone/stage/build/test/package/cache/generated-code+load/import/execute-from-memory-backed-or-unregistered-extracted-code+tool/AI writing-code-outside-root+copy-then-execute bypass+data-file-containing-hidden-executable-code+fallback-to-external-source+automatic-root-expansion+exception-by-module/administrator/debug/recovery', E'Read-only invocation of an OS component or specifically approved immutable third-party runtime outside the root does not authorize GPTBridge code to be stored, generated, modified, imported, staged, or executed there; all GPTBridge inputs, wrappers, configuration with executable behavior, outputs containing code, and working state remain inside DIR[DIR_PROJECT_ROOT]');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (345, E'C32', E'3', E'absolute-environment-dependency-root', E'DEPENDENCY-ROOT:DIR[DIR_MANAGED_DEPENDENCY_ROOT] is sole managed dependency root; Windows-native registered tools and Ollama registered store are exceptions. ADMISSION:staging directory may be created only after new-dependency permission or for an already registered update candidate. ACTIVE-LAYOUT:environments|runtimes|sdks|toolchains|packages|caches|models|staging; each identity has exactly one ACTIVE and at most one ROLLBACK_ONLY generation. PURGE:after retention expiry and zero references,automatic deletion removes old version directories,package/cache objects,old environments and staging remnants; audit receipts remain in PostgreSQL,not as executable artifacts.; UPDATE-DETECTION:every-24-hours+immediate-governed-security-advisory-event; RETIREMENT-TAG:mandatory from SUPERSEDED through PURGE_READY and binds dependency-id+old-version+successor-version+state+reason+zero-consumer-progress+rollback-deadline+scheduled-purge-at\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:unapproved-staging/download/install+dependency-outside-root+global/user-profile/temp fallback+multiple-active+more-than-one-rollback+old-version-after-PURGED+cache-preserving-purged-code+symlink/reparse-escape+missing-or-stale-retirement-tag+update-detection-interval-not-24-hours', E'Only Windows 11 native tools serviced by Windows and registered Ollama execution/download/model-storage paths on C drive are exempt; neither exception permits GPTBridge project code or unrelated dependencies outside their canonical roots');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (346, E'C33', E'3', E'sql-query-pushdown', E'RULE:set-based-data-work executes-at-owning-SQL-engine; PUSH-DOWN:filter+projection+join+aggregation+grouping+window+sorting+distinct+pagination+existence+constraint+upsert+transactional-condition+authorized-row/column restriction; APPLICATION:submits-bounded-parameterized-query-contract+receives-only-required-columns/rows/aggregates; POSTGRESQL:central-structured-authoritative queries; retired embedded SQL storage has zero active query consumers; QUERY-PLAN:EXPLAIN-based evidence for-new/changed/hot paths+index/selectivity/row-estimate/temp-sort/full-scan thresholds; PAGINATION:keyset-preferred+stable-order+bounded-limit; BULK:batch/set operation+no-N+1; SECURITY:parameter binding+server-side scope predicates+transaction/isolation/deadline/cancellation; OBSERVE:query-id+contract-version+duration+rows-scanned/returned+plan-hash+timeout without-sensitive-literals; FALLBACK:application-side operation only-for-non-SQL semantics after-bounded-pushdown and documented evidence; FSHARP:after bounded SQL reduction, owns typed data analysis, machine-learning pipelines and high-correctness complex calculation where typed immutable functional modeling materially improves correctness; FSHARP-NO:database-authority+unbounded-fetch+duplicate-algorithm-authority', E'FORBID:fetch-all-then-filter/sort/group/join/page+SELECT-star production-contract+string-concatenated-SQL+N+1+unbounded-result+offset-only-large-pagination+application-enforced-row-security+SQL-business-policy/sovereign-decision+cross-owner-direct-database+query-without-timeout+silent-client-side-fallback+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'Small already-bounded result sets may receive final presentation-only formatting outside SQL');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (347, E'C34', E'3', E'sql-first-data-reduction-semantic-business-boundary', E'PIPELINE:request>CSharp-application>parameterized-bounded-PostgreSQL set operation>bounded-result>FSharp-domain-validation/business-semantics>typed-result; SQL-OWNER:data-selection+relational-integrity+set-computation; CSHARP-OWNER:application+workflow+SQL-orchestration; FSHARP-OWNER:business-meaning+validation+state-transition; RUST:approved SQL adapter/runtime path permitted by versioned contract; PYTHON:retired;no governance-thin adapter and no business or SQL orchestration role', E'FORBID:fetch-all-before-relational-reduction+SQL-business-authority+Python-domain-model-as-production-owner+Python-business-policy/workflow+Python-SQL-orchestration+unbounded-transfer', E'non-relational-semantic-post-processing-after-maximum-safe-SQL-reduction');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (348, E'C35', E'3', E'complete-governed-directory-domain-set', E'MASTER-DIRECTORY:directory-master-catalog is the exhaustive registry of every governed directory class; REQUIRED-DOMAINS:law-structure+special-law+provision-classification+project-architecture+identity-module+permission-capability+tool-route+data-schema-authority+API-event-contract+service-process-port-environment+model-resource-dependency+configuration-credential-secret+version-release-artifact+audit-evidence-retention+backup-recovery-migration+UI-window-feature-entry+command-code+fault-code+maintenance-manual+test-flow; OWNER:permission-sovereign for directory definition+identity+registration+relationship+version+activation+retirement+access and write decisions; DOMAIN-AUTHORITY:referenced bodies remain with their codex-declared domain owners and directory ownership grants no body authority; MASTER-ENTRY:directory-code+canonical-name+scope+authority-kind+required-fields+relationships+coverage-rule+implementation-state+introduced-version+retired-version; COMPLETENESS:no governed identity may exist outside exactly-one applicable registered directory and every directory appears in master catalog; IMPLEMENTATION-STATE:mandated-pending-implementation cannot be represented as active and blocks dependent verified release; CONVERGENCE:legacy permission registries become projections or implementations of the matching master entry and cannot remain parallel authority; VALIDATION:permission-sovereign verifies master coverage+schema+ownership+links before activation DIRECTORY-STORAGE:every directory managed by permission-core is persisted in the registered local PostgreSQL authority only; PostgreSQL is the sole current structured storage and transaction boundary for directory entries,relationships,lifecycle and write receipts; alternate embedded database,file,cache,mirror or module-private state cannot be directory authority or write fallback.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:unregistered-directory-class+parallel-master-catalog+directory-owned-by-other-sovereign+missing-required-domain+active-status-before-implementation-proof+legacy-registry-as-separate-authority+directory-ownership-changing-domain-body-authority+catch-all-entry-hiding-unclassified-identity+permission-core-directory-outside-PostgreSQL+alternate embedded database-or-file-as-directory-authority+directory-write-fallback-outside-PostgreSQL+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'Third-party opaque internals require no internal directory entries, but their artifact adapter interface permission data and failure exposure require registered entries');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (349, E'C36', E'3', E'data-authority-storage-rag-special-law', E'SCOPE:Git history+SQL official mutable data+Rust-Vector-Engine/RAG semantic candidates+LLM inference boundary+schemas+transactions+retention+reconciliation; OWNER:decision-sovereign owns-domain decisions with data-governance-sub-sovereign managing data modules while permission-sovereign owns directory registration; IDENTITY:CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW+section-14+immutable provision identities; AUTHORITY:codex+A60+D40 with special-over-general precedence only-inside-declared-scope; INPUT:registered directory identities+current version+permission proof+owner evidence; RULE:one accountable owner+typed decisions+governed executor only+no cross-domain authority; RELATIONSHIPS:permission-special-law+data-schema-authority-directory+backup-recovery-migration-directory; LIFECYCLE:register>validate>activate>operate>observe>repair-or-rollback>retire with versioned lineage; VALIDATION:identity+owner+scope+schema+relationships+permission+runtime generation+evidence all current; FAILURE:deny ambiguous or cross-owner mutation and preserve authoritative data; EVIDENCE:authority map+schema version+transaction proof+lineage+integrity hash+backup and restore verification', E'INHERITS:A135#SPECIAL_LAW_BOUNDARY', E'No emergency development debug administrator or performance condition may bypass authority permission isolation evidence or rollback boundaries');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (350, E'C37', E'3', E'git-worktree-special-law', E'SCOPE:Git source/history/index/worktrees/commits/merges/hooks/audit/rollback; OWNER:automation-core owns Git automation while permission-core owns registered path scope; ENTRY:GitRepository.run only; TRACKED-ALLOWLIST:authored source+Codex/contracts+SQL migrations+required configuration+non-rebuildable tests/audit evidence+human-authored documentation; EXCLUDED:runtime-state+logs+cache+temp+build/dist+packages+virtual-environments+models+database-instances+coverage+generated-indexes+rebuildable artifacts+secrets; VALIDATION:path ownership+ignore policy+staging scope+immutable commit+audit+fast-forward; FAILURE:stop only affected item,retain work and continue independent queue entries\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:track-excluded-class+secret-commit+generated-churn-without-explicit-non-rebuildable-registration+whole-index-commit+raw-Git-write+second-coordinator+force-operation', E'No emergency development debug administrator or performance condition may bypass authority permission isolation evidence or rollback boundaries');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (351, E'C38', E'3', E'privacy-personal-data-special-law', E'SCOPE:personal+sensitive+private+biometric+financial+behavioral data across collection+use+storage+indexing+inference+export+deletion; OWNER:decision-sovereign owns domain decisions and data-governance-sub-sovereign manages data modules and permission-sovereign owns directory registration; IDENTITY:CODEX_PRIVACY_PERSONAL_DATA_SPECIAL_LAW+section-24; AUTHORITY:codex+A60+D40; INPUT:registered identities+permission proof+current version+owner evidence; RULE:purpose limitation+data minimization+classification+consent or codex basis+field-level access+retention+erasure+non-inference; RELATIONSHIPS:permission-special-law+directory-special-law+audit-special-law; LIFECYCLE:classify>authorize>operate>observe>verify>retain-or-erase>retire; VALIDATION:schema+owner+scope+permission+relationships+evidence; FAILURE:deny access and contain affected data scope; EVIDENCE:append-only redacted proof+timestamp+correlation+verifier', E'FORBID:unregistered-scope+cross-owner-authority+permission-bypass+secret-or-personal-data leakage+unbounded-operation+silent-failure+success-without-evidence+scope-overreach', E'No emergency administrator debug development performance or convenience exception bypasses confidentiality integrity permission evidence or isolation');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (352, E'C39', E'3', E'reconnect-with-zero-automatic-code-overwrite-special-law', E'SCOPE:all channel disconnect/reconnect and every automatic health preservation repair recovery watchdog startup or maintenance action; OWNER:information-layer owns reconnect state and delivery+decision-sovereign classifies failure+decision-sovereign approves repair objective+permission-sovereign validates mutation scope+release-update-sync-sub-sovereign alone reviews code change; DISCONNECT:immediately invalidate ready+fence prior session/generation+preserve last acknowledged cursor/outbox/checkpoint+keep unrelated routes and independent tools running; RECONNECT:automatic single-flight+fresh authentication/session/generation+bounded exponential backoff+jitter+circuit breaker+subscription renewal+authoritative snapshot+gap detection+ordered idempotent replay+revision/hash convergence before ready; RECONNECT-IS-NOT-REPAIR:transport/session restoration may not write restore replace regenerate format revert reset checkout merge patch or otherwise mutate source code scripts manifests contracts schemas lockfiles or certified artifacts; AUTOMATIC-REPAIR-CODE-PROHIBITION:no automatic process sovereign agent watchdog maintenance task recovery tool startup routine or learned recipe may overwrite source code or select a code version; CODE-FAULT:quarantine evidence+keep last active certified release+fail closed only affected capability+submit typed change request; any source mutation requires explicit decision assignment+permission proof+system-programming review+versioned candidate+tests+human-authorized certified activation; BASELINE:repair may restore runtime state only from the exact active certified immutable artifact and only when byte-identical digest proves no source change; mismatch means stop and request human decision; PROTECTION:before any permitted repair record path identity+content hash+Git state+active release+rollback proof and after operation prove unchanged source hashes; RECOVERY-SUCCESS:channel current+cursor contiguous+snapshot/revision/hash converged+source tree and active release hashes unchanged+stability window passed\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:auto-repair-overwrite-code+automatic-source-restore+automatic-code-generation+automatic-checkout/reset/revert/merge/patch/format+learned-recipe-code-mutation+watchdog-code-mutation+reconnect-triggered-code-change+packaged-default-over-active-source+uncommitted-work-overwrite+candidate-as-repair-baseline+reconnect-ready-before-convergence+parallel-reconnectors+stale-session-reuse+unbounded-retry+repair-success-without-before/after-source-hash-proof', E'No disconnect outage startup failure corruption suspicion or availability emergency authorizes automatic source-code mutation; emergency action is limited to route isolation process containment and preservation of evidence and user work.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (353, E'C40', E'3', E'automatic-repair-preservation-and-no-overwrite-special-law', E'SCOPE:all automatic repair health preservation recovery startup watchdog maintenance learned recipe and governed repair execution; SUCCESSOR:C39 refined so automatic repair may perform only evidence-bounded minimal repair and never replacement or reset; OWNER:decision-sovereign diagnoses+health-maintenance-test-sub-sovereign manages repair evidence while permission-sovereign grants exact path/action scope+release-update-sync-sub-sovereign reviews any code repair method+governed executor applies+independent verifier accepts; REPAIR-DEFINITION:minimal localized correction to the identified defect while preserving unaffected bytes structure history configuration user work and active certified release; REQUIRED-BEFORE:exact fault code+root-cause evidence+target allowlist+before hash+Git index/worktree state+backup/checkpoint+patch plan+rollback proof+test plan+decision and permission proofs; ALLOWED:smallest deterministic in-place patch limited to authorized defective region+additive compatibility shim+configuration value correction+rebuild generated artifact from its same authoritative source when source itself is unchanged; PROHIBITED-METHOD:whole-file or directory replacement+copy-over+template/default restoration+Git checkout/reset/restore/revert/clean+branch/worktree switching+history rewrite+database snapshot rollback as code repair+package reinstall over source+regeneration that discards edits+delete-and-recreate+blind formatting+LLM whole-file rewrite; UNCOMMITTED-WORK:immutable to automatic repair+overlap means stop and request user decision; PATCH:three-way context+preimage hash+bounded changed lines+atomic write+postimage hash+diff review; FAILURE:patch mismatch test failure scope expansion ambiguity or hash drift=>no mutation or atomic rollback of only this attempted patch+retain evidence; VERIFICATION:syntax/type/contract/focused regression+governance audit+source diff proves only authorized minimal repair+runtime stability window; RECONNECT:transport recovery remains source-nonmutating and cannot invoke code repair merely because a channel disconnected; LEARNING:may propose repair recipe only and cannot widen target choose version or execute without current proof\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:overwrite+reset+replacement+restore-default+checkout+clean+revert+delete-recreate+whole-file-rewrite+whole-directory-sync+uncommitted-change-loss+scope-creep+blind-pattern-replacement+repair-without-root-cause+repair-without-preimage/postimage-hash+repair-from-stale-baseline+repair-by-version-selection+reconnect-triggered-source-mutation+self-authorized-repair+self-verification+success-before-diff-and-tests', E'Emergency containment may stop or isolate the affected capability without modifying source; any later automatic code repair still requires every scope evidence patch and verification condition of this article.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (354, E'C41', E'3', E'whole-codex-repair-and-continuity-integration', E'WHOLE-CODEX-INTEGRATION:all main-codex outlines+subordinate ordinances+special laws+permission-sovereign directories apply as one non-skippable hierarchy; REPAIR-ORDER:authority and identity>scope owner>evidence and preservation>channel continuity>minimal repair method>independent verification>certified activation>stability publication; GENERAL-RULE:C40 no-overwrite/no-reset preservation boundary governs every automatic repair across every domain and more-specific law may narrow but never weaken it; CHANNEL:B46+C39 reconnect first without source mutation and only an independently proven source defect may enter C40 repair chain; STARTUP:B47 ten-second deadline failure is not permission to overwrite or reset code; LIVE-CHANGE:B48 candidate failure never becomes automatic replacement of active code; RELEASE:D28+D29 retain exact active certified baseline and rollback is a new explicit certified activation not repair reset; DATA:authoritative data repair uses owner transaction semantics and cannot be misrepresented as source-code replacement; TOOLS:each independent individual retains own failure boundary and main-system repair cannot mutate its source or terminate it; CONFLICT:preservation+no-overwrite+no-reset+explicit owner+current permission+minimal scope+strongest verification prevail; ACCEPTANCE:one trace proves fault>owner>scope>method>before/after hashes>diff>tests>audit>activation or no-activation>stability without loss of user work', E'FORBID:any-law-interpreted-to-authorize-overwrite/reset+special-law-exception-that-weakens-C40+repair-owner-combination+cross-individual-repair+automatic-version-rollback+startup-deadline-used-as-destructive-repair-authority+channel-failure-used-as-code-mutation-proof+successful-runtime-used-to-hide-source-loss', E'Only an explicit human-governor successor provision may change the no-overwrite/no-reset boundary; operational urgency and automated decisions cannot create an exception.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (355, E'C42', E'3', E'automatic-repair-preservation-special-law', E'AUTOMATIC-REPAIR:exact root-cause evidence>preserve Git/index/worktree/user state+before hashes>exact decision/permission/programming-review proof>smallest deterministic targeted patch>post-hash/diff/tests/audit/stability; METHOD:repair-only; UNCOMMITTED-OVERLAP:stop; DISCONNECT:reconnect without source mutation; FAILURE:no mutation or rollback only attempted patch', E'FORBID:overwrite+reset+replacement+restore-default+checkout+clean+revert+delete-recreate+whole-file-rewrite+directory-sync+version-selection+uncommitted-loss+self-authorization+self-verification', E'Containment may isolate an affected capability but never expands automatic source mutation authority.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (356, E'C43', E'3', E'update-and-reload-special-law', E'UPDATE-RELOAD:candidate isolated from active certified runtime; full precheck; edit/build/test/reject cannot stop restart disconnect or degrade active generation; compatible hot-reload uses transactional snapshot+dependency order+full rollback; incompatible change uses ready blue-green successor before atomic switch; frontend reuses same window host; failure retains active release; rollback is new explicit certified activation; control traffic has reserved capacity\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:uncertified-update+partial-live-reload+candidate-active-import+save-triggered-restart+reload-disconnect+default-over-active+automatic-reset/rollback+activation-before-ready+mixed-generation', E'Security containment may disable only an affected artifact; activation still requires certification.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (357, E'C44', E'3', E'directory-coverage-and-special-law-convergence', E'SCOPE:directory relationships+fault-to-manual coverage+special-law successor convergence+identity groups+independent-tool isolation; RULE:all relationship endpoints use immutable DIR_* directory codes and one row per source-target edge; composite physical table-name targets are invalid; every retryable or repairable registered fault maps to at least one maintenance manual and test flow; overlapping active special provisions must declare one successor and remove predecessor from effective set while preserving identity and lineage; identity groups require a dedicated directory; every ordered pair of main-system and independent tools requires a failure-isolation matrix entry covering process window data channel resource repair update and shutdown; PENDING:directory implementation remains explicitly pending until inventory format relationship consumer failure-injection rollback and zero-gap evidence pass; EXTERNAL:signature and 星澄 confidential-storage gates remain open until their independent proofs exist and cannot be self-closed by codex text; RELEASE:open required gate blocks verified activation but does not erase the prior valid codex state', E'FORBID:physical-table-name-as-directory-relationship-identity+multi-target-string-in-one-edge+repairable-fault-without-manual+parallel-active-duplicate-special-provisions+identity-group-without-directory+independent-tool-without-pairwise-isolation-matrix+pending-directory-marked-active-without-evidence+external-gate-self-asserted-complete+deleting-superseded-identity', E'External signature and encrypted 星澄 storage completion require their declared external evidence and therefore remain visible open gates until independently satisfied.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (358, E'C45', E'3', E'git-top-level-directory-classification', E'PHYSICAL-IDENTITY:Git top-level directory is DIR[DIR_PROJECT_ROOT]; CANONICAL-CLASSIFICATION:git-top-level-directory co-located with PROJECT_GPTBRIDGE project root; AUTHORITY:the repository metadata+index+references+objects+hooks+configuration+tracked working trees and version-control runtime artifacts must resolve inside DIR[DIR_PROJECT_ROOT] after canonical path and reparse-point resolution; SINGLE-ROOT:no alternate active Git top-level or worktree root outside DIR[DIR_PROJECT_ROOT]; WORKTREE:each governed worktree must be a registered descendant path and preserve branch+index+ownership isolation; OPERATIONS:commit+merge+sync+audit+push originate from the registered Git root and follow coordinator authority; MIGRATION:legacy external worktrees become nonlaunchable read-only migration evidence until moved+validated+retired', E'FORBID:Git-active-root-outside-DIR[DIR_PROJECT_ROOT]+external-active-worktree+alternate-dot-git-authority+gitdir-pointer-escape+symlink/junction/reparse-escape+unregistered-worktree+cross-worktree-index-mutation+worker-direct-push+force-push/ref-delete/non-fast-forward-without-explicit-governance-approval', E'A legacy external worktree may remain read-only during a registered migration window; it cannot receive commits, synchronization, runtime writes, or remain active after the internal successor is validated.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (359, E'C46', E'3', E'top-level-directory-path-special-law', E'SCOPE:all project+Git+main-system+startup-core+governance-codex+local-model+independent-tool and registered module roots; OWNER:permission-sovereign exclusively registers path codes and canonical targets; IDENTITY:each top-level root has one immutable uppercase path-code+lower-kebab canonical-name+one canonical absolute path+entity-kind+parent+logical owner+activation state; RESOLUTION:environment variables and configuration reference path-code only and resolver canonicalizes case+separator+relative segments+symlink+junction/reparse target before descendant validation; BOUNDARY:no owned local artifact may resolve outside registered root; EXTERNAL:PostgreSQL+Rust-Vector-Engine+external service storage uses registered opaque authority endpoints and is never encoded as local path exception; MIGRATION:old and target roots recorded with one-way state transition+read-only old root+atomic reference cutover+tests+rollback; COMPLETION:new architecture is complete only after target validation+all references cut over+rollback window closed+legacy data reconciled+old root safely deleted+deletion proof recorded; NO-LEGACY-ROOT:no completed architecture may retain old directory+junction+symlink+redirect+duplicate+backup inside active namespace; AUTHORITY:directory declaration and its implementation obligation are both mandatory', E'FORBID:hardcoded-physical-path-outside-directory+unregistered-root+duplicate-active-root+path-code-reuse+relative/absolute traversal+symlink/junction/reparse/environment escape+case-alias collision+implicit external-storage exception+active-before-validation+legacy-write/launch-after-cutover+complete-before-old-root-deletion+retained-old-root/junction/symlink/redirect/duplicate/backup-in-active-namespace', E'Operating-system required locations may be used only through a registered external-location code with exact owner, permission, lifecycle, cleanup and non-authoritative status; immutable audit evidence may retain hashes and manifests but not the old working root.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (360, E'C47', E'3', E'system-stability-fault-reduction-self-repair-speed-and-isolation-special-law', E'OBJECTIVES:maximize stable availability+reduce preventable faults+minimize detection/containment/recovery time+preserve bounded execution latency+guarantee owner-local blast radius; OWNER:runtime-sovereign owns continuity+decision-sovereign owns health classification and reliability priorities+health-maintenance-test-sub-sovereign manages repair verification+permission-sovereign owns exact authority+automation-sovereign owns budgets and resource allocation with resource-dependency-sync-sub-sovereign managing resource modules+information-layer owns cross-layer signals; SLO:each capability declares availability+latency p50/p95/p99+throughput+error rate+queue age+resource headroom+fault budget+detection deadline+containment deadline+recovery objective+stability window; PREVENTION:typed contracts+bounded resources+dependency timeouts+bulkheads+circuit breakers+backpressure+admission control+idempotency+checkpointing+preflight+fault injection+capacity margin; SPEED:critical-path priority+parallel independent work+event-driven waits+bounded payloads+cache with freshness proof+no duplicate probes+no busy polling+deadline propagation+load shed noncritical work before control degradation; REPAIR:detect>classify exact fault code>isolate>preserve state/evidence>select registered manual>permission check>bounded minimal repair with no overwrite/reset>independent verification>stability window>close or escalate; REPAIR-LIMIT:no self-modification of source+no authority expansion+no repeated ineffective repair+failure budget and circuit breaker; ISOLATION:per-individual process+generation+queue+pool+quota+session+data+logs+repair+update+shutdown and shared dependency tenant/bulkhead; CASCADE-PREVENTION:one owner failure cannot restart+stop+mutate+starve+lower health verdict of another; MEASUREMENT:every release compares baseline/regression and blocks activation on reliability or latency regression beyond declared budget\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:unbounded queue/retry/resource+retry storm+shared failure budget+global restart/kill+cross-owner repair+repair-by-overwrite/reset+repair-without-root-cause/manual/permission/evidence+same-actor-final-verification+performance-by-average-only+latency-without-percentiles+speed-by-skipping-governance/safety/durability+stability-from-process-existence+fault masking+premature-success+repeated-repair-after-budget+dependency-cascade', E'Emergency containment may immediately stop only the exact hazardous owner operation; it must preserve evidence and cannot bypass later authority, repair, verification, isolation or stability-window requirements.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (361, E'C48', E'3', E'noninterrupting-channel-anomaly-isolation', E'INVARIANT:an anomaly must never globally interrupt an information channel or unrelated route; ACTION:isolate only the exact anomalous message+event+stream+session+tenant+capability or owner generation while preserving control+heartbeat+ack+healthy traffic; REDUNDANCY:critical routes maintain independent control lane+bounded alternate transport/session and authoritative cursor checkpoint so service continues in degraded authenticated mode; DETECTION:malformed payload+sequence gap+stale generation+auth anomaly+backpressure+timeout+jailbreak indicator+dependency fault becomes typed quarantined item and not channel-wide shutdown; STATE:healthy partitions remain connected+affected partition marked isolated/degraded+state-changing action for affected scope fails closed+read-only last-confirmed state marked stale where required; RECOVERY:diagnose isolated cause+fresh authentication/generation+snapshot/cursor/hash reconciliation+independent verification+stability window then rejoin without duplicate side effect; CASCADE:no anomaly may consume unrelated retry/failure budgets or restart/stop another individual; OBSERVABILITY:continuous status includes isolation scope+reason+since+healthy-route count+recovery owner and never secret payload\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:global-channel-close-for-local-anomaly+unrelated-route-interruption+control/heartbeat-starvation+drop-anomaly-without-evidence+apply-quarantined-message+continue-affected-state-changing-command+shared-retry-budget+channel-wide-restart+silent-degraded-state+rejoin-before-convergence+duplicate-side-effect', E'If every redundant route is physically unavailable, the channel remains in an explicit isolated degraded state with control recovery attempts and preserved evidence; it may not falsely report connected or discard state.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (362, E'C49', E'3', E'automatic-cleanup-backup-repair-update-converged-under-automation-sovereign', E'SCOPE:automatic-cleanup+automatic-backup+automatic-repair+automatic-update; DECISION-OWNER:automation-sovereign exclusively decides schedule+priority+dependency order+cross-module consistency target+conflict disposition+activation or cancellation+acceptance; MANAGEMENT:matching no-decision no-execution sub-sovereigns manage registered cleanup+backup+repair+update modules+assign exact work+coordinate division+collect evidence; EXECUTION:module-execution-layer only; ORDER:preflight>星澄 permission review when permission affected>decision>module assignment>checkpoint/backup>bounded action>verification>stability window>status convergence; ISOLATION:exact owner+path+data+release+generation scope and unrelated individuals continue; PRESERVATION:no source overwrite/reset+no uncommitted-work mutation+no deletion before verified backup and retention decision+update only certified candidate+repair only minimal registered method; FAILURE:quarantine exact operation+preserve evidence/state+no global rollback/restart+sync decision for retry or cancellation\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:parallel ownership outside automation-sovereign+sovereign or sub-sovereign direct execution+cleanup without exact target and retention proof+backup without restore verification+repair by overwrite/reset+uncertified update+cross-owner mutation+global restart/rollback+shared failure budget+success before convergence', E'Explicit one-time user commands remain lawful but still use the same module-execution, isolation, evidence and preservation boundaries.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (363, E'C50', E'3', E'automation-core-final-responsibility', E'OWNER:automation-core. RESPONSIBILITY:orchestrate authorized workflow scheduling,synchronization target,dependency order,atomic boundary,conflict isolation,retry,cancellation,update,backup,restore,repair,retention and convergence evidence. AUTHORITY:automation-core never creates policy or permission;it accepts current decision and permission artifacts. EXECUTION:registered modules perform bounded work and return typed receipts;runtime-core owns process execution mechanics. DOMAIN-SPLIT:resource,dependency,channel,release,state,repair,backup,cleanup,retention,learning-evidence and audit-delivery are module responsibilities under one automation-core contract,not sub-sovereigns. SUCCESS:all required identities,versions,states and receipts converge and independent verification passes.', E'FORBID:automation-sovereign-or-sub-sovereign+automation-self-authorization+module-authority+overlapping-module-owner+implicit-target+unverified-overwrite-reset-delete-update-repair-or-restore+success-before-convergence', E'Emergency containment may isolate the exact affected scope but cannot transfer policy,permission or execution authority.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (364, E'C51', E'3', E'backend-code-update-automation-sovereign-privilege', E'TRIGGER:certified backend code update candidate enters activation synchronization; PRIVILEGED-ACTOR:automation-sovereign; SPECIAL-PRECEDENCE:this narrow privilege overrides the general zero-execution rule only for synchronization processing and only during the bounded backend update transaction; ALLOWED-EXECUTION:freeze matching intake+capture active release/state/cursor hashes+verify candidate certificate and backend/frontend/contract generation+coordinate drain/checkpoint+atomically switch registered release pointer+renew routes/subscriptions+reconcile snapshot/cursor/hash+verify convergence+publish typed status; CODE-BOUNDARY:no source code editing+generation+repair+replacement+reset and no selection of update content; TARGET-AUTHORITY:decision-sovereign accepts change content+permission-sovereign authorizes exact scope after 星澄 review+automation-sovereign executes only the already-authorized synchronization transaction; ISOLATION:exact backend owner+release+generation only and independent tools/unaffected routes continue; TRANSACTION:single writer+idempotency key+preimage/postimage roots+checkpoint+bounded deadline+rollback to prior certified pointer only before irreversible commit+append-only evidence; SUCCESS:all declared artifacts+contracts+routes+state+cursor+hashes converge through stability window; FAILURE:quarantine candidate+retain prior certified runtime+isolate exact route/generation+no global restart', E'FORBID:backend source mutation+choosing or altering update content+permission self-grant+execution outside trigger/scope/deadline+whole-file overwrite/reset+uncertified artifact+cross-owner update+parallel synchronizers+partial publish+ready before convergence+global interruption+suppressed evidence', E'Immediate containment may stop only the exact unsafe activation transaction; it cannot modify code or expand synchronization authority.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (365, E'C52', E'3', E'automation-sovereign-global-update-execution-and-convergence', E'GLOBAL-UPDATE:sole automation coordinator updates registered dependencies after timing/gates and never admits a new dependency without explicit permission artifact. TRANSACTION:affected inventory>stage>compatibility/security/config/backup/test>canary>waves>A/B atomic handover>stability>retire prior. RETIREMENT:prior generation becomes ROLLBACK_ONLY for registered bounded window; successful window+zero consumers/locks/manifests/processes+completed migration produces PURGE_READY and automatic complete deletion; failed successor rolls back before purge. TERMINAL:ACTIVE current+optional one ROLLBACK_ONLY or PURGED prior; no indefinite standby/archive.; UPDATE-DETECTION:every-24-hours+immediate-governed-security-advisory-event; RETIREMENT-TAG:mandatory from SUPERSEDED through PURGE_READY and binds dependency-id+old-version+successor-version+state+reason+zero-consumer-progress+rollback-deadline+scheduled-purge-at\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:unapproved-new-dependency+second-coordinator+normal-update-before-14-days+false-emergency+overwrite-active+purge-before-stability/rollback-expiry/zero-reference+retain-multiple-old-versions+hidden-partial-failure+missing-or-stale-retirement-tag+update-detection-interval-not-24-hours', E'Critical security updates may shorten canary and observation timing but cannot bypass certification, 星澄 review, permission authorization, signed provenance, isolation, journal, evidence, compatibility or rollback readiness; an actively exploited target may be isolated while unaffected channels remain available.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (366, E'C53', E'3', E'cpp-six-domain-namespace-and-include-dependency-special-law', E'GOVERNANCE-UNIT:C++ six-domain governance applies to namespace+symbol ownership+include/link dependency edges,not source-file or folder count; CANONICAL-NAMESPACES:gptbridge::native::parser|gptbridge::native::vector|gptbridge::native::memory|gptbridge::native::token|gptbridge::native::transform|gptbridge::native::binding; PHYSICAL-ALLOW:parser.cpp+vector.cpp+transformer.cpp are a valid three-file core and no empty/artificial memory.cpp,token.cpp,binding.cpp or six-folder layout is required; COLOCATION:a translation unit may implement multiple canonical namespaces only when every symbol belongs to exactly one namespace and all edges obey the DAG; DAG:memory=>none; token=>memory; parser=>token+memory; vector=>memory; transform=>memory and vector only when explicitly declared; binding=>parser+vector+memory+token+transform; NO-REVERSE:callee cannot include/call dependent/upstream namespace; C-ABI:gptbridge_native.h+gptbridge_native.c remain the language-neutral contract/thunk outside C++ namespace ownership and D60 controls the sole consumer path; BINDING-NAMESPACE:gptbridge::native::binding is private C++/pybind11 adaptation ownership only and cannot become a second public contract; CHECKER:parse namespaces+fully qualified symbols+headers/includes+calls+link graph,resolve each symbol to one domain,compare actual graph to declared DAG,detect cycles+reverse edges+unmapped/global symbols+duplicate owners and report physical files separately from logical namespaces; HEADER:private header declares one primary namespace or an explicit bounded multi-namespace boundary and cannot expose private implementation across forbidden edges; TEST:one logical-domain test group per namespace+dependency graph test+cycle injection+co-location fixture+current-three-file fixture+D59 release gate; SUPERSESSION:D37 requirements for own folder,one domain per source module or six physical units are non-operative and replaced by C53.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:checker equating namespace count with file count+mandatory six cpp files/folders+namespace-less native symbol except exact C ABI exports+wrong/reverse dependency+cycle+memory dependency+token calling parser/vector/transform/binding+parser calling vector/transform/binding+vector calling parser/token/transform/binding+transform calling parser/token/binding or undeclared vector+binding owning algorithm/policy+include cpp+duplicate/unmapped symbol+physical layout used as proof without namespace graph.', E'Compiler-generated anonymous/internal symbols may remain translation-unit local when checker traces them to one enclosing canonical namespace owner and proves no cross-domain edge or exported identity.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (367, E'C54', E'3', E'canonical-javascript-csharp-sql-native-fsharp-topology-special-law', E'TOPOLOGY:B166-managed UI client>selected approved shell and typed bridge>application/workflow API;branches resolve through current B166 single-owner allocation and PostgreSQL authority;TEST-AUDIT:CSharp sole orchestration+owner-language native runners+C++23 Audit Engine;FAILURE:typed fail-closed without alternate owner', E'FORBID:pytest-or-Python-test/audit/verification+Python-application-path+contractless-cross-owner-call+alternate-owner-on-failure', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (368, E'C55', E'3', E'javascript-esm-governance-checker-structure-and-dependency-dag-evidence-special-law', E'ROOT:governance checker JavaScript-ESM subtree uses code/; STRUCTURE:code/checkers/LanguageBoundaryChecker.js+code/checkers/DependencyDagChecker.js;code/policy/LanguagePolicy.js+code/policy/DependencyPolicy.js;code/registry/GovernanceCheckerRegistry.js; DIRECTORY-EXCEPTION:B75 JavaScript-ESM directory allowlist is extended only for this registered governance checker subtree with policy and registry roles below; CHECKERS:LanguageBoundaryChecker performs D62 language/origin/owner/directory/ABI/API/size gate and DependencyDagChecker performs D64 resolved edge graph+DAG+cycle verification; POLICY:LanguagePolicy and DependencyPolicy contain immutable declarative data only,no scanning/resolution/filesystem/network/process/evidence/verdict/repair side effects; REGISTRY:GovernanceCheckerRegistry registers exact checker id+policy id+trigger+input/output schema+rule set+version and performs no scan,decision or repair; DEPENDENCY-POLICY-DAG:{javascript-esm=>information_layer}+{c=>cpp}+{binding=>parser|vector|token|transform|memory}+{parser=>token|memory}+{vector=>memory}+{token=>memory}+{transform=>memory}+{memory=>none}; CANONICAL-QUALIFICATION:javascript-esm>information_layer expands to B32 canonical contract;Python is retired and no python>native or python-qualified expansion exists; graph uses canonical node/edge ids and denies every undeclared edge; CYCLE:any directed cycle is FAIL even when each edge appears locally allowed; DIAGNOSTIC:never only FAIL dependency violation; output FAIL plus source:<canonical path>,target:<canonical path>,edge:<source-role>-><target-role>,rule:<exact ids>,reason:<typed human-readable boundary>,expected:<canonical path>; example JavaScript-ESM direct Python uses edge=javascript-esm->python-direct,rule=B32/B50,expected=no-python-target-exists; READONLY-V1:scan+resolve+classify+compare+evidence+PASS/WARN/FAIL only; decision remains existing governance chain.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:checker automatic import/include/build/path rewrite+file move+automatic CMake/csproj/tsconfig mutation+checker-created exception/allowlist+policy executable scan logic+registry authority+generic dependency failure without exact source,target,edge,rule,reason,expected+cycle accepted because component edges are locally allowed+undeclared DAG edge+text-only dependency proof.', E'None for mutation or exception creation. Owner-neutral remediation context may name the expected edge but cannot contain or execute a patch.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (369, E'C56', E'3', E'vector-lineage-outbox-generation-and-recovery', E'WRITE-BOUNDARY:one PostgreSQL transaction writes resource+chunk+embedding+revision+scope+tombstone+durable-index-outbox-event;APPLICATION-DUAL-WRITE:forbidden;INDEX-WORKER:bounded Rust owner consumes idempotently+in-batches+generation-aware+crash-recoverable and records index-state acknowledgement;QUEUE-BOUNDARY:PostgreSQL stores durable mutation events but is not used for high-frequency ephemeral runtime events;GENERATION:index_generation+schema_version+embedding_model+embedding_version+dimensions+distance_metric+source_revision_watermark+build_hash+created_at+verified_at;READ:query cannot mix incompatible generations;RECOVERY:last verified generation remains active until replacement passes', E'FORBID:independent-synchronous-dual-write+unbounded-outbox-consumer+ack-before-index-update+generation-without-watermark+mixed-dimension/model/metric+failed-rebuild-overwriting-last-verified-generation', E'Concrete algorithms, thresholds, index layouts and batch values remain implementation-layer rules and require no Codex amendment while boundaries stay unchanged.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (370, E'C57', E'3', E'xingcheng-auxiliary-repair-update-user-switch-confirmation-and-fault-cardinality', E'CONTROL-SURFACE:星澄 auxiliary system owns the user-facing control surface for automatic repair and automatic update. It exposes two independent explicit switches:automatic_repair_enabled and automatic_update_enabled; default and persisted state must be visible,attributable to the user and never inferred from model intent. DETECTION:health observation,fault classification,evidence collection,isolation and non-mutating diagnosis may continue regardless of execution switch so faults remain observable. EXECUTION-GATE:a repair/update mutation may execute only when its corresponding switch is enabled AND the user confirms the concrete pending action. DOMAIN-SCOPE:the repair side of this surface governs user-facing repair intents presented on the auxiliary surface only; faults of the governed runtime classified by the maintenance sovereign and routed to 星澄 for autonomous governed repair under C105 are outside the switch and confirmation scope of this article, are never presented as user-confirmation items, and are not gated by repair_release or automatic_repair_enabled. Confirmation binds action_id,fault_id or update_id,scope,target,proposed method,risk,rollback/fallback,evidence digest and expiry; it is one-time,non-transferable and invalid after material plan/evidence change. A switch alone is not confirmation;confirmation alone cannot bypass a disabled switch. Existing lawful one-time manual commands remain valid only for their explicit scope. CARDINALITY:the detector assigns one incident snapshot as SINGLE_FAULT when exactly one independently actionable fault exists,or MULTI_FAULT when two or more exist; correlated symptoms may share a root_cause_group but each distinct fault keeps its own fault_id,evidence,severity,impact,isolation state,proposed action and confirmation state. PRESENTATION:SINGLE_FAULT displays one complete fault item. MULTI_FAULT displays every fault individually in deterministic severity/time/fault_id order,shows total and unresolved counts,and provides per-fault confirmation;bulk confirmation is forbidden unless every included action is expanded,individually selectable and explicitly confirmed in the same user act. SEQUENCING:multi-fault execution is one action at a time;after each action re-detect and refresh remaining evidence because one repair may invalidate another diagnosis. Failure of one item is isolated and cannot hide,cancel or auto-authorize others. UPDATE:automatic update follows the same switch+confirmation rule and must show version/source/hash/affected scope,compatibility evidence and rollback;backend synchronization privilege does not waive user confirmation. AUDIT:record switch changes,prompt,decision,actor,time,action result and refreshed fault set without secrets. UI close/cancel/expiry means no mutation.', E'FORBID:hidden or combined switch+switch enabling itself+model/repair engine impersonating user confirmation+execute-on-detection+confirmation reused across actions+silent bulk repair/update+multi-fault collapsed into one generic message+showing only first fault+repair failure suppressing other faults+changed plan using stale confirmation+disabled switch bypass+confirmation dialog defaulting to approval+code overwrite/reset as repair.', E'Immediate reversible isolation may occur without confirmation solely to stop active damage while preserving unaffected operation; it cannot modify source code,apply an update,erase evidence or become a repair, and must be displayed as an isolated fault action for subsequent user decision.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (371, E'C58', E'3', E'postgresql-pgvector-rust-activation-order', E'ORDER:1 PostgreSQL extension/schema/migration parity;2 canonical resource+chunk+vector+scope+lineage identities;3 Rust-native-vector-engine contract and deterministic rebuild;4 hybrid retrieval parity and PostgreSQL post-verification;5 legacy vector-service zero-consumer proof;6 legacy data/config/package/runtime removal;7 recovery rebuild evidence;DEPENDENCY:each stage consumes current evidence from predecessors;FAILURE:blocks affected and downstream activation while verified upstream capability remains;REENTRY:resume earliest invalid stage', E'FORBID:stage-skip+parallel-activation-bypass+Rust-before-canonical-pgvector+legacy-service-after-cutover+deletion-before-canonical-migration+completion-without-rebuild-and-zero-consumer-proof', E'Historical retired-service identity may remain only in lineage and removal evidence.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (372, E'C59', E'3', E'database-runtime-pool-query-schema-health-and-cross-engine-integrity', E'POOL-ISOLATION:central-index,transport,audit and each module-private database use separately budgeted connection pools with owner,max/open/idle/wait/lease metrics and reserved critical capacity;one workload cannot exhaust another pool. READ-WRITE-PATH:code exposes distinct read and write paths even on one host;transaction consistency and read-after-write requirements are explicit and routing may later change without contract drift. SQL-SAFETY:all runtime values use prepared statements or parameterized queries;SQL string concatenation/interpolation for transport,locator,resource lookup and every runtime query is prohibited. TIMEOUTS:every runtime statement has a bounded statement_timeout;transactions have lock_timeout,idle timeout and bounded deadlock/serialization retry with jitter,idempotency and total deadline;retry never duplicates committed side effects. PERFORMANCE-EVIDENCE:slow-query log stores redacted query digest,role/module,mean,p95,p99,rows examined/returned,calls and plan identity without secrets or raw personal values. Periodic analysis identifies unused/duplicate indexes and abnormal sequential scans;index removal/addition requires workload,query-plan,write/storage and rollback evidence. RETENTION:audit,transport history,model inference history and repair history each declare retention,archive/legal-hold,purge owner and proof;central append-only audit uses governed archival/purge rather than runtime mutation. VACUUM-ANALYZE:registered native health/maintenance execution observes bloat,dead tuples,statistics freshness and transaction age,then schedules bounded VACUUM/ANALYZE through governed execution;Python is retired and manual recurring dependence is forbidden. SCHEMA-CONTRACT:startup verifies expected schema version,tables,columns/types/nullability,constraints,indexes,RLS/policies,extensions and migration head before write readiness. DRIFT:actual catalog is deterministically compared to approved migration-derived schema digest;out-of-band change becomes SCHEMA_DRIFT,blocks unsafe writes and cannot be silently adopted. MIGRATION-DRY-RUN:before formal migration validate dependency graph,lock/table-rewrite risk,name/type/default conflicts,data conversion,space/time budget,upgrade order,rollback or downgrade feasibility and mixed-version compatibility;destructive or irreversible steps require explicit evidence and user/governance authorization. MODULE-DB-HEALTH:each module database state is exactly healthy|degraded|reconcile_required|read_only|failed with reason,evidence,time and allowed operations;health state does not change authority. LOCATOR:verify locator target identity,existence,boundary and content/version hash;missing or mismatched target is orphaned and is never returned as valid. TOMBSTONE:resource deletion first writes deleted/tombstoned status,revision,time,actor,reason and correlation_id;downstream cleanup and audit complete before policy-governed purge;hard delete cannot erase required lineage. VECTOR-FRESHNESS:compare derived-index resource_id/chunk_id/resource_version/content_hash/embedding version to PostgreSQL;older or mismatched vector is stale,excluded from authoritative retrieval and queued for idempotent rebuild. CENTRAL-SHAPE:central index stores necessary normalized frequently queried fields;JSONB is for bounded typed extension data with schema,size/index/retention rules and cannot become an unbounded catch-all. CROSS-ENGINE-EVENT:every PostgreSQL>Rust-derived-index transition uses one correlation_id with resource_id,from/to revision,hash,status,idempotency key and audit linkage across the entire chain. All controls obey the C58 stage order.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:shared universal pool+unbounded connection acquisition+mixed hidden read/write route+SQL concatenation/interpolation+unbounded statement/lock wait+unbounded deadlock retry+raw sensitive slow-query text+automatic index churn+unbounded history+manual-only vacuum/analyze+write-ready before schema check+accepting schema drift as baseline+production migration without dry-run+unknown module DB health+returning orphan locator+immediate unaudited hard delete+serving stale vector as current+unmanaged alternate embedded database WAL+all-DB blocking startup scan by default+JSONB dumping ground+cross-engine update without correlation_id.+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'A parameterized administrative migration statement may contain approved static identifiers that cannot be bound,provided identifiers come from a closed registry and are quoted/validated;emergency read-only access may proceed under schema drift only when compatibility is proven and audited.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (373, E'C60', E'3', E'observable-verifiable-recoverable-postgresql-pgvector-rust-platform', E'PLATFORM:PostgreSQL+pgvector canonical authority and Rust-native-vector-engine rebuildable acceleration operate as one local vector platform;HEALTH:POSTGRESQL|PGVECTOR|RUST_VECTOR_ENGINE|MIGRATION|REBUILD|RETRIEVAL each emits healthy|degraded|stale|rebuild_required|failed with scope+revision+evidence+allowed-operations;CONSISTENCY:every derived entry matches PostgreSQL resource+chunk+revision+content+embedding+scope;MISMATCH:mark stale/rebuild_required and block derived use;RECOVERY:detect>isolate>discard-derived>rebuild-from-PostgreSQL>verify>activate>audit;LEGACY:retired vector service is excluded from health and runtime and tracked only by removal evidence', E'FORBID:health-masking+derived-mismatch-overwrite+Rust-promotion-to-authority+legacy-service-health-or-fallback+recovery-without-canonical-proof', E'Historical retired-service identity may remain only in lineage and removal evidence.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (374, E'C61', E'3', E'three-engine-self-observation-diagnosis-and-controlled-optimization', E'AUTOMATIC-DATA-MAINTENANCE:PostgreSQL+Rust-Vector-Engine self-observe,self-diagnose and self-maintain through one registered event-driven maintenance flow; EVENTS:schema/migration+query-plan+capacity+WAL+transport-backlog+source-revision+index-generation+permission+restore; ACTIONS:bounded analyze/vacuum/reindex/rebuild/reconcile/retention/connection-generation-fence and safe additive index maintenance; SAFETY:canonical migration/schema/permission contracts control every action; reversible deterministic actions execute automatically; destructive,authority-changing or unknown-effect actions fail closed and quarantine; CAPACITY:30/90/180-day forecast+warning/critical/fail-closed; EVIDENCE:before/after plan+counts+hashes+generation+latency+resource+result; SCHEDULER:existing sole automation scheduler only', E'FORBID:second-maintenance-scheduler+manual-confirmation-as-normal-path+automatic-destructive-DDL+authority-changing-optimization+unbounded-query/retry+reopen-before-certification+retired-engine-consumer+success-without-evidence', E'An approved emergency may cancel a query,throttle/reject new low-priority work or isolate a failing pool without mutation confirmation to preserve stability;it must remain reversible,visible and audited and cannot create/drop an index,purge data or reopen a failed store.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (375, E'C62', E'3', E'bounded-vector-query-planning-and-authority-verification', E'PLANNER:one Rust RAG query planner selects only necessary governed paths from semantic-ANN-vectord-rs|exact-or-small-scope-pgvector|pgvector-degradation|PostgreSQL-FTS+vectord-rs-hybrid|relational-filter-first;SELECTION:scope+capability+health+estimated-candidate-size+deadline+resource-envelope;PARALLELISM:independent lexical+semantic+metadata preparation may execute concurrently through existing bounded scheduler then one bounded join;AUTHORITY-VERIFY:all candidate IDs use one bounded PostgreSQL batch validation before context;CHECKS:resource-exists+chunk-exists+revision-current+status-active+tombstone-false+scope-allowed+embedding-compatible;FAILURE:drop invalid candidate and fail-closed/degrade exact capability according to policy;NPLUSONE:forbidden', E'FORBID:query-all-backends-unconditionally+unbounded-spawn/thread/task+per-candidate-SQL+candidate-context-before-authority-check+scope-post-check-only+retired-vector-service-route+Python-query-planner', E'Concrete algorithms, thresholds, index layouts and batch values remain implementation-layer rules and require no Codex amendment while boundaries stay unchanged.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (376, E'C63', E'3', E'postgresql-pgvector-rust-rag-stage-order', E'ORDER:1 PGVECTOR_CANONICAL_SCHEMA;2 POSTGRESQL_RESOURCE_CHUNK_SCOPE_LINEAGE;3 RUST_NATIVE_VECTOR_REBUILDABLE_ACCELERATION;4 HYBRID_DENSE_KEYWORD_METADATA_PARITY;5 CODE_RAG;6 AGENTIC_RAG;7 MEMORY_RAG;RULE:each stage requires current predecessors;PostgreSQL-only canonical retrieval may remain available when Rust acceleration is degraded;legacy vector service has no stage and no fallback role', E'FORBID:reorder+skip+Rust-as-canonical+legacy-vector-stage+later-RAG-label-substituting-for-foundation+activation-with-stale-predecessor', E'Historical retired-service identity may remain only in lineage and removal evidence.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (377, E'C64', E'3', E'vector-backpressure-cache-cancellation-and-projection', E'BACKPRESSURE:bounded priority queue interactive>maintenance>rebuild using existing scheduler/resource envelope;ADAPTATION:batch+queue+cache+chunk are tuned only within registered ceilings from queue-depth+CPU+RAM+DB-latency+index-latency+interactive-load;CACHE:key includes resource_id+revision+scope_id+embedding_model+embedding_version+query/config-generation and remains non-canonical;CANCELLATION:request>RAG>planner>vectord-rs>PostgreSQL>reranker>context-builder with necessary audit receipt retained;LOW-COPY:large cross-layer payload uses resource/chunk/revision+offset/reference and governed streaming where owner-local benchmark supports it;POOL:existing workload-class PostgreSQL pools only', E'FORBID:unbounded-channel+Tokio-task-or-thread-per-request+rebuild-starving-interactive+cache-key-with-resource-or-query-only+work-continuing-after-cancel+second-connection-pool+per-embedding-transaction+large-buffer-clone-without-evidence', E'Concrete algorithms, thresholds, index layouts and batch values remain implementation-layer rules and require no Codex amendment while boundaries stay unchanged.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (378, E'C65', E'3', E'rag-index-state-reconciliation-collection-topology-and-reranker-fallback', E'INDEX-STATE:every indexed resource/chunk has an authoritative index_state recording at minimum embedding_model,embedding_dimension,chunk_size,chunk_overlap,chunking_version,parser_version,rag_schema_version,content_sha256,indexed_at plus resource_id,chunk_id,source_revision,pipeline_version,backend_generation and status. Reindex planning compares each field and marks only the exact affected resources/chunks stale. A change such as chunk_size 1200/overlap 200 to 1600/250 invalidates entries built under the old pair and their dependent chunk/point mappings;it does not authorize deleting/rebuilding unrelated compatible data or the entire collection. STATE-MACHINE:runtime RAG state is exactly CANONICAL,DEGRADED or RECONCILING. CANONICAL requires healthy Rust-Vector-Engine and PostgreSQL,matching index_state and complete queue. Verified Rust-Vector-Engine/PostgreSQL fault moves affected scope to DEGRADED;canonical writes fail closed and only a registered bounded non-authoritative in-memory cache may serve an already verified read snapshot;each deferred mutation remains in PostgreSQL transport with reconciliation_required=true. Canonical recovery moves to RECONCILING,which must verify source SHA256,resolve owning-module original content,re-chunk under current index_state,re-embed with canonical model/dimension,idempotently write Rust-Vector-Engine,update PostgreSQL,verify resource/chunk/point counts+IDs+hashes+versions and drain/close queue. Only then may reconciliation_required=false and state return CANONICAL. Service availability alone cannot transition to CANONICAL;derived Rust vectors are never canonical and are rebuilt only from PostgreSQL-authoritative content and pgvector metadata. COLLECTION-TOPOLOGY:one Rust-Vector-Engine instance and one canonical collection gptbridge_shared_knowledge serve all authorized local models and four RAG behaviors. Physical per-rag-type or per-model canonical collections are forbidden. Logical isolation uses governed point metadata rag_type with one value or rag_types array containing only hybrid-rag,code-rag,agentic-rag,memory-rag;server-side metadata filters and post-result authorization apply. A chunk may carry multiple rag_types only when each membership has evidence and compatible lifecycle/version. RERANKER-OBSERVABILITY:every retrieval response/evidence reports reranker.requested,reranker.active,reranker.fallback,reranker.reason,model/version and timing. If qwen3-reranker-0.6b is unavailable/not cached,the lawful fallback is RRF with active=false,fallback=rrf and a typed reason such as model_not_cached;successful response cannot imply reranker participation. ORDER:this provision supersedes the shorter C63 work order with the binding sequence:1 Canonical Rust-Vector-Engine;2 PostgreSQL canonical metadata;3 recoverable cross-store write consistency;4 reconciliation;5 index versioning;6 dual-layer authorization filtering;7 stage observability including reranker;8 Code RAG;9 Agentic RAG;10 Memory RAG;11 retrieval benchmark. Stage N activation requires fresh PASS evidence from 1..N-1;isolated experimental work cannot certify a later stage.;MUTABLE-VALUES:resolve-current-values-from-owner-versioned-contract-or-registry;CODEX:retains-owner+boundary+prohibition+acceptance-dimensions-only', E'FORBID:index_state missing any minimum field+whole-collection rebuild when exact affected scope is provable+CANONICAL on endpoint availability alone+direct degraded-vector transfer+clearing reconciliation before count/ID/hash/version proof+four physical canonical RAG collections+unregistered rag_type+multi-rag membership without evidence+silent reranker fallback+response claiming reranker active when RRF fallback ran+skipping the eleven-stage order.+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation;FORBID:deployment-version+benchmark-result+model-threshold+port+path+operational-tunable-as-permanent-Codex-literal', E'A full rebuild is lawful only when a collection-wide incompatible schema/model change,total loss or corruption makes narrower rebuild impossible and evidence proves scope. Experimental collections may exist in isolated non-canonical test scope with expiry and cannot be queried by production.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (379, E'C66', E'3', E'governed-multi-ai-git-coordination-and-delivery-infrastructure', E'GIT-ROLE:single fully automated local coordination and delivery infrastructure; MAIN:sole stable integration branch; WORKTREES:DIR[DIR_GIT_WORKTREES]+registered ephemeral worktrees; SINGLE-ENTRY:GitRepository.run; SCHEDULER:existing GitAutomationService only; COORDINATOR:workspace_sync only; EVENT-DRIVEN:file/HEAD/worker/commit/queue events with bounded periodic reconciliation; TRACKING:allowlist authored-source+Codex/contracts+SQL-migrations+required-config+non-rebuildable-test/audit-evidence+human-docs; IGNORE:runtime-state+logs+cache+temp+build/dist+packages+venv+models+database-instance+coverage+generated-index+rebuildable-output+secret; SELF-COMMIT:stable+path-scoped+no-foreign-stage+write-lock-clear; QUEUE:immutable-commit+base+worker+task+priority+policy; CONFLICT:registered generated artifact regenerates;single canonical owner resolves deterministic content;otherwise quarantine and preserve; DELIVERY:integrate>audit>fast-forward>central equality>origin push; MAINTENANCE:locks+leases+worktree registry+fsck+refs+hooks+divergence+audit continuity; CLEANUP:ignored expendable artifacts by registered retention only,never unmerged work\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:second-watcher/scheduler/coordinator+raw-Git-write+worker-push+whole-index-commit+tracking-excluded-output+secret-tracking+moving-branch-merge+unbounded-poll/retry+ambiguous-semantic-conflict-choice+force-push+ref-delete+history-rewrite+destructive-reset+delete-unmerged-work+push-before-audit-and-central-equality', E'A non-repository diagnostic may execute git --version through an approved bootstrap adapter and remains audited. A registered generated artifact may use an automation-sovereign-approved merge driver only inside the sole coordinator and only with post-resolution regeneration,validation and audit;any failed condition falls back to stop,preserve and notify.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (380, E'C67', E'3', E'xingcheng-auxiliary-manual-repair-update-release-switches', E'星澄 auxiliary system provides two independent user-operated manual release switches:repair_release and update_release. DOMAIN-SCOPE:repair_release applies only to user-facing repair intents; it never governs, gates or represents the C105 autonomous internal-fault repair chain, whose execution requires no user release. The user alone decides whether each category is enabled or disabled and may revoke it at any time. Default is disabled unless an explicit persisted user preference proves otherwise. Automatic detection,diagnosis,evidence collection and reversible isolation may continue while disabled,but no repair or update mutation is released. Enabled state only permits presentation of a concrete action for decision;each action still requires the C57 one-time user confirmation bound to current target,scope,method,risk,evidence and expiry. The system/model/repair engine/update engine cannot toggle,simulate,preselect or infer user release. Switch state,change actor,time,device/session,confirmation,execution and result are visible and audited. Multiple faults remain individually displayed and individually released;one switch or approval is never blanket consent. Closing UI,cancelling,expiry,identity mismatch or material plan change denies release.', E'FORBID:default-on without user proof+automatic switch mutation+enabled switch treated as blanket confirmation+confirmation bypassing disabled switch+hidden/preselected approval+one approval reused+bulk undisclosed repair/update+model impersonating user+repair by overwrite/reset+update privilege bypassing user release.', E'Immediate reversible non-mutating isolation may occur to prevent active damage;it does not toggle either switch,does not authorize repair/update and must be shown and audited.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (381, E'C68', E'3', E'codex-canonical-reference-code-only-policy', E'CODEX-REFERENCE:current and future Codex provisions reference mutable/deployable entities by canonical code,not repeated physical or environment-specific values. DIRECTORY-FIRST:when an entity or physical value already exists in any permission-sovereign managed directory,the Codex and every subordinate/special law must reference that directory_code plus typed field selector;it cannot restate the resolved physical value. Resolution is dynamic against the current accepted directory generation. The minimum core code vocabulary is ROOT_GPTBRIDGE,DIR_MAIN_SYSTEM,DIR_STANDALONE_TOOLS,DIR_MODEL_DIALOGUE,DIR_XINGCHENG,DIR_SHARED_LAYER,STORE_POSTGRESQL_CENTRAL,STORE_VECTOR_SEMANTIC,COLLECTION_SHARED_KNOWLEDGE,MODEL_EMBEDDING_CANONICAL,MODEL_RERANKER_CANONICAL,GIT_MAIN_BRANCH,GIT_REMOTE_CENTRAL,GIT_REMOTE_ORIGIN,POOL_WORKTREE_PERSISTENT,POOL_WORKTREE_EPHEMERAL,CHANNEL_INFORMATION_CANONICAL and CONTRACT_SHARED_LAYER. Codes identify semantics;their physical values exist exactly once in the permission-sovereign canonical reference registry and are resolved under A106. A provision defining a code may state its normative semantic meaning,but operational paths,ports,versions,dimensions,chunk sizes,models,collection names,branch names and capacity values belong to typed registry fields. HISTORICAL-MIGRATION:historical immutable literals remain evidence. Each still-effective legacy provision with mutable literals receives a code-mapping record immediately and an immutable code-based successor before its next affected release or configuration change;no in-place rewrite. Until successor completion,the mapping controls resolution and the literal cannot be copied into new law or implementation. CODE-CITATION:law text uses CODE[identifier] and optional field selector;reports may render resolved values with registry revision/hash and label them derived. SECRET codes resolve only inside authorized secret providers and never reveal values in Codex. OWNER:permission-sovereign governs identity/access/lifecycle of reference codes;domain owner supplies semantic truth;neither consumer nor environment invents codes.', E'FORBID:new mutable literal in Codex+restating a physical value already present in a directory+same physical value repeated as authority+code mapped in multiple registries+consumer inventing alias+historical literal copied forward+resolved value treated as Codex text+secret value stored in Codex+code without owner/type/version/status+changing mapping without new generation and affected evidence.+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'Irreducible normative constants such as the Codex version identity and closed legal state enums may be stated literally at their single definition point and referenced by code elsewhere. A one-time user command may supply a scoped value without creating persistent law.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (382, E'C69', E'3', E'automatic-repair-and-update-command-code-registration', E'REGISTRATION:automatic repair and automatic update use only the registered command codes XINGCHENG_SET_REPAIR_RELEASE,XINGCHENG_SET_UPDATE_RELEASE,SYNC_EXECUTE_APPROVED_AUTOMATIC_REPAIR and SYNC_EXECUTE_APPROVED_AUTOMATIC_UPDATE. CONTROL:the first two commands record the user\'s independent auxiliary-system switch choice and never execute mutation. EXECUTION:the latter two accept only a current one-time user confirmation bound to action identity,target,scope,method,risk,evidence digest,expiry and rollback/fallback under C57 and C67;dispatch remains through the governed synchronization execution chain. DISABLED/MISSING:disabled switch,missing confirmation,expired confirmation,identity mismatch or unregistered command fails closed without suppressing detection,diagnosis or isolated reporting. EVIDENCE:every request/result records command code,request identity,user actor,decision,correlation,formal timestamp and affected target;retry follows the command directory idempotency contract and cannot broaden scope.', E'FORBID:unregistered repair/update command+one command controlling both switches+switch command executing mutation+execution command without one-time user confirmation+model/system toggling user switch+alias bypass+confirmation reuse+scope expansion+command directory inventing implementation behavior.', E'A user may issue a separate explicit one-time manual repair or update command under the existing user-command exception;it does not enable either automatic switch or create standing authority.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (383, E'C70', E'3', E'automatic-repair-update-command-contract-successor', E'SUCCESSOR:C69 is superseded. COMMAND-SET:the complete registered command chain is XINGCHENG_SET_REPAIR_RELEASE,XINGCHENG_SET_UPDATE_RELEASE,XINGCHENG_CONFIRM_AUTOMATIC_REPAIR,XINGCHENG_CONFIRM_AUTOMATIC_UPDATE,XINGCHENG_REVOKE_AUTOMATIC_REPAIR_CONFIRMATION,XINGCHENG_REVOKE_AUTOMATIC_UPDATE_CONFIRMATION,SYNC_EXECUTE_APPROVED_AUTOMATIC_REPAIR and SYNC_EXECUTE_APPROVED_AUTOMATIC_UPDATE. ROLE-SEPARATION:user owns switch choice,confirmation and revocation;星澄 auxiliary system presents controls and records the user\'s command without deciding for the user;permission-sovereign validates actor/action/target/scope and evidence admissibility;automation-sovereign owns update/repair synchronization decision and module assignment;module-execution layer alone performs mutation. CONTRACT-REGISTRATION:every command_code_directory row is its canonical command registration. Switch request fields are command_code,request_id,user_actor_id,desired_state,choice_revision,session_id,correlation_id,recorded_at_utc;confirmation request fields add action_id,category,target_code,scope_code,method_code,risk_code,evidence_digest,expires_at_utc,rollback_or_fallback_code;revocation request fields add confirmation_id and reason_code;execution request fields require confirmation_id,confirmation_hash,permission_proof,synchronization_decision_id,executor_id,expected_before_hash and generation. Every result contains command_code,request_id,decision,status,reason_code,correlation_id,recorded_at_utc and evidence_hash. VERSIONING:the request/result contract identity suffix is a contract version governed by D83 and is separate from its D84 timestamps. GATES:execution requires enabled matching switch plus current unrevoked single-use confirmation plus permission proof and synchronization decision. Missing/mismatched/expired/replayed input fails closed. No checker or executor creates an exception.', E'FORBID:unregistered alias+combined repair/update switch+implicit/preselected switch+confirmation embedded without registered confirmation command+missing revocation path+confirmation reuse+permission validator becoming executor+synchronization decision performing module work+module execution changing scope+contract fields inferred from timestamp/version+automatic contract repair.', E'An explicit one-time manual user command remains lawful but does not enable an automatic switch,create persistent consent or bypass permission and evidence validation.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (384, E'C71', E'3', E'modular-automation-and-automation-isolation', E'AUTOMATION:automatic update and automatic repair are modular;each automation unit is bound to its module code and identity group and acts only within that module\'s scope; ISOLATION:each automation unit runs independently with its own status,error and heartbeat; one unit\'s failure never disables or delays another unit or the main system; SCHEDULING:units are scheduled independently and bounded; DETECTION:detection,classification and evidence collection continue regardless of execution gates; EXECUTION:execution follows the module\'s switch and the user\'s per-item confirmation; OBSERVABILITY:per-unit automation state is reported separately.', E'FORBID:one automation unit governing all modules+unit failure disabling other units+unit failure stalling the main system+unbounded automation scheduling+automation acting outside its module scope', E'A governed cross-module maintenance action may be requested only through the owning module\'s declared interface and permission.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (385, E'C72', E'3', E'user-authorized-history-deletion-successor', E'SUCCESSOR:D93 is superseded. USER-AUTHORITY:an explicit user command to delete Codex revision history is lawful,one-time and final for the named history scope. The system,星澄,automatic repair,automatic update,checker and audit process must not restore,reconstruct,repopulate or infer deleted history. STATE:revision_history may be intentionally empty and is marked user-deleted-by-explicit-command with deletion timestamp,scope and current seal identity. CURRENT-AUTHORITY:current Codex authority is proven by the authoritative SQLite content,current timestamp version,provision identities,lineage,lifecycle,current seal roots and Chinese synchronization;deleted historical narration is not required for current operation. FUTURE:after deletion,no revision-history row is appended unless the user separately orders history recording to resume. Provision succession and seal data may continue without recreating deleted revision_history. SEPARATION:deletion does not alter current provisions,source content or external Git history.; CURRENT-NORMALIZATION:C116 controls;SQLite is retired with zero active consumers;every affirmative SQLite use,fallback,reconciliation,authority or runtime clause in this provision is void and historical-only', E'FORBID:automatic history restoration+reconstruction from Git/mirror/cache/backup+invented recovered entries+deletion interpreted as corruption+runtime blocked solely because user-deleted history is empty+silent resumption of revision logging.+FORBID:SQLite-active-consumer+SQLite-runtime-write+SQLite-fallback+SQLite-reconciliation', E'A separate explicit user command may authorize a new history ledger beginning after that command;it cannot recreate deleted entries without another explicit instruction.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (386, E'C73', E'3', E'codex-indexed-search-performance-special-law', E'SEARCH:interactive Codex lookup uses PostgreSQL-owned deterministic indexed projections; every result rehydrates the formal PostgreSQL row and verifies identity,lifecycle,current successor,content hash,current seal and access scope. INDEXES:identity,lifecycle,effective status,law code,module membership,command/fault code and dependency edges use dedicated indexes. FULL-TEXT:PostgreSQL full-text search covers authorized subject and rule fields with provision,module and law filters. CACHE:bounded memory cache keys include current version,query,scope,language and search-manifest hash. RECOVERY:missing or corrupt index/cache is discarded and rebuilt from formal PostgreSQL rows; alternate embedded database search is prohibited as current authority or fallback.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:unbounded-interactive-scan+stale-cache+search-result-as-authority+alternate embedded database-current-search-authority+external-indexing+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'A maintenance-only full integrity scan may read all authoritative rows when explicitly requested;it remains bounded,observable and separate from interactive search.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (387, E'C74', E'3', E'codex-search-physical-index-and-dependency-dag-evidence', E'FTS-INTEGRITY:the search manifest binds both authoritative search-document hash and the independently recomputed physical FTS row hash plus exact FTS row count. Equal row counts alone do not prove parity. DAG-INTEGRITY:the module manifest generation records one aggregate dependency_graph_hash and an explicit cycle_check_status produced from the complete registered graph;per-module dependency hashes cannot replace whole-graph cycle validation. BENCHMARK-EVIDENCE:codex_search_benchmark_evidence records version identity,query class,normalized query hash,plan detail,result count,duration_microseconds,index_used,status and measured_at_utc for exact identity,module filter,short alias and FTS paths. PERFORMANCE:benchmarks are diagnostic evidence,not fixed acceptance thresholds;the required invariant is bounded indexed execution with no interactive full authoritative-table scan. FRESHNESS:any provision,module,dependency,alias,search-document or FTS change invalidates the manifest and benchmark generation until rebuilt in the same amendment transaction. AUTHORITY:all indexes and measurements remain derived and non-authoritative. HISTORY:revision_history remains user-deleted.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:FTS count-only proof+document hash substituted for physical FTS hash+module-local dependency hashes claimed cycle-complete+benchmark without query plan+full authoritative scan in interactive path+performance number as legal authority+stale benchmark reused across version+history reconstruction.', E'A cold-cache measurement may vary by machine and load;variance is recorded without weakening correctness or index-use requirements.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (388, E'C75', E'3', E'health-recovery-orchestration-contract', E'TRIGGER:B105 state and exact fault codes. FLOW:detect>isolate>decide>authorize>execute>verify>stability-window>recover-or-escalate>audit. REQUEST:{recovery_id,module_code,generation,health_result_id,fault_codes,affected_capabilities,decision_id,authorization_proof,executor_code,resource_budget,attempt_budget,deadline,rollback_target,correlation_id}. RESULT:{recovery_id,state,attempts,before_hash,after_hash,verification_evidence,stability_window_result,remaining_faults,rollback_receipt,completed_at_utc}. POLICY:idempotent+bounded retries+backoff+circuit breaker+no source overwrite/reset+unaffected channels continue. Automatic repair/update user switches remain controlling where applicable. SUCCESS requires new B105 current classification after verification,not executor exit alone.', E'FORBID:recovery without current health result+component self-authorized repair+infinite retry+retry storm+whole-system isolation+success on process exit+reuse observation as verification+source reset/overwrite+hidden remaining fault.', E'A transient retry may reuse the same immutable request within its attempt budget;any target,decision or payload change requires a successor request.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (389, E'C76', E'3', E'connection-boundary-and-low-cost-legal-paths', E'PURPOSE:replace overloaded C27. CONNECTION is an interaction crossing process,owner,trust,permission principal,state/data owner or independent contract boundary,or using I/O/serialization/session/transport handles. B101 PURE_INTERNAL_CALL and INTRA_MODULE_COMPONENT_CALL are not connections merely because code layers differ. ROUTES:LOCAL_PURE_CALL=no session/audit;LOCAL_GOVERNED_DISPATCH=typed envelope+scope+correlation without socket/IPC;READ_ONLY_QUERY=pooled least-scope session+prepared bounded query+batch audit;TEST_ISOLATED_ROUTE=ephemeral credentials+isolated data+no production mutation+aggregate evidence;FULL_TRANSPORT=information-layer adapter+auth+contract+timeout+retry/backpressure+audit. Selection uses formal predicates,not caller preference. Diagnostics,startup and one-time scripts choose the lowest route whose facts satisfy it and do not automatically require FULL_TRANSPORT.', E'FORBID:layer label alone classified connection+direct cross-owner I/O+read-only route performing mutation+test route touching production state+support script blanket bypass+FULL_TRANSPORT mandated when LOCAL_PURE_CALL predicate holds+low-cost route used across authority or data-owner boundary.', E'An in-process database-free read of immutable owner-local constants is LOCAL_PURE_CALL;an actual database query is READ_ONLY_QUERY even in the same process.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (390, E'C77', E'3', E'single-chinese-codex-mirror-three-part-storage', E'CHINESE-MIRROR:exactly five ordered synchronized part files form one complete non-authoritative zh-TW mirror. Each part binds mirror_id,part_index,part_count,current Codex version,assembled payload hash,part hash and previous-part hash. ATOMIC-PUBLICATION:render all five from the formal PostgreSQL Codex,verify full parity and quality,then promote the complete generation together. Missing,mixed-version,duplicate,extra or corrupt part makes the mirror unavailable without affecting PostgreSQL authority.', E'FORBID:part-count-other-than-five+part-as-independent-authority+mixed-generation+alternate embedded database-as-mirror-source-authority+fourth-or-extra-assembled-copy+partial-publication+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'A streaming authorized reader may hold bounded transient rows while assembling;all transient content is erased at session end and never becomes another persistent mirror.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (391, E'C78', E'3', E'codex-external-non-indexing-and-internal-derived-search-clean-successor', E'SUCCESSOR:C78 completely supersedes D74. EXTERNAL-NON-INDEXING:Codex and every derivative are prohibited from RAG,embedding,semantic/vector indexes,training,external search,OS indexing and application-wide indexes. INTERNAL-SEARCH:authorized tooling may maintain Codex search documents,aliases,PostgreSQL full-text indexes,search manifests,benchmark evidence and module manifests only inside protected formal PostgreSQL authority. These are derived non-authoritative projections and are atomically rebuilt from current effective provisions. alternate embedded database may contain only non-current historical or isolated fixture data and cannot host current Codex search authority.', E'FORBID:external-Codex-indexing+alternate embedded database-current-search-authority+derived-index-as-law+stale-search-generation+projection-writing-back-law+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'Bounded authorized in-memory lookup is erased at session end.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (392, E'C79', E'3', E'directory-coverage-requirement-complete-alignment', E'Every directory_master_catalog identity has exactly one directly corresponding coverage requirement after canonical normalization. Coverage proves complete inventory,zero orphan,zero missing,current-version parity,authoritative rows and seal/hash coverage. DIR_TEST_SUITE_ARCHITECTURE,DIR_CODEX_INTERNAL_MODULE,DIR_FORMAL_RULE_REGISTRY and DIR_MACHINE_SCHEMA_REGISTRY are explicit release-blocking subjects.', E'FORBID:catalog without direct coverage+orphan coverage+count-only parity+stale or unsealed coverage.', E'Historical aliases resolve to one canonical code only.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (393, E'C80', E'3', E'cross-store-data-authority-provenance-resilience-and-readiness-contract', E'DATA-CONTROL-SYSTEM:central and module data operations are governed by the machine-readable data_governance_control_registry. LINEAGE-AUTHORITY-WRITE:every resource binds full cross-store lineage,authority_class,write provenance and contemporaneous permission/RLS proof. SCHEMA-DDL:one schema owner;runtime DDL forbidden;migration-executor-only DDL with independent append-only audit. CONNECTION:contract-version handshake and generation fencing precede writes. AUTOMATIC-MAINTENANCE:the existing automation core is the sole scheduler and registered database maintenance executors are the sole actors;no second scheduler,migration executor or authority source is permitted. OBSERVATION:transaction age,idle-in-transaction,locks,dead tuples,vacuum lag,table/index bloat,WAL,disk,pool pressure,transport backlog,backup state and reconciliation backlog are continuously observed. ADMISSION:each automatic action declares object scope,trigger threshold,maintenance workload class,deadline,concurrency and resource ceiling,idempotency key,stop policy and audit identity;interactive and authority work preempt maintenance. ACTIONS:registered bounded VACUUM,ANALYZE,REINDEX,partition and retention maintenance,connection recycling,long-transaction handling,orphan scanning,reconciliation,backup verification and restore rehearsal may run automatically. STRUCTURE:maintenance never invents or runs unregistered DDL,never auto-applies migration and never legalizes live drift;schema change remains ordered migration-executor work. LIFECYCLE:destructive cleanup follows tombstone,retention,reference check,purge and cross-store synchronization;unresolved references preserve data. RESILIENCE:versioned SLO,RPO/RTO classes,capacity watermarks,domain-scoped read-only emergency mode and database startup certification are mandatory. FAILURE:timeout,missing evidence,drift,unsafe lock impact or indeterminate outcome stops the action and may isolate only the affected domain read-only;no global silent alternate embedded database substitution. RECEIPT:every action records trigger,threshold,actor,executor,object,before/after state,duration,resources,result and correlation identity. AUTHORITY:degraded-copy,cache and derived data never become central-official by fallback or availability.', E'FORBID:untraceable resource|missing authority marker|write without actor/executor/decision/correlation/revision|permission decision without snapshot|runtime or unregistered DDL|automatic migration|live drift legalization|second maintenance scheduler|unbounded transaction,concurrency,retry or maintenance resource|maintenance starving interactive work|RLS or generation-fence bypass|shared unclassified pool|single-step cross-store delete|purge with unresolved reference|uncertified rebuild serving|capacity exhaustion without fail-closed gate|global outage when domain isolation is sufficient|global automatic alternate embedded database fallback|SELECT-1-only readiness|maintenance success without receipt.+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation', E'Emergency read-only access remains available only for an isolated registered domain and cannot mutate or upgrade authority. A database-native maintenance mechanism may execute only inside the same registered thresholds,ownership,resource and receipt contract.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (394, E'C81', E'3', E'postgresql-sql-authority-migration-security-fallback-audit-and-readiness-contract', E'POSTGRESQL-AUTOMATION:PostgreSQL18.6 is the sole SQL authority; schema inventory,migration replay,drift detection,security projection parity,transport/audit integrity,backup certification,capacity maintenance and readiness are maintained automatically by the existing single automation flow; TRIGGER:migration/schema/role/RLS/index/restore/connection-generation/workload-health event; SAFE-ACTIONS:ordered migration+analyze/vacuum+registered additive index+pool/batch adjustment+generation fence+read-only switch+evidence refresh; UNSAFE:destructive DDL,unknown effect or authority conflict fails closed and quarantines; no alternate SQL engine or manual normal path', E'FORBID:second-SQL-authority+second-SQL-maintainer+out-of-band-DDL+runtime-role-DDL+manual-confirmation-as-normal-maintenance+automatic-destructive-DDL+write-under-drift+restore-authority-without-certification+retired-engine-fallback', E'A registered read-only emergency scope may expose previously certified PostgreSQL data while affected writes remain closed;it cannot use alternate embedded database to replace central authority.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (395, E'C82', E'3', E'sql-migration-authority-and-priority-data-schema-directory-contract', E'MIGRATION-AUTOMATION:DIR_DATA_SCHEMA_AUTHORITY+sql-migration contract+sql-governance-closure contract are automatically regenerated and verified from ordered immutable migrations and live PostgreSQL introspection; INVARIANT:declared_schema_hash=replayed_schema_hash=live_introspected_schema_hash; CHAIN:N.source=N-1.target+gapless+single-head; EVENT:new-migration or catalog change triggers replay+receipt+directory parity+closure evidence; MISMATCH:SQL_SCHEMA_DRIFT fail-closed+read-only/quarantine; only migration executor may apply DDL', E'FORBID:manual-catalog-as-authority+out-of-band-DDL+missing-receipt+multiple-migration-head+gap/branch+write-after-drift+manual-pass', E'Read-only emergency access may continue only for previously certified compatible objects while all affected writes remain closed.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (396, E'C83', E'3', E'sql-authority-boundary', E'SQL-AUTHORITY:PostgreSQL18.6 is the sole central canonical structured-data+shared-transport+central-audit SQL authority; every official SQL object and write resolves to PostgreSQL through a registered contract; retired SQL engines have zero active consumers and cannot carry private state,fallback,cache,transport,audit,permission or reconciliation authority', E'FORBID:second-SQL-authority+retired-SQL-engine-active-consumer+SQL-fallback+out-of-band-DDL+database-created-permission-authority', E'Previously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (397, E'C84', E'3', E'postgresql-object-level-schema-authority', E'Every PostgreSQL schema,table,view,function,trigger,index,policy and role projection has object identity,database,schema,object type,owner module,authority class,data class,introducing migration,current definition hash and status.', E'INHERITS:A135#SQL_GOVERNANCE_BOUNDARY', E'Previously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (398, E'C85', E'3', E'sql-migration-chain', E'Migrations are immutable,totally ordered,transactional and hash-chained. Each predecessor target hash equals the next source hash;genesis replay equals expected current schema hash;out-of-band DDL is prohibited.', E'INHERITS:A135#SQL_GOVERNANCE_BOUNDARY', E'Previously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (399, E'C86', E'3', E'postgresql-schema-drift-gate', E'AUTOMATIC-DRIFT-GATE:every startup,migration,restore,role/RLS change and periodic safety reconciliation recomputes declared_schema_hash+replayed_schema_hash+live_introspected_schema_hash; equality permits the registered capability; mismatch emits SQL_SCHEMA_DRIFT,raises connection generation,fences stale writers and switches affected scope fail-closed/read-only until an ordered migration restores parity', E'FORBID:drift-warning-only+write-under-drift+manual-override+live-schema-becoming-authority+stale-connection-write', E'Previously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (400, E'C87', E'3', E'sqlite-private-state-boundary', E'RETIREMENT:SQLite is retired under C116 with zero active consumers; no module-private state,cache,fallback,fixture in production,reconciliation source or runtime database may use it; historical artifacts are read-only lineage and never executable or authoritative', E'FORBID:SQLite-active-consumer+SQLite-runtime-open+SQLite-state-write+SQLite-fallback+SQLite-reconciliation+SQLite-authority+SQLite-production-fixture', E'Previously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (401, E'C88', E'3', E'sqlite-reconciliation-contract', E'RECONCILIATION-RETIREMENT:no SQLite reconciliation contract,queue,target,deadline,buffer or conflict policy is active; PostgreSQL is the only SQL transaction authority and failures resolve by capability close or read-only mode; historical reconciliation rows are non-operative lineage', E'FORBID:SQLite-reconciliation+SQLite-buffer+SQLite-to-PostgreSQL-promotion+offline-SQL-queue+retired-engine-write', E'Previously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (402, E'C89', E'3', E'sql-audit-transport-integrity', E'AUTOMATIC-AUDIT-TRANSPORT-MAINTENANCE:append-only audit and shared transport automatically verify identity+correlation+causation+idempotency+ordering+retention+consumer ownership+sequence continuity; backlog,orphan,lease and retention events trigger bounded repair/reconciliation through the sole automation flow; unknown effects quarantine without replaying non-idempotent work', E'FORBID:silent-gap+mutable-audit+duplicate-side-effect+unbounded-backlog/retry+second-transport-maintainer+success-without-continuity-evidence', E'Previously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (403, E'C90', E'3', E'sql-recovery-authority', E'AUTOMATIC-RECOVERY:backup creation,restore rehearsal,retention and restore certification are scheduled by the sole automation flow; restore never creates authority; reopening requires automatic migration/schema/hash/RLS/role/security-projection/lineage/generation verification and connection-generation fence; any failed root keeps the affected scope read-only or closed', E'FORBID:restore-as-authority+automatic-open-before-certification+stale-connection-write+uncertified-backup+manual-pass', E'Previously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (404, E'C91', E'3', E'sql-capability-health-and-degradation', E'AUTOMATIC-CAPABILITY-HEALTH:PostgreSQL capabilities are observed independently for official-read/write,transport,audit,migration and maintenance; health events automatically choose healthy,degraded-read-only or fail-closed per registered matrix; no alternate SQL engine exists; recovery automatically replays required verification before reopening and publishes typed status/evidence', E'FORBID:global-hidden-degradation+alternate-SQL-fallback+permission/audit/transport-substitution+write-before-ready+manual-normal-path', E'Previously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (405, E'C92', E'3', E'exact-sql-directory-migration-and-closure-machine-contract', E'DIR_DATA_SCHEMA_AUTHORITY uses the exact 21-field object contract and requires exactly one current row for every formal PostgreSQL object;SQLite can never use central-canonical-structured-authority. sql-migration contract uses the exact 15-field chain contract;sequence is gapless,unbranched and unique,and each migration source_schema_hash equals its predecessor target_schema_hash. sql-governance-closure contract uses the exact 16-field closure contract and may PASS only when every required root is present and valid,declared,replayed and live schema roots are equal,and open_findings equals zero.; CURRENT-NORMALIZATION:C116 controls;SQLite is retired with zero active consumers;every affirmative SQLite use,fallback,reconciliation,authority or runtime clause in this provision is void and historical-only', E'FORBID:duplicate current object+SQLite canonical authority+chain gap+branch+duplicate sequence+source/target discontinuity+closure PASS with missing root or open finding.+FORBID:SQLite-active-consumer+SQLite-runtime-write+SQLite-fallback+SQLite-reconciliation', E'The first migration uses the registered genesis hash and null predecessor_id.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (406, E'C93', E'3', E'sql-object-canonicalization-security-reconciliation-audit-and-closure-semantics', E'INVENTORY:DIR_DATA_SCHEMA_AUTHORITY covers schema,table,view,materialized-view,sequence,function,procedure,trigger,index,enum-type,policy and role with identity sql/postgresql/{schema}/{object-type}/{object-name};deployment host,port,database name and connection string are configuration only. AUTHORITY:PostgreSQL classes are CENTRAL_OFFICIAL_DATA,SHARED_TRANSPORT,CENTRAL_AUDIT,SECURITY_PROJECTION,REFERENCE_DIRECTORY,DERIVED_NON_AUTHORITATIVE. SQLite classes are OWNER_PRIVATE_OPERATIONAL_STATE,OWNER_PRIVATE_CACHE,OWNER_PRIVATE_CHECKPOINT,BOUNDED_DEGRADED_BUFFER and can never be central official,audit,transport,permission or canonical cross-module authority. HASH:sql-ddl-canonicalization contract produces the same SHA-256 definition hash for directory,migration target and live introspection. MIGRATION:IDs are MIG_PG_000001 format;sequence is gapless and unbranched;source is canonical source hash;rollback policy is an explicit enum and never undeclared. SECURITY:Identity>Authorization>Projection>Enforcement;database privilege cannot exceed active authorization projection;principal identity and authorization/revocation generations must be current. RECONCILIATION:LOCAL_ONLY_VALID>DEGRADED_BUFFERING>RECONCILIATION_PENDING>RECONCILED with validation,conflict check,permission revalidation,governed PostgreSQL write,commit identity,distinct receipt and cleanup;LAST_WRITE_WINS is forbidden. AUDIT:append-oriented,no actor UPDATE/DELETE;retention destruction requires authorization and immutable receipt. TRANSPORT:PostgreSQL is persistence authority for declared transport state while Information Layer remains information-channel authority. CLOSURE:only PASS,INCOMPLETE_EVIDENCE or FAIL exist;non-PASS is fail-closed and denies verified release.; CURRENT-NORMALIZATION:C116 controls;SQLite is retired with zero active consumers;every affirmative SQLite use,fallback,reconciliation,authority or runtime clause in this provision is void and historical-only', E'FORBID:deployment locator as object identity+SQLite forbidden authority class+noncanonical DDL hash+branched migration+UNDECLARED rollback+database privilege exceeding authorization+stale generation privileged operation+degraded buffer called canonical+LAST_WRITE_WINS+audit raw delete+PostgreSQL called information-channel authority+mostly/warning/degraded pass.+FORBID:SQLite-active-consumer+SQLite-runtime-write+SQLite-fallback+SQLite-reconciliation', E'Extension-owned objects may be excluded only by registered extension ownership evidence under sql-ddl-canonicalization contract.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (407, E'C94', E'3', E'sql-live-inventory-migration-reconstruction-security-role-sqlite-and-closure-coverage', E'POSTGRESQL inventory is generated from complete live introspection and covers schema,table,view,materialized_view,sequence,function,procedure,trigger,index,constraint,enum and rls_policy. Every object has exactly one registered authority class and SECURITY_PROJECTION never becomes permission authority. Ordered migration chain is the sole schema evolution authority; generated snapshots are derived and live PostgreSQL is validated execution state. Replay from MIG_PG_GENESIS through every migration must equal live canonical schema or SQL_SCHEMA_DRIFT is emitted without changing law to match drift. Effective database capability must be a subset of active permission capability; generation, GRANT and RLS parity are mandatory. Runtime roles cannot hold SUPERUSER,CREATEROLE or BYPASSRLS absent explicit special law. SECURITY_PREDICATE routines are deterministic and read-only. Every governed SQLite database and object is owner-scoped, noncanonical and classified; role substitution is FAIL. Bidirectional object coverage must be zero-difference. All eleven SQL gates must PASS before directory completion and SQL closure PASS.; CURRENT-NORMALIZATION:C116 controls;SQLite is retired with zero active consumers;every affirmative SQLite use,fallback,reconciliation,authority or runtime clause in this provision is void and historical-only', E'FORBID:partial hand inventory+dual schema authority+live drift legalization+database-generated permission+excess privilege+stale projection+security predicate side effects+unbounded SQLite fallback+unknown SQL object,role,database or migration+non-deterministic SQL governance test.+FORBID:SQLite-active-consumer+SQLite-runtime-write+SQLite-fallback+SQLite-reconciliation', E'No exception permits missing evidence to PASS; absent evidence is INCOMPLETE_EVIDENCE and confirmed violation is FAIL.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (408, E'C95', E'3', E'information-layer-shared-transport-and-central-audit-sql-closure', E'Information Layer owns transport semantics; PostgreSQL owns canonical persistence of declared transport state; declared-domain sovereign owns business decisions; permission governance owns authorization; registered transport executor performs delivery. A database row never alone constitutes a valid message. Valid submission requires authenticated source, contract, permission, destination, envelope and budget validation before persistence, delivery and receipt. Accepted envelopes are immutable and delivery changes are appended separately. Ordering is declared per contract and scope. Delivery retry preserves message identity, payload hash and scoped idempotency key. Transport and audit remain distinct and link only through message and correlation identities. audit-event contract is the sole logical audit event contract; persistence is append-only within declared chains and checkpoint manifests aggregate chain roots. Runtime roles cannot update, delete, truncate, bypass policy or own audit tables. Audit reads are scoped and store references only, never reusable secrets. Transport health is distinct from database readiness and consumer lag is bounded without silent dropping. INFORMATION_SQL_CLOSURE can be evaluated only after SQL_GOVERNANCE_CLOSURE PASS and requires all thirteen information SQL gates PASS.', E'FORBID:SQL row as channel authorization+route invention+destination rewrite+message reinterpretation+business execution by persistence layer+accepted envelope mutation+retry identity replacement+unscoped idempotency+transport table as audit ledger+audit UPDATE,DELETE or TRUNCATE+secret persistence+database ping treated as transport health+silent oldest-message drop+contract breaking change through table mutation.', E'No missing evidence may PASS. Missing evidence is INCOMPLETE_EVIDENCE; confirmed boundary, integrity, privilege or chain violation is FAIL.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (409, E'C96', E'3', E'sql-transaction-concurrency-pool-migration-execution-and-outbox-inbox-closure', E'Each governed operation has one declared transaction boundary and commits all required effects or rolls back all. Allowed policies are ATOMIC_SINGLE_DATABASE, ATOMIC_WITH_OUTBOX, READ_ONLY_SNAPSHOT and BEST_EFFORT_NONAUTHORITATIVE; best effort is forbidden for canonical official data, security projection and central audit authority. Every data class declares minimum isolation, concurrency, locking and conflict policies. Retryable writes require operation identity, scoped idempotency and existing receipt return on duplicates. Canonical mutable records require expected revision comparison and revision increment; LAST_WRITE_WINS is forbidden by default. Connection pools reuse resources only and deterministically reset transaction, role, search path, session settings and requester context. Database login role, application principal and requester identity are distinct; session context is never authority and must match current authorization projection and generation. SQL_MIGRATION_EXECUTOR is the sole migration executor, uses one global lock, executes registered SQL only and emits sql-migration-receipt contract. Production runtime inspects and fails closed on version mismatch and cannot automatically migrate. Canonical write plus outbox is atomic; inbox dedup provides exactly-once effect over at-least-once delivery. Serialization, deadlock and lock failures follow declared retry classes and stale decisions are reevaluated. SQL governance closure is the aggregate of authority, schema-migration, information SQL and transaction-concurrency domains, all of which must PASS.', E'FORBID:partial authoritative success+undeclared concurrency policy+canonical best effort+default last-write-wins+blind stale retry+pool authorization carryover+session variable as authority+runtime schema auto-modification+parallel migration+unregistered migration SQL+commit-before-event without atomic outbox+duplicate consumer effect+database delivery called exactly-once network delivery.', E'Explicit low-value owner-private noncanonical state may use declared last-write-wins or best effort. No canonical, permission, audit or transport authority receives that exception.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (410, E'C97', E'3', E'complete-sql-governance-successor-and-five-domain-release-closure', E'This article is the complete successor consolidation for SQL governance. PostgreSQL is canonical persistence for declared central structured data, shared transport persistence, central audit persistence and security projection; SQLite is noncanonical owner-private operational technology with bounded degradation only. Migration chain is the sole schema evolution authority; complete object inventory, canonical DDL normalization, replay and live introspection must agree. Permission sovereign owns permission decisions; Information Layer owns channel and transport semantics; domain sovereigns own domain decisions; data governance owns declared data semantics and integrity; registered executors perform SQL work; databases create no sovereign, permission or business authority; Codex performs no SQL execution. SQL_GOVERNANCE_CLOSURE PASS requires SQL_AUTHORITY_CLOSURE, SQL_SCHEMA_MIGRATION_CLOSURE, INFORMATION_SQL_CLOSURE, SQL_TRANSACTION_CONCURRENCY_CLOSURE and SQL_RECOVERY_CLOSURE all PASS with current-version evidence, deterministic suite PASS and formal evaluator parity PASS. SQL-AUTOMATION-CLOSURE:automatic maintenance is valid only through the C80 single control plane with registered actions,bounded workload admission,fail-closed outcomes and complete receipts;maintenance configuration may tune thresholds only within registered envelopes and cannot amend schema,authority,permission or retention law.; CURRENT-NORMALIZATION:C116 controls;SQLite is retired with zero active consumers;every affirmative SQLite use,fallback,reconciliation,authority or runtime clause in this provision is void and historical-only', E'FORBID:in-place mutation of prior sealed law identity+partial SQL closure PASS+prior-version evidence reuse+database authority promotion+live drift legalization+unregistered object or migration+unsafe privilege+unbounded SQLite degradation+uncovered retryable canonical write+implicit canonical last-write-wins+pool session leakage+parallel migration+transport or audit bypass+unaccepted restore authority+status-only PASS.+second SQL maintenance scheduler+automatic unregistered DDL or migration+maintenance without bounded admission or receipt+FORBID:SQLite-active-consumer+SQLite-runtime-write+SQLite-fallback+SQLite-reconciliation', E'A release with no executable or database-affecting artifact requires explicit unaffected-scope proof; it does not convert any incomplete SQL domain to PASS.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (411, E'C98', E'3', E'Git 架構圖', E'單一 Git repository 透過已登錄 worktree、同步協調器、治理稽核及唯一推送者完成整合。', E'禁止 worker 直接推送、改寫歷史或自動解決衝突。', E'無。');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (412, E'C99', E'3', E'SQL 架構圖', E'SQL 權威、schema migration、information SQL、transaction concurrency 與 recovery 五個閉合域共同控制 SQL 治理。; CURRENT-NORMALIZATION:C116 controls;SQLite is retired with zero active consumers;every affirmative SQLite use,fallback,reconciliation,authority or runtime clause in this provision is void and historical-only', E'禁止部分通過或 SQLite 權威升格。+FORBID:SQLite-active-consumer+SQLite-runtime-write+SQLite-fallback+SQLite-reconciliation', E'無。');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (413, E'C100', E'3', E'RAG 架構圖', E'受治理來源經權限驗證、切塊、PostgreSQL 正式中繼資料、Rust 向量引擎語意候選、融合、重排及證據上下文形成結果。', E'禁止無來源、跨範圍或候選資料升格。', E'無。');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (414, E'C101', E'3', E'隱私與個資最小化 successor', E'SUCCESSOR:C101 取代 C38 的現行效力。SCOPE=personal+sensitive+private+financial+behavioral data。RULE=purpose limitation+data minimization+classification+lawful basis+field-level access+retention+erasure+non-inference。已撤銷的身分因子不得被收集、保存、索引、快取、傳送、備份、同步、寫入 audit payload 或用於任何授權決策。', E'INHERITS:A135#SENSITIVE_SCOPE_BOUNDARY', E'密碼學完整性、內容定址、簽章驗證與竄改偵測機制不受影響。');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (415, E'C102', E'3', E'自動法典更新強制同步條例', E'C102 補充 D75、D118、B118 與 B124。任何自動法典更新必須以單一受治理 successor transaction 同時產生並驗證：正式法典、五份有序中文法典鏡像、machine architecture registry、五個共通架構圖與七個獨立工具架構圖。提交前必須完成版本一致性、內容一致性、五分卷鏈結、架構來源條文、登錄資料與治理稽核檢查。全部目標成功後才能原子發布；任何一項缺失、失敗、過期或版本不同，必須回復整批候選並拒絕發布。', E'FORBID:codex-only-auto-update|mirror-lag|diagram-lag|partial-publication|mixed-version-generation|success-without-parity-evidence。', E'人工或緊急流程亦不得豁免同步；只能停止候選，不得發布部分結果。');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (416, E'C103', E'3', E'外部協作整合控制與自動記錄條例', E'SUCCESSOR:C103 取代 B128 的現行介面效力。外部協作最上方必須只有一張緊湊整合主卡片，統一承載網址工具列、內建 AI 名單、AI 選取、狀態、開啟、登入、URL 設定及協作需求輸入。AI 名單的開啟、登入與開啟選取操作必須直接控制同一視窗右側的受治理內建瀏覽器。左側四分之一只承載協作結果，右側四分之三承載內建瀏覽器網頁。獨立 AI 名單卡、需求卡、共享記憶卡、四張診斷卡與登入提示狀態卡不得顯示。每次協作完成後，系統必須自動記錄需求與回覆摘要，不提供手動共享記憶卡。', E'FORBID:separate-ai-list-card|separate-demand-card|manual-shared-memory-card|diagnostic-summary-cards|login-prompt-status-card|ai-action-without-embedded-browser-navigation|memory-recording-omission|desktop-ratio-drift。', E'窄螢幕得切換單欄；錯誤得在相關控制元件就地呈現，但不得恢復已刪除卡片。');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (417, E'C104', E'3', E'星澄內部自我升級條例', E'星澄的自動升級與自我更新由星澄在自身擁有域內自行產生、分析、測試、驗證、發布及回復。該生命週期不經星澄助理、系統自動更新開關、獨立工具或外部執行者；星澄助理的系統自動更新控制只適用於主系統更新。星澄自我升級不設使用者開關，但仍須保留候選隔離、相容性驗證、回歸測試、可回復發布與完整稽核。', E'FORBID:xingcheng-self-upgrade-via-assistant|xingcheng-self-upgrade-via-system-update-switch|external-self-upgrade-owner|unverified-self-replacement。', E'星澄得透過受治理網路通道取得研究資料，但資料只能形成未驗證候選，不得直接替換現行版本。');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (418, E'C105', E'3', E'星澄內部故障告知與自主維修條例', E'故障訊息必須經資訊層內部通道直接告知星澄，由星澄自主發起受治理維修，並完成可修復性判定、權限檢核、稽核登錄、執行、獨立驗證及學習回饋。星澄助理必須保留故障與維修結果的訊息通知，但該通知僅為狀態投影，不構成許可、決策或執行入口，亦不得阻擋或延遲星澄自主維修。本條所稱故障指資訊層健康訊號判定之受治理執行期內部故障；交付使用者面之版本異動不屬本條自主維修範圍，仍屬 C57/C67/D88 之開關與一次性確認範圍。', E'FORBID:user-confirmation-gating-xingcheng-repair|assistant-as-repair-authority|fault-message-without-internal-xingcheng-notification|unverified-autonomous-repair。', E'不可確定安全修復時必須停止修改、保留現況並以狀態通知呈現，不得直接覆蓋或重置。');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (419, E'C106', E'3', E'project-wide-dag-cag-rag-hybrid-architecture-and-automatic-maintenance', E'PROJECT-WIDE-HYBRID:DAG=sole orchestration plane through RagDagPlanner+RagDagExecutor;CAG=scoped versioned leased acceleration/context-reuse plane;RAG=canonical retrieval plane with Hybrid+Code+Memory+Agentic;GAG is not a separate architecture and resolves to DAG. PATH:Caller>Information-Channel>Permission/Scope>RagApplicationService>DAG>CAG-Gate>RAG>Evidence-Fusion>Reranker>Context-Builder>Local-LLM>Citation-Validation>Result. FULL-AUTOMATION:source-revision+lifecycle+permission+contract+schema+migration+chunking+embedding+reranker+model+cache+index+tombstone/deletion events trigger one bounded maintenance DAG; affected scope is calculated automatically; RAG incrementally upserts/tombstones/orphan-scans/rebuilds Rust vector projections; CAG invalidates/verifies/expires/evicts scoped entries; DAG recompiles/validates/switches immutable acyclic generations and recovers verified checkpoints; SQL replays migrations,checks drift,maintains safe structures/fences generations/certifies recovery; low-frequency full reconciliation is compensation only. AUTHORITY:PostgreSQL structured authority+Rust-Vector-Engine derived index+CAG derived cache; PUBLICATION:PREPARING>INDEXING>VERIFYING>READY atomically; SAFETY:deterministic reversible work executes automatically;unknown-effect/destructive/authority-conflict fails closed+quarantines; EVIDENCE:each run binds inputs+versions+roots+counts+orphans+invalidations+resources+latency+result', E'FORBID:second-scheduler/planner/executor+GAG-parallel-plane+DAG-cycle+DAG-replaces-application-service+CAG-replaces-RAG+CAG-authority+unscoped-cache+stale-cache-current+raw-shell/SQL/filesystem-node+permission-bypass+cross-scope-index+partial-publication+uncited-result+unbounded-agent-loop+manual-confirmation-as-normal-path+automatic-destructive-or-unknown-effect-mutation+success-without-evidence+retired-engine-consumer', E'A registered capability degradation policy may use previously verified bounded data with explicit expiry,capacity,source and reconciliation target;it cannot alter authority or permission boundaries.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (420, E'C107', E'3', E'git-sql-rag-cag-dag-integration-division', E'Five-plane integration and automated division of labor: Git is the source and history authority (never a data authority); PostgreSQL is canonical; RAG is the canonical retrieval plane; CAG is a safe, versioned, scoped, non-authoritative cache; DAG is the bounded acyclic orchestration plane (query / multi-RAG / index / rebuild / repair) and never replaces the Application Service.\nSovereigns decide and divide work only; registered module executors perform it; workers and the self-commit service never push; conflicts stop the cycle for human resolution; timeouts fail closed; a CAG hit is never authority; a DAG must not be cyclic or unbounded; every automatic action is auditable.', E'', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (421, E'C108', E'3', E'xingcheng-pretraining-data-pipeline', E'Complete pretraining data pipeline with eleven mandatory elements: Corpus Registry, Dataset Version, Language Classification, Source Tracking, License Validation, Unicode Normalization (with original-to-normalized mapping), Document Deduplication, Sequence Packing, Training/Validation Split, Token Count, Dataset Integrity. Language direction: Traditional Chinese primary, then English, programming languages, mathematics, science, general knowledge and reading comprehension.\nTraining data must be traceable, verifiable and reproducible. Confidential codex content (including the five zh-TW mirror parts and the codex database), permission data, Xingcheng private auxiliary channels, runtime state / audit journals and unauthorized data must never be added to a training set automatically (fail-closed); license validation precedes ingestion. Normalization must preserve the original-to-normalized mapping and must not damage code, paths, proper nouns or semantics.\nThe retired Python training/corpus.py is historical-only; the governed corpus pipeline is the native lane xcm_corpus.h (star-pretrain-corpus/v1) inside xc_modeltool with the star-corpus-registry/v1 source registry at runtime/settings/corpus-registry.json and the incremental star-corpus-scan-state/v1 contract verified by IncrementalCorpusContract; it lands all eleven mandated elements and enforces the exclusion rule fail-closed by path fragment and registry gate before any read.', E'', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (422, E'C109', E'3', E'planning-document-retirement', E'Blueprint,roadmap,phased-plan,flow-plan and equivalent planning files are retired and MUST NOT be created or restored. Current work is governed directly by the formal PostgreSQL Codex authority,registered contracts and explicit current instructions. Historical planning material remains Git history only and has no current force. Work status belongs in registered lifecycle,obligation and evidence projections rather than a parallel planning document.', E'FORBID:new blueprint|restored blueprint|parallel roadmap|planning file treated as authority|historical planning text controlling current work.', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (423, E'C110', E'3', E'gptbridge-connection-recovery-and-event-sequence', E'Frontend-backend connection resilience beyond a single WebSocket reconnect: backend update (new requests to the new release, old requests finish), backend crash (gateway reconnects, UI keeps state), Tauri main crash (launcher/watchdog restores it); three recovery levels: transport, backend release restart/rollback, application launcher/watchdog. LLM streaming continuity keeps received tokens, reconnects, queries generation state by request id, continues the draining backend\'s stream when possible and otherwise shows an honest interrupted state with a regenerate action. A unified event-sequence envelope (request_id, backend_generation, sequence, event, data) lets the gateway detect duplicate, lost and out-of-order events for model streaming, maintenance state and Git results.\nAn interrupted generation must never be presented as still generating; the transport layer alone is insufficient for backend or application recovery.\nregistered Codex contract section 10.14 records the design; three-level recovery, streaming continuity and the event-sequence envelope are not implemented (gap G52).;MUTABLE-VALUES:resolve-current-values-from-owner-versioned-contract-or-registry;CODEX:retains-owner+boundary+prohibition+acceptance-dimensions-only', E';FORBID:deployment-version+benchmark-result+model-threshold+port+path+operational-tunable-as-permanent-Codex-literal', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (424, E'C111', E'3', E'gptbridge-maintenance-update-integration', E'MAINTENANCE-UPDATE-INTEGRATION:the five current cores coordinate through registered modules,not sub-sovereigns. automation-core schedules update and backup modules; decision-core determines health acceptance and repair disposition; permission-core enforces scope and records directory/audit evidence; runtime-core performs governed process cutover or rollback; xingcheng-assistant audits alignment and notifies the user. Every module is single-owner,typed,fail-closed and non-authoritative. Historical maintenance sub-sovereign names are lineage-only under B162.', E'FORBID:active-maintenance-sub-sovereign+new-parallel-maintenance-authority+module-self-authorization+update-without-current-core-owner', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (425, E'C112', E'3', E'dag-cag-rag-machine-contract-maintenance-and-verification-registry', E'C106 is carried by machine_schema_registry,machine_schema_lineage,machine_schema_parity_evidence,test_suite_architecture_directory,implementation_obligations and architecture_diagram_artifact_registry. Required contracts include rag-dag-plan contract,rag-dag-node contract,rag-dag-edge contract,rag-dag-execution-context contract,rag-dag-execution-result contract,cag-entry contract,cag-invalidation-event contract,cag-gate-decision contract,rag-policy contract,rag-observability contract and rag-hybrid-benchmark contract. Automatic maintenance additionally requires versioned contracts for source-change events,index generations,publish barriers,tombstones,reconciliation,orphan findings,rebuild certification and maintenance receipts. Every contract declares field types,nullability,enums,ranges,version,compatibility,unknown-field policy,semantic hash and lineage. Producer,validator,persistence and canonical descriptor parity must be recomputable before parity_status becomes PASS. Mandatory suites cover DAG,CAG,RAG,scope security,degradation,invalidation,reconciliation,orphan handling,rebuild,citation,resource bounds and benchmarks. OBL_DAG_CAG_RAG_HYBRID may advance beyond evidence-submitted only after every contract parity,mandatory suite,zero scope leakage,current-generation publication and benchmark gate is verified. CAG maintenance contracts must also bind cache-entry lifecycle,invalidation causation and propagation,scope and permission-generation validation,capacity and expiry enforcement,orphan reconciliation and cag-maintenance-receipt contract;parity remains PENDING until producer,gate,persistence,invalidation consumer and receipt validator share one semantic contract. DAG maintenance contracts must bind graph-generation identity,typed node and edge descriptors,acyclic validation,execution lease,checkpoint,resume,cancellation,deadline,retry classification,compensation,reconciliation,quarantine,cleanup and dag-maintenance-receipt contract. Parity remains PENDING until planner,executor,node validators,persistence,recovery worker and receipt validator use one semantic contract and demonstrate atomic generation switching.', E'FORBID:prose-only-contract|schema-without-version-or-lineage|pending-parity-treated-pass|test-count-as-semantic-parity|maintenance-without-receipt-contract|rebuild-without-certification|benchmark-without-security-and-citation-gates|obligation-complete-with-open-evidence.+CAG-maintenance-PASS-without-end-to-end-invalidation-and-receipt-parity+DAG-maintenance-PASS-without-cycle-recovery-and-receipt-parity', E'Existing runtime evidence may support evidence-submitted status but cannot replace missing persistence or cross-representation semantic parity.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (426, E'C113', E'3', E'自動清理、刪除權限與世代保留條例', E'自動清理由自動化核心管理排程與流程，刪除執行只能由運行核心下發給已登錄之單一職責模組；星澄助理得稽查並分類垃圾，但不得自行刪除。刪除前必須完成 lifecycle 狀態、引用、owner、authority class、保留期、容量上限與排除範圍檢查；未解析引用一律 fail-closed 保留。模型權重與 adapter 至少保留 active 與上一代；RAG index、release、作業目錄、報告、日誌、暫存與退役資料依受管政策進入標記、冷卻、引用檢查、排程、刪除與審計流程。法典、中文鏡像、法典候選在 amendment 尚未完成時、治理證據、稽核證據、active 世代、使用中資源及 lifecycle 引用產物不得刪除。每模組容量、七十二小時年齡、備份保留一份及中間快照用畢即刪等數值為受管清理政策；任一容量或年齡門檻先到即可觸發，但不得凌駕禁止刪除範圍。所有刪除必須記錄對象、依據、引用判定、執行者、回收量與結果；kill switch 停止刪除但不得停止觀測與告警。', E'FORBID:delete-governance-or-audit-evidence|delete-active-or-referenced-generation|delete-before-codex-retirement|unregistered-delete-executor|unbounded-retry|cleanup-without-audit', E'依法定資料保存、調查保全或生命週期引用所需者延長保留；其例外必須具期限、owner 與審計依據。');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (427, E'C114', E'3', E'Git 規範單一控制條引用收斂', E'C66 是多工作者 Git 協調、提交、整合、同步、推送、衝突處理與稽核的唯一現行控制條。C22、C37、E138 與 P86 的重述停止作為獨立現行控制來源並解析至 C66；其歷史文本保留供 lineage 與舊引用解析。任何 Git 派生契約、hook、worker、coordinator、special-law directory 與搜尋投影只能引用 C66，領域摘要不得新增或改變 C66 的權限、禁止與流程。', E'FORBID:parallel-git-controlling-provision|derived-summary-overriding-C66|stale-current-reference-to-retired-git-restatement', E'歷史證據得引用原條號，但 current controlling basis 必須解析為 C66。');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (428, E'C115', E'3', E'rust-native-vector-engine-and-pgvector-hybrid-architecture', E'CANONICAL:PostgreSQL-18.6+pgvector is sole structured+embedding+vector+resource/chunk/revision/scope/tombstone authority;DERIVED:vectord-rs is Rust-native high-performance rebuildable non-authoritative semantic index and retrieval acceleration;VECTOR-CONTRACT:vector-contract contract;IDENTITY:resource_id+chunk_id+revision uniquely locates a vector generation and embedding-model/version changes create a new identity;SCOPE:validated before retrieval and again before context;TOMBSTONE:never a candidate;RECOVERY:PostgreSQL deterministic bounded stream>temporary vectord-rs generation>verification>atomic generation switch>retire previous;DEGRADATION:vectord-rs unavailable routes only to bounded pgvector retrieval;IMPLEMENTATION-DETAIL:index-kind+precision+codec+batch-range+planner-threshold+buffer strategy remain owner-local non-authoritative rules under B164', E'FORBID:second-vector-authority+canonical-data-in-vectord-rs+retired-vector-service-runtime/fallback+Python-production-RAG-or-vector-runtime+embedded-SQL-canonical-vector+unverified-candidate+mixed-incompatible-generation+in-place-index-destruction+unbounded-vector-work', E'Concrete algorithms, thresholds, index layouts and batch values remain implementation-layer rules and require no Codex amendment while boundaries stay unchanged.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (429, E'C116', E'3', E'retired-dependency-register', E'RETIRED-REGISTER:retired dependency identities remain historical only;LEGACY-VECTOR-SERVICE:status=RETIRED,successor=PostgreSQL-pgvector+Rust-native-vector-engine,active-consumers=0,launch=DENIED,upgrade=DENIED,removal=REQUIRED after canonical data migration and rollback window;OTHER-RETIRED:preserve current registered successors and zero-consumer requirement;PURGE:package+configuration+route+runtime-state+data artifacts are removed only after owner inventory+canonical migration+zero-consumer+rollback-expiry evidence', E'FORBID:new-or-active-dependency-on-retired-item+retired-item-in-release+legacy-vector-service-install/start/query/write/fallback+retired-version-without-label+purge-before-migration-proof', E'Historical retired-service identity may remain only in lineage and removal evidence.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (430, E'C117', E'3', E'automation-core-package-version-reconciliation', E'PACKAGE-VERSION-SYNC:the automation core owns periodic package version reconciliation as a registered periodic flow: detect installed toolchain and package versions across every governed surface (vendored toolchains, language runtimes, dependency manifests, services), run governed upgrades through Winget where one exists under policy bounds,with Visual Studio Installer as the only other authorized download channel;language package managers (Cargo,Go modules,NuGet,npm,pip,bun and successors) never perform a network download and may use only vendored or already-registered dependency artifacts inside the registered dependency root;components installed through the Visual Studio Installer (MSVC toolset,Windows SDK and VS-managed build components) remain a registered exception, and reconcile declared codex versions to installed actuals by emitting codex-amendment-request artifacts through the governed intake pipeline -- never by direct authority writes; upgrades are fail-closed when the ecosystem is offline or vendored;PACKAGE-LIST:the registered technologies table in config/package-version-sync.json is the sole package inventory and no entry may be added,removed or have its mode changed without an explicit permission artifact.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:direct codex writes outside the amendment pipeline|network package fetch by any language package manager|unbounded upgrade commands|version drift left unreconciled without an emitted amendment or recorded deferral|private scheduling outside AutomationCore|package-list-change-without-explicit-permission|bun-package-download', E'vendored toolchains are detect-only (their replacement is a distribution act, not a package update); retired ecosystems (Node.js, TypeScript, PyTorch, Qdrant, alternate embedded database, Electron, Python, NumPy, JAX per C116) are never upgraded');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (431, E'D1', E'4', E'amendment', E'AMENDMENT:explicit-signed-higher-version-full-replacement', E'FORBID:incremental/runtime-amendment', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (432, E'D2', E'4', E'governor-and-seal', E'GOVERNOR:human-operator; OFFICE:codex; AMEND:deliberate-act; SEAL:versioned-digest-manifest; VERIFY:before-every-load', E'FORBID:non-governor-seal/forged-manifest/verify-skip', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (433, E'D3', E'4', E'audit-ledger', E'AUDIT:ledger-per-managed-action; WRITE:governed-executor; STORE:data-governance-sub-sovereign-declared; RETENTION:by-governance-policy; READ:codex+maintenance-analysis', E'FORBID:audit-mutation/audit-suppression/unauthorized-audit-read', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (434, E'D4', E'4', E'violation-closure', E'VIOLATION:stop-record-adjudicate; DETECT:maintenance-monitoring; STOP:deny-fail-closed; RECORD:fault-determination+audit-ledger; ADJUDICATE:codex-final', E'FORBID:violation-without-record/self-adjudication/continued-execution-after-violation', E'');
