INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (436, E'D6', E'4', E'file-extension-conventions', E'FILE-EXT:per-language-canonical; PYTHON:src=.py/stub=.pyi/test=test_*.py/pkg-init=__init__.py; TYPESCRIPT:logic=.ts/jsx-ui=.tsx/decl=.d.ts/test=.test.ts+.test.tsx; C:impl=.c/interface=.h/test=*_test.c; CPP:impl=.cpp/header=.hpp/template-inline=.inl(when-needed)/test=*_test.cpp; CSHARP:src=.cs/proj=.csproj/solution=.sln/test=*Tests.cs; SQL:general=.sql/migration=.sql; BOUNDARY:C-uses-.h+CPP-uses-.hpp-for-language-edge-visibility; FORBID:inventing-custom-extensions; BASIS:codex+B38-architecture-hybrid', E'FORBID:custom-file-extensions; FORBID:cross-language-extension-mismatch; FORBID:mixing-.h-for-cpp-or-.hpp-for-c; FORBID:non-declared-extension', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (437, E'D7', E'4', E'test-framework-final-ownership', E'TEST-TIER:unit-by-implementation-language+cross-language-integration-under-CSharp-TestSuiteOrchestrator;UNIT:C/C++=native-harness|Rust=cargo-test|Go=go-test|CSharp/FSharp=dotnet-test|JavaScript-ESM=Rust-hosted-browser-contract-harness|Julia=Julia-native-test|PostgreSQL=migration-replay;INTEGRATION:CSharp-TestSuiteOrchestrator is sole orchestrator and emits typed test result contract;PYTHON:none;TRAINING:JAX training artifacts are validated by native contract and model-evaluation suites without Python test ownership.', E'FORBID:second-test-orchestrator+Python-test+pytest+cross-language-unit-framework-mixing+skip-required-integration-tier', E'None.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (438, E'D8', E'4', E'self-health-test-necessity', E'SELF-HEALTH-TEST:necessary-for-self-maintenance-health; OWNER:health-maintenance-test-sub-sovereign; SCOPE:governed-tools-declare-test-files; REQUIRE:collectable-offline+no-live-model-dependency; DETECT:governance-audit-collects-managed-test-files; BASIS:codex+D7-test-framework-tiering\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。', E'FORBID:delete-required-test-file; FORBID:test-depends-on-live-model/network; FORBID:uncollectable-test-file', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (439, E'D9', E'4', E'absolute-codex-immutability', E'SEALED-VERSION:read-only+content-addressed+permanently-preserved; ACTOR-WITH-MUTATION-POWER:none; REVISION:create-new-complete-version+new-digest+new-seal-only; PRIOR-VERSION:unchanged', E'FORBID:any-update/delete/patch/append/rewrite/schema-mutation/in-place-migration/restore-overwrite/hot-update/repair/database-write/trigger/procedure/tool-write/runtime-write/human-direct-edit-to-sealed-codex', E'Creating and sealing a distinct complete successor version is not modification of an existing sealed version.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (440, E'D10', E'4', E'codex-modification-history', E'HISTORY:inside-official-codex-database+ordered+hash-chained; EACH-ENTRY:change-id+version+date+scope+summary+previous-hash+entry-hash; SEALED-VERSION:no-history-write; SUCCESSOR-VERSION:copy-complete-prior-history+append-current-release-entry+seal', E'FORBID:delete/reorder/rewrite/backdate/fabricate/history-gap/in-place-append-to-sealed-version; FORBID:postgresql-as-history-authority', E'History is appended only while constructing an unsealed complete successor version.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (441, E'D11', E'4', E'codex-file-protection-and-authority-boundary', E'AUTHORITY:the current PostgreSQL Codex is authoritative through permission,transaction,version,current-binding and seal controls;filesystem attributes never create authority. READONLY:only current generated confidential Chinese mirror parts,the registered governance package entry and registered shared-layer enforcement sources require filesystem read-only protection. WRITABLE:architecture projections,renderer inputs and all other non-mirror workspace files are governed writable. PUBLICATION:an authorized publisher may unlock a required protected target only for verified atomic replacement and must restore protection before completion. CANDIDATE:a candidate has no current authority until verified,published,bound and sealed.', E'FORBID:filesystem-readonly-as-authority+all-Codex-files-readonly+unauthorized-write+in-place-current-authority-mutation+unsealed-candidate-as-current+protected-target-left-writable+content-or-version-drift', E'None.');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (442, E'D12', E'4', E'provision-update-recertification', E'ANY-PROVISION-CHANGE:creates-new-candidate+new-permanent-identity+new-lineage+new-content-hash; RECERTIFICATION:integrity+identity+history+complete-version-seal-required; EFFECTIVE:only-after-recertified-successor-activation; PRIOR-PROVISION:active-until-then+retained-after-supersession', E'FORBID:reuse-prior-identity/signature/hash+in-place-update+self-certification+partial-certification+activate-before-recertification+retire-old-provision-before-successor-effective', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (443, E'D13', E'4', E'atomic-provision-supersession', E'ACTIVATION-EVENT:identity+recertification+complete-version-seal+official-entry-publication; SAME-INSTANT:successor-status=active+predecessor-status=superseded; PREDECESSOR-AFTER-ACTIVATION:no-legal-effect+history-only; GAP/OVERLAP:none', E'FORBID:old-and-new-simultaneously-effective+delayed-old-law-expiry+rollback-by-native-javascript-esmivating-old-identity+delete-superseded-history', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (444, E'D14', E'4', E'codex-without-codex-view', E'CODEX:cannot-view-or-cite-codex-content; RECEIVE:signed-opaque-adjudication-result+provision-identities+verification-status-without-rule-text; ACTION:verify-envelope+identity+freshness+audit+coordinate-authorized-outcome', E'FORBID:codex-direct-codex-read+rule-text-disclosure+independent-codex-interpretation+business-execution', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (445, E'D15', E'4', E'deterministic-version-classification', E'VERSION-UNIT:0.00001 integer-arithmetic; GENESIS:1.00000; AFTER-GENESIS:evaluate-all-effective-changes+select-highest-precedence-degree+apply-exactly-one-corresponding-increment; MULTIPLE-SAME-DEGREE:one-increment; CROSS-DIGIT-CARRY:base-10; COMPLETE-RECONSTITUTION:+1.00000 without-reset; RESET/REBASE/REUSE-AFTER-THIS-GENESIS:none; AMBIGUOUS-OR-NO-MATCH:deny-seal', E'FORBID:floating-point+manual-increment-selection+increment-summing+degree-inflation/deflation+version-reuse+version-reset+history-rebase+seal-with-ambiguous-classification', E'This complete reconstitution establishes the sole one-time 1.00000 genesis; no later reset exception exists');
