INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (447, E'D17', E'4', E'candidate-build-review-and-governed-seal', E'CANDIDATE:built through governed tooling with complete diff,identity,lineage,version classification and integrity evidence;REVIEW:required before publication;SEAL:issued only by the registered Codex amendment and certification process after deterministic verification of the current epoch lineage and declared integrity roots;ACTIVATION:only after seal,projection parity and atomic publication.', E'FORBID:self-seal|unreviewed-seal|candidate-as-effective-law|seal-with-missing-lineage|seal-outside-registered-amendment-process.', E'');
INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (448, E'D18', E'4', E'ghost-provision-prohibition', E'NEW-PROVISION:must-be-active-for-at-least-one-complete-effective-version-before-supersession; ZERO-EFFECTIVE-PERIOD:invalid+retired-not-law; SUPERSESSION-VERSION:must-match-revision-history', E'FORBID:birth-and-death-same-version+incorrect-effective-version+ghost-lineage-node', E'');
