INSERT INTO "articles" ("position", "provision_id", "section_index", "subject", "rule", "prohibition", "exception") VALUES (451, E'D21', E'4', E'api-contract-versioning', E'EACH-API/IPC/EVENT/SCHEMA-CONTRACT:stable-id+semantic-version+typed-fields+compatibility-range; BREAKING-CHANGE:new-major+consumer-migration+dual-read-window-or-atomic-cutover; REMOVAL:usage-proof+review', E'FORBID:unversioned-contract+silent-breaking-change+producer-only-upgrade+indefinite-compatibility-shim', E'');
