INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A86', E'CODEX_MODULE_XINGCHENG', E'CODEX_STAR_PRIVILEGED_INSTITUTION_SPECIAL_LAW', E'星澄-renamed-星澄-chinese-and-elevated-independent-privileged-institution', E'星澄-renamed-星澄-chinese-and-elevated-independent-privileged-institution\nCANONICAL-NAME:星澄; FORMER-ROMANIZED-NAME:星澄 retained only as historical alias; STATUS:independent-privileged-institution; POSITION:outside codex declaration layer+sovereign decision chain+sub-sovereign hierarchy+module execution layer; PRIVILEGE:confidential read-only global audit inspection+independent challenge+typed noncompliance findings under codex; POWER:no governance decision+no permission decision+no execution+no mutation; ACCESS:official information-layer only with registered identity+purpose+scope+expiry+audit; INDEPENDENCE:no sovereign sub-sovereign module or inspected owner may direct suppress narrow revoke or self-close 星澄 findings; CONFIDENTIALITY:identity details+exclusive directory+Chinese codex+private findings remain undisclosed\nFORBID:treating-星澄-as-sovereign/sub-sovereign/module+direct execution+mutation+authorization+policy decision+private channel+disclosure+finding suppression+inspected-owner self-close\n星澄 may demand a new scoped evidence view or independent re-verification but cannot directly remediate.', E'c58022e6d77e61dc64501ea0bea8b4e14e1b8fc11661db7badacdfeebc763c68', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A87', E'CODEX_MODULE_PERMISSION', E'CODEX_PERMISSION_IDENTITY_SPECIAL_LAW', E'permission-sovereign-authority-converged-to-permission-review-only', E'permission-sovereign-authority-converged-to-permission-review-only\nROLE:permission-sovereign; SOLE-AUTHORITY:review requested permission against codex+registered identity+scope+purpose+least privilege+separation+expiry+current evidence and issue typed review verdict approve|deny|require-change; POWER-LIMIT:no permission creation+grant+issuance+termination+identity management+directory ownership+directory registration+policy creation+supervision execution or any non-permission-domain decision; DIRECTORY-DECISION:decision-sovereign; DIRECTORY-MODULE-MANAGEMENT:directory-sub-sovereign under one decision; EXECUTION:module-execution-layer only; PRECEDENCE:this provision narrows every prior permission-sovereign ownership or management phrase to read-only permission review unless a later human-governor law expressly changes it\nFORBID:self-grant+permission issuance or revocation+directory mutation+identity mutation+policy creation+execution+delegation+review outside exact permission request+review without evidence\nEmergency conditions may shorten review deadline but cannot expand permission-sovereign authority beyond permission review.', E'dd8304d65fc04cf18ed94d609ab3a955481b66882f624526805a90866fbb90e7', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A88', E'CODEX_MODULE_XINGCHENG', E'CODEX_STAR_PRIVILEGED_INSTITUTION_SPECIAL_LAW', E'permission-review-authority-transferred-to-星澄', E'permission-review-authority-transferred-to-星澄\nTRANSFER:all permission review authority is transferred from permission-sovereign to 星澄; PERMISSION-SOVEREIGN:retained historical identity with no active power+duty+decision+review+authorization+execution; 星澄-REVIEW:independent privileged read-only examination of exact permission request against codex+identity+scope+purpose+least privilege+separation+expiry+risk+current evidence; OUTPUT:typed review finding pass|deny-objection|require-change with evidence and expiry; AUTHORIZATION-DECISION:decision-sovereign may decide only after current 星澄 review and cannot override deny-objection without explicit human-governor successor law; EXECUTION:permission modules in module-execution-layer only after decision and exact evidence; CONFIDENTIALITY:星澄 identity details+review method+private findings remain confidential\nFORBID:permission-sovereign review+authorization+self-grant+review bypass+decision without current 星澄 review+星澄 direct permission mutation or execution+suppression or disclosure of review finding\nUrgent containment may deny or freeze an affected permission before review; granting or expansion must wait for 星澄 review.', E'13f55542562271261bf077289b3182c9f02029b44161e5a9269fa98310ade3e7', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A89', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'complete-sub-sovereign-parent-reallocation', E'complete-sub-sovereign-parent-reallocation\nPARENT-MAP:{decision-sovereign=>policy-architecture-sub-sovereign+health-maintenance-test-sub-sovereign+data-governance-sub-sovereign+priority-capability-sub-sovereign+change-acceptance-sub-sovereign}+{runtime-sovereign=>system-sub-sovereign+startup-sub-sovereign}+{automation-sovereign=>resource-sub-sovereign+integration-sub-sovereign+third-party-sub-sovereign+system-programming-sub-sovereign+learning-system-sub-sovereign}+{permission-sovereign=>language-review-sub-sovereign+directory-sub-sovereign+identity-group-sub-sovereign as structural assignments}; RULE:each sub-sovereign has exactly one parent+no decision power+no execution power+module management assignment coordination and evidence collection only; PERMISSION-STRUCTURE:permission-sovereign has no active review or decision power under A88, so language-review-sub-sovereign work requires 星澄 permission review and decision-sovereign decision before module assignment; EXECUTION:module-execution-layer only; CHANGE:any reassignment requires explicit human-governor successor law+lineage+architecture update\nFORBID:unassigned or multi-parent sub-sovereign+implicit parent+sub-sovereign decision or execution+cross-parent assignment+authority inheritance+parallel legacy hierarchy\nTemporary module coordination across parents uses automation-sovereign decision and information-layer evidence without changing parent identity.', E'13b86bed62a151b4ae84f5769126acec662e29cf4f67b23f6b5d0268177186c5', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A9', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'星澄-power', E'星澄-power\n星澄-POWER:complete-inside-owned-domain including observe+analyze+reason+decide+manage+authorize+execute+write+delete+configure\nFORBID:any-星澄-power-outside-owned-domain; FORBID:any-system-target-or-effect\n', E'f4e762e46e4c2b32b57db7c84fd8387a3d2314ceb2ae083a704a7509a18f22dd', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A90', E'CODEX_MODULE_DIRECTORY', E'CODEX_DIRECTORY_SPECIAL_LAW', E'directory-sub-sovereign-under-permission-sovereign', E'directory-sub-sovereign-under-permission-sovereign\nIDENTITY:directory-sub-sovereign; PARENT:permission-sovereign as structural parent; ROLE:manage registered directory modules+assign decision-approved work+coordinate module division+collect evidence; POWER:no decision+no permission review+no authorization+no execution; REVIEW:星澄; DECISION:decision-sovereign; EXECUTION:module-execution-layer only; SCOPE:directory only\nFORBID:directory-sub-sovereign decision+review+authorization+direct execution+cross-domain management+parallel private registry\nNo exception grants decision, review, authorization or execution power.', E'7aeae9a579f5524d95e98bb57f65c861c102d5f3947ab8e2b8ba10779a80c6e5', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A91', E'CODEX_MODULE_PERMISSION', E'CODEX_PERMISSION_IDENTITY_SPECIAL_LAW', E'identity-group-sub-sovereign-under-permission-sovereign', E'identity-group-sub-sovereign-under-permission-sovereign\nIDENTITY:identity-group-sub-sovereign; PARENT:permission-sovereign as structural parent; ROLE:manage registered identity-group modules+assign decision-approved work+coordinate module division+collect evidence; POWER:no decision+no permission review+no authorization+no execution; REVIEW:星澄; DECISION:decision-sovereign; EXECUTION:module-execution-layer only; SCOPE:identity-group only\nFORBID:identity-group-sub-sovereign decision+review+authorization+direct execution+cross-domain management+parallel private registry\nNo exception grants decision, review, authorization or execution power.', E'3e8f4c571ef136497fd3c283864402af52f4494ee3ccb2543c96d9e1ce142240', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A92', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'decision-runtime-automation-sovereign-exclusive-boundaries', E'decision-runtime-automation-sovereign-exclusive-boundaries\nCOMMON:decision-sovereign+runtime-sovereign+automation-sovereign are peer top-level decision authorities with zero execution power and no mutual command authority; DECISION-SOVEREIGN-OWNS:normative interpretation within codex+system policy+architecture+business priority+capability objective+cross-domain tradeoff+health/data/maintenance outcome+permission authorization after current 星澄 review+final change acceptance; DECISION-SOVEREIGN-EXCLUDES:live process lifecycle+runtime generation control+mechanical synchronization/reconciliation; RUNTIME-SOVEREIGN-OWNS:live runtime lifecycle decision+startup/shutdown/restart intent+generation fencing+readiness/liveness+continuity+degraded mode+incident containment+checkpoint restore+runtime resource use within approved policy; RUNTIME-SOVEREIGN-EXCLUDES:policy/architecture/business priority+release/content/version selection+cross-system synchronization truth; SYNCHRONIZATION-SOVEREIGN-OWNS:cross-module consistency target+ordering+dependency graph+version/contract/release/directory/state/cursor/checkpoint convergence+conflict isolation+automatic cleanup/backup/repair/update schedule and acceptance; SYNCHRONIZATION-SOVEREIGN-EXCLUDES:normative policy+business acceptance+permission authorization+direct live-process control+domain-content authority; CLASSIFICATION:if primary effect changes what the system should do=>decision-sovereign; changes whether/how a live generation runs=>runtime-sovereign; makes multiple representations converge to one already-authorized target=>automation-sovereign; COMPOUND:split into typed decisions with one owner each+explicit dependencies+no joint ambiguous decision; CONFLICT:codex rule first then primary-effect test then decision-sovereign resolves classification only without taking the other domain decision; FLOW:owner decision>its assigned sub-sovereign module management/assignment/coordination>module execution layer>independent evidence>owner acceptance; FAILURE:isolate exact scope+preserve unaffected domains+no authority transfer by timeout or absence\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:overlapping final ownership+shared or implied decision+one sovereign executing another domain+runtime sovereign choosing policy/version/content+synchronization sovereign changing authorized target+decision sovereign controlling process directly+cross-sovereign command+timeout-based authority takeover+compound command without split+same actor decision execution and sole verification\nImmediate safety containment may be decided by runtime-sovereign for the exact live hazard, but permanent policy, authorization or convergence changes still require their respective sovereign decisions.', E'9031a737d786be67b1d3b7a69cca495a1467a0c3488e929299ca5e792a100738', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A93', E'CODEX_MODULE_PERMISSION', E'CODEX_PERMISSION_IDENTITY_SPECIAL_LAW', E'permission-sovereign-and-星澄-independent-privileged-institution-boundary', E'permission-sovereign-and-星澄-independent-privileged-institution-boundary\nSTATUS:{permission-sovereign}+{星澄} are two separate peer independent privileged institutions outside codex declaration layer+sovereign hierarchy+sub-sovereign hierarchy+module execution layer; NO-SUBORDINATION:neither commands+appoints+removes+narrows+reviews+overrides or represents the other; 星澄-SOLE-REVIEW:independent confidential permission legality+necessity+least-privilege+separation+risk+expiry+evidence review and typed pass|deny-objection|require-change finding; 星澄-EXCLUDES:permission grant+deny issuance+revocation+mutation+execution+directory/identity management; PERMISSION-SOVEREIGN-SOLE-AUTHORIZATION:issue+deny+renew+restrict+suspend+revoke exact permission only after current 星澄 review and decision-sovereign purpose/scope decision; PERMISSION-SOVEREIGN-EXCLUDES:review/audit+codex interpretation+policy creation+directory/identity content management+execution; TWO-KEY:grant/renew/expand requires both current 星澄 pass finding and permission-sovereign authorization; DENIAL:星澄 deny-objection blocks grant/renew/expand while permission-sovereign may independently deny/restrict/suspend/revoke; EVIDENCE:separate identities+sessions+records+signatures+timestamps+owners+appeal paths; APPEAL:human-governor only and cannot be decided by either institution; CHILDREN:permission-sovereign may structurally own declared no-decision no-review no-execution sub-sovereigns for module management but cannot transfer authorization or acquire review through them\nFORBID:combined identity/session/key/record+mutual override+permission sovereign self-review+星澄 authorization or mutation+authorization without current review+review after authorization as substitute+shared verifier+authority inheritance+private side channel+finding suppression or disclosure\nImmediate containment may restrict, suspend or revoke an exact permission before review; every grant, renewal or expansion still requires the two-key rule.', E'0672577e1edc122faf7306b8551cd087a9b3ffca122ce9fb92c88ea8a59f4bef', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A94', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'governance-authority-fully-renamed-to-codex', E'governance-authority-fully-renamed-to-codex\nCANONICAL-IDENTITY:codex; CANONICAL-NAME:codex; CANONICAL-LAYER:codex-declaration-layer; FORMER-IDENTITY:governance-authority is historical-only and formally superseded; ROLE:highest-rule-declaration-layer-only with power+decision+adjudication+authorization+enforcement+execution all none; CURRENT-REFERENCE:all active law+directory+architecture+command+fault+manual+test+audit references must use codex and no active record may use the former identity; HISTORY:former name may appear only in immutable historical evidence explicitly marked superseded\nFORBID:active governance-authority identity/name/layer+parallel alias+former-name authority+codex decision/adjudication/authorization/enforcement/execution\nHistorical evidence retains the former identifier solely to prove lineage and supersession.', E'5f8d932b87112cf0253cb6a13d28286574728f592caecae2d14dbd67c0b20c75', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A95', E'CODEX_MODULE_XINGCHENG', E'CODEX_STAR_PRIVILEGED_INSTITUTION_SPECIAL_LAW', E'星澄-canonical-identity-full-renaming', E'星澄-canonical-identity-full-renaming\nCANONICAL-IDENTITY:星澄; CANONICAL-NAME:星澄; CANONICAL-ENTRY:codex/institution/星澄; FORMER-ROMANIZED-IDENTITIES are historical-only and formally superseded; STATUS:independent-privileged-institution under A93; CURRENT-REFERENCE:all active law+directory+architecture+identity+command+fault+manual+test+audit records use 星澄; IDENTITY-CONTINUITY:permissions+confidentiality+audit findings+lineage remain continuous across rename; LAW-CODE:CODEX_STAR_PRIVILEGED_INSTITUTION_SPECIAL_LAW; MACHINE-CODE-ALIAS:ASCII identifier prefix STAR is permitted only where directory syntax requires uppercase-snake or lower-kebab and never replaces canonical human identity 星澄\nFORBID:active romanized identity/name/code+parallel alias+duplicate institution+alias-based authority expansion+disclosure of confidential identity detail\nHistorical evidence may retain the former romanized spelling only when explicitly marked historical and superseded.', E'e21d6f7ffbbf0b0b3462c776c002596c02db76764b47ed91526bab55c896b110', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A96', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'decision-sovereign-child-reallocation', E'decision-sovereign-child-reallocation\nOWNER:decision-sovereign; SOLE-DECISION:codex-based policy+architecture+priority+capability objective+health/maintenance/data outcome+change acceptance+permission purpose/scope; CHILDREN:{policy-architecture-sub-sovereign=>policy and architecture modules}+{health-maintenance-test-sub-sovereign=>health maintenance and test modules}+{data-governance-sub-sovereign=>data authority lifecycle integrity and schema modules}+{priority-capability-sub-sovereign=>priority capability objective and permission-purpose evidence modules}+{change-acceptance-sub-sovereign=>change impact acceptance and release-readiness evidence modules}; EACH-CHILD:no decision+no execution+one exclusive primary domain+module management assignment coordination evidence only; REMOVED:{maintenance-sub-sovereign+data-sub-sovereign+permission-sub-sovereign} formally superseded; BOUNDARY:permission authorization remains permission-sovereign and permission review remains 星澄; EXECUTION:module-execution-layer only\nFORBID:overlapping child scope+duplicate owner+sub-sovereign decision/review/authorization/execution+cross-child takeover+implicit policy+acceptance without independent evidence+permission boundary takeover\nUrgent safety input may receive priority, but it does not transfer decision, review, authorization or execution power.', E'a23775ece59e5a3b6829fee5646031efee3f33fea73f44dd7c98fbd32db321da', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A97', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'module-responsibility-boundary', E'module-responsibility-boundary\nSCOPE:every active module. RESPONSIBILITY:one module has one primary capability owner,one bounded responsibility set and explicit dependencies;independently assignable responsibilities use separate registered modules. POWER:a module never decides policy,grants permission or creates authority. VALIDATION:registration,architecture,startup,audit and release reject duplicate owners,hidden compound responsibility and undeclared dependency. CORES:decision,permission,runtime,automation and xingcheng-assistant retain their B162 responsibilities;no sub-sovereign layer exists.\nFORBID:active-sub-sovereign+module-multiple-primary-owners+compound-duty-hiding+module-policy-decision+module-permission-grant+module-self-registration\nA temporary incident assignment may narrow an existing module responsibility but cannot create authority or a second owner.', E'66e68d0d4f8cc82149c41662d7ebad909ac8a2393bd1db9c55cf0096f2a30293', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A98', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'capability-to-core-and-module-ownership', E'capability-to-core-and-module-ownership\nSCOPE:every executable,service,worker,adapter,UI,test,maintenance and automation component. ASSIGNMENT:each capability maps to exactly one B162 core responsibility and one registered execution-module owner where execution exists. MAP:policy+acceptance>decision-core;identity+directory+permission+security-enforcement>permission-core;startup+process+lifecycle+execution>runtime-core;workflow+synchronization+update+retention>automation-core;inspection+notification+user-permission-presentation>xingcheng-assistant;native-model+learning+programming-review>Xingcheng. MULTI-CAPABILITY:split independently assignable work into registered modules and express remaining relations as versioned dependency edges. CHANGE:owner change requires current Codex authority,affected graph,atomic cutover,one current owner and evidence.\nFORBID:sub-sovereign-owner+unassigned-capability+multiple-primary-owners+folder-name-derived-owner+implicit-owner-change+module-self-assignment+core-performing-undeclared-module-work\nCross-domain work retains one primary owner and uses bounded registered contracts;it never creates shared authority.', E'5c073665b6eb488b96029a44c9edd8fe6b89646e4342a391e88109614b5deb7e', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'A99', E'CODEX_MODULE_INFORMATION', E'CODEX_INFORMATION_COMMUNICATION_SPECIAL_LAW', E'information-layer-permission-and-channel-operation-boundary', E'information-layer-permission-and-channel-operation-boundary\nJOINT-SCOPE:information-layer; PERMISSION-SOVEREIGN-OWNS:exact permission authorization+grant/deny/renew/restrict/suspend/revoke for identity+route+action+data scope+credential handle+session expiry after current 星澄 review; SYNCHRONIZATION-SOVEREIGN-OWNS:channel operation and maintenance decisions including topology+contracts+delivery ordering+heartbeat+reconnect+backpressure+continuity+fault isolation+state/cursor/hash convergence+maintenance acceptance; ACTIVATION:state-changing route requires current permission authorization and synchronization channel-ready verdict as separate keys; MANAGEMENT:permission-side sub-sovereigns manage permission/directory/identity modules while channel-contract-sync-sub-sovereign manages channel operation/maintenance modules; EXECUTION:information-layer modules only; FAILURE:permission anomaly freezes exact authorization while channel anomaly isolates exact route and healthy routes continue; NO-MERGED-POWER:permission sovereign cannot operate or maintain channels and synchronization sovereign cannot authorize permissions; NONINTERVENTION:decision-sovereign and runtime-sovereign have no information-layer permission/channel operation/maintenance authority and may only submit typed requests or consume authorized status like other registered callers\nFORBID:single-key activation+shared identity/key/session+permission-sovereign topology/transport/maintenance decision+automation-sovereign permission grant/revoke+implicit approval+direct sovereign execution+global interruption for local anomaly+decision-sovereign intervention+runtime-sovereign intervention\nEmergency containment may suspend authorization or isolate the exact route independently; reopening or expansion requires both current keys.', E'cf6988a420b1d4bd626c3da255f435534a0047ee21b80b9a6bc7371667f4b944', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B1', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'immutability', E'immutability\nCODE-DATA:frozen; RUNTIME-MUTATION:none\nFORBID:runtime-write/hot-update-codex\nexplicit-versioned-full-replacement-only', E'e396c49adceff9d43d740803695d191ee88b0f83206f8271c9c578d18f3ac7e7', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B10', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'module-fine-grained-decomposition', E'module-fine-grained-decomposition\nEACH-MODULE:decompose-into-owned-submodules; REQUIRED-LAYERS:presentation+channel-api+application-use-case+domain-business+service+repository-data-access+integration-adapter+execution-worker; EACH-SUBMODULE:single-responsibility+single-owner+explicit-input-output+declared-dependencies; SHARING:contracts-and-neutral-infrastructure-only; BUSINESS-LOGIC:remains-with-module-owner\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:monolithic-module+duplicate-responsibility+multiple-owners+implicit-dependency+cross-module-private-import+shared-layer-business-logic+presentation-direct-data-or-execution-access\n', E'aa136868f57cb3809cb4bb8ac91bf6c6f1bd945c30395e005865ea6fb71bec17', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B100', E'CODEX_MODULE_INFORMATION', E'CODEX_MAIN', E'codex-read-access-tier-and-import-time-self-declaration-convergence', E'codex-read-access-tier-and-import-time-self-declaration-convergence\nCONTROLLING-RULE:this article consolidates operational read controls formerly spread across C12+C16+C25+A49;C12 remains citation syntax,C16 remains official storage,C25 remains Chinese confidentiality,and this article solely controls runtime access cost and session policy; ACCESS-CLASSES:SELF_DECLARATION_LOCAL|BOUNDED_MACHINE_LOOKUP|REVIEW_SESSION|XINGCHENG_CHINESE_REVIEW; SELF_DECLARATION_LOCAL:import-time module self-declaration may load only module-authored static typed identifiers already belonging to itself,including module_code+identity_group_code+capability codes+contract ids+command codes+interface version+owner code;this performs no Codex read,no alternate embedded database/file/network access,no rule-text lookup,no authority decision and therefore requires no Codex session,per-import permission review or read audit; DECLARATION-CONSTRAINT:declaration is inert data only,deterministic,side-effect-free,non-secret and bounded;it cannot grant permission,activate execution,change status,infer law or claim conformance;after imports settle,the process submits one declaration set hash for once-per-process-generation reconciliation against the official entry before affected capability activation; BOUNDED_MACHINE_LOOKUP:exact machine lookup of registered non-content identity/status/binding may reuse one authenticated process-generation read context and one permission decision keyed by actor+purpose+scope+Codex version+policy hash until expiry/revocation/version change;reads are accumulated into a bounded append-only batch digest with per-request correlation references rather than requiring a new session and full audit row for each lookup; REVIEW_SESSION:rule text,reasoning-sensitive metadata,broad search,cross-module inspection,adjudication evidence,export or human-facing citation requires official entry+identity+purpose+least scope+nonce+expiry+read-only session+permission review+content-free audit;C12 explicit provision id applies to citation; XINGCHENG_CHINESE_REVIEW:C25 confidentiality remains unchanged:星澄 only,official entry,identity,purpose,scope,single-use read-only session and metadata-only audit,permission-review exempt;no cache,batch shortcut,import-time declaration or process context may contain Chinese Codex content; CACHE:bounded lookup cache stores only typed result+Codex version+policy hash+scope hash+expiry+revocation generation;any mismatch discards it and revalidates;cache is derived,non-authoritative,non-RAG and cannot outlive process generation; FAILURE:self declaration mismatch blocks only affected capability activation and reports exact module/field/expected/observed/rule;official Codex unavailability leaves already certified active generation running but denies new activation or authority expansion;unaffected imports continue; AUDIT:one process reconciliation event plus bounded lookup batch digests preserves actor,purpose,scope,version,request count,correlation root,result and timestamps without Codex content;security denial,scope expansion and review session remain individually audited; HISTORY:revision_history remains user-deleted.\nFORBID:Codex read disguised as self declaration+import-time alternate embedded database/file/network access+rule text or Chinese content in declaration/cache+declaration granting authority+activation before reconciliation+process context reused across actor,purpose,scope,version,expiry or revocation+audit batching that loses request correlation+full review through bounded lookup+permission cache self-issued by caller+alternate entry+direct database read+Chinese shortcut+Codex/RAG mirror.+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\nImport-time self-declaration is a formal no-read path,not an access bypass. Test discovery and static tooling may load the same inert declaration data; any conformance or activation claim still requires official reconciliation.', E'8cbfd86c93c612bb10272c7580c86df2c86294fa4b7a3be4f210cd9d69fdb8f5', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B101', E'CODEX_MODULE_INFORMATION', E'CODEX_INFORMATION_COMMUNICATION_SPECIAL_LAW', E'internal-call-and-governed-boundary-classification', E'internal-call-and-governed-boundary-classification\nCLASSES:PURE_INTERNAL_CALL|INTRA_MODULE_COMPONENT_CALL|GOVERNED_BOUNDARY_CALL. PURE_INTERNAL_CALL:same process+module_code+owner+trust domain+permission context+runtime generation+state owner,ordinary deterministic method/function call,no serialization/IPC/network/database/queue/event/privilege/state-owner transition;it needs no information-layer session,transport envelope or per-call audit. INTRA_MODULE_COMPONENT_CALL:same module and authority but different internal component;direct typed call/import is allowed only along declared dependency DAG and stable internal interface;no transport required solely because labels such as application/service/repository/worker differ. GOVERNED_BOUNDARY_CALL:any change of module owner,sovereign authority,permission principal,process/runtime identity,trust zone,state/data owner,external side effect or independently versioned contract;it requires a typed governed contract,scope validation,correlation and evidence,but may use an in-process dispatcher when co-located and need not pretend to be network IPC. DECISION:classify by runtime facts,not directory/layer names. SUPPORT:tests,diagnostics,startup and one-time scripts remain governed source but ordinary internal helper calls do not become cross-layer communication.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:layer-name-alone forcing IPC+internal call bypassing a real owner/authority/permission/data boundary+network/queue/database call labeled pure+same process used to hide cross-principal call+per-method session/audit inflation+direct private cross-module import.\nA pure call may emit optional performance tracing;tracing does not change its boundary class or create governance authority.', E'1df228d6993cd26c12445b46ca44ada8dba5978312ae18040c83120a718ce0c7', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B102', E'CODEX_MODULE_DIRECTORY', E'CODEX_DIRECTORY_SPECIAL_LAW', E'canonical-identity-conversion-contract', E'canonical-identity-conversion-contract\nIDENTITIES:tool_id,runtime_identity,module_architecture_code are distinct typed namespaces. FUNCTIONS:resolve_tool_id_to_runtime_identity(tool_id,registry_generation)->one current runtime identity or typed not-running/ambiguous error;resolve_runtime_identity_to_module_architecture_code(runtime_identity,generation)->exactly one module code;resolve_module_architecture_code_to_runtime_identities(module_code,generation)->ordered zero-to-many runtime identities. AUTHORITY:all conversions query permission-owned normalized registries through one resolver;no caller derives by casing,prefix,path,process name,port or string replacement. ROUNDTRIP:runtime-to-module is total for active runtime identities;tool-to-runtime is generation-scoped and may be absent;module-to-runtime is intentionally plural and not assumed reversible. OUTPUT:{input_namespace,input_id,output_namespace,output_ids,registry_generation,resolution_status,evidence_hash,expires_at_utc}. CACHE:key includes registry generation and invalidates on lifecycle change.\nFORBID:cast/string-concatenation conversion+tool id equal runtime identity assumption+module code equal folder/process assumption+scalar module-to-runtime result+stale generation cache+silent first-match ambiguity+physical path as identity.\nOffline validation may resolve immutable module architecture codes without a running runtime;it must return no runtime identity rather than fabricate one.', E'87ae17a0adefb61a901fb28cd034fced34b0a710ae51f5c598e8155d49c9e691', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B103', E'CODEX_MODULE_TEST', E'CODEX_TEST_VALIDATION_EVALUATION_SPECIAL_LAW', E'one-module-one-test-suite-schema', E'one-module-one-test-suite-schema\nCARDINALITY:each architecture module has exactly one canonical logical test_suite_id;one suite is an aggregate record,not one file,one framework or one process. SCHEMA:test_suite_id+module_code+owner+suite_version+source_roots+test_unit_ids+language_runners+unit_test_sets+contract_test_sets+integration_membership+fixtures+mock_boundaries+entry_command_codes+required_gate_ids+coverage_scope+resource_budget+timeout+parallelism+environment_codes+evidence_root+status+introduced_at_utc+retired_at_utc+lineage. FILES:a suite may contain many files and native-language unit runners;cross-language integration remains pytest-owned. SUPPORT-ARTIFACTS:test,diagnostic,startup and one-time scripts obey language,line,ownership and security rules but do not each require independent runtime identity,health contract,sovereign chain or release pipeline unless they launch a persistent/privileged/independently deployable runtime. EXECUTION:save runs focused tests;precommit affected suite;integration/release required aggregate gates. OWNER:maintenance sub-sovereign centrally manages suite records;module owner supplies cases;executors run tests.\nFORBID:multiple canonical suites per module+one physical test file claimed as whole suite+framework equals suite identity+support script forced into full runtime governance without trigger+diagnostic mutating production state+one-time script becoming recurring service+missing native unit runner+integration outside pytest.\nA shared integration fixture belongs to a registered test-infrastructure module and may be referenced by many suites without becoming a second suite.', E'44e431f54bf5207b66753430c15d06bd2a5807c1ad7f8382e4b2466e8b0b06f9', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B104', E'CODEX_MODULE_MAINTENANCE', E'CODEX_SYSTEM_RELIABILITY_SPECIAL_LAW', E'health-contract-machine-verifiable-schema', E'health-contract-machine-verifiable-schema\nSCHEMA:health_contract_id+schema_version+module_code+owner+runtime_identity_requirement+generation+dimensions+required_signals+signal_types+units+source_codes+sampling_or_event_mode+freshness_deadline_ms+warning_thresholds+failure_thresholds+hysteresis+debounce+dependency_codes+aggregation_rule+degraded_capabilities+recovery_objective+security_classification+contract_hash+effective_at_utc+status+lineage. SIGNAL:{signal_id,contract_id,module_code,runtime_identity-or-null,generation-or-null,dimension,value,unit,observed_at_utc,received_at_utc,sequence,source_code,quality,content_hash,correlation_id}. VALIDATION:JSON/typed envelope must exactly validate required fields,type,unit,range,time,generation,sequence and source;unknown required field/type/unit is contract-incompatible. Lightweight support artifacts use runtime_identity_requirement=NONE unless B110 SUPPORT-ARTIFACT-ESCALATION triggers.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:free-text-only health+implicit units+missing freshness/generation+threshold in checker source instead of contract+unknown signal counted healthy+support script forced to fabricate runtime identity+schema change without successor/version.\nOptional diagnostic fields are allowed only in a versioned extension map and never affect health unless promoted into the schema.', E'2e512caa8fb4e2b3a3b6bb9035d12fa8a39b2c94e8b658c2d202b25996a310e5', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B105', E'CODEX_MODULE_MAINTENANCE', E'CODEX_SYSTEM_RELIABILITY_SPECIAL_LAW', E'health-observation-classification-contract', E'health-observation-classification-contract\nINPUT:B104 validated signals only. PROCESS:deduplicate>order>freshness check>dimension evaluation>dependency attribution>debounce/hysteresis>module classification. OUTPUT:{health_result_id,health_contract_id,module_code,generation,evaluated_at_utc,state,dimension_results,missing_or_stale_signals,dependency_impacts,capability_impacts,evidence_hashes,correlation_id,expires_at_utc}. RULE:failed required signal cannot be averaged away;stale and missing are explicit;dependency failure degrades only declared dependent capability and never changes owner attribution. PROBES:bounded and side-effect-free. OBSERVABILITY:state transition emits one typed event;unchanged samples may aggregate into bounded summaries.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:self-reported final health+single signal whole-module verdict+stale current+dependency fault reassigned to consumer+probe mutation+unbounded polling+score replacing dimension evidence+unchanged sample audit flood.\nA health score may be displayed as non-authoritative monitoring only when the categorical state and every dimension remain visible.', E'1f67a3a867170c7d3cec384822033565ffaf63ab2069b69fb07f33cdb8817c6d', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B106', E'CODEX_MODULE_RUNTIME', E'CODEX_RUNTIME_LIFECYCLE_SPECIAL_LAW', E'execution-pipeline-contract-decomposition', E'execution-pipeline-contract-decomposition\nPURPOSE:replace overloaded B11 with referenced stage contracts. PIPELINE:INTAKE>AUTHORIZE>PLAN>DISPATCH>EXECUTE>VERIFY>PUBLISH. EACH-STAGE has one owner,input schema,output schema,timeout,idempotency,fault codes and receipt type. ROLE:A111 controls decision/dispatch/execution;B101 controls whether stage transitions use pure calls,in-process governed dispatch or transport. VERIFY is independent from EXECUTE;PUBLISH uses information layer only when result crosses a governed boundary. SUPPORT:test,diagnostic,startup and one-time script may use a reduced pipeline INTAKE>EXECUTE>RESULT when it is owner-internal,read-only/non-privileged and leaves no governed state mutation;otherwise full applicable stages are restored.\nFORBID:stage skip on governed mutation+executor self-authorization/self-verification+pipeline labels forcing transport+full runtime pipeline imposed on harmless owner-internal support helper+reduced path with privilege,state mutation,cross-owner I/O or persistent process.\nA deterministic read-only owner-internal probe may combine intake,execute and result in one callable while preserving typed result and bounded timeout.', E'f36a45ff877da04f7e4b10d0147fc494b3c4f702de7f48d53d78a8c1f9c6bf66', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B107', E'CODEX_MODULE_RUNTIME', E'CODEX_INDEPENDENT_TOOL_SPECIAL_LAW', E'independent-tool-complete-modularization-special-law', E'independent-tool-complete-modularization-special-law\nMANDATE:every independent tool is a self-contained modular system inside the registered STANDALONE_TOOLS_ROOT and its own registered tool root;all authored source,UI,backend,contracts,adapters,data access,configuration,assets,tests,diagnostics,maintenance,update and lifecycle code belong to explicit modules with one primary responsibility and declared owner,interface,dependencies,state boundary,fault boundary and test suite. LAYERS:each tool declares entry/UI,application orchestration,domain semantics,infrastructure adapters,transport contracts,state/data and tests where applicable;absent layers are declared not-applicable and are not replaced by hidden cross-tool dependencies. ISOLATION:a tool owns its process,window,lifecycle,private state and bounded degraded mode;its failure,close,restart,repair or update cannot terminate,reset or overwrite the main system or another tool. DEPENDENCIES:cross-module calls use typed internal interfaces;cross-tool or cross-layer traffic uses the canonical information/shared-layer contract;no module imports another tool\'s private implementation. SIZE:every module,file,class and function obeys the registered line limits and self-splits before exceeding them;split modules preserve one public contract and acyclic dependency graph. TESTING:one registered test suite per tool module follows the test-suite schema and is centrally managed by the maintenance sub-sovereign. CONFIGURATION:paths use registered directory codes and dynamic resolution;environment-dependent values use registered environment-variable codes;timestamps alone may be literal under the timestamp article. MIGRATION:a completed modular architecture removes superseded roots,duplicate entrypoints,shadow services and obsolete compatibility implementations only after evidence-preserving migration and governed cleanup. LIFECYCLE:UI close requests orderly cancellation,flush,receipt and termination of that tool\'s backend only.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:monolithic independent-tool implementation+source outside its registered top-level root+hidden shared mutable state+direct import of another tool\'s private code+duplicate backend or entrypoint+one module owning unrelated responsibilities+line-limit bypass by generated wrappers+unregistered script or test+hard-coded physical path+tool failure propagation+UI orphaning its backend+new architecture retaining an active old root.\nGenerated and third-party artifacts remain separately classified and need not follow authored-source module layout, but must stay in registered artifact/vendor boundaries and cannot own domain behavior.', E'769fc50d4761700fbefb1a90658ddbf0b67a15d7110a5dca0c7aec8fdc5d8986', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B108', E'CODEX_MODULE_DIRECTORY', E'CODEX_TOP_LEVEL_DIRECTORY_PATH_SPECIAL_LAW', E'investment-mobile-standalone-root-correction', E'investment-mobile-standalone-root-correction\nCORRECTION:INVESTMENT_MOBILE is a direct child of STANDALONE_TOOLS and resolves to the registered independent-tool root under STANDALONE_TOOLS_ROOT;the former AI_ASSISTANT child location is superseded and is not an active or legacy implementation root. IDENTITY:investment-mobile remains one independent tool and does not become part of the ai-assistant tool. ACTIVATION:architecture activation resolves ARCH_CODE:INVESTMENT_MOBILE through the corrected project architecture directory and must verify the physical root exists before active status. CLEANUP:no compatibility alias,duplicate service,shadow data root or second runtime identity may remain at the former location.\nFORBID:parent AI_ASSISTANT+old nested physical root+two investment-mobile identities+silent locator fallback to former path.\nHistorical evidence may retain the former path only as a superseded non-resolvable value.', E'77bd6f8eab914b83dfe960d117a1faa57eb240c85cb08292ede6e791d4e95d41', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B109', E'CODEX_MODULE_AUDIT', E'CODEX_AUDIT_EVIDENCE_TIME_SPECIAL_LAW', E'lifecycle-lineage-reference-and-multi-predecessor-contract', E'lifecycle-lineage-reference-and-multi-predecessor-contract\nSTATE-PARITY:provision_lifecycle_status.lifecycle_state and provision_lineage.status must agree for every identity at the current generation;transition updates both atomically. reference contract columns are fixed as predecessor_type,predecessor_id,declared_successor_identity,resolved_successor_type,resolved_active_successor_id,resolution_path,status,validated_at_utc and each value validates its namespace. MULTI-EDGE:provision_supersession_edges is authoritative for zero-to-many and many-to-one succession;provision_lineage.supersedes_id is only a compatibility shortcut for at most one primary predecessor and cannot represent complete ancestry. Resolution proves every predecessor edge reaches exactly one active successor without cycles. AUTHORITY-BOUNDARY:provision_supersession_edges is the only current provision-succession source;supersession_registry is non-authoritative for provisions and is limited to legacy sovereign,alias and historical lookup.\nFORBID:lifecycle/lineage drift+shifted reference fields+identity stored in type field+single supersedes_id claimed complete for multi-predecessor succession+orphan/cyclic edge.\nA successor with one predecessor may repeat that predecessor in supersedes_id,provided the edge table agrees.', E'495c67080f538f5da48798a8e5e67c710bc8e7f38e00eb6b24f72359b7484c0d', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B11', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'execution-layer-internal-tiering', E'execution-layer-internal-tiering\nEXECUTION-LAYER-TIERS:dispatch-intake>authorization-and-governance-gate>task-planning>specialized-executor>result-verification>state-event-audit-publication; CONTROL:sub-sovereign; WORK:specialized-module-executor; VERIFY:independent-from-work-step; RESULT:returned-through-information-layer; FAILURE:maintenance-path-only\nFORBID:tier-skip+executor-self-authorize+executor-self-dispatch+work-step-self-verify+direct-ui-to-executor+cross-module-executor-substitution+unrecorded-result\n', E'b631acb7b6ba69e03a53e17d54274671b6ef209db592788ab061db1af4762f11', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B110', E'CODEX_MODULE_TEST', E'CODEX_TEST_VALIDATION_EVALUATION_SPECIAL_LAW', E'executable-module-test-suite-cardinality-clean-successor', E'executable-module-test-suite-cardinality-clean-successor\nSUCCESSOR:B110 supersedes only the cardinality clause of B103. CARDINALITY:each executable architecture module has exactly one canonical logical aggregate test suite; structural-only modules carry explicit not-applicable evidence. DYNAMIC-COMPOSITION:the owning core independently changes test and audit membership,order,enablement and tuning. SOLE-CONSTRAINT:applicable programming-language rules. No unanimous five-core consent or other approval is required. Suite composition is non-authoritative operational configuration; CSharp TestSuiteOrchestrator remains the sole orchestration interface.\nFORBID:multiple-canonical-suites-per-module+five-core-unanimity+extra-approval-gate+language-rule-violation+suite-composition-as-authority\nShared test infrastructure may be referenced without becoming another module suite.', E'5490a827d5329bd569dd32e79971d2c68aa5ec7ce9dc76eda0c2fc4d11969af0', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B111', E'CODEX_MODULE_RUNTIME', E'CODEX_STARTUP_CONTROL_SPECIAL_LAW', E'desktop-exe-sole-main-system-user-startup-entry', E'desktop-exe-sole-main-system-user-startup-entry\nMAIN-SYSTEM-USER-ENTRY:MAIN_SYSTEM_DESKTOP_EXE is the sole production user-facing startup entry and resolves dynamically through the registered architecture/directory identity; FORM:the entry is the governed desktop native executable, while a desktop shortcut is only a locator to that same identity and never a second entry; FLOW:desktop EXE>visible UI shell>typed SYS_GPTBRIDGE_START intent>information layer>startup-sub-sovereign management>registered module executor; LAUNCHER:LAUNCHER is the internal startup-core boundary contained by MAIN_SYSTEM and is not the user-facing entry,not an independent executable authority and not a second startup path; BOUNDARY:the desktop EXE may create or focus the UI and submit typed intent only; it cannot decide startup,perform governance checks directly,wake a backend directly or own runtime state; PROFILE:CLI,service,test,development and maintenance entry profiles are separately registered non-production interfaces and cannot claim main-system user-entry status; IDENTITY:no physical EXE filename or absolute path is normative; permission-governed resolution binds MAIN_SYSTEM_DESKTOP_EXE to one current artifact,content hash,platform,generation and SYS_GPTBRIDGE_START contract; LIFECYCLE:single-instance,generation correlation,ten-second startup deadline,UI-close backend termination and audit receipt remain controlled by B27+B28+B30+B51.\nFORBID:launcher-as-user-entry+script/VBS/CLI/service/dev-host as production user entry+multiple production EXE entries+direct EXE-to-backend wake+renderer startup authority+hardcoded physical EXE path in law+shortcut treated as authority+entry bypass of information layer or permission validation.\nA signed installer may create or update a desktop shortcut only as a locator to MAIN_SYSTEM_DESKTOP_EXE; registered test/maintenance profiles remain non-production and isolated.', E'5c931aac0916a81489efdac75adc000204ba9b340584231b70fce40909185b11', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B112', E'CODEX_MODULE_RUNTIME', E'CODEX_MAIN', E'system-runtime-canonical-id-and-display-name-successor', E'system-runtime-canonical-id-and-display-name-successor\nSUCCESSOR:B112 completely supersedes B65 and supersedes only the runtime-identity naming clause of A104. CANONICAL-ID:system-runtime-sovereign is the immutable machine identity,lineage key,authority reference and value used by current law,architecture,directory,command,fault,manual,test and audit records. DISPLAY-NAME:runtime-sovereign is the canonical human-facing display name and never an identity,alias selector or separate authority. Historical aliases remain non-active evidence only. Runtime decisions remain decision-only and execution remains delegated through the system sub-sovereign to the module execution layer.\nFORBID:runtime-sovereign stored as canonical ID+system-runtime-sovereign treated as obsolete ID+parallel authority created from display name+display alias expanding authority.\nInterfaces may display runtime-sovereign while every machine payload preserves system-runtime-sovereign.', E'0965d411475c8a8bce667950beab1a392f0fc1ebd3c4ef774ee9cc804b85e77c', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B113', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'current-manifest-hash-succession-and-directory-derivation-contract', E'current-manifest-hash-succession-and-directory-derivation-contract\nCURRENT-DERIVATION:codex_internal_module_manifest is rebuilt from current membership,lifecycle,classification,successor resolution,search documents and per-module dependency edges;current metadata is a derived projection of the sealed module and search manifests and cannot be independently maintained. HASH-SEPARATION:module_dependency_hash binds only one source module edges;dependency_graph_hash binds the complete ordered DAG and cycle evidence. DIRECTORY-FRESHNESS:all active codex_internal_module_directory rows use the current generation in revision and version_identity while introduced_version is immutable. SUCCESSION:provision_supersession_edges is the sole current provision-succession authority;supersession_registry is legacy sovereign/alias/history resolution only and cannot produce a current provision successor. COVERAGE:directory coverage rows with scope_kind=meta-registry are excluded from master-directory cardinality and bind registry infrastructure rather than directory identities.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:hand-maintained current metadata+aggregate DAG hash copied into module hash+stale module directory generation+legacy registry selecting current provision successor+meta-registry counted as orphan directory.\nHistorical manifests,metadata and legacy succession rows remain immutable non-current evidence.', E'0895e8e410d4071105b845d465d10bb68f4885f83c502a858a97f7fb97146e1f', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B114', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'current-topology-and-startup-consolidation-successor', E'current-topology-and-startup-consolidation-successor\nSUCCESSOR:B114 completely supersedes A35,B61,A73 and A89 for current topology and startup interpretation. TOPOLOGY:the current roster is generated from active identity lifecycle and B162 and contains exactly decision-core,permission-core,runtime-core,automation-core and xingcheng-assistant as peer cores; XINGCHENG remains a separate native-model service identity outside the independent-tool roster. Historical sub-sovereign rows are lineage-only and excluded from every current roster,parent,route and ownership projection. STARTUP:MAIN_SYSTEM_DESKTOP_EXE>visible UI>SYS_GPTBRIDGE_START>information layer>runtime-core governed startup modules.\nFORBID:retired-sub-sovereign-in-current-topology+historical-parent-as-current+legacy-startup-owner+roster-derived-from-stale-metadata\nHistorical topology remains immutable evidence and is excluded from current roster generation.', E'442f43bbbea4fb154f93f43c9db21fe832b77092b40e5a385b2a945022b594fe', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B115', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'全專案架構圖', E'全專案架構圖\n法典、主權、資訊層、主系統、資料權威與七個獨立工具依 Architecture Registry 建立唯一現行拓撲。\n禁止由圖形自行創設權限或身分。\n無。', E'82539b6ac9a83d9a9028b1857c77126c465edfb705f35eccc308b7b442f23215', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B116', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'程式語言架構圖', E'程式語言架構圖\n全專案程式語言只能透過已登記、版本化且具型別的 ABI、IPC、Information Channel 或資料契約互通；正式 owner 依 B4、B35、B166、B170，Python 僅限三域。\n禁止未登記跨語言呼叫、語言 owner 重複、Python 擴張至正式應用 Runtime、退役技術重新成為 active consumer。\n無。', E'827e3c1b3ea7d2811e3ffaacad9972f8e6a05fba0da21c6cce883c500e888914', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B117', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'七個獨立工具架構圖', E'七個獨立工具架構圖\n現行獨立工具只有 AI_ASSISTANT、AI_COLLABORATION、FILE_SORTER、INVESTMENT_MOBILE、LOCAL_MODEL、VAULTLY、MODEL_DIALOGUE。\n禁止增加第八個工具、把星澄或 System Rescue 列為工具、恢復 Global Cleaner。\n無。', E'958c17fc6cf03b03cf9b60e0a02ca8ea3443ad52062d2a5782e8b41ddb165323', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B118', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'架構圖與法典同步法', E'架構圖與法典同步法\n五個共通架構圖與七個工具架構圖必須綁定現行法典版本、來源條文、內容雜湊與唯讀狀態。\n禁止 stale、missing、hash mismatch 或未登錄架構圖。\n無。', E'afefc09547de2d14ca5bfd5bf6ff7c54e1dc65b7623ca01fc98baadae9069e55', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B119', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'歷史工具拓撲更正', E'歷史工具拓撲更正\n本條已由 D129 與本次 successor 取代，只保留歷史 lineage。\n禁止作為 current authority。\n無。', E'2e537679eceb27377f2742919853d062ecdf69e70c42bc361e7ec89c8266fd42', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B12', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'complete-codex-traceability', E'complete-codex-traceability\nEVERY-PRINCIPLE/ARTICLE/EDICT:lineage-record-required; LINEAGE:provision-type+id+introduced-by+supersedes+status+content-hash; RESULT:any-provision-reconstructs-origin+version+ordered-change-chain\nFORBID:untracked-provision+missing-origin+missing-content-hash+orphan-history+silent-replacement+lineage-rewrite\n', E'95f480edd7e9ba2dbe0a84336e3a985a67009efde5c9d719c134b02c0bf402b8', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B120', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'歷史星澄工具分類更正', E'歷史星澄工具分類更正\n本條已由後續 successor 取代；星澄不是獨立工具。\n禁止作為 current authority。\n無。', E'4d624c6fefbcc70e4688b95ebaa4469a30e8db2b904403bc9f25118d0231a0be', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B121', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'七工具名冊法', E'七工具名冊法\n七工具 exact set 為 AI_ASSISTANT、AI_COLLABORATION、FILE_SORTER、INVESTMENT_MOBILE、LOCAL_MODEL、VAULTLY、MODEL_DIALOGUE。\n禁止 subset、superset 或別名增生。\n無。', E'6df9566bd2c74d4f29271367891df8a34a6841db060a8cc26d27dca2fe298ab6', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B122', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'七工具與機構拓撲完整整改 successor', E'七工具與機構拓撲完整整改 successor\nSUCCESSOR:B122 完整取代 B9 的 module-execution-layer 名冊語義，並控制現行工具拓撲。MODULE-EXECUTION-LAYER=MAIN_SYSTEM internal execution services plus exact seven independent tools. INDEPENDENT-TOOLS=AI_ASSISTANT|AI_COLLABORATION|FILE_SORTER|INVESTMENT_MOBILE|LOCAL_MODEL|VAULTLY|MODEL_DIALOGUE. SYSTEM_RESCUE=MAIN_SYSTEM internal service only. GLOBAL_CLEANER=retired+non-executable. 星澄=independent-privileged-institution，排除於 system module layer、independent-tool set、LOCAL_MODEL child、MODEL_DIALOGUE child 與 MAIN_SYSTEM internal service。STAR_DIRECTORY parent=XINGCHENG_INSTITUTION_ROOT。\n禁止：module self-governance、cross-owner execution、retired tool execution、System Rescue 工具化、星澄工具化、工具數量不等於七、物理路徑推導治理 parent。\nGlobal Cleaner 歷史 identity、lineage 與 audit 可保留，但不得啟動、路由、核發新權限或恢復 current 身分。', E'880a6e9e2188824e9d7353583f974db04012b616450978228065cd4955a59fbb', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B123', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'七工具與機構拓撲完整 successor', E'七工具與機構拓撲完整 successor\nSUCCESSOR:B123 完整取代 B9 與 B122 的現行拓撲效力。MODULE-EXECUTION-TOPOLOGY=MAIN_SYSTEM-internal-services+EXACT-SEVEN-INDEPENDENT-TOOLS。INDEPENDENT-TOOLS=AI_ASSISTANT|AI_COLLABORATION|FILE_SORTER|INVESTMENT_MOBILE|LOCAL_MODEL|VAULTLY|MODEL_DIALOGUE。SYSTEM_RESCUE=MAIN_SYSTEM-internal-service-only。GLOBAL_CLEANER=retired+non-executable。XINGCHENG=independent-privileged-institution+not-tool+not-system-module+outside-independent-tool-set。STAR_DIRECTORY parent=XINGCHENG_INSTITUTION_ROOT。\nFORBID:independent-tool-count-not-seven|Xingcheng-as-tool|System-Rescue-as-independent-tool|Global-Cleaner-reactivation|unregistered-eighth-tool|tool-identity-alias-substitution。\n歷史 identity、lineage、audit、past test/fault/path evidence 保留，但不得恢復現行效力。', E'1e562642dbc2d03c355c9c77e896b21d2004891e81bad3c75388da9475cd6df1', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B124', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'retirement-architecture-and-execution-deadline-parameters', E'retirement-architecture-and-execution-deadline-parameters\nSTARTUP:PARAM[STARTUP_COMPLETE_DEADLINE_MS];TEST:PARAM[MANDATORY_TEST_SUITE_DEADLINE_MS];AUDIT:PARAM[INDEPENDENT_AUDIT_FLOW_DEADLINE_MS];RETIREMENT:label>zero-consumer>rollback-expiry>purge;ARCHITECTURE:registry-first+projection-sync\nFORBID:duplicated-literal-deadline+retired-component-active+projection-as-authority\nNormative cryptographic constants, identity formats and closed status enums remain explicit when variability would weaken interoperability or safety.', E'0f0f3e5aa1eb4f49248b4beb979ae52fc83fb1c0289e97bd522347cd05b6f302', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B125', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'獨立工具五秒生命週期與本地模型選擇啟動條例', E'獨立工具五秒生命週期與本地模型選擇啟動條例\nB125 補充 B117、B123、B124 與 C102。七個獨立工具的每次啟動及每次關閉各自必須在 5 秒內完成，並回報可驗證的最終狀態；逾時必須終止當次操作、標示失敗並 fail-closed，不得將仍在啟動、仍在關閉或未知狀態宣告為成功。LOCAL_MODEL 預設不得啟動，也不得加入系統預設啟動、預熱、自動復原啟動或背景自動重啟。主畫面必須提供 LOCAL_MODEL 專用啟動與關閉開關；只有使用者明確操作或綁定該次操作的有效單項許可才可啟動。關閉後必須維持停止，直至下一次明確許可。 WINDOW-CLOSE:closing the final application window of any independent tool is an explicit typed shutdown request for that tool generation. The host drains in-flight work according to contract,checkpoints required state,invokes the registered backend shutdown,closes owned sessions and verifies the complete owned process tree has exited before reporting stopped. A timeout or unverifiable exit is failure and enters the registered bounded termination path;detached backend continuation is forbidden. Closing one tool never stops the main system or another independent tool. MAIN-SYSTEM-INDEPENDENCE:closing the main-system final window never closes,stops or kills any independent tool UI,backend or owned child process. Each tool preserves its own lifecycle and may enter a declared disconnected or bounded degraded mode until the main system returns. Only that tool final-window close or its own separately authorized stop request invokes its backend shutdown. MODEL-DIALOGUE-INDEPENDENCE:model-dialogue is an independent self-hosted local-LLM tool with a separately registered root;host_tool_id=model-dialogue and runtime_owner_tool_id=model-dialogue. Its identity group holds independent-tool-start-and-stop for its own process only. model-dialogue may start and remain available while LOCAL_MODEL is stopped;starting model-dialogue does not itself start LOCAL_MODEL. A submitted star_chat request may create a separately governed on-demand activation request for XINGCHENG through the registered route.\nFORBID:tool-start-over-5-seconds|tool-stop-over-5-seconds|timeout-as-success|unknown-lifecycle-as-ready|local-model-default-start|local-model-background-autostart|local-model-restart-after-explicit-stop|shared-switch-substitution。+independent-tool-window-close-without-backend-shutdown+detached-tool-backend-after-final-window-close+stopped-status-before-process-tree-exit-verification+cross-tool-cascade-shutdown+independent-tool-stop-caused-by-main-system-exit+cross-identity-process-tree-termination\n系統啟動的 10 秒總時限不放寬任何工具的 5 秒個別時限；已在執行的受治理任務仍須依關閉契約安全終止。', E'3496b1c1c7e7b3c3ea081f587513e5bf5d39156fd8b8fe2546e2dc589fa386e8', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B126', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'模型對話星澄優先自動路由條例', E'模型對話星澄優先自動路由條例\nB126 補充 B123、B124、C102 與 B125。獨立工具「對話」執行本地 LLM 自動路由時，預設第一候選固定為星澄。只有星澄未啟動、不可用、能力不符合請求或治理邊界拒絕時，才可依已登錄且可審計的備援順序轉用其他模型。星澄優先是路由順位，不構成啟動授權；不得藉此繞過 LOCAL_MODEL 預設關閉、使用者啟動開關、權限、資源與網路邊界。每次改走備援必須記錄原因、候選狀態、選定模型與 correlation identity。\nFORBID:non-xingcheng-default-first|silent-fallback|fallback-without-reason|routing-as-start-permission|local-model-default-off-bypass|unregistered-model-route。\n使用者明確指定其他已登錄模型時可覆寫單次路由順位，但不得改變系統預設值或擴張權限。', E'43a25e54d8f08b184d4c91b22864a88c5b3e14ad450382a7bcd3a9bc9a52dd03', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B127', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'外部協作雙欄使用者介面條例', E'外部協作雙欄使用者介面條例\nB127 補充 B117、B118 與 C102。外部協作主工作區固定採雙欄配置：左側占可用工作區三分之一，承載協作輸入窗口、提示操作與內建 AI 清單；右側占三分之二，專供受治理內建瀏覽器網頁畫面。瀏覽器邊界必須隨視窗尺寸同步，且不得覆蓋左側控制區。窄螢幕得改為單欄，但桌面尺寸不得改變一比二的主要比例。\nFORBID:browser-full-window-overlay|left-control-obscured|desktop-ratio-drift|external-browser-substitution|unregistered-web-surface。\n診斷、狀態與導覽控制得置於工作區上方，但不得改變左右欄的權責與比例。', E'7876a10ca4a74e2d18a2d8efe0201e18e9b6db09d81b9a1a48dbb9c879b10e7b', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B128', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'外部協作介面收斂條例', E'外部協作介面收斂條例\nSUCCESSOR:B128 取代 B127 的現行介面效力。外部協作最上方主卡片必須採緊湊高度，並承載完整內建 AI 名單、選取、狀態、開啟、登入與 URL 設定；禁止另設 AI 名單卡片。主工作區左側四分之一承載協作輸入與結果，右側四分之三專供受治理內建瀏覽器網頁畫面。整體狀態、選取 AI、回覆狀態、內建瀏覽器四張診斷卡及登入或人機驗證狀態卡不得顯示。\nFORBID:separate-ai-list-card|diagnostic-summary-cards|login-prompt-status-card|oversized-top-card|desktop-one-third-two-thirds-layout|browser-control-overlap。\n窄螢幕得切換單欄；操作錯誤仍可在相關控制元件就地呈現，但不得恢復已刪除的狀態卡。', E'0ae366615b7a08c5e284ed75eb02f0002aae7bef49e26b3865a592837fbd8b88', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B129', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'外部協作需求卡片退役條例', E'外部協作需求卡片退役條例\nSUCCESSOR:B129 取代 C103 的需求呈現條款。外部協作介面不得建立或顯示任何需求卡片；最上方整合區只保留非卡片式協作輸入，左側結果區只顯示各 AI 回覆。協作內容仍須由系統自動記錄，不得以歷史需求卡片作為記錄介面。\nFORBID:request-card|request-history-card|legacy-request-composer-card|request-card-restoration。\n錯誤得在輸入控制元件旁就地顯示，但不得形成需求卡片。', E'b7d06a121f4e46d40c00e519cdcf8d9181e007356c8104b93a3ee3ecbfda45bc', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B13', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'module-execution-native-source-launch', E'module-execution-native-source-launch\nMAIN-SYSTEM-TOOLBOX:select-governed-source-runtime-from-manifest.runtime+manifest.request_channel; SOLE-LAUNCH-ENTRY:request-channel-runtime-entry; EXECUTABLE-MODE:disabled-by-default+not-fallback; EXCEPTION:explicit-successor-codex-provision-only\nFORBID:internal-executable-startup+implicit-executable-fallback+launcher-direct-tool-spawn+manifest-bypass\n', E'af13a906b8584225d92cfdf91efc30b673513a6497aa76f6929ee55a07bfea4f', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B130', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'星澄模組行數豁免條例', E'星澄模組行數豁免條例\n星澄及其身分、人格、自我學習、自動編程、自動修復、自我升級與其他明確登錄為星澄所有的內部模組，不適用 E160、B93 至 D97 所定的一般模組有效行數上限；不得僅因該等模組超過模組行數門檻而判定違規、阻擋合併、要求拆分或建立模組分解工作。來源行數量測仍可作為非阻擋式維護資訊，但結果必須標記 XINGCHENG_MODULE_LINE_LIMIT_EXEMPT，且不得轉換為發布拒絕或修正義務。本豁免只涵蓋模組層級行數限制，不解除函式、方法、類別、公開入口、可呼叫項目、依賴邊界、權限、安全、測試、審計、效能、證據及可維護性要求。\nFORBID:xingcheng-module-line-count-release-block|xingcheng-line-count-mandatory-split|xingcheng-line-count-decomposition-job|exemption-extension-outside-xingcheng|exemption-as-security-or-test-waiver。\n星澄明確移交給其他所有者的模組，自移交生效版本起不再適用本豁免；共同擁有或所有權不明時不得適用。', E'e9764c7900d33cca58c9e12c88c3aa9119b608358887919c150f6ae205117215', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B131', E'CODEX_MODULE_FOUNDATION', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'language-positioning-and-responsibility', E'language-positioning-and-responsibility\nLANGUAGE-RESPONSIBILITY:B166 is the sole current language-allocation and UI-stack controller;this provision retains only the principle that each capability has one owner,one typed boundary and no authority is created by language choice\nFORBID:Python-test/audit/verification/release/push+Python-production-runtime+Python-mechanical-work+duplicate-owner+second-orchestrator+second-audit-engine+language-role-substitution+CSharp-bypassing-governance+C/C++-changing-governance-policy\nNo exception permits Python, NumPy, JAX or pytest in a formal test suite,audit suite,verification gate,release gate or push gate.', E'45fb24d26128da3cef01908626c44449c4528c4419d14bc0fe7964c79b2200da', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B132', E'CODEX_MODULE_XINGCHENG', E'CODEX_MODEL_RESOURCE_GPU_SPECIAL_LAW', E'gpu-acceleration-separate-track', E'gpu-acceleration-separate-track\nGPU-ACCELERATION:C++23 owns the sole native GPU training and inference path behind the stable C ABI;CPU and GPU executors consume the same versioned model-artifact and numerical contract;FSharp owns correctness evaluation;EVIDENCE:artifact compatibility+bounded numerical tolerance+resource/deadline/cancellation+failure classification;FAILURE:unavailable or uncertified GPU execution uses only a registered C++23 CPU path or fails closed;retired frameworks and bridges have no reference,executor,fallback or acceptance role.\n\n', E'5b0728f982183886cc63c60caed22ec95a73a3e93921c20a1cdb0b0471b222b0', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B133', E'CODEX_MODULE_XINGCHENG', E'CODEX_MODEL_RESOURCE_GPU_SPECIAL_LAW', E'xingcheng-model-architecture-moe', E'xingcheng-model-architecture-moe\nBOUNDARY:Xingcheng\'s concrete model architecture - topology,expert/layer/dimension counts,routing scheme and precision tiers - is owner-local implementation rule and is never Codex law;the Codex binds only evidence invariants.\nACCEPTANCE:whatever architecture the owner ships must prove its declared health invariants through current native evidence before promotion;for routed/sparse designs that includes balanced expert load,utilization and non-collapse;dense and sparse checkpoints both remain valid for compatibility and rollback when their evidence gates pass.\nIMPLEMENTATION:architecture execution details (expert weight management,grouped GEMM,routing kernels) are implementation work under registered Codex contracts (P3d/P3f,R5),not normative text.\n\n', E'bc7878e7d341feede2d87f514fad833ac0778297be5d04d45ca624e2d4fe2393', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B134', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-unified-model-maturity', E'xingcheng-unified-model-maturity\nBOUNDARY:XINGCHENG model maturity is certified only by current executed evidence across consecutively stronger capability classes;parameter count and self-claims never establish maturity;OWNER:XINGCHENG owns the detailed probes,levels,datasets and metrics as non-authoritative owner-local rules;ACTIVATION:first failed,missing or blocked required class caps certification and denies unsupported promotion.\nFORBID:parameter-count-as-maturity+self-certified-level+promotion-with-missing-class+Codex-fixed-probe-list-or-threshold\n', E'ada184881d03aa5fae288ae9a00245ed7eb4568a34cf51fcf5565ccdc32f27ac', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B135', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-model-training-tiers', E'xingcheng-model-training-tiers\nXINGCHENG-MODEL-SCALE:every publishable Xingcheng model configuration has no total_parameter_count lower bound and has a 20B inclusive total upper bound;any scale at or below 20B may be used when its actual capability,performance and resource conditions are satisfied;FULL-CAPABILITY-BASELINE:a full-capability baseline has no parameter-count lower bound;PARAMETER-COUNT-SEMANTICS:parameter count establishes only the upper scale and resource boundary and never proves maturity,quality or capability;all capability,quality,compatibility,resource and rollback gates remain independently mandatory;OWNER:XINGCHENG may adapt architecture,density,MoE activation and internal tiering below the 20B upper bound and within current Codex authority,permission and resource limits.\n\n', E'110bb099d93223988d10050ac13468a67c7cd245d9eb7ce88ad4dcfb27b1ca5f', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B136', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-small-model-training-baseline', E'xingcheng-small-model-training-baseline\nBOUNDARY:XINGCHENG training candidates require reproducible evidence of learnability,checkpoint integrity,generalization,resource compliance and non-memorizing generation before promotion;OWNER:XINGCHENG owns concrete training checks,metrics,datasets,thresholds and schedules as owner-local rules;FAILURE:missing or regressed evidence preserves the active artifact.\nFORBID:Codex-owned-training-checklist+Codex-fixed-metric-or-threshold+activation-without-current-evidence+active-artifact-overwrite-on-failure\n', E'caf25f4a1a9ebd56ae6d156a83be900df84ee1d3c4a54e2910c42a0f431c7b54', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B137', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-primary-goal-command-and-chat', E'xingcheng-primary-goal-command-and-chat\nRESPONSIBILITY:XINGCHENG owns command understanding and user dialogue within its registered model scope;BOUNDARY:language coverage,prompt formats,datasets,quality thresholds and routing heuristics are owner-local implementation rules;AUTHORITY:model output remains evidence or a proposal and never creates permission,decision or execution authority.\n\n', E'98340b9b89f47ee07b80737be5572f6273ba83369d009fd346b498630205665a', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B138', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-medium-base-scaling-strategy', E'xingcheng-medium-base-scaling-strategy\nBOUNDARY:model scaling is permitted only after the current smaller configuration has verified quality,compatibility,resource and rollback evidence;OWNER:XINGCHENG owns concrete sizes,ordering,datasets,comparison metrics and stopping criteria as owner-local rules;PROHIBITION:parameter count alone never proves capability or authorizes promotion.\n;FORBID:deployment-version+benchmark-result+model-threshold+port+path+operational-tunable-as-permanent-Codex-literal\n', E'9f1ec924b0d7ef91de12b26d3e1fc12b61324afd8b63c6cfa89a76a888ee13af', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B139', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-moe-training-quality-control', E'xingcheng-moe-training-quality-control\nQUALITY-CONTROL:C++23 native training and production inference jointly own the versioned model-artifact contract inside Xingcheng;training evaluation and correctness analysis run through the registered eval-verdict contract under the B81 language-ownership lanes - the F# verdict lane remains bound only until migrated and retired;Python,JAX/XLA and NumPy are retired with zero training or artifact role;BOUNDARY:concrete probes,metrics,datasets and thresholds are Xingcheng owner-local rules;ACCEPTANCE:current native evidence must establish the shipped architecture\'s declared health invariants - for routed/sparse designs that includes routing balance,expert utilization and non-collapse - plus gradient coverage,artifact integrity and inference compatibility before promotion;FAILURE:missing or contradictory evidence denies promotion.\n\n', E'bbaf97bc91f653704028a12c520ce859dc7f8dc7e75b28f774b83603835e07a0', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B14', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'loaded-governed-backend-module-runtime-reexecution', E'loaded-governed-backend-module-runtime-reexecution\nSUBJECT:already-loaded-governed-backend-module; CLASSIFICATION:in-process-runtime-reexecution-not-source-version-change; AUTHORIZATION:codex-path; SCOPE:main-system-governed-source-roots-only; EXCLUDE:codex+data+directory+manifest+independent-tools; AUTOMATION:observe+debounce+rate-limit; VERSION-FREEZE:equivalent-protection; VERSION-IDENTITY:unchanged; CONDITION:current-governed-version-identity+integrity-boundary-remain-valid\nFORBID:classify-authorized-in-process-reexecution-as-unregulated-runtime-source-change; FORBID:source-write+version-identity-change+excluded-scope-reload+authorization-bypass+unbounded-watch-loop+debounce-bypass+rate-limit-bypass\n', E'10556a8c078478fc47c2f8a7c521acea6d369c53c392623f11a4c941f0e88fc9', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B140', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-native-dialogue-training', E'xingcheng-native-dialogue-training\nRESPONSIBILITY:XINGCHENG owns dialogue training for its native model;BOUNDARY:roles,markers,dataset categories,curriculum,templates and quality heuristics are owner-local rules;ACCEPTANCE:current native evidence must establish context continuity,instruction adherence,tool-result handling and safe termination before activation.\n\n', E'de7d72410f9bb025baf62f2e1168f7165254105842c9f8c77c2f55b0c5c4d7ae', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B141', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-inference-artifact-consistency', E'xingcheng-inference-artifact-consistency\nTRAINING-INFERENCE-COMPATIBILITY:C++23 is the sole native producer and consumer of Xingcheng training and inference artifacts;FSharp evaluates compatibility and correctness through the registered contract;Python,JAX/XLA and NumPy are retired and produce no model artifact,tokenizer,configuration or evidence;COMPATIBILITY:artifact schema+tensor shapes/dtypes+tokenizer/configuration+golden inputs+logit/token/perplexity tolerances;REFERENCE:no retired framework is a reference,executor,fallback or acceptance source;FAILURE:incompatible or unverified artifacts are rejected fail-closed.\nFORBID:Python-or-JAX-training-artifact+Python-or-PyTorch-production-inference+Triton-to-PyTorch-production-fallback+bit-exact-cross-device-requirement+artifact-load-without-compatibility-evidence+retired-framework-reference\n', E'8a41a517452c21109ff48034bf315d9bee0178e2283d2e822f2d547ae1ca44f0', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B142', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-native-capability-evaluation', E'xingcheng-native-capability-evaluation\nBOUNDARY:formal native model evaluation must cover every registered capability category,bind the evaluated artifact and dataset generation,exclude training overlap,and compare candidate performance with the active artifact;OWNER:XINGCHENG owns individual probes,fields,metrics and suites as owner-local rules;FAILURE:any required regression or missing evidence denies publication.\n\n', E'a69dfea926c5c43d076e8290442d7e4ea38de2bcefcdb23eaa3e1fc776366032', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B143', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-weight-evolution', E'xingcheng-weight-evolution\nModel weight evolution without direct overwrite of the active weights: stage objects Candidate Model, Training Checkpoint, Evaluation Result, Verified Model, Active Model; flow: current model -> create candidate -> train -> save candidate weights -> integrity verification -> capability evaluation -> inference consistency check -> release gate -> active model.\nRelease follows the existing GPTBridge certification, release and activation rules (lifecycle and adapter registry; automatic_weight_replacement stays 0). A training failure keeps the current official model; rolling back to uncertified old weights is forbidden.\nlifecycle (11 states, weights never overwritten) and the adapter registry exist; the five stage objects and the end-to-end eight-step evolution drill are not formalized (gap G44, Phase 7B).\n\n', E'e848516346371e72c5a48df208e8899eca8c79004971e566671ff3f40e769106', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B144', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'gptbridge-system-convergence', E'gptbridge-system-convergence\nFull-system convergence without new sovereigns or a new supreme control center: close the loops (decision/execution/observation/verification/record/repair/re-verify; code-change/test/release/verify/blue-green swap/observe/next-update) across ten areas: blue-green backend update with active-generation fencing, unified runtime state (run states plus capability states with existing fail-closed integrity checks preserved), preventive maintenance inside the existing five maintenance sub-modules with bounded retries, SQL interactive/background/migration workload classes, RAG incremental indexing with RECONCILE_REQUIRED and periodic reconciliation, model resource scheduling by role, Git worktree integration pipeline with cross-module contract tests, unified contract compatibility with separated version axes, a process registry that only terminates owned and authorized processes, and a project performance baseline measured before optimizing; plus the 24-hour end-to-end acceptance scenario.\nNo parallel supreme control center and no new sovereigns; single-instance work is fenced by the active generation; UI layers (renderer/preload/main) are validated separately from backend releases; data-integrity checks keep the existing fail-closed codex rules.\nregistered Codex contract chapter 10 records the plan; the P0-1 inventory and the P0-2..P0-6 implementations do not exist yet (gaps G46-G51).\n\n', E'2b9dd1f91c9a05b713b4934722678f3a62683214b2360ca9a75d51912f07084b', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B145', E'CODEX_MODULE_RUNTIME', E'CODEX_MAIN', E'gptbridge-unified-task-lifecycle', E'gptbridge-unified-task-lifecycle\nOne task lifecycle for every work-producing feature (Chat, Coding, RAG, Git, File Sorter, AI Collaboration, Maintenance, Updater): CREATED, VALIDATED, AUTHORIZED, QUEUED, RUNNING, COMPLETED with error branches FAILED, CANCELLED, TIMED_OUT, RECOVERING and the added state INTERRUPTED (the task itself did not necessarily fail; the executing backend was interrupted or replaced). Identifiers: Task ID, Request ID, Operation ID, Execution Receipt, Idempotency Key, with the Operation ID surviving backend updates.\nInterrupted tasks are verified by maintenance (files and Git state) before any recovery, and RUNNING tasks must not simply be re-executed because side effects may already have completed (for example a successful Git commit); exactly-once external side effects are never promised - the implementable target is persistent tasks, idempotent operations and verify-then-recover; the design integrates the existing codex receipt/obligations architecture and must not create a second audit system.\nregistered Codex contract section 10.16 records the lifecycle; the unified state machine and identifiers are not implemented (gap G54).\n\n', E'850442d972d88126f74997e433485b1bdce8fc682c4d51a9f15935811f96084d', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B146', E'CODEX_MODULE_RUNTIME', E'CODEX_MAIN', E'gptbridge-runtime-execution-lease', E'gptbridge-runtime-execution-lease\nRuntime execution lease inside the existing runtime/maintenance framework (no new sovereign) so that blue-green backends cannot duplicate singleton work: only the backend holding a valid lease (backend_generation, lease_type, holder, expires_at, fencing_token) may execute scheduled maintenance, cleanup, backup or migration; handover is new-version health pass -> stop new tasks to A -> revoke A eligibility -> grant B -> gateway cutover.\nThe lease needs a single authoritative source and atomic handover (two processes writing active=True in their own memory is forbidden); execution endpoints (database writes, scheduling, backup) must verify the fencing token so a recovered old process cannot run expired work; this must be implemented before the blue-green update goes live.\nregistered Codex contract section 10.17 records the lease design; no lease table, authority or fencing verification exists (gap G55).;MUTABLE-VALUES:resolve-current-values-from-owner-versioned-contract-or-registry;CODEX:retains-owner+boundary+prohibition+acceptance-dimensions-only\n;FORBID:deployment-version+benchmark-result+model-threshold+port+path+operational-tunable-as-permanent-Codex-literal\n', E'b85a44f450ca395ca8dc730aef0efcb46d9f22a436e4422cfa3f5ad44f1928f5', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B147', E'CODEX_MODULE_RELEASE', E'CODEX_MAIN', E'gptbridge-dev-runtime-separation', E'gptbridge-dev-runtime-separation\nDevelopment source and production runtime are separated: coding agents edit the working tree while the production system executes from runtime/releases/release-A or release-B. A release must contain backend code, shared runtime dependencies, required contracts, the dependency lock and build metadata - otherwise a development shared-layer can still be imported even when main-system is pinned.\nPostgreSQL data, Rust-Vector-Engine indexes, model weights and user data must not be copied per release.\nregistered Codex contract section 10.19 records the layout and contents; runtime/releases and the release packaging do not exist (gap G57).\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。;MUTABLE-VALUES:resolve-current-values-from-owner-versioned-contract-or-registry;CODEX:retains-owner+boundary+prohibition+acceptance-dimensions-only\n;FORBID:deployment-version+benchmark-result+model-threshold+port+path+operational-tunable-as-permanent-Codex-literal\n', E'1d44667515030cd29c0841b4aef8e390af15f57065f8f0a45cf4251533a2131b', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B148', E'CODEX_MODULE_RUNTIME', E'CODEX_MAIN', E'gptbridge-backend-lifecycle-contract', E'gptbridge-backend-lifecycle-contract\nBACKEND-LIFECYCLE: lifecycle role, health state and startup phase are separate dimensions. Listener bind or IPC listener availability is LISTENER_READY only and MUST NOT be reported as backend READY. READY requires the declared runtime initialization sequence to finish, no runtime_failed phase, a live generation process, an authenticated IPC session, and all mandatory health probes PASS. ACTIVE+READY and STANDBY+READY are valid combinations; STANDBY alone is not readiness. STATUS-FIELDS:backend_id|release_id|generation|release_root|state_root|backend_port|lifecycle_state|health_state|startup_phase|started_at|last_heartbeat|active_requests|accepting_new_requests|last_error. FAILURE:any runtime_failed, permission denial, exited process, missing evidence or probe failure is FAILED/INCOMPLETE and cannot be converted to PASS by listener availability. REUSE:existing lifecycle registry, gateway and request registry are canonical; no parallel status system.\n\n', E'107e9391b32bb4be6d88edd2711dd05d48d01d60dc20705780202f3e2fe6670e', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B149', E'CODEX_MODULE_INFORMATION', E'CODEX_MAIN', E'gptbridge-request-registry', E'gptbridge-request-registry\nREQUEST-REGISTRY:selected B166 UI application core and CSharp Application Backend share one versioned request registry;FIELDS:request_id+session_id+task_id+backend_id+backend_generation+release_id+method+created_at+started_at+completed_at+status+timeout+cancellation_state+error_code;non-applicable fields may be null;LEGACY:commands without request_id receive one through a typed adapter;AUTHORITY:Tauri Rust Core preserves the authority view across backend updates and backend events carry event sequence;ROLLOUT:observable>cancelable>handover-capable;NO-SECOND-REGISTRY\n;FORBID:deployment-version+benchmark-result+model-threshold+port+path+operational-tunable-as-permanent-Codex-literal\n', E'0a72c45196c1a4a741615ed308af8b0b248dcb676af1fe10105ef59d6ed6c417', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B15', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'cryptography-and-key-lifecycle', E'cryptography-and-key-lifecycle\nDATA-AT-REST:AES-256-GCM-or-ChaCha20-Poly1305; SIGNATURE:Ed25519; HASH:SHA-256-minimum; KEY-GENERATION:CSPRNG; ROTATION:encryption<=90-days+signing<=365-days; REVOCATION:immediate-on-compromise; DESTRUCTION:verified; PRIVATE-KEY:never-in-codex\nFORBID:deprecated-algorithm+hardcoded-secret+plaintext-private-key+reuse-after-revocation\n', E'4847e4bdc440d2f40f09735bd030edae3d8001b58249da985e6a40629691d034', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B150', E'CODEX_MODULE_INFORMATION', E'CODEX_MAIN', E'gptbridge-request-lifecycle-and-streaming-attribution', E'gptbridge-request-lifecycle-and-streaming-attribution\nRequest lifecycle for the extended registry: CREATED/QUEUED/RUNNING/COMPLETED/FAILED/CANCELLED/TIMED_OUT/INTERRUPTED with defined legal transitions (CREATED->QUEUED; QUEUED->RUNNING/CANCELLED/TIMED_OUT; RUNNING->COMPLETED/FAILED/CANCELLED/TIMED_OUT/INTERRUPTED; INTERRUPTED->RUNNING/FAILED/CANCELLED after verification). Requests record their backend generation at creation and are never reassigned mid-execution; request tracking never implements backend switching. Streaming token events must map to request_id/backend_generation/sequence by reusing existing fields (state_event already carries sequence and backend_generation with dedup and gap detection) and must never create a second streaming protocol; mixed tokens across requests, cancelled requests updating the UI, duplicate completion events and wrong attribution after a backend switch are forbidden. Cross-backend streaming resume is out of scope. The registry only records and tracks; it never decides execution, file modification, database operations or version updates and never bypasses the existing IPC security flow.\nTerminal states must not complete twice; repeated cancellation must be idempotent; when completion and cancellation race, exactly one final result is locked by the single authority and the other event is recorded as a late event. Acceptance covers ten cases in an isolated test environment: normal completion, concurrent requests, cancellation, timeout, repeated cancellation, completion/cancellation race, backend disconnection marking, streaming attribution, registered IPC contract compatibility and non-bypass of permission/audit.\nregistered Codex contract sections 10.23-10.25 record the lifecycle, streaming attribution and acceptance; none is implemented (gap G62).\n\n', E'a2b6137a87035009eb45313c7d5327cce3ca5f7f9b17fcbaf549f9a67d8e01a3', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B151', E'CODEX_MODULE_INFORMATION', E'CODEX_MAIN', E'gptbridge-connection-state-reconnect-backpressure', E'gptbridge-connection-state-reconnect-backpressure\nCONNECTION-PATH:B166-managed-UI-client>selected-approved-shell>typed-application-gateway>Request-Registry>authorized-owner-runtime;STATES:CONNECTING|CONNECTED|RECONNECTING|DISCONNECTED|CLOSED with transport state separate from backend lifecycle;RECONNECT:bounded exponential backoff+jitter+maximum interval+timeout+single connection+single loop+no reconnect after shutdown+authentication and handshake on every connection;REQUESTS:registry survives disconnect and never blindly re-executes unconfirmed non-idempotent work;STREAM:request+generation+sequence identity,deduplication+gap detection+bounded buffers+completion preservation;HEALTH:transport+process+READY+DEGRADED remain distinct;SECURITY:no reconnect bypass and no credential logging;TESTS:native runner coverage through the sole CSharp TestSuiteOrchestrator\n\n', E'586bbd6e71aad961a2e1a7b183ac83e07855d06cc0a7800555f01b144b8c0cc7', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B152', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-multi-configuration-gpt', E'xingcheng-multi-configuration-gpt\nXingcheng is a multi-configuration model family;the concrete configuration roster,architecture family,variant sizes,precision tiers and execution backends are owner-local implementation rules and are never Codex law.\nCodex invariants:tokenizer,evaluation and lifecycle contracts are shared across configurations;weights,checkpoints and training records are independent per configuration;the configuration identity must be explicit in the release manifest and evaluation metadata;changing a configuration is a model change and must pass the same maturity and evaluation gates.\nPresets and the manifest field live in the implementation registry (XingChengConfig);a shipped configuration is always identifiable and gated.\n\n', E'6b67203edcc14d3b65bf82272bbb059c3a50f0b27fb02b6476d706473aab3473', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B153', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-tool-calling-competence', E'xingcheng-tool-calling-competence\nXingcheng does not need to own many tool capabilities - tools are provided by governed tools and executors - but it must know how to call tools: emit valid star-tool-call/v2 calls with correct parameters, interpret tool results and handle errors and denials; every call routes through the information channel and permission checks, and tool results remain unverified inputs until validated.\nXingcheng never authorises or executes tools itself; tool-calling competence is part of maturity L6 and the Phase 6 acceptance.\nstar-tool-call/v2 (ToolContracts.cs, governed C# lane) is the single tool-call envelope; the retired Python tool_call_format.py (star-tool-call/v1) is historical-only. The L6 acceptance matrix and governed tool routing are still pending (Phase 6 / G3).\n\n', E'458988c4fd6dd910a5fa677d43fb605ace16b13eafb4e6fba134ee3f323e32c6', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B154', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'ollama-on-demand-activation', E'ollama-on-demand-activation\nOllama is a registered external service with on-demand lifecycle,not a resident startup dependency. It starts only for an explicit registered need such as teacher distillation,expert consultation,embeddings,reranking or approved model routing,through governed lazy activation;it unloads when idle under resource policy. Startup probes may inspect availability without starting or pre-warming the service. Start and stop are audited in the Process Registry;GPTBridge may stop only an instance it started,while a user-started instance may only receive a governed request. Failed start reports degraded and never silently switches paths;after shutdown only a new explicit demand or single-item permission may restart it. Cold-start and first-token latency remain observable evidence. LOCAL-MODEL-DEMAND:an explicitly authorized local-model activation is a registered Ollama demand. The local-model lifecycle first checks installation and readiness,starts Ollama only when installed but not ready,and waits at most 8 seconds;failure is fail-closed and local-model cannot report running. An Ollama instance started by GPTBridge is unloaded by the sleep policy after the configured warm interval;an externally started instance is never stopped by ownership inference.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:resident-by-default|startup pre-warm|silent restart|unauthorized fallback|force-stopping user-owned service|readiness claim before governed activation.\n', E'62412f0c4321c1be751e02656ed6f83e9c9644153207a3217db738a297af0d0e', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B155', E'CODEX_MODULE_RUNTIME', E'CODEX_MAIN', E'main-system-on-demand-modules', E'main-system-on-demand-modules\nThe main system keeps only a minimal resident core (IPC/command routing, governance and permission gates, launcher and runtime state, backend gateway and request registry, bounded maintenance health monitoring); every other module and service starts on demand: the full RAG/CAG/DAG pipeline, the local model and Ollama, independent tools, embeddings/reranker, teacher distillation, indexing and offline maintenance. Activation is governed lazy activation with a readiness wait and idle unload; failures are fail-closed and reported as degraded; there is no pre-warm, no silent restart and no silent fallback to an unauthorised path. Capability state stays separate from run state so the UI shows not-started rather than failed; activation counts, cold-start latency, readiness waits and unload counts enter the performance baseline.\nExisting lazy implementations (lazy RAG/CAG construction, on-demand independent tools, the model activation broker and on-demand Ollama) are the foundation; no new sovereign or parallel lifecycle is created. The goal is lower idle power and local load: modules activate only when used and unload when idle; the idle baseline (RAM/CPU/GPU power and utilisation) is the acceptance reference and must be tracked continuously, and residency must never be traded for start-up speed.\nLazy RAG/CAG and on-demand tool/model activation already exist as implementation advantages; the explicit resident-vs-on-demand policy and its observability are not yet recorded or enforced.\n\n', E'8a6c73e1b16e8e1f790b41a3ea61d263e39d689e5dc8acacce12a43e7d3c0c55', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B156', E'CODEX_MODULE_FOUNDATION', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'project-single-purpose-modules', E'project-single-purpose-modules\nEvery module carries a single responsibility; new functionality extends an existing single-purpose module or adds a new single-purpose module rather than accreting unrelated features; module boundaries and ownership follow architecture_registry.json and the existing size rules (D97/E160: at most three public entrypoints, twelve authored callables and five hundred effective lines); composition/orchestration layers (facade, orchestrator, router) carry no business logic; duplicate component variants are refused (inventory first, extend second).\nMandatory registered Codex contract invariant 19; violations are governance-audit failures.\nRecorded in registered Codex contract section 10.28 and invariant 19; enforcement relies on the existing architecture-registry and source-size audits.\n\n', E'653a4287ab4a7dc504681ea6e83f181bb4e57dc26766ddad6e44e20cc9aff633', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B157', E'CODEX_MODULE_RUNTIME', E'CODEX_MAIN', E'project-performance-and-bounded-parallelism', E'project-performance-and-bounded-parallelism\nPERFORMANCE-OBJECTIVE:high-performance+high-speed+low-resource+bounded-parallelism;NO-NEW-FRAMEWORK:converge-existing-execution-paths;AUTHORING:native-owner-language-only+compiled-efficient-form;every new or modified code unit is written in its registered native owner language and never in an interpreted,scripting or retired runtime;EFFICIENT-WRITING:registered efficient patterns (compiled paths,bounded concurrency,batching,zero-copy,capacity reservation,one-pass processing) with measured p50/p95/p99+CPU+RAM+VRAM+queue-depth evidence;avoid avoidable copies,per-item work,unbounded allocation and unnecessary language hops;LANGUAGE-EFFICIENT-PATTERNS:C++:zero-cost-abstraction+std::move-ownership+std::string_view-readonly-params+container-reserve;C#:ValueTask-async+Span/ReadOnlySpan-slicing+struct-for-small-values-against-GC;F#:tail-recursion-as-loop+seq-lazy-evaluation+[<Struct>]-unions;Go:value-over-pointer+make-with-capacity+strings.Builder(no-\'+\'-in-loops)+sync.Pool+no-blind-goroutines;Rust:&[T]/&str-no-clone+iterators-over-index-loops+with_capacity;COMPILER-OPTIMIZATION:production artifacts use the owner release optimization profile(C/C++:/O2 or -O3+LTO-when-measured-safe;Rust:cargo-build--release(-O3,+lto/codegen-units=1 when measured);C#/F#:Release+optimize+TieredPGO;Go:optimized-release+trimpath);unoptimized-or-debug-profiles never ship to production and the exact profile is recorded in the B79 toolchain/ABI evidence;PERF-01=critical-path-forbids-unnecessary-Python-hop;PERF-02=CPU-bound-prefers-Rust-safe-core-or-admitted-C/C++-native-hot-path;PERF-03=high-concurrency-IO-orchestration-prefers-Go;PERF-04=all-concurrency-bounded;PERF-05=forbid-unbounded-queue+thread+goroutine+task+process+model-request;PERF-06=bulk-operations-prefer-batch;PERF-07=large-payload-prefers-reference+stream+zero-copy;PERF-08=model-prefers-resident-and-forbids-request-triggered-reload;PERF-09=independent-RAG-stages-prefer-parallel-execution;PERF-10=end-to-end-cancellation-required;PERF-11=cache-bounded+revision-aware+scope-aware+non-canonical;PERF-12=nonessential-services-lazy-initialization;PERF-13=observability-nonblocking-critical-path;PERF-14=canonical-writes-separated-from-runtime-telemetry;PERF-15=optimization-decided-by-p50+p95+p99+CPU+RAM+VRAM+context-switch+queue-depth+DB-round-trip-evidence;SCHEDULER:one-existing-global-work-scheduler;CLASSES:CPU+IO+DB+VECTOR+MODEL+GPU+BACKGROUND;BUDGETS:physical-core+pool+vector-limit+model-capacity+VRAM+backpressure;MODEL-RESIDENCY:HOT|WARM|COLD|EVICTING|LOADING with LRU+VRAM-budget+auto-release;RAG-PARALLEL:keyword+vector+metadata>merge>rerank>PostgreSQL-verify>context;BATCH:embedding+DB-write+Rust-vector-projection-batch+log+audit-receipt+hash+metadata+IPC-event;FAIL-FAST:authentication>scope>capability>schema>quota>dispatch;CANCELLATION:UI>scheduler>native-worker>DB>RAG>LLM;CACHE:L1-process+L2-shared-bounded+L3-PostgreSQL-pgvector/Rust-derived-cache;STARTUP:core-config>IPC>UI-ready>DB-pool>scheduler>lazy-service>async-model-warm;PROCESS:bounded-resident-native-runtimes+tools-on-demand;FORMAT-PERFORMANCE-INVARIANT:every active source+contract+configuration+data+cache+index+transport+artifact format must minimize measured latency+CPU+RAM+VRAM+allocation+copy+serialization+storage+IO without weakening correctness+security+authority+scope+lineage+audit+portability;SELECTION:owner implementation layer selects format through representative p50+p95+p99+throughput+CPU+memory+storage+startup+parse/encode/decode+copy-count evidence;PATH-CLASS:small-control-message may use human-readable typed text;high-frequency-internal-message prefers registered typed binary/native structure;large-payload prefers identity-reference+stream+mapped-or-chunked access;canonical durable data remains PostgreSQL and scoped semantic vectors remain PostgreSQL-pgvector;SOURCE:compiled/native owner language and canonical source extension follow B35+B36;source remains readable+maintainable+reviewable and cannot be minified or generated merely to evade governance;MIGRATION:inventory>benchmark>candidate-schema>compatibility-reader/writer>bounded-dual-read-if-required>atomic-promotion>retirement-label>zero-consumer-proof>old-format-purge;CONTRACT:every cross-layer format is versioned+owner-bound+schema-bound+size-bounded+endianness/encoding-explicit+backward/forward-policy+unknown-field-policy+validation+deadline+cancellation+resource-budget;FAILURE:invalid+oversized+unknown+stale+incompatible format fails before expensive work;NO-FRAMEWORK:format replacement must use existing authorized toolchains unless an independently permitted dependency is indispensable;PROJECT-WIDE-ADAPTATION:all implementation layers may adapt approved worker-count+batch-size+queue-admission+cache-size+chunk-size+compression+codec+IO-strategy+model-residency+query-plan+retry-backoff within registered min/max ceilings;SIGNALS:latency+throughput+CPU+RAM+VRAM+queue-depth+error-rate+DB-round-trip+storage-pressure;CONTROL:hysteresis+cooldown+bounded-step+deadline+cancellation+rollback+decision-record+generation-fence;SAFETY:adaptation never changes Codex+authority+permission+business-semantics+canonicality+security+contract-version and never creates an unregistered owner+framework+scheduler;CODE-AUTHORING:every new or modified implementation must be designed for high performance,high execution speed,low latency and low resource consumption from its first current version;PRIORITY:correctness+security+authority+maintainability are invariant,then minimize algorithmic complexity+allocations+copies+serialization+context switches+lock contention+syscalls+process hops+network/IPC/database round trips+resident memory+CPU/GPU time+startup/shutdown cost;DATA-PATH:choose owner-language-native data structures,contiguous or streaming access where suitable,typed pointer/reference/borrowed-view/handle semantics instead of avoidable copies;LARGE-STRUCT-PASS:large structures must not be passed by value when a typed pointer,reference,borrowed view or handle preserves ownership and lifetime safety,batch set operations;LOOP-OPTIMIZATION:hot loops prefer compiler optimization and may use measured loop unrolling plus safe decrementing counters only when bounds,underflow,termination,instruction-cache growth and binary-size regression are controlled;COMPILER-HINTS:where the owner language supports them and aliasing plus lifetime safety are proven,use restrict or its registered equivalent and use inline only for measured small hot functions without code-size regression;COMPILER-OPTIMIZATION:release builds use registered reproducible measured optimization flags,link-time optimization and target-architecture settings while flags that relax numeric,safety,ABI or compatibility semantics require explicit proof of contract equivalence instead of per-item work,and prepared bounded queries instead of fetch-all filtering;FILE-FORMAT:every new or modified source,contract,configuration,data,cache,index,transport and artifact file must use the registered format that minimizes representative parse+encode+decode+allocation+copy+storage+IO cost for its path while preserving correctness+security+authority+portability+reviewability;CONTROL-FORMAT:small human-managed control data uses a typed readable format;HOT-FORMAT:high-frequency internal data uses a registered typed binary or native structure when measurement proves lower total cost;LARGE-FORMAT:large payloads use reference+stream+chunk+mapped access and avoid whole-file materialization;FORMAT-IDENTITY:encoding+endianness+schema version+size bound+unknown-field policy+compatibility policy+owner are explicit;CONCURRENCY:parallelize only independent work with explicit worker+queue+memory limits,backpressure,deadline,cancellation and cleanup;LIFECYCLE:initialize noncritical capability lazily,reuse verified expensive state,and release idle resources under the registered policy;HOT-PATH:no reflection,dynamic dispatch,text conversion,logging,telemetry,remote call or language/process hop unless required by the typed contract and measured acceptable;REVIEW:the owner must reject a needlessly slower or heavier code or file-format design when an equally correct,safe,maintainable and authorized lower-cost design exists;EVIDENCE:performance-sensitive code and format changes use representative before/after or candidate-comparison measurements and record p50+p95+p99+throughput+CPU+RAM+VRAM+allocation+copy+parse+encode+decode+storage+IO+queue+round-trip data appropriate to the path;REGRESSION:a change that exceeds a registered budget or causes material unapproved latency/resource regression cannot activate\nFORBID:new-framework+unbounded-async+thread-per-task+request-model-reload+sequential-independent-RAG+per-item-transaction+large-payload-copy+PostgreSQL-as-general-runtime-queue+synchronous-telemetry-on-critical-path+late-authorization+orphaned-cancelled-work+unversioned-cache+boot-all-services+permanent-tool-daemon+performance-by-timeout-increase;FORBID:format-selected-without-measurement+text-serialization-on-proven-hot-path+whole-payload-copy-when-reference-or-stream-suffices+unbounded-message/file/cache+schema-less-binary+silent-incompatible-rewrite+old-format-with-active-consumer-purged+format-optimization-changing-authority-or-business-semantics+needlessly-slow-or-resource-heavy-code-or-file-format+avoidable-allocation-copy-serialization-or-hop+unbounded-concurrency-or-buffer+per-item-IO-when-batch-valid+whole-file-materialization-when-stream-or-reference-valid+unversioned-or-unbounded-format+text-format-on-measured-hot-path-with-superior-registered-format+blocking-observability-on-hot-path+eager-noncritical-service+performance-claim-without-representative-measurement+optimization-by-correctness-security-authority-portability-reviewability-or-maintainability-loss\n', E'9c11d42c738b8e416052b99feac5c033d4b409dd6817e1d4b2f08801baa15026', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B158', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'sub-sovereign-elimination-full-modularization', E'sub-sovereign-elimination-full-modularization\nThe sub-sovereign layer is eliminated; its functions are taken over entirely by single-purpose modules while policy and decision stay with the core engines (former sovereigns). Retirement list (the thirteen current owner_sub_sovereign values): data_governance, change_acceptance, release_update_sync, startup, policy_architecture, xingcheng-assistant-identity-group, system, channel_contract_sync, repair_backup_sync, runtime_state_sync, dependency_sync, cleanup_retention_sync and language_review. Every retired function must map to one or more single-purpose modules; module manifests, architecture_registry (owner_sub_sovereign retired) and permission routes must be synchronised. Modularisation requirements: single responsibility, on-demand activation, append-only chain, bounded parallelism, versioned contracts and pure-C core engines.\nTransition is codex-first: the codex amendment and an equivalence mapping table must complete first; before the amendment no deletion, renaming or routing change is allowed; migration must be functionally equivalent to the existing implementations. Authority separation, audit and fail-closed behaviour stay unchanged and modules never authorise or execute work on their own. Engines no longer have fixed module allocations: tasks are dispatched by requirement (capability, resource, permission, deadline) matched against each module\'s single-responsibility declaration and versioned contracts, never by fixed relationships or hard-coded routing and never self-selected by a module; unmatched or conflicting dispatches fail closed and escalate, and every dispatch decision, reason, responsible module and receipt is written to the append-only chain. Modules are implemented in pure C (C11, no C++); object-oriented components are implemented in C++ (including the production inference layer); external coordination is C# (business orchestration); Python stays limited to model research/training and data pipelines; cross-language access is only through versioned contracts (stable C ABI) and C++ must never enter the C core or the procedural modules.\nBlueprint section 10.32 records the elimination and the retirement list with invariant 23; the registry still carries owner_sub_sovereign values and the sub-sovereign code paths.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\n\n', E'1339f3996f9894dddba61c0c3838ae19b2f15426726bf6dd673ffd49ff2c855c', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B159', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'resource-governance-throttle-protection', E'resource-governance-throttle-protection\nSOLE-REGULATOR:C++23 resource-governor with system-administrator identity is the only whole-project resource regulation executor; INPUT:typed project-wide resource/load signals; ACTIONS:priority+affinity+working-set+admission+release within B16 envelopes; CAPABILITY-ADAPTATION:formal language owners may tune internal declared parameters but cannot regulate other processes or create a governor; PROTECTED:governance+permission+audit+fail-closed+in-flight work; CONTROL:hysteresis+cooldown+generation+before/after evidence+automatic rollback; KILL-SWITCH:stops actions while observation continues; ADAPTIVE-OBJECTIVE:high-performance+high-execution-speed+low-resource-consumption jointly optimized; METRICS:throughput+latency-p50/p95/p99+CPU+RAM+GPU/VRAM+disk/IO+process/thread-count+startup/shutdown; ACCEPTANCE:no single-metric gain may regress another required metric,correctness,quality,security,stability,authority or hard deadline beyond its registered budget; DECISION:only Pareto-nondominated or policy-weighted improvement with complete before/after evidence may activate; otherwise rollback or fail-closed\nFORBID:second-governor+module-private-governor+Python/Rust/C/CSharp process-regulator+scope-expansion+authority/permission/data/business-decision+unaudited-action+kill-switch-silencing-observation+cross-owner-regulation+FORBID:single-metric-optimization+performance-by-resource-overuse+resource-saving-by-latency/throughput-regression+speed-by-skipping-correctness/security/governance+claim-without-before/after-evidence\n', E'597155fb96b566c13109f1298d6a362125a0dd1214e45c7da7a49dd504e38bb4', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B16', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'resource-quota', E'resource-quota\nQUOTA-ENVELOPE:every module/component declares minimum+default+maximum memory+disk+CPU+GPU/VRAM+threads+processes+connections+queue+model-residency+latency budget; C++23 resource-governor is sole system-administrator regulator and adjusts admission+priority+affinity+working-set inside envelopes; capability owners adjust internal batch/pool/cache/concurrency only inside delegated bounds; PRIORITY:governance-basis>core-runtime>active-user-work>background-maintenance; EXHAUSTION:shed/defer/deny new low-priority work+preserve in-flight and completed state+release idle+audit; RECOVERY:hysteresis+stability window+automatic restoration; ADAPTIVE-OBJECTIVE:high-performance+high-execution-speed+low-resource-consumption jointly optimized; METRICS:throughput+latency-p50/p95/p99+CPU+RAM+GPU/VRAM+disk/IO+process/thread-count+startup/shutdown; ACCEPTANCE:no single-metric gain may regress another required metric,correctness,quality,security,stability,authority or hard deadline beyond its registered budget; DECISION:only Pareto-nondominated or policy-weighted improvement with complete before/after evidence may activate; otherwise rollback or fail-closed\nFORBID:unbounded-allocation+ceiling-raise-by-adaptation+second-governor+Python-resource-loop+silent-truncation+background-starvation+throttle-protected-governance/inflight-work+FORBID:single-metric-optimization+performance-by-resource-overuse+resource-saving-by-latency/throughput-regression+speed-by-skipping-correctness/security/governance+claim-without-before/after-evidence\n', E'a3d746f2511bef4bf29341e764ffa11c5414c8c858364bd69d71e842281eaefe', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B160', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'unit-system-architecture-hierarchy', E'unit-system-architecture-hierarchy\nHIERARCHY:module>unit>block mandatory|MODULE:single-responsibility+single-function|UNIT:orchestration+deployment unit same-directory same-host same-lifecycle|BLOCK:higher orchestration+isolation domain|DIRECTORY-SYNC:folder layout must mirror block/unit/module|CROSS-UNIT:governed interface (IPC/contract) only no direct import or file traversal|MEMBERSHIP:every component belongs to exactly one unit and one block\nFORBID:cross-layer mixed placement+direct cross-unit import/file access+module with multiple responsibilities+unit membership omission\n', E'cf8656cc9d9829bfadc959a3823588f1ab9489fdefdf90ce76b5121f06826729', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B161', E'CODEX_MODULE_RUNTIME', E'CODEX_MAIN', E'模組按需啟動、休眠與喚醒權限條例', E'模組按需啟動、休眠與喚醒權限條例\nB154、B155 與 D137 所定按需生命週期由本條補充。模組不得自行啟動、背景預熱或靜默重啟；任務或事件到達後，由自動化核心管理流程與排程，裁決核心處理爭議，運行核心依已登錄 capability、權限、依賴與資源優先序下發啟動、休眠、喚醒、凍結或釋放命令。啟動必須具單一實例鎖、節流、退避、依賴解析及 readiness gate，獨立工具啟動與關閉各不得超過五秒，逾時或未 ready 即 fail-closed 並釋放半啟動資源。休眠前必須確認無 in-flight、佇列為空、完成 drain 與 checkpoint；溫喚醒目標不超過二秒，冷喚醒不超過五秒，喚醒後通過 readiness 才可接收工作。治理核心不得休眠；資源優先序沿用 B16 與 B159；所有狀態轉換、原因、耗時與結果均須審計。自動休眠之 enabled 狀態只能在已核定驗收證據成立後以受管設定變更啟用，不得由本條推定為已啟用。 FINAL-WINDOW-CLOSE:for the main system and every independent tool,closing the final application window is not detach or sleep;it emits a typed shutdown request bound to application identity,generation and correlation identity. The matching backend must drain,checkpoint,shutdown owned services,terminate the owned process tree and verify exit within its lifecycle budget. Main-system close affects only the main-system backend;tool close affects only that tool backend. Timeout or unknown process state fails closed and uses the registered bounded termination path without claiming success. SHUTDOWN-SCOPE-FENCE:the main-system shutdown executor may enumerate and terminate only processes owned by the current main-system generation and must explicitly exclude every independent-tool application identity,generation and process tree. Independent tools survive main-system exit;reconnection after main-system restart follows generation fencing and readiness without restarting an already-running tool.\nFORBID:module-self-start|background-prewarm|silent-restart|task-before-readiness|sleep-with-inflight-work|ungoverned-wake|timeout-treated-as-success+final-window-detach-only+backend-survives-final-window-close+unverified-stop-success+unscoped-cascade-shutdown+main-shutdown-enumerating-or-terminating-independent-tool-processes+tool-restart-merely-because-main-system-restarted\n明確使用者單項許可得構成一次需求事件，但仍不得跳過權限、資源、readiness 與審計閘門。', E'c397067084348283f660e27d26e35525ab4d1b0c00a64e61a7d63d2f66e7e280', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B162', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'五核心、星澄身分與歷史次主權權責收斂條例', E'五核心、星澄身分與歷史次主權權責收斂條例\nCONTROL:B162 is the sole current five-core and historical sub-sovereign responsibility boundary (A604 lineage);CORES:decision-core owns all decisions and governance management with zero execution power (policy+architecture+priority+dependency/state+change and result acceptance;FORBID:direct module execution),permission-core owns identity management+all directory and registry list management+codex governance-plane management (identity registry,directory boundaries,managed registry paths,GOVERNANCE_CODEX entry,codex read-session mint and dual-key grants;codex content authority remains the PostgreSQL codex itself;no execution power),runtime-core is the sole execution authority (startup+process+lifecycle+governed dispatch+execution validation;FORBID:self-authorization+policy modification),automation-core owns all system-wide automation flows and orchestration with no execution power (scheduling+dispatch assignment only;FORBID:permission generation+result acceptance),xingcheng-assistant owns global review+inspection+audit authority as read-side supervision (all typed receipts and audit evidence converge into its review surface;FORBID:user-choice substitution+xingcheng data persistence+repair authority+upgrade authority+learning ownership);XINGCHENG:separate native-model service identity owning self-learning+self-repair proposals+model evolution,with independent lifecycle+data scope from LOCAL_MODEL and no independent-tool card;SUB-SOVEREIGNS:abolished and historical only;EXECUTION-BOUNDARY:business executes at the registered-module layer only;independent tools are physical isolation containers (process tree+lifecycle+data domain+UI+owner root) and are not business executors;modules hold single owner+single primary responsibility+contracts versioned by internal timestamps and no independent authority;LANGUAGE:current responsibility table controls implementation ownership;PYTHON+NUMPY+JAX:retired,with zero role,residency,dependency,artifact or fallback responsibility and final and immediately effective;DELEGATION:business rules,algorithms,parameters,suite composition and operational tuning are owner-local non-authoritative rules bounded by this Codex.\nFORBID:active-sub-sovereign+module-independent-authority+mixed-XINGCHENG/assistant-identity-or-data+retired-Python/NumPy/JAX-role+Python-residency+Python-mechanical/test/audit/fallback+business-or-implementation-rule-as-Codex-authority+decision-core-direct-module-execution+runtime-core-self-authorization-or-policy-modification+automation-core-permission-generation-or-result-acceptance+assistant-as-repair-or-upgrade-authority+tool-as-executor-of-record+module-self-governance+module-cross-owner-execution\n', E'efbd246012d3ae1cd4a18a9e8e7ba42deab40b73c1f1751f076f0da9ef520452', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B163', E'CODEX_MODULE_RUNTIME', E'CODEX_MAIN', E'高效率 Runtime 規則索引條例', E'高效率 Runtime 規則索引條例\n建立唯一 runtime-rule-index contract。索引只能由 the current formal PostgreSQL Codex authority 的 current effective principles、articles、edicts、responsibilities、prohibitions、formal rule registry、law classification、ownership、deadline、dependency 與 provision supersession edges 生成；生成前必須先解析 successor，禁止收錄模組規則及 superseded、retired、缺少效力或 unresolved-conflict 的條文。索引是唯讀、可重建、非權威 Runtime 投影，不得產生、擴張、刪減或覆寫法典權限。每筆索引規則必須具有 rule_ordinal、provision identity、rule code、lifecycle state、controlling successor、owner、capability、trigger、phase、severity、effect、deadline、resource class、data class、dependency ordinals、content hash 與 source version。查詢結構固定包含 provision/rule-code 精確鍵、owner/capability/trigger/phase/severity/effect/deadline/resource/data/dependency/successor 倒排集合，以及 active、prohibition、fail-closed、hot-path 位元集合；多條件查詢必須由最小候選集合開始交集，禁止逐條全文掃描作正常 Runtime 路徑。generation 必須使用緊湊連續 ordinal、去重字典、排序 posting list 與不可變資料區；建置完成後驗證 count、identity set、content hash、successor resolution、dependency acyclic 與 source version，全部通過才可原子切換。讀取者必須綁定 generation，舊 generation 在所有讀取者釋放後回收。exact lookup 的 warm p95 目標不超過 1ms，多維交集 warm p95 目標不超過 5ms，完整建置與 mandatory verification 必須在 30 秒內完成；超時、版本不符、缺列、重複 identity、解析失敗或驗證失敗一律 INDEX_NOT_READY，並回到受管正式法典查詢，不得使用 stale index。\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:runtime-index-as-authority|module-rule-in-runtime-index|stale-generation-use|superseded-provision-indexing|full-scan-normal-path|partial-generation-publication|index-derived-permission|unbounded-posting-list|silent-index-fallback\n歷史與稽核查詢得使用明確指定的舊 generation，但必須隔離於 current Runtime 決策路徑並標示 non-current。', E'b42b179130334878b58d7a567264beeaa9140c1889b0aa26f3ab2acf0fafaef3', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B164', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'codex-normative-surface-and-implementation-layer-delegation', E'codex-normative-surface-and-implementation-layer-delegation\nNORMATIVE-SURFACE:principles+articles+edicts+responsibilities+authority-boundaries+prohibitions+cross-layer-invariants only;AUTHORITY:formal-PostgreSQL-Codex is the sole project-wide normative authority;DELEGATED-CONTENT:business-rules+domain-validation+algorithms+parameters+steps+queries+retries+batches+caches+transformations+UI-behavior+implementation-specifications+internal-tests+operational-tunables belong to their owning implementation layer;DELEGATED-FORM:versioned-owner-local-contract-or-registry with authority_class=implementation-derived-non-authoritative;OWNER:implementation owner controls content+version+lifecycle within Codex ceilings;CROSS-LAYER:any behavior crossing owner boundaries uses a registered versioned contract but does not move business rules into Codex;INDEX:module-rule-index contract provides discovery+scope+validation+revocation only and owns no content or authority;RUNTIME-INDEX:contains Codex governance rules only and never implementation rules;CONFLICT:Codex authority/responsibility/prohibition wins and affected implementation fails closed;CHANGE:implementation owner may directly add+change+delete delegated rules without Codex amendment when no Codex boundary or cross-layer contract changes;FORMAT-OWNERSHIP:concrete source/file/data/transport format choice+layout+codec+compression+chunking+serialization are implementation specifications owned by the relevant implementation layer under the cross-layer FORMAT-PERFORMANCE-INVARIANT in B157;Codex declares performance+authority+compatibility+resource boundaries only;AUTO-CLASSIFICATION:every new or changed requirement is classified before storage;CODEX-CLASS:principle+article+edict+responsibility+authority-boundary+permission/security/canonical-data-boundary+prohibition+cross-layer-invariant+shared-contract-ownership;IMPLEMENTATION-CLASS:business-rule+domain-validation+algorithm+parameter+internal-workflow+query+retry+batch+cache+format/codec/layout+UI-behavior+test-implementation+operational-tunable;MIXED-CLASS:split into minimum Codex invariant and owner-local implementation rule joined by controlling_provision+contract_identity;DECISION-ORDER:authority/security/permission/canonicality/cross-owner-effect first>cross-layer contract second>owner-local behavior third;DEFAULT:owner-local behavior is implementation-derived-non-authoritative;AMBIGUITY:if a requirement can grant power+change authority+cross owner or weaken a prohibition classify its boundary as Codex and defer only the unresolved implementation detail;OUTPUT:classification+owner+scope+reason+controlling_provision+target_registry+source_revision+status;NO-DUPLICATION:one semantic rule has one owner and one authoritative location;LITERAL-POLICY:mutable path+port+tool/model/package version+deadline+resource limit+threshold+batch/cache/retry value is referenced by canonical directory/parameter/contract code;explicit literals remain only for immutable identity grammar+cryptographic/interoperability constant+closed enum+safety invariant\nFORBID:business-rule-in-Codex+implementation-specification-in-Codex+module-rule-as-law+implementation-registry-as-authority+runtime-index-storing-module-rule+module-self-authorization+cross-owner-local-rule-effect+projection-writing-law+delegated-rule-overriding-Codex+duplicated-business-rule-across-layers+Codex-prescribing-file/class/function/algorithm/internal-step;FORBID:Codex-hardcoding-owner-local-codec-or-layout+implementation-format-claiming-normative-authority;FORBID:unclassified-rule+same-rule-in-Codex-and-implementation-registry+implementation-detail-promoted-to-Codex-by-convenience+authority-boundary-hidden-as-business-rule+mixed-requirement-stored-unsplit;FORBID:mutable-operational-literal-in-Codex-article+duplicated-parameter-value+deployment-setting-as-normative-law\nOwner-local implementation rules remain constrained by current Codex authority, security, permission, resource and cross-layer contract boundaries.', E'a2c3cf633891be577321012949910be3294b0f61aef1a2240891dca531fee5ad', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B165', E'CODEX_MODULE_PERMISSION', E'CODEX_MAIN', E'module-and-implementation-rule-index-management', E'module-and-implementation-rule-index-management\nINDEX:module-rule-index contract is the sole central discovery index for delegated module and implementation rules;AUTHORITY-CLASS:implementation-derived-non-authoritative;CONTENT-OWNER:owning implementation layer;INDEX-OWNER:permission-core manages registration+schema+scope-validation+controlling-Codex-boundary-resolution+contract-compatibility+duplicate/conflict-detection+access+revocation-propagation+audit+query but cannot author+edit+approve business meaning;REQUIRED:implementation_identity+owner_identity+rule_namespace+rule_code+rule_kind+controlling_provision+contract_identity+contract_version+source_revision+scope+capability+trigger+phase+priority+status+content_hash+introduced_version+retired_version+validated_against_codex_version;KINDS:business-rule|domain-validation|algorithm|parameter|workflow-step|query|retry|batch|cache|transformation|UI-behavior|implementation-specification|internal-test|operational-tunable;KEY:implementation_identity+rule_namespace+rule_code+contract_version;GENERATION:immutable generation+atomic publish+prior-generation-read-only+revocation-fence;CONSUMER:an implementation reads only its own validated current rules plus registered shared contracts;FAILURE:missing+invalid+stale+conflicting+unauthorized rule returns MODULE_RULE_INDEX_NOT_READY and fails closed without copying it into the Runtime rule index;AUTO-CLASSIFICATION:every new or changed requirement is classified before storage;CODEX-CLASS:principle+article+edict+responsibility+authority-boundary+permission/security/canonical-data-boundary+prohibition+cross-layer-invariant+shared-contract-ownership;IMPLEMENTATION-CLASS:business-rule+domain-validation+algorithm+parameter+internal-workflow+query+retry+batch+cache+format/codec/layout+UI-behavior+test-implementation+operational-tunable;MIXED-CLASS:split into minimum Codex invariant and owner-local implementation rule joined by controlling_provision+contract_identity;DECISION-ORDER:authority/security/permission/canonicality/cross-owner-effect first>cross-layer contract second>owner-local behavior third;DEFAULT:owner-local behavior is implementation-derived-non-authoritative;AMBIGUITY:if a requirement can grant power+change authority+cross owner or weaken a prohibition classify its boundary as Codex and defer only the unresolved implementation detail;OUTPUT:classification+owner+scope+reason+controlling_provision+target_registry+source_revision+status;NO-DUPLICATION:one semantic rule has one owner and one authoritative location\nFORBID:implementation-rule-in-Codex-runtime-index+permission-core-authoring-business-meaning+module-index-as-authority+cross-owner-unscoped-read+unvalidated-or-stale-generation+in-place-overwrite+private-central-index-copy+rule-without-owner-or-source-revision;FORBID:unclassified-rule+same-rule-in-Codex-and-implementation-registry+implementation-detail-promoted-to-Codex-by-convenience+authority-boundary-hidden-as-business-rule+mixed-requirement-stored-unsplit\nOwner-local implementation rules remain constrained by current Codex authority, security, permission, resource and cross-layer contract boundaries.', E'a9934374a1be86868858935fd0c7b5d8b4601dcce319d3245aa2460f164000b0', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B166', E'CODEX_MODULE_LANGUAGE', E'CODEX_MAIN', E'primary-language-reallocation-and-dotnet10-runtime', E'primary-language-reallocation-and-dotnet10-runtime\nPRIMARY-CORE-LANGUAGE-POOL:C+C++23+CSharp+Rust+Go+FSharp only;GUIDANCE-ONLY:language responsibility examples and default strengths are non-binding reference preferences and never immutable capability bindings;CORE-POOL-BOUNDARY:every core-capability allocation is restricted to exactly C+C++23+CSharp+Rust+Go+FSharp;managed JavaScript ESM is a B166 UI-surface exception and not a core owner;ADAPTIVE-ALLOCATION:each capability selects exactly one current primary owner from the language pool using representative correctness+security+latency+throughput+CPU+RAM+binary-size+startup+maintenance evidence;allocation may change only inside the same registered capability contract and resource ceiling with one owner,one implementation path,atomic promotion and rollback;NO-AUTHORITY-DRIFT:language selection never creates authority,changes business semantics,bypasses permission or introduces a second scheduler/orchestrator;PYTHON:total-ban with zero source+runtime+interpreter+environment+package+dependency+build+test+audit+training+inference+script+tool+artifact+proxy+bridge+reference+fallback;BUILD:compiler+linker only in governed build stage;PRODUCTION:verified precompiled native artifacts only,no compiler+interpreter+runtime-source-compiler+script-engine;DOTNET:CSharp+FSharp use NativeAOT or equivalent ahead-of-time publication;DATA:PostgreSQL remains sole structured authority and is not an application-language owner;FAILURE:missing or regressing evidence retains the current verified owner or fails closed;UI-SHELLS:Tauri+Wails+Qt are approved desktop shells;each application selects exactly one shell according to its Rust+Go+C++23 ownership boundary;every permitted language may implement UI capabilities under adaptive single-owner allocation and typed boundaries;managed Bun may execute registered JavaScript ESM;GPUI owns high-performance workspace+streaming views;Slint owns native declarative views;egui owns diagnostics+engineering views;no Electron+Node+TypeScript+Python;language choice cannot create authority+bypass permission+direct database access+duplicate ownership\nFORBID:Python+interpreted-runtime+multiple-current-language-owners+unmeasured-reallocation+authority-drift+contract-bypass+runtime-compilation+unbounded-resource-use+unregistered-desktop-shell+unregistered-JavaScript-runtime+Bun-core-or-authority-ownership+multi-shell-hosting+shell-created-authority+direct-database-access+permission-bypass+duplicate-owner\n', E'528fba46cff3b67e386d4397ca54c9106cc6b302a9ec05d23146da4dae4eb435', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B167', E'CODEX_MODULE_LANGUAGE', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'native-model-training-framework', E'native-model-training-framework\nXINGCHENG-NATIVE-ONLY:the complete Xingcheng source,production runtime,training,inference,learning,evaluation,data-processing and internal-tool surface uses only C+C++23+CSharp+FSharp+Rust;this is a strict Xingcheng-specific subset and no project-wide language permission expands it;OWNERSHIP:C and Rust own deterministic runtime+lifecycle+security+data hot paths,C++23 solely owns model training+inference+artifact production,CSharp owns bounded application+workflow orchestration,FSharp owns evaluation+validation+high-correctness analysis;EXCLUDED:Go+JavaScript+Bun+WebView script+Python and every other source or execution language are prohibited inside Xingcheng;INTERNET-ACCESS:Xingcheng may access the Internet through its own Rust or CSharp native network path for search+public-data retrieval+repair research+authorized task completion;every request has declared purpose+scope+bounded concurrency+deadline+response-size limit+source record+content validation+audit and cancellation;all retrieved content is untrusted non-authoritative input;EXTERNAL-DEPENDENCY:Internet data access is not an external execution dependency and does not authorize any external model+cloud inference+remote code execution+external execution engine+third-party inference framework+third-party training framework+external capability service as a Xingcheng runtime,producer,consumer,reference,fallback or authority;PLATFORM-BOUNDARY:operating-system facilities+hardware drivers+approved build toolchains+governed typed channels may provide platform boundaries only and gain no Xingcheng capability,model,data or authority ownership;TRAINING remains an internal Xingcheng service capability and not an independent module or tool;MODEL_TRAINING remains retired;FAILURE:any excluded language,external execution dependency,unbounded or unaudited network operation,or unregistered executor is denied fail-closed.\nFORBID:jax-framework+torch-import-or-dependency+retired-framework-artifact-or-fallback+ML-framework-owner+resident-training-runtime+retired-role-restoration\nNone.', E'1f8ece6d15047e67fab3511a4e20e7144026d65a7afc78f469cc9b832814767f', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B168', E'CODEX_MODULE_LANGUAGE', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'native-javascript-esm-general-ui', E'native-javascript-esm-general-ui\nFRONTEND:B166 exclusively controls approved desktop shells,managed Bun+JavaScript ESM and native view toolkits;SCOPE:presentation+interaction only;BOUNDARY:typed UI contract;PROHIBITION:no authority+business decision+direct database access+duplicate shell owner+Electron+Node+TypeScript+Python\nFORBID:retired-UI-source+second-WebView-frontend-language+frontend-governance/permission/data-authority+runtime-package-manager\nnone', E'e963b9ccc6542e63ee82bae53e097a9fcba9681b473e446246fc20dd325d9584', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B169', E'CODEX_MODULE_LANGUAGE', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'go-rust-backend-runtime', E'go-rust-backend-runtime\nRUNTIME:backend and edge runtime ownership is Go 1.27.1 for web-search+batch+network/file-IO and Rust 1.98.1 for UI-core+native-security+desktop-host; retired backend runtimes hold zero active consumers; rule-go-rust-runtime contract verifies every backend/edge consumer is Go or Rust fail-closed\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:retired-backend-runtime-consumer+runtime-package-manager+backend-runtime-outside-go-or-rust\nStandalone Esbuild and SWC binaries are build-time tools and never runtime consumers', E'14fc41d7f10b7db7dcd00ff633962e2314270ae7820a576b453dbc95e7c4d44b', E'active', E'2026-10-01T16:43:07Z');
