INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B36', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'exclusive-language-source-extension-map', E'exclusive-language-source-extension-map\nSOURCE-EXTENSION-MAP:resolve current permitted languages and extensions from the registered language directory controlled by B166;EXCLUSIVITY:one-file=one-language;GENERATED:canonical target extension+generated identity+owner+content hash;PROJECT-METADATA:not language source\nFORBID:retired-UI-source-extensions+custom-extension+language-content/extension-mismatch+source-hidden-in-config/data/template/archive+extensionless-project-source+classifier-bypass\nExternal third-party source retained solely for license compliance may preserve upstream names inside an immutable quarantined dependency artifact; it cannot be compiled, imported, loaded, modified, or treated as GPTBridge project source', E'444f6c832610255293400dc4cf8006d94d8f9bf03e902bc08876eb17cab7c6af', E'active', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'B37', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'native-csharp-windows-dotnet-boundary', E'native-csharp-windows-dotnet-boundary\nFLOW:CSharp-application-orchestration>versioned-interface>Windows/.NET API; RUST/C own lifecycle and process boundary; CSHARP-OWNER:application+workflow+API+Windows/.NET/CLR/WinRT/COM invocation+platform-lifetime+typed-error-translation; FSHARP-OWNER:business logic+validation; PYTHON:retired with zero role;no governance adapter,control,orchestration or fallback; RETURN:typed result through same contract; PROCESS:information-layer for cross-process boundary\nFORBID:Python-control-orchestration+Python-business-policy/workflow+Python-Windows-lifecycle+direct-or-untyped-bypass+duplicate-Windows-capability+CSharp-bypassing-governance\nWindows 11 native command-line tools remain governed platform adapters under the CSharp platform boundary and the information-layer process boundary', E'b63a300e85969044ee0f1b5ee0700888f2124ee289673247910fed622a7445de', E'active', E'2026-10-01T16:43:07Z');
