INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'D36', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'converged-c-and-pybind11-native-boundaries', E'converged-c-and-pybind11-native-boundaries\nNATIVE-BOUNDARY-FORMS:1-C-ABI-language-neutral,2-pybind11-Python-specific; ALL-NATIVE-CROSSINGS:one-of-these-only; C-ABI:extern-C+fixed-width-types+opaque-handles+versioned-struct-size+status-code+explicit-buffer/allocator ownership+symbol-allowlist+ABI-baseline; PYBIND11:one-versioned-extension-module+generated-or-verified-signature/stub+strict-type/shape/range validation+explicit-copy-or-zero-copy ownership+GIL release/acquire declaration+exception-map+interpreter/finalization safety; SHARED-C++-CORE:both-boundaries call-same-internal-kernel+no-logic fork; COMPATIBILITY:C-ABI-major/minor+pybind-module/API-version bound-to-same-release/artifact-root; TEST:ABI dump+symbol check+Python stub parity+cross-boundary golden result+memory/lifetime/thread/error tests; C-ROLE:boundary-not-performance/business; PYBIND11-ROLE:binding-library-not-seventh-application-language+no-independent authority\nFORBID:third-native-boundary+raw-C++-ABI/name-mangling/STL/exception exposure+pybind11-business-logic+untyped-capsule+implicit-ownership+cross-runtime-free+unversioned-extension+different-results-between-C-and-pybind11+binding-loaded-from-outside-C31/C32 roots\nDirect C-only operating-system APIs remain behind the registered C boundary and do not alter the performance mainline', E'39e2fb4d5a3757b303194b30bd12b8fdd7148cc638945fb0462f0467a3368752', E'superseded', E'2026-10-01T16:43:07Z');
INSERT INTO "codex_search_document" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content", "content_hash", "lifecycle_state", "version_identity") VALUES (E'article', E'D37', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'cpp-performance-core-six-domain-decomposition', E'cpp-performance-core-six-domain-decomposition\nCPP-DOMAINS:parser+vector+memory+token+transform+binding+model-inference; PRODUCTION:C++ owns admitted native compute and inference behind registered C ABI; BINDING:mechanical typed translation only; DEPENDENCY-DAG:explicit+acyclic+bounded; TEST:native suite+ABI+memory+numeric tolerance+JAX-training-artifact compatibility; PROMOTION:profile+contract+parity evidence; UNAVAILABLE:typed unavailable or registered non-Python owner,never Python production fallback\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:Python-production-owner+Python-test-oracle-as-authority+Python-fallback+public-C++-ABI+duplicate-native-domain+unbounded-allocation+binding-policy-or-workflow\nA generated binding file may exceed ordinary generated-file size only through an D97 file-specific exception; binding responsibility and generated parity checks remain mandatory', E'20fd0094c97e504ebd1f8765afd4f28510e88373a753c1178daed5cf371a5420', E'superseded', E'2026-10-01T16:43:07Z');
