INSERT INTO "codex_search_fts" ("provision_type", "provision_id", "module_code", "law_code", "subject", "content") VALUES (E'article', E'D26', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'uncertified-version-effect', E'uncertified-version-effect\nCERTIFICATION-STATUS:an integrity-valid candidate remains non-binding until the registered governed certification process verifies its current epoch lineage,declared roots and publication state;AUTHORITY:no actor,tool,database row or candidate may create authority merely by asserting certification;EFFECT:uncertified generation remains candidate-only;FALLBACK:last validly sealed current generation;IF-NONE:fail-closed and inspection-only.\nFORBID:self-certification|fabricated-certification-evidence|uncertified-binding-enforcement|external-approval-gate-not-declared-by-current-policy.\n');
