INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (1, E'article', E'A1', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'governance-rule', E'governance-rule\nFORM:codex-file; STORAGE:independent; LAYER:highest\nFORBID:arbitrary-amendment\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (2, E'article', E'A10', E'CODEX_MODULE_PERMISSION', E'CODEX_MAIN', E'permission-termination', E'permission-termination\nAUTOMATIC-STOP:permission-core automatically chooses SUSPEND|REVOKE|TERMINATE when expiry,identity/role revocation,scope loss,generation raise,security event,contract invalidation or controlling-basis retirement occurs; DirectoryAuthority atomically applies the mapped lifecycle operation,raises applicable fences and emits receipt; affected sessions/connections fail closed immediately while unrelated permissions continue\nFORBID:retain-permission-after-stop-trigger+unauthorized-stop+silent-stop+hard-delete-history+stop-without-receipt+caller-bypass\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (3, E'article', E'A100', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'canonical-human-name-and-machine-domain-alias-boundary', E'canonical-human-name-and-machine-domain-alias-boundary\nHUMAN-NAMES:法典+星澄 and all sovereign/sub-sovereign canonical names remain authoritative; MACHINE-ALIASES:ASCII area identifiers xingcheng+maintenance+data-integrity+resource-allocation+information-channel+system-programming+system-learning+dependency-governance are compatibility domain selectors only; POWER:none; IDENTITY:none; DISPLAY:none; RESOLUTION:machine alias must resolve to exactly one current canonical identity through the identity directory; SPLIT:resource and dependency synchronization use separate single-duty sub-sovereigns; RETIRE:alias removed only after all certified consumers migrate\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:machine alias as displayed or legal identity+alias-based authority+multiple identity resolution+alias bypass of 星澄 confidentiality+merging independent resource and dependency duties\nHistorical machine aliases are lineage-only data and cannot be used by a current consumer,route,publication or identity decision.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (4, E'article', E'A102', E'CODEX_MODULE_PERMISSION', E'CODEX_PERMISSION_IDENTITY_SPECIAL_LAW', E'legacy-authority-reference-resolution-special-law', E'legacy-authority-reference-resolution-special-law\nLEGACY-REFERENCE:any retired sovereign or sub-sovereign identifier embedded in an otherwise current provision is historical non-operative vocabulary. RESOLUTION:B162 is the sole controlling normalization for eliminated sub-sovereigns and maps the responsibility to one current five-core domain or registered module; the old identity never participates in permission,ownership,routing,execution or lifecycle resolution. Missing or ambiguous current module mapping fails closed and does not revive the historical identity.\nFORBID:legacy-identity-as-current+legacy-route+retired-parent+supersession-registry-reviving-sub-sovereign+implicit-authority-transfer\nA historical quotation may preserve the original spelling when marked historical and non-operative; machine aliases remain ASCII and never become a human canonical identity.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (5, E'article', E'A103', E'CODEX_MODULE_PERMISSION', E'CODEX_IDENTITY_GROUP_SPECIAL_LAW', E'machine-readable-sovereign-hierarchy-module-assignment-and-signature-special-law', E'machine-readable-sovereign-hierarchy-module-assignment-and-signature-special-law\nAUTHORITATIVE-REGISTRIES:sovereign_hierarchy_registry preserves historical sub-sovereign lineage only; no sub-sovereign row may be active. Current governance ownership is the five-core roster fixed by B162. module_assignment_registry binds each executable module directly to one current core domain,decision basis,permission enforcement,review identity and exact execution identity; it cannot name a retired sub-sovereign as current manager. VALIDATION:all current identities resolve to active canonical core or registered module identities,authority and execution remain separated,and every legacy reference normalizes through B162. CERTIFICATION:current validity uses registered governed authorization+deterministic integrity seal+lineage closure+atomic publication and must equal sealed-governed-authorization.\nFORBID:active-sub-sovereign-row+retired-manager+historical-identity-routing+module-self-authority+certification-state-drift\nA module with multiple capabilities is assigned by its dominant capability; other sub-sovereigns may coordinate through typed assignments but cannot become an additional manager. Human signature remains an external completion condition and is not waived by technical audit success.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (6, E'article', E'A106', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'dynamic-governance-code-resolution-and-hardcoding-elimination', E'dynamic-governance-code-resolution-and-hardcoding-elimination\nPRINCIPLE-PRESERVATION:the Codex fixes governing principles,authority,identity,ownership,permission,prohibitions,security boundaries,typed contracts,hard deadlines and maximum resource ceilings;these invariants remain unchanged until an explicit Codex amendment. PRINCIPLE-BOUNDED-ADAPTATION:every registered owner may automatically select or tune algorithms,data structures,formats,batch size,bounded concurrency,pools,caches,query plans,model residency,maintenance cadence,backpressure and degradation behavior when the result remains inside every current Codex principle and registered envelope. INPUT:current typed measurements and current configuration generation. CONTROL:owner+scope+validation+bounded step+hysteresis+cooldown+deadline+cancellation+decision record+generation fence+automatic rollback. OBJECTIVE:correctness+security+authority first,then jointly improve performance,execution speed,latency and resource consumption. ACCEPTANCE:only a measured non-regressing result may activate. FAILURE:unknown,stale,conflicting,out-of-envelope or principle-changing adaptation keeps the last verified state or fails closed. FORBID:self-amending-Codex+authority-or-owner-change+permission-expansion+business-semantic-change+contract-bypass+hard-limit-relaxation+new-unregistered-framework/scheduler/authority+single-metric-optimization.\nFORBID:hardcoded-mutable-value+environment-as-authority+adaptive-authority/permission/contract-change+unbounded-envelope+self-created-code+cache-across-generation+silent-fallback+Python-private-adaptation-loop+FORBID:single-metric-optimization+performance-by-resource-overuse+resource-saving-by-latency/throughput-regression+speed-by-skipping-correctness/security/governance+claim-without-before/after-evidence\nA bootstrapping locator may contain the minimum fixed GPTBridge root identity needed to open the permission-owned registry,provided its exact scope is declared by the top-level-path special law and every subordinate value resolves dynamically. Isolated tests may use fixture literals that cannot escape the test boundary.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (7, E'article', E'A107', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'governed-environment-variable-binding-fallback', E'governed-environment-variable-binding-fallback\nRESOLUTION-ORDER:1 Codex fixed invariant;2 permission-sovereign directory/reference code and typed field;3 approved governed environment variable for a mutable deployment value not already stored in a directory;4 explicit one-time user command for its exact scope. If a physical/entity value exists in a directory,consumers use CODE[directory_code].field and cannot duplicate it in an environment variable as a second authority. ENV-SCOPE:environment variables may provide machine/session/deployment-specific values such as feature activation,temporary endpoint binding,process-local budget,toolchain discovery hint,non-persistent test fixture or secret-provider reference when no canonical directory field applies. Every allowed variable uses GPTBRIDGE_ prefix and has registry identity,owner,purpose,value type,required/optional status,validation/range,confidentiality,default policy,scope,consumer allowlist,generation and reload/restart semantics. AUTHORITY:environment is input/binding only,never Codex,directory,permission,data or identity authority. Its value cannot redefine owner,role,canonical ID,resource revision,law state or security boundary. VALIDATION:read once into a typed configuration snapshot at the governed boundary;reject unknown,malformed,out-of-range,conflicting,stale or unauthorized variables with a typed finding. No module reads arbitrary process environment throughout business logic. Optional absence uses an explicitly registered safe default or disabled state;no guessed path/port/model/credential. CHANGE:environment changes produce a new configuration generation and affected-scope validation;hot application follows update/reload law and cannot interrupt unrelated runtime. SECRET:prefer secret-provider references;when a secret value must enter through environment it is never persisted,echoed,logged,placed in evidence,child-process command line or inherited beyond the minimum allowlisted process. TESTS:fixture variables are isolated and cleared after test. EVIDENCE:record variable code,presence,source,generation,validation result and value hash/redaction,never confidential plaintext.\nFORBID:environment duplicate of directory-owned physical value+environment treated as authority+unregistered variable+arbitrary os.environ/process.env reads in domain logic+secret logging/inheritance+silent coercion+unsafe implicit default+environment redefining identity/permission/law+change without generation invalidation+hardcoded fallback after missing variable.\nThe minimum bootstrap variable may locate CODE[ROOT_GPTBRIDGE] registry when the top-level-path law permits it;the resolved root must be validated and cannot broaden containment. CI/tests may inject registered fixture variables only inside isolated scope.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (8, E'article', E'A108', E'CODEX_MODULE_PERMISSION', E'CODEX_PERMISSION_IDENTITY_SPECIAL_LAW', E'permission-sovereign-formal-audit-validation-authority', E'permission-sovereign-formal-audit-validation-authority\nAUTHORITY:permission-sovereign is the sole formal owner of audit validation across the system. It defines and applies validation of audit identity,access scope,sequence,hash chain,signature,correlation,completeness,retention/rotation,confidentiality and admissibility against Codex-derived rules. It may return validated,rejected,incomplete,stale or conflict evidence and gate acceptance/release where audit proof is required. It has no module execution power and cannot rewrite/delete audit records,invent domain truth,repair code,approve its own unauthorized action or suppress a finding. COLLECTION:modules/shared-layer/synchronization executors append evidence through governed channels;they do not self-validate. XINGCHENG:星澄 retains independent inspection,correlation,challenge and finding capability under B81 but does not issue the formal permission-sovereign audit-validity verdict. Permission-sovereign cannot direct or suppress 星澄 findings;it validates their identity,scope,integrity and admissibility while domain truth remains with the domain owner. SEPARATION:validator identity is distinct from event actor,evidence collector and remediation executor. Validation decisions are themselves append-only audited and independently challengeable.\nFORBID:module self-validating its audit+permission-sovereign executing repair/update+validator altering source evidence+星澄 formal verdict impersonation+permission validation suppressing independent finding+same actor producing and finally validating privileged evidence without separation+audit acceptance with broken hash/identity/scope/confidentiality.\nA module may perform local pre-validation for fast feedback,marked non-authoritative;formal acceptance still requires permission-sovereign validation.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (9, E'article', E'A109', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'typed-complete-successor-resolution-successor', E'typed-complete-successor-resolution-successor\nSUCCESSOR:D94 is superseded. REGISTRY:provision_reference_resolution_v2 covers every superseded principle,article,edict and sovereign with typed predecessor identity. Each row records predecessor_type,predecessor_id,declared_successor_identity,resolved_successor_type,resolved_active_successor_id,resolution_path,status and validation timestamp. STATUS:resolved-active means the full chain terminates in exactly one active provision of the applicable type;cross-type-retirement-basis means a retired identity cites an active provision as its retirement authority rather than becoming that provision;retired-no-successor means retirement is terminal and no current semantic successor may be inferred;unresolved or cycle is incomplete evidence. INTERPRETATION:current citations automatically traverse resolved-active chains. Historical citations remain historical. A terminal retirement cannot be revived or mapped by similarity. COVERAGE:registry row count and typed predecessor set exactly equal lifecycle superseded set. FAILURE:missing row,duplicate typed predecessor,cycle,non-active resolved target or invented target blocks only the affected interpretation and produces a precise Codex finding. HISTORY:the user-deleted revision_history remains empty.\nFORBID:untyped predecessor collision+partial resolution registry+invented successor+retired identity revival+cross-type retirement authority treated as identity replacement+cycle hidden+missing target treated compliant+revision history reconstruction.\nA terminal retired identity may remain without successor when the lifecycle evidence explicitly closes it and no active rule depends on it as current authority.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (10, E'article', E'A110', E'CODEX_MODULE_PERMISSION', E'CODEX_MAIN', E'permission-decision-and-directory-authority-execution-boundary', E'permission-decision-and-directory-authority-execution-boundary\nBOUNDARY:permission-core decides automatically;DirectoryAuthority executes exact directory transaction;permission-core never writes and DirectoryAuthority never decides. EVENTS:request+identity/role/scope/purpose/risk/expiry/generation/revocation/security+Codex/directory change. DECISION-ACTIONS:ISSUE|DENY|ACTIVATE|RENEW|RESTRICT|SUSPEND|REVOKE|TERMINATE exactly one. DIRECTORY-OPERATIONS:CREATE_REVISION|ACTIVATE_REVISION|MARK_RESTRICTED|MARK_SUSPENDED|MARK_REVOKED|MARK_TERMINATED|NO_OP through fixed action-operation map. RECORD:decision binds subject+permission+resource+scope+constraints+basis+input-evidence+issuer+times+expiry+predecessor+generation+correlation+content identity; RECEIPT binds decision+operation+entry+transaction+idempotency+before/after revision+result+verification; IDEMPOTENCY:same key/payload returns prior receipt,changed payload conflicts. AUTOMATION:no human or second-key confirmation on the normal path; privileged action still requires automatically verifiable separation,least-privilege and current evidence. FAILURE:deny before write or rollback exact target+isolate\nFORBID:permission-core-persistence+DirectoryAuthority-policy-choice+self-grant+self-review+manual-confirmation-as-normal-path+MANAGE-as-operation+SUPERVISE-mutation+unregistered-map+mutable-decision/receipt+hard-delete+changed-payload-retry+generic-success-without-after-verification\nA governed executor may retry the same immutable idempotent directory operation after a transient failure; retry never changes the decision,scope,target,operation or payload.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (11, E'article', E'A111', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'canonical-core-module-execution-responsibility-model', E'canonical-core-module-execution-responsibility-model\nROLES:DECISION_CORE=POLICY_AND_ACCEPTANCE;PERMISSION_CORE=IDENTITY_SCOPE_PERMISSION_DIRECTORY_SECURITY_ENFORCEMENT;RUNTIME_CORE=STARTUP_PROCESS_LIFECYCLE_GOVERNED_EXECUTION;AUTOMATION_CORE=AUTHORIZED_WORKFLOW_SCHEDULING_AND_SYNCHRONIZATION;XINGCHENG_ASSISTANT=INSPECTION_NOTIFICATION_USER_PERMISSION_PRESENTATION;XINGCHENG=NATIVE_MODEL_OWNED_CAPABILITIES;MODULE=BOUNDED_EXECUTION_WITHOUT_AUTHORITY;INFORMATION_LAYER=TYPED_CONTRACT_AND_STATUS. PIPELINE:decision intent>permission validation>registered dispatch>module execution>typed receipt>status projection. Each request activates exactly one role identity per participant;co-location never merges roles.\nFORBID:sub-sovereign-role+core-module-role-mixing+module-policy-choice-or-self-authorization+status-as-decision+role-inferred-from-class-or-folder+transport-defining-authority\nA component may expose multiple technical interfaces only when every request preserves its single registered role and authority boundary.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (12, E'article', E'A112', E'CODEX_MODULE_MAINTENANCE', E'CODEX_AUTOMATIC_REPAIR_SPECIAL_LAW', E'health-governance-outline', E'health-governance-outline\nPURPOSE:replace monolithic C24 with independently provable contracts. COMPONENTS:B104 health contract schema+B105 observation and classification+C75 recovery orchestration. STATES:healthy|degraded|stale|reconcile_required|failed. OWNERSHIP:component owner emits signals;maintenance health management validates observations;decision sovereign decides health-impact policy;registered executor performs recovery;information layer carries contracts/status. PROOF:each component article has separate evidence and gate result;overall health never passes by averaging failed or missing required components.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:single monolithic health pass+subcontract skipped+health score replacing state+recovery evidence used as observation evidence+missing component treated healthy.\nA module may declare a subset of dimensions only when the schema marks the others not-applicable with ownership and dependency proof.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (13, E'article', E'A113', E'CODEX_MODULE_INFORMATION', E'CODEX_STAR_PRIVILEGED_INSTITUTION_SPECIAL_LAW', E'codex-official-read-session-and-attested-reader-schema', E'codex-official-read-session-and-attested-reader-schema\nSCHEMA:codex-read-session contract is the registered machine contract for official-entry reads {session_nonce|requester_identity|identity_attestation|purpose_code|provision_scope|permission_review_id|issued_at|expires_at|single_use|codex_version}. AUTHORITATIVE-READS:every sovereign authoritative view passes governance-codex://official;the requester identity is bound to a single-use session minted by the entry owner (permission-sovereign) after per-request review;least provision scope;the nonce is consumed exactly once;expiry is bounded;replayed+expired+scope-widened or mismatched sessions deny. SELF-DECLARATION:a sovereign may self-mint only its own declaration read. AUDIT:metadata-only per attempt with result;content never enters audit. CHINESE-VIEW:star-only;permission-review-exempt;all other official-entry controls plus read-only remain. RESPONSE:typed+version-identified+requested-scope-only.\nFORBID:bare-requester-string as identity+unbound session+scope beyond the declared provision+replay+expired reuse+self-minting for another sovereign\'s declaration+Chinese view by any non-star identity+content in audit+alternate entry+credential sharing\nImport-time sovereign self-declaration uses the bounded self-attested session;it never waives nonce+expiry+single-use+scope or audit.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (14, E'article', E'A114', E'CODEX_MODULE_PERMISSION', E'CODEX_MAIN', E'attested-execution-identity-derivation', E'attested-execution-identity-derivation\nDERIVATION:an execution identity is resolved from the authenticated shared-layer channel claimant and its sealed-registry binding:the requested tool manifest id equals the requested tool;the channel claimant is the sealed-registry governed identity;the registry-pinned bound manifest declares that identity when the claimant differs from the hosting owner;the module registry declares the exact execution identity for the resolved module architecture code. CONSISTENCY:all four values must agree before any governed execution;an unresolved+unattested or mismatched identity denies. SELF-DERIVATION:comparing two values derived from the same request input is not attestation and is forbidden.\nFORBID:request-echoed execution identity+self-derived comparison+channel claimant outside the sealed registry+bound manifest that does not declare the channel identity+registry execution-identity mismatch+execution before four-way resolution+placeholder identity\nA standalone single-tool runtime attests that tool\'s own chain;hosting-owner resolution applies only through the sealed-registry bound manifest,never through free text.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (15, E'article', E'A115', E'CODEX_MODULE_PERMISSION', E'CODEX_PERMISSION_IDENTITY_SPECIAL_LAW', E'permission-decision-transport-and-append-only-ledger', E'permission-decision-transport-and-append-only-ledger\nAUTOMATIC-PERMISSION-LEDGER:ISSUE|ACTIVATE|RENEW|RESTRICT|SUSPEND|REVOKE|TERMINATE append immutable events to PostgreSQL permission decision ledger; each event is produced automatically from current typed trigger and policy result and carries permission_id+decision_id+revision+subject+scope+basis+generation+effective/expiry time+correlation+result; ledger is restart source of truth; prior events remain immutable; current state is deterministic projection; unrecordable decision denies; callers never infer grant from transport acceptance\nFORBID:caller-inferred-grant+module-self-issued-id+in-memory-authority+ledger-mutation/deletion+silent-ledger-failure+unrecorded-transition+manual-confirmation-as-normal-path+automatic-renew-with-stale-basis\nImmediate containment may suspend or revoke an exact permission before review;every grant+renewal or expansion still requires the two-key rule.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (16, E'article', E'A116', E'CODEX_MODULE_INFORMATION', E'CODEX_INFORMATION_COMMUNICATION_SPECIAL_LAW', E'bidirectional-multiplexed-channel-special-law', E'bidirectional-multiplexed-channel-special-law\nDIRECTION:every canonical information channel supports governed bidirectional request,response,event,acknowledgement,cancellation,health and recovery traffic over one typed transport contract; either endpoint may originate an authorized message without reversing ownership or permission boundaries. MULTIPLEXING:one physical connection may carry multiple isolated logical streams concurrently; every frame binds channel_code,connection_generation,stream_id,message_id,correlation_id,sequence,direction,operation_id,schema_version,deadline,priority and authorization_context. ORDERING:sequence is strict per stream; no global ordering is implied across independent streams; response,event and acknowledgement preserve correlation. FLOW-CONTROL:each stream has bounded queue,window,rate,budget,timeout,cancellation and backpressure; congestion or failure in one stream is isolated and cannot block healthy streams. FAIRNESS:priority scheduling reserves capacity for control,health and recovery traffic while preventing starvation. RECONNECT:reconnection creates a new connection generation, resumes only acknowledged resumable streams from durable checkpoints, rejects stale frames and deduplicates idempotency keys. HALF-CLOSE:each direction may close independently; final channel shutdown occurs only after both directions close or a governed fatal isolation decision. SECURITY:authentication,authorization,classification and audit apply per logical stream and message,not merely per socket. OWNERSHIP:information-layer owns information truth and service;shared-layer implements transport and contracts;automation-sovereign operates and maintains channels;permission-sovereign decides access;decision/runtime sovereigns do not intervene;星澄 may traverse within its lawful privilege but cannot bypass per-stream controls.\nFORBID:single-direction-only canonical channel+head-of-line blocking across independent streams+shared sequence across unrelated streams+cross-stream identity/permission/evidence reuse+unbounded streams or queues+silent frame loss+stale-generation acceptance+automatic code overwrite/reset during recovery+failure propagation to healthy streams+connection-level authorization substituted for per-stream authorization.\nA strictly one-way external protocol may use one direction only when its registered adapter still exposes the canonical bidirectional contract and explicitly marks the unavailable direction; this exception creates no second transport authority.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (17, E'article', E'A117', E'CODEX_MODULE_AUTHORITY', E'CODEX_SYSTEM_RELIABILITY_SPECIAL_LAW', E'sovereign-multicore-parallel-collaboration-special-law', E'sovereign-multicore-parallel-collaboration-special-law\nSCOPE:decision-sovereign,runtime-sovereign,automation-sovereign and independent privileged institutions may deliberate,review,coordinate and exchange evidence concurrently through isolated logical work units;parallelism does not grant execution power to a sovereign that lacks it. DECISION-SOVEREIGN:parallel analysis is joined into one deterministic decision and never becomes module execution. RUNTIME-SOVEREIGN:parallel readiness,health and lifecycle coordination is joined before dispatch and never performs module work. SYNCHRONIZATION-SOVEREIGN:may run bounded multicore channel,update,synchronization,backup,repair,cleanup and logging coordination only within its expressly executable privileges. PERMISSION-SOVEREIGN:parallel permission and audit-verification checks remain independent from execution and converge into one permission result. 星澄:may perform privileged parallel analysis,review,automation coordination and lawful native execution under its special law. SUB-SOVEREIGNS:may parallelize dispatch planning,module supervision and evidence collection but possess no actual module execution power. MODULE-EXECUTION:actual work remains with registered module executors. SCHEDULING:eligible CPU work uses adaptive bounded multicore workers;I/O work uses bounded asynchronous concurrency;capacity reserves protect UI,channels,database and recovery paths. ISOLATION:each work unit has task_id,owner,active_role,generation,scope,permission,resource budget,deadline,cancellation,checkpoint and receipt. JOIN:dependencies form an acyclic graph;mandatory branches verify before deterministic stable-order convergence. FAILURE:a failed worker or branch is quarantined,retried or degraded independently while healthy collaboration continues. CONFLICT:shared mutable targets and irreversible effects serialize under one lawful transaction or lock owner.\nFORBID:sovereign execution by relabeling parallel analysis+sub-sovereign module execution+unbounded worker creation+use of every core without reserve+shared mutable state without ownership+cross-task credential/evidence reuse+nondeterministic merge+completion before mandatory join+fault cascade+parallel conflicting decisions presented as multiple authority results.\nEmergency capacity reduction may serialize work without violating the collaboration contract;serialization changes throughput only and never transfers authority.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (18, E'article', E'A118', E'CODEX_MODULE_INFORMATION', E'CODEX_INFORMATION_COMMUNICATION_SPECIAL_LAW', E'sovereign-subsovereign-direct-information-layer-route', E'sovereign-subsovereign-direct-information-layer-route\nDIRECT-ROUTE:a sovereign and any lawfully attached sub-sovereign may address each other directly without an intermediary sovereign,while every message still enters the canonical information-layer service and is carried only by the shared-layer typed transport implementation. ROUTE:sovereign identity -> information-layer authorization+contract+correlation -> shared-layer logical stream -> attached sub-sovereign identity,and the reverse path uses the same contract. BIDIRECTIONAL:request,response,event,acknowledgement,cancellation,health,dispatch-status and evidence may originate from either endpoint within its role. BOUNDARY:direct means logical endpoint selection only;it never means in-process bypass,direct filesystem/database access,private import,unaudited IPC or authority inheritance. VALIDATION:each stream proves current attachment,active identity,role,scope,permission,generation,schema,deadline,sequence and correlation before delivery. AUTHORITY:the sovereign retains only its declared decision or privileged power;the sub-sovereign retains dispatch,module-management and coordination duties and gains no module execution power. INFORMATION-OWNERSHIP:information-layer owns information service and routing truth;shared-layer implements channel and contract;automation-sovereign operates and maintains transport;permission-sovereign decides access. ISOLATION:one sovereign-sub-sovereign stream has its own queue,budget,backpressure,checkpoint and fault domain;failure cannot interrupt unrelated streams. TOPOLOGY:attachment is resolved dynamically from the registered hierarchy and identity generation,never from hard-coded physical addresses.\nFORBID:direct-call bypass of information-layer+private cross-boundary method/import used as transport+permission inheritance from attachment+sub-sovereign execution+unregistered attachment+hard-coded endpoint+cross-stream credential/evidence reuse+uncorrelated response+stale-generation delivery+failure propagation.\nA pure call wholly inside one process,module,owner,trust,principal,generation and state-owner remains an internal implementation call under the call-boundary rule;once sovereign or sub-sovereign identities differ,this direct-route article applies.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (19, E'article', E'A119', E'CODEX_MODULE_PERMISSION', E'CODEX_PERMISSION_IDENTITY_SPECIAL_LAW', E'active-identity-metadata-and-dynamic-location-contract', E'active-identity-metadata-and-dynamic-location-contract\nIDENTITY-METADATA:current viewer,actor,owner and route metadata is derived from the active identity and hierarchy registries at the current generation;retired,abolished or superseded identities are excluded from active lists and retained only in lineage. CHINESE-MIRROR:its content viewer remains exclusively 星澄 regardless of generic machine-Codex metadata. LOCATION:physical values already governed by a directory entry are referenced by architecture,directory,tool,module,command,fault or environment code and resolved dynamically through the registered current-generation resolver;duplicate physical literals outside the authoritative directory are invalid. TIMESTAMP:only timestamp fields may contain literal time values under the timestamp format article;version identity and timestamps remain separate typed fields. AUDIT:permission-sovereign verifies authorization and audit integrity;星澄 reviews Codex-versus-implementation conformity and reports issue class,rule,code,path and detailed evidence without generic findings.\nFORBID:retired identity in active metadata+Chinese mirror viewer expansion+duplicated hard-coded physical path+timestamp used as an untyped substitute for another field+generic finding without exact file or registered target.\nA directory\'s authoritative physical_root field may contain the resolved physical value as the single source of truth;all consumers use its code.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (20, E'article', E'A120', E'CODEX_MODULE_RELEASE', E'CODEX_RELEASE_VERSION_SPECIAL_LAW', E'epoch-two-canonical-identity-and-seal-authority', E'epoch-two-canonical-identity-and-seal-authority\ncodex_version_epochs is canonical epoch identity authority and contains one active E2 row. epoch_seal_manifest binds E2,version identity,history head,counts and roots. Metadata,certification evidence,seal_manifest and epoch tables agree exactly. Empty epoch tables with active E2 metadata are invalid. Retirement requires explicit successor. E2 remains pending external signatures.\nFORBID:metadata-only epoch+empty epoch registry+multiple active E2 rows+root mismatch+pending candidate presented certified.\nPre-genesis legacy history head may be registered but never reconstructed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (21, E'article', E'A121', E'CODEX_MODULE_PERMISSION', E'CODEX_PERMISSION_IDENTITY_SPECIAL_LAW', E'registered-bounded-codex-proxy-clean-successor', E'registered-bounded-codex-proxy-clean-successor\nSUCCESSOR:A121 completely supersedes A22 and D16. ACCESS:registered sovereigns and a registered bounded Codex proxy may use governance-codex://official read-only through permission-authorized scope. A proxy is an adapter identity,not a sovereign,sub-sovereign,executor or delegated credential holder;it may retrieve only requested provisions and submit amendment candidates,diffs and evidence. It has no seal,certification,adjudication,authorization,decision,execution,activation or direct database power. PRECEDENCE:this explicit bounded exception is part of the controlling rule and no longer depends on more-specific-rule inference.\nFORBID:anonymous/direct database access+proxy authority inheritance+credential delegation+scope expansion+proxy decision/execution+silent A22/D16 conflict resolution.\nCertified audit tooling retains its separate metadata/integrity read profile.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (22, E'article', E'A122', E'CODEX_MODULE_AUTHORITY', E'CODEX_PERMISSION_IDENTITY_SPECIAL_LAW', E'codex-normative-authority-terminology-clean-successor', E'codex-normative-authority-terminology-clean-successor\nSUCCESSOR:A122 completely supersedes A12. TERMINOLOGY:Codex is the highest normative authority and rule declaration layer only;it is never operational authority and has no identity,decision,execution,authorization,adjudication,command or control power. Runtime actors apply Codex through their own registered authority and receipts. The phrase operational-authority is retired for Codex and may describe only an active registered runtime institution within its scope.\nFORBID:calling Codex operational authority+deriving runtime power from normative rank+Codex as active sovereign or executor.\nCodex integrity enforcement by tooling is execution owned by that tooling,not power exercised by Codex.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (23, E'article', E'A123', E'CODEX_MODULE_PERMISSION', E'CODEX_PERMISSION_IDENTITY_SPECIAL_LAW', E'canonical-command-permission-action-contract', E'canonical-command-permission-action-contract\nEvery command permission_action is exactly action:target using the registered action and target identities;display names,hyphenated approximations and inferred values are invalid. SYS_GPTBRIDGE_START is start:main-system. Registration validates the permission capability directory and command contract before dispatch.\nFORBID:permission_action without colon+display-name permission+action or target mismatch+dispatch before permission resolution.\nA versioned alias may be accepted only during a registered migration window and resolves to one canonical action:target.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (24, E'article', E'A124', E'CODEX_MODULE_XINGCHENG', E'CODEX_LEARNING_SYSTEM_SPECIAL_LAW', E'learning-sub-sovereign-transfer-to-xingcheng', E'learning-sub-sovereign-transfer-to-xingcheng\nHISTORICAL-TRANSFER:learning-evidence-sync-sub-sovereign is retired lineage and cannot be current owner or parent. CURRENT:the self-learning capability is an owned XINGCHENG module; XINGCHENG controls its model-domain learning while automation-core may schedule system update workflows and xingcheng-assistant only audits and notifies. IDENTITY:legacy references normalize through B162 and do not revive a sub-sovereign.\nFORBID:active-learning-sub-sovereign+assistant-owning-native-model-learning+legacy-route+cross-database-authority\nSynchronization modules may transport opaque learning events under channel law but acquire no learning ownership,content authority or management power.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (25, E'article', E'A125', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'automation-sovereign-canonical-rename', E'automation-sovereign-canonical-rename\nRENAME:synchronization-sovereign is canonically renamed automation-sovereign; DISPLAY:自動主宰; IDENTITY:automation-sovereign is the sole active identity and inherits without expansion every former synchronization-sovereign duty,power,restriction,child relationship,module decision assignment,contract,receipt and lineage; RETIREMENT:the former name is a historical deprecated alias only and cannot authenticate,decide,receive assignment or coexist as an active sovereign; SCOPE:automation-sovereign decides automation synchronization,resource convergence,channel continuity,state convergence,release/update transactions,repair/backup,cleanup/retention,automatic logging and dependency coordination through its assigned sub-sovereigns,excluding learning-sub-sovereign transferred to 星澄 by A124; EXECUTION:its exceptional certified update execution remains limited exactly by C52 and all other execution stays with registered module executors; MIGRATION:all current registries,contracts,metadata,rosters,module assignments,permission viewers and machine references resolve to automation-sovereign; compatibility input using the old alias must resolve one-way to automation-sovereign during a registered bounded migration and output only the canonical identity.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:active synchronization-sovereign identity+dual old/new sovereigns+old alias authentication or authority+rename used to expand power+learning-sub-sovereign returned to automation-sovereign+unregistered string substitution at runtime.\nImmutable historical revision and audit records retain the name originally recorded; their resolver presents automation-sovereign as the current successor without rewriting historical bytes.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (26, E'article', E'A126', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'database-security-projection', E'database-security-projection\nSECURITY-PROJECTION:permission-core decision>authorization artifact>PostgreSQL principal/principal_scope/RLS/can_read/can_write projection>enforcement; projection refresh,expiry,generation fence,suspension,revocation and termination propagate automatically from the permission ledger; principal_id resolves registered identity+generation+scope and is not Codex actor identity by implication; projection can deny on stale state but cannot issue,renew or expand permission\nFORBID:database-row-creates-permission+projection-self-grant/self-renew+scope-expansion+stale-generation-write+principal-equals-actor-by-implicit-mapping+projection-as-authority\nPreviously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (27, E'article', E'A127', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'中文法典五分卷鏡像法', E'中文法典五分卷鏡像法\n中文鏡像由五個同版本、有序、雜湊鏈結且可重建組合根的唯讀分卷構成。\n禁止缺卷、重號、斷鏈或三分卷 current。\n無。');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (28, E'article', E'A128', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'法典文字完整性與轉碼防護條例', E'法典文字完整性與轉碼防護條例\nA128 補充 D75、D118、A127、B118 與 C102。正式法典、五份中文法典與全部架構圖必須使用 UTF-8，並在候選發布前拒絕替代字元、連續問號占位、錯誤轉碼片段、非預期控制字元及不可還原文字。既有受損顯示文字得以不改變規範語義的精確修復交易更正，並必須重建搜尋文件、中文鏡像、修訂鏈與 seal roots。\nFORBID:lossy-encoding|replacement-character|repeated-question-placeholder|mojibake-publication|text-check-bypass|pass-with-corrupted-normative-text。\n合法問句中的單一問號不受禁止；歷史語義不得藉文字修復而改寫。');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (29, E'article', E'A129', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'故障手冊移交星澄學習模組條例', E'故障手冊移交星澄學習模組條例\nFAULT-MANUAL-LEARNING:the registered XINGCHENG learning module receives read-only fault messages,formal manuals,use outcomes and update suggestions for autonomous learning. FAULT-DIRECTORY:permission-core retains fault identity,classification and directory authority in PostgreSQL. The learning module gains no fault mutation,permission,repair-decision or repair-execution authority. Any learning-evidence-sync-sub-sovereign wording is historical and normalizes through B162.\nFORBID:active-learning-sub-sovereign+learning-module-mutating-fault-directory+learning-as-repair-authority+non-PostgreSQL-fault-directory\n手冊正式內容的法典修訂仍須走受治理修訂及驗證流程。');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (30, E'article', E'A13', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'integration', E'integration\nOWNER:channel-contract-sync-sub-sovereign; SCOPE:cross-sovereign-module-structural-interface/channel/sync/bus; BASIS:codex-delegation\nFORBID:channel-contract-sync-sub-sovereign-decision-layer-coordinate/overstep-exec\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (31, E'article', E'A130', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'gptbridge-integrated-objectives', E'gptbridge-integrated-objectives\nIntegrated registered Codex contract objectives: seven operational goals (high speed, high performance, low load, automated operation, high stability, autonomous learning and upgrade); Xingcheng can chat with the user and complete tasks through governed permission and safety gates; no huge dataset is required; the model is quantifiable, distillable, accelerable, reason-capable and web-searchable. Each objective maps to an existing registered Codex contract mechanism (acceleration chapter, resource governance, automation division, convergence chapter, self-learning, L5/L6, T1-T4 tiers, maturity ladder, teacher-distillation pipeline, C core / C++ layer / caches / quantization, governed web channel).\nThe objectives must be pursued through the existing sovereign structure and mechanisms; no new sovereign or parallel control system is introduced.\nregistered Codex contract integrated-objectives block records the mapping; the objectives themselves are program goals, not new components.\n\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (32, E'article', E'A131', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'gptbridge-implementation-precedence', E'gptbridge-implementation-precedence\nWhen a verified implementation is superior to stale descriptive text or a non-authoritative projection,preserve the implementation and converge the formal Codex or registered contract through the governed amendment path. Never roll back superior verified behavior merely to match retired planning text. Every convergence records affected provision or contract,source revision,evidence,authority boundary and unresolved gaps. This rule does not permit implementation to amend law,generate permission or bypass fail-closed controls.\nFORBID:registered Codex contract authority|rollback to retired planning text|implementation self-authoring law|evidence-free superiority claim|projection overriding formal Codex.\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (33, E'article', E'A133', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'core-deployment-topology', E'core-deployment-topology\nIDENTITY-SEPARATION:decision,permission,runtime,automation and xingcheng-assistant remain distinct peer governance identities;DEPLOYMENT:they may share one local host but retain separate process,data,permission and failure boundaries according to the architecture registry;XINGCHENG-SEPARATION:xingcheng native model and xingcheng-assistant use separate identities and separate databases and neither database grants authority to the other;CROSS-BOUNDARY:only registered versioned channels;CODEX:the formal PostgreSQL Codex is read through governed scope,while the Chinese mirror is a non-authoritative projection synchronized with it;MAINTENANCE:authorized cores may maintain the formal Codex only through its amendment controls. DATA-RESIDENCY:all data owned by or created for Xingcheng, including identity, personality, memory, conversation context, learning corpus, training state, weights, checkpoints, evaluation evidence, repair knowledge, tool-use state and runtime records, must remain exclusively inside the registered Xingcheng domain and Xingcheng-owned storage. CROSS-DOMAIN:other cores, tools and the Xingcheng assistant may receive only the minimum typed result or an opaque owner-scoped reference through a registered channel; they may not persist, mirror, cache, index, train on, back up or claim authority over Xingcheng data. ACCESS:authorized processing outside the owning process must execute against Xingcheng-owned storage under Xingcheng scope without transferring custody. LIFECYCLE:retention, recovery, migration and deletion remain Xingcheng-owned and must preserve the same boundary.\nFORBID:identity collapse|database mixing|co-residency implying authority|ungoverned cross-boundary channel|mirror treated as authority|deployment location creating permission.+Xingcheng-data-outside-Xingcheng-domain+cross-domain-copy-or-cache+shared-database-mixing+assistant-storage-of-Xingcheng-data+external-indexing-or-training+custody-transfer-by-reference+backup-outside-owner-boundary\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (34, E'article', E'A134', E'CODEX_MODULE_XINGCHENG', E'CODEX_LEARNING_SYSTEM_SPECIAL_LAW', E'星澄自主訓練權限、資源與政策權屬條例', E'星澄自主訓練權限、資源與政策權屬條例\nSUCCESSOR:A134 supersedes D131。星澄得在其已登錄之模型、人格、自我學習與自動編程領域內自主決定訓練時機、課程、資源申請、評估、分階段上線與回滾；訓練一律按需啟動、完成即釋放，且不得成為常駐程序。自主訓練不得擴張星澄的權限、資料範圍、網路範圍、工具範圍或法典效力。資源優先序固定為治理與安全閘門、使用者互動與現役推論、受管修復工作、背景自主訓練；資源不足或與推論衝突時，訓練必須延後或停止。訓練觸發門檻、資料來源、合成資料比例、課程選擇、GPU／時間／次數預算、評估套件、auto_activate、熔斷、保留與回滾政策皆屬受管政策；星澄只能依政策執行，不得自行修改。政策變更由裁決核心裁決，權限核心完成測試與審計，星澄助理完成法典對齊稽查，運行核心執行。候選成果只有在資料、品質、成熟度、資源、回歸與回滾閘門全數通過後才可啟用；任一閘門失敗均維持現役權重不變並 fail-closed。\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:self-expanded-authority|self-modified-policy|training-priority-over-governance-or-active-inference|resident-training-worker|activation-without-evaluation-and-rollback|unbounded-resource-budget\n總督得依正式 amendment 調整政策權屬或資源優先序；調整前不得由 runtime 設定反向產生法典權限。');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (35, E'article', E'A135', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'共同禁止條款引用條例', E'共同禁止條款引用條例\n建立三組唯一共同禁止條款。SPECIAL_LAW_BOUNDARY＝parallel-authority、directory-self-registration、cross-domain-decision、permission-bypass、direct-ungoverned-execution、unversioned-change、unbounded-retry、success-without-proof、special-law-scope-overreach。SENSITIVE_SCOPE_BOUNDARY＝unregistered-scope、cross-owner-authority、permission-bypass、secret-or-personal-data-leakage、unbounded-operation、silent-failure、success-without-evidence、scope-overreach。SQL_GOVERNANCE_BOUNDARY＝authority-inversion、implicit-identity-casting、unbounded-fallback、out-of-band-DDL、schema-drift-continuation、projection-treated-as-permission-authority、release-before-complete-PASS-evidence。A62–A67、C38–D44、C83–D127 與 C101 的現行表示應引用相應條款；引用不縮減原有效力，領域特有禁止仍由各條保留。\nFORBID:duplicate-common-prohibition-text|reference-that-weakens-effect|unresolved-common-clause\n已 superseded 條文僅保留歷史，不重寫其內容。');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (36, E'article', E'A137', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'法典五類規範分類條例', E'法典五類規範分類條例\n法典固定分為 PRINCIPLE 原則、ARTICLE 條文、EDICT 敕令、RESPONSIBILITY 權責、PROHIBITION 禁止事項。前三類是互斥結構主類；後兩類是規範面向。每個 provision 必須恰有一個結構主類並標示權責及禁止事項。權限核心管理非權威分類投影，不得改變原 provision 效力。分類缺失、重複、未知或 successor 不一致時，法典索引不得啟用且 VERIFIED_RELEASE_DENIED。\nFORBID:unclassified-current-provision|multiple-structural-primary-classes|classification-changing-provision-effect|classification-as-parallel-authority\n同一 provision 得同時具有權責與禁止事項面向。');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (37, E'article', E'A138', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'法典唯一控制命題與跨層重述收斂條例', E'法典唯一控制命題與跨層重述收斂條例\n法典收斂採一個規範命題一個 controlling provision。原則、條文與敕令之間語義相同或高度重疊的文本，必須在 codex_normative_convergence_registry 指向唯一 controlling provision；其餘 provision 保留原身分、層級、歷史與補充面向，但標示為 restatement-non-independent，不得形成平行控制來源。敕令與其他層級重述時由敕令控制；原則與條文重述時由原則控制；後位明示 successor 優先於一般層級規則。Runtime 規則索引只索引 controlling rule，並可合併 subordinate provision 明確存在而 controlling provision 未重述的權責或禁止事項，但不得改變控制文本。共同禁止條款的引用及不同客體的模板實例不是重複。無法唯一解析、出現多個 current controller、控制條失效或合併面向衝突時，一律 NORMATIVE_CONVERGENCE_CONFLICT、索引拒絕啟用且 VERIFIED_RELEASE_DENIED。\nFORBID:parallel-controlling-provision|unresolved-cross-layer-restatement|multiple-current-controller|restatement-overriding-controller|runtime-indexing-subordinate-restatement|facet-merge-changing-controller\n不同客體、不同適用範圍或依法引用共同禁止條款者，經 scope 證明後得維持各自 controlling provision。');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (38, E'article', E'A14', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'actors', E'actors\nACTOR-CLASSES:human-operator/governed-app/sovereign/星澄; REQUESTER:one-of-declared-classes; IDENTITY:verified-at-entry\nFORBID:undeclared-actor-class/forged-identity/requester-impersonation\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (39, E'article', E'A15', E'CODEX_MODULE_PERMISSION', E'CODEX_MAIN', E'bootstrap', E'bootstrap\nBOOTSTRAP:initial-allowlist; AUTHORITY:codex-one-time; TIMING:first-valid-load; EFFECT:directory-driven-thereafter\nFORBID:post-bootstrap-seed/privilege-escalation-path\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (40, E'article', E'A16', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'interface-layer', E'interface-layer\nINTERFACE-LAYER:presentation-of-decisions-state;AUTHORITY:no-decide-no-exec;STACK:resolve-current-approved-shell+UI-runtime+native-view-toolkit from B166;BIND:all-modules-and-all-execution\nFORBID:interface-decision+interface-execution+frontend-governance/permission/data-authority\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (41, E'article', E'A17', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'cross-layer-information-layer', E'cross-layer-information-layer\nINFORMATION-LAYER:cross-layer-peer-authority; AUTHORITY-RANK:equal-to-sovereign-layer; COMPONENTS:shared-layer+postgresql+rust-vector-engine+status+events+ipc; EXCLUSIVE-AUTHORITY:information-channel+transport+state+structured-data+semantic-index; CONTENT-OWNERSHIP:source-and-authorized-consumer; GOVERNANCE:directly-bound-by-codex+codex\nFORBID:sovereign-or-sub-sovereign-override-information-layer-authority; FORBID:information-layer-own-sovereign-business-decision-or-module-execution; FORBID:component-duty-substitution; FORBID:alter-message-or-authoritative-data-outside-governed-operation\n');
