INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (287, E'article', E'C2', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'system-responsibility', E'system-responsibility\nGIT:version+history; POSTGRESQL:central-structured-official-data+shared-transport+audit; POSTGRESQL-PGVECTOR:canonical-semantic-vector-authority; RUST-VECTOR-ENGINE:rebuildable-derived-semantic-index; RAG:hybrid+code+agentic+memory; LLM:understand-reason-operate; OWNERSHIP:local-governed\nFORBID:role-substitution/alternate embedded database-as-central-official-or-shared-audit/local-vector-as-canonical-semantic-index/unreconciled-fallback+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (288, E'article', E'C20', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'frontend-backend-recovery-boundary', E'frontend-backend-recovery-boundary\nSTATUS:information-layer-real-time-to-all-active-ui; HEALTH-OWNER:health-maintenance-test-sub-sovereign; REPAIR-DECISION:decision-sovereign; RUNTIME-RESTART:runtime-sovereign; CODE-CHANGE:release-update-sync-sub-sovereign; LEARNING:learning-evidence-sync-sub-sovereign\nFORBID:maintenance-owning-non-health-decisions+duplicate-repair-owner+stale-ui\n');
