INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (290, E'article', E'C23', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'code-extraction-prohibition', E'code-extraction-prohibition\nCODE-EXTRACTION:forbidden-from-backup+snapshot+recovery-artifact+cache+replica; BACKUP:owner-scoped-restore-only-no-code-reproduction; RECOVERY:byte-identical-restore-only-no-code-extraction; HOT-UPDATE:version-gated-replacement-no-code-duplication; REPAIR:governed-executor-only-no-code-copy\nFORBID:code-extraction-from-backup/code-reproduction-from-snapshot/code-fork-from-recovery/code-duplication-during-hot-update/code-copy-during-repair/unauthorized-code-recovery\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (291, E'article', E'C25', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'single-codex-with-星澄-only-Chinese-exception', E'single-codex-with-星澄-only-Chinese-exception\nSOLE-AUTHORITY:the current local PostgreSQL gptbridge_codex at governance-codex://official is the one and only Governance Codex authority;NO-FILE-AUTHORITY:no SQL dump,database file,JSON,cache,export,backup,search projection,architecture document or generated artifact is a Codex authority or parallel Codex;ONLY-MIRROR-EXCEPTION:exactly five synchronized read-only governance_codex.zh-TW.part files may exist as one non-authoritative Chinese language mirror;MIRROR-RIGHTS:adjudication-none+execution-none+import-none+write-none+authority-none;CONFLICT:PostgreSQL current effective law always prevails;FAILURE:missing,stale,mixed-version or damaged Chinese parts become unavailable and never create a fallback authority;PROHIBITION:no other Codex mirror or machine Codex copy may be retained\nFORBID:parallel-codex-authority+file-codex-authority+SQL-dump-mirror+database-file-mirror+JSON-mirror+backup-as-authority+mirror-fallback+non-Chinese-codex-mirror\n星澄-only Chinese read exception; no authority or permission-review requirement; official-entry identity scope session and audit remain mandatory');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (292, E'article', E'C26', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'frontend-backend-connection-fault-tolerance', E'frontend-backend-connection-fault-tolerance\nSCOPE:main-system+every-independent-tool frontend/backend; OWNER:information-layer-connection-controller-only; STATE-MACHINE:idle>connecting>authenticating>synchronizing>connected>degraded>reconnecting>repairing>failed; TRANSITION:typed+monotonic+generation-id+reason+timestamp+attempt-count; SESSION:authenticated+authorized+contract-versioned+generation-fenced+single-active-per-client-route; LIVENESS:bidirectional-heartbeat+deadline+miss-threshold+transport-close+protocol-error+backend-generation-change; DETECTION:any-liveness-failure-immediately-invalidates-ready-and-blocks-state-changing-commands; RECONNECT:automatic-single-flight+cancel-prior-attempt+bounded-exponential-backoff+jitter+rate-limit+maximum-attempt-window+fresh-session-token+fresh-generation; RESYNC:resubscribe+send-last-acknowledged-event-cursor+backend-gap-check+authoritative-full-snapshot-on-gap-or-generation-change+monotonic-event-replay-with-idempotency-key+client-ack; READY-GATE:transport+authentication+authorization+contract-compatible+subscription+snapshot-current+cursor-contiguous+required-runtime-health; COMMANDS:connected-ready-generation-only+request-id+idempotency-key+acknowledged-result; OFFLINE/DEGRADED/REPAIRING:fail-closed+no-implicit-queue+no-stale-replay; REPAIR-ESCALATION:reconnect-budget-exhausted>information-layer-signal>maintenance-health-classification>decision>permission>system-runtime-or-programming>governed-executor>independent-verification>fresh-reconnect; UI:all-connection-state+reason+attempt+last-success+repair-state published-in-real-time-through-information-layer; RECOVERY-SUCCESS:new-generation-ready+stable-heartbeat-window+snapshot-and-cursor-verified; COVERAGE:same-contract-for-development+production+hot-reload+post-repair\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:frontend-owned-WebSocket+direct-backend-connection+multiple-reconnect-loops+concurrent-session-generations+socket-open-as-ready+fixed-delay-retry+unbounded-retry+retry-storm+reuse-expired-session+command-while-not-ready+silent-command-buffer+out-of-order-event-apply+cursor-gap-ignore+stale-snapshot-as-current+UI-manual-refresh-dependency+repair-success-before-stability-window+hidden-failed-state+information-layer-bypass\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (293, E'article', E'C28', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'third-party-sovereign-optimized-responsibility', E'third-party-sovereign-optimized-responsibility\nDEPENDENCY-AUTHORITY:automation-core automatically updates registered dependency versions but cannot admit a new dependency identity/source/runtime without current explicit permission artifact. ADMISSION:request declares purpose+owner+consumers+alternatives+direct/transitive graph+source+exact candidate+license+security+privilege/network/data/resource footprint; permission-core allow/deny precedes any fetch/install/lock/execute. UPDATE:registered identity follows 14-day normal rule or verified emergency exception and all gates;every package download uses exactly Visual Studio Installer or Winget;language package managers (including Bun) never perform a network download and use only vendored or already-registered artifacts;a package neither channel can provide requires an explicit permission artifact;Python and Node.js are forbidden:no download,install,execution,residency or final effective state. RETIREMENT:consumer cutover+stability+zero active consumer+zero lock/manifest/runtime reference+data/config migration+bounded rollback retention+purge receipt; terminal PURGED means no binary,package,cache,environment,model artifact or executable reference remains. INVENTORY:current+rollback-only+retirement state machine machine-readable.; UPDATE-DETECTION:every-24-hours+immediate-governed-security-advisory-event; RETIREMENT-TAG:mandatory from SUPERSEDED through PURGE_READY and binds dependency-id+old-version+successor-version+state+reason+zero-consumer-progress+rollback-deadline+scheduled-purge-at\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:unapproved-new-package+implicit-transitive-admission+package-manager-auto-add+language-manager-network-download+package-list-addition-without-explicit-permission+unapproved-source/repository+download-before-admission+retired-version-active-consumer+indefinite-old-version-retention+purged-artifact-reference+deletion-before-proven-cutover+missing-or-stale-retirement-tag+update-detection-interval-not-24-hours\nA dependency without an upstream signature may be considered only when its exact bytes are content-addressed, independently provenance-verified, reproducibly acquired from an approved source, sandbox-tested, explicitly risk-accepted, and bounded to a noncritical scope');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (294, E'article', E'C29', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'local-code-and-third-party-dependency-boundary', E'local-code-and-third-party-dependency-boundary\nBOUNDARY:local authored code remains authority;third-party dependencies are exact pinned immutable artifacts. NEW-ADMISSION:explicit permission required for every new identity,source,introduced transitive dependency and package-list addition; no permission means no network fetch,installation,manifest/lock change or execution;package download channels are exactly Visual Studio Installer and Winget;language package managers (including Bun) never perform a network download and use only vendored or already-registered artifacts except under an explicitly permitted exception;Python and Node.js are forbidden without exception. EXISTING-UPDATE:D28/C28 automated timing and gates. RETIREMENT:replace consumers+remove lock/manifest reference+verify zero runtime load+retain at most one prior version during bounded rollback window+automatic purge after expiry; purge removes installed files,caches,staging remnants and rebuildable artifacts while retaining only audit/receipt metadata.; UPDATE-DETECTION:every-24-hours+immediate-governed-security-advisory-event; RETIREMENT-TAG:mandatory from SUPERSEDED through PURGE_READY and binds dependency-id+old-version+successor-version+state+reason+zero-consumer-progress+rollback-deadline+scheduled-purge-at\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:unmanaged/unapproved-dependency+implicit-download+dependency-confusion+floating-version+runtime-self-install+package-postinstall-unreviewed-execution+old-binary/cache-after-purge+multiple-rollback-generations+third-party-as-authority+missing-or-stale-retirement-tag+update-detection-interval-not-24-hours\nOperating-system components may use OS-attested identity and servicing provenance when byte-level pinning is unavailable; exact platform version and capability scope remain required');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (295, E'article', E'C3', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'hot-update', E'hot-update\nHOT-UPDATE:version-gated-frozen-boundary; APPLY:requires-governance-authorization\nFORBID:unauthorized-runtime-replace/hot-update-codex\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (296, E'article', E'C30', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'global-timestamp-propagation', E'global-timestamp-propagation\nSCOPE:all-main-system+independent-tools+sovereigns+sub-sovereigns+information-layer+executors+frontend/backend+PostgreSQL+PostgreSQL-pgvector+Rust-derived-index-metadata+RAG+model-operations+files-cross-owner+Git-operations+commands+requests+responses+events+state+data-mutations+decisions+permission-proofs+execution-proofs+health+repair+learning+audit+errors+retries+checkpoints+backups+releases+versions+UI-projections; REQUIRED-FIELDS:event-or-record-id+occurred-at-utc-RFC3339+recorded-at-utc-RFC3339+timezone-IANA+local-display-time-RFC3339-with-offset+monotonic-sequence+clock-source+clock-status+origin-generation+correlation-id; AUTHORITY:occurred-at assigned-once-by-origin-owner+recorded-at assigned-once-by-authoritative-store/ledger; PROPAGATION:information-layer validates-format/drift/generation+preserves-original-times+adds-hop-received/sent timestamps without-overwrite; STORAGE:PostgreSQL=timestamptz-UTC+sequence+canonical-vector-metadata,Rust-derived-index=UTC-string+source-record-id/revision,JSON/API=RFC3339-UTC+explicit-timezone,UI=localized-display-derived-from-UTC+shows-staleness; PRECISION:minimum-millisecond+preserve-higher-source-precision; ORDER:origin-monotonic-sequence+causal-parent+authoritative-revision determine-order+wall-clock-never-sole-order; CLOCK:D20 authenticated-source+max-drift-5-seconds; DRIFT/UNKNOWN-CLOCK:mark-untrusted+block-expiry/security/release/order-sensitive mutation+permit-redacted-diagnostic-only; REPLAY:retain-original-occurred-at/sequence+new-delivery-time-separated; MIGRATION:legacy-record-without-time remains-legacy-unknown+must-not-fabricate; RETENTION/TZ-CHANGE/DST:never-change-stored-UTC+render-current-or-recorded-zone-explicitly; UI-SYNC:D31 includes-commit-time/event-time/render-time/ack-time and calculates-lag; AUDIT:append-only timestamp evidence+clock corrections as-new-events\nFORBID:missing-timestamp-on-new-record+naive-local-time+timezone-abbreviation-only+server-receipt-time-replacing-origin-time+timestamp-overwrite/backdate/future-date beyond-tolerance+fabricated-legacy-time+wall-clock-only-order+cross-generation-sequence reuse+UI-generated-authoritative-time+database-default-time-as-origin-when-origin-known+silent-clock-drift+timestamp-stripping at-channel/serialization/indexing/export+different-module-private-time-format+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\nPure ephemeral arithmetic within one synchronous function requires no timestamp until it becomes state, output, event, decision, evidence, log, metric, cache entry, or cross-boundary value');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (297, E'article', E'C31', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'absolute-gptbridge-code-root-containment', E'absolute-gptbridge-code-root-containment\nCANONICAL-CODE-ROOT:DIR[DIR_PROJECT_ROOT]; SCOPE:all-GPTBridge-owned/authored/copied/generated/transformed/downloaded/vendored/patched/extracted/staged/executable project source+scripts+modules+packages+plugins+extensions+hooks+launchers+workers+migrations+code-templates+embedded-code+build-inputs+runtime-loaded-code+hot-update/hot-reload artifacts+test-code+repair-code+AI/programming-tool output+Git-worktrees/object-database/index/hooks; LOCATION-RULE:every-in-scope path after absolute-normalization+case-folding+drive-resolution+environment-expansion+short-name-resolution+symlink/junction/mount/reparse-target-resolution must-equal-root or be-strict-descendant-of-root; ROOT-BOUNDARY:path-component boundary not-string-prefix; DIRECTORY-AUTHORITY:permission-sovereign registers-all-approved-code-directories under-root only; PROGRAMMING:release-update-sync-sub-sovereign may-plan/dispatch changes only-to-registered-descendants; EXECUTION:runtime-sovereign validates executable/module/script/working-directory/import/search/plugin/temp-generated-code paths before-dispatch; INFORMATION-LAYER:rejects cross-root code transfer/write/extract/load/execute requests+publishes typed-denial; GIT:main-repository+.git+all-worktrees+shared-object-database+hooks must-reside-within-root+external-worktree-path forbidden; GENERATION:temporary/generated/build/package/cache/coverage/test/recovery/repair code stored only-in-approved-root descendants+atomic-promote-within-same-boundary; IMPORT/PATH:PYTHONPATH/NODE_PATH/PATH/plugin/module-resolution cannot introduce GPTBridge project code from outside-root; ARCHIVE:pre-scan+canonicalize-each-entry+reject-absolute/parent-traversal/reparse/hardlink escape before-extract; HOT-UPDATE/REPAIR:source+staging+rollback+active-release all-inside-root and D28/D29 identity rules still-apply; AUDIT:operation+actor+requested-path+resolved-path+root+decision+content-hash+timestamp+correlation-id without-secret; CHECKPOINTS:startup+code-change+tool-call+Git-operation+dependency-install+generation+build+test+package+hot-update+repair+runtime-load; FAILURE:any-unresolved/ambiguous/nonexistent-parent/reparse-loop/case-alias/device-path/network-path/outside-root=>fail-closed+no-create/write/copy/move/load/import/execute+report-to-user; EXISTING-OUTSIDE-CODE:quarantine-reference+do-not-load+move requires-explicit-governed migration that first validates-destination-inside-root and never-deletes-source-until-hash-verified; THIRD-PARTY-BOUNDARY:operating-system executables and externally-installed immutable third-party runtimes are-not-GPTBridge-project-code and may-be-invoked only-by-exact-approved-identity through-C28 governed-executor+cannot receive/store/generate/modify GPTBridge code outside-root; DATA:non-code user data governed-separately+must-never-contain executable-project-code to-evade-boundary\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:any-project-code-outside-DIR[DIR_PROJECT_ROOT]+DIR[DIR_GIT_WORKTREES] or-other-sibling-worktree+user-profile/Desktop/Documents/Downloads/AppData+ProgramData+Windows/System/other-drive/UNC/network/share/cloud-sync/temp as-project-code-root+symlink/junction/reparse/mount/hardlink escape+path-prefix-confusion+relative-traversal+8.3-alias/device-path escape+environment-variable redirection+external-Git-worktree/object-store/hook+outside-root-clone/stage/build/test/package/cache/generated-code+load/import/execute-from-memory-backed-or-unregistered-extracted-code+tool/AI writing-code-outside-root+copy-then-execute bypass+data-file-containing-hidden-executable-code+fallback-to-external-source+automatic-root-expansion+exception-by-module/administrator/debug/recovery\nRead-only invocation of an OS component or specifically approved immutable third-party runtime outside the root does not authorize GPTBridge code to be stored, generated, modified, imported, staged, or executed there; all GPTBridge inputs, wrappers, configuration with executable behavior, outputs containing code, and working state remain inside DIR[DIR_PROJECT_ROOT]');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (298, E'article', E'C32', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'absolute-environment-dependency-root', E'absolute-environment-dependency-root\nDEPENDENCY-ROOT:DIR[DIR_MANAGED_DEPENDENCY_ROOT] is sole managed dependency root; Windows-native registered tools and Ollama registered store are exceptions. ADMISSION:staging directory may be created only after new-dependency permission or for an already registered update candidate. ACTIVE-LAYOUT:environments|runtimes|sdks|toolchains|packages|caches|models|staging; each identity has exactly one ACTIVE and at most one ROLLBACK_ONLY generation. PURGE:after retention expiry and zero references,automatic deletion removes old version directories,package/cache objects,old environments and staging remnants; audit receipts remain in PostgreSQL,not as executable artifacts.; UPDATE-DETECTION:every-24-hours+immediate-governed-security-advisory-event; RETIREMENT-TAG:mandatory from SUPERSEDED through PURGE_READY and binds dependency-id+old-version+successor-version+state+reason+zero-consumer-progress+rollback-deadline+scheduled-purge-at\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:unapproved-staging/download/install+dependency-outside-root+global/user-profile/temp fallback+multiple-active+more-than-one-rollback+old-version-after-PURGED+cache-preserving-purged-code+symlink/reparse-escape+missing-or-stale-retirement-tag+update-detection-interval-not-24-hours\nOnly Windows 11 native tools serviced by Windows and registered Ollama execution/download/model-storage paths on C drive are exempt; neither exception permits GPTBridge project code or unrelated dependencies outside their canonical roots');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (299, E'article', E'C33', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'sql-query-pushdown', E'sql-query-pushdown\nRULE:set-based-data-work executes-at-owning-SQL-engine; PUSH-DOWN:filter+projection+join+aggregation+grouping+window+sorting+distinct+pagination+existence+constraint+upsert+transactional-condition+authorized-row/column restriction; APPLICATION:submits-bounded-parameterized-query-contract+receives-only-required-columns/rows/aggregates; POSTGRESQL:central-structured-authoritative queries; retired embedded SQL storage has zero active query consumers; QUERY-PLAN:EXPLAIN-based evidence for-new/changed/hot paths+index/selectivity/row-estimate/temp-sort/full-scan thresholds; PAGINATION:keyset-preferred+stable-order+bounded-limit; BULK:batch/set operation+no-N+1; SECURITY:parameter binding+server-side scope predicates+transaction/isolation/deadline/cancellation; OBSERVE:query-id+contract-version+duration+rows-scanned/returned+plan-hash+timeout without-sensitive-literals; FALLBACK:application-side operation only-for-non-SQL semantics after-bounded-pushdown and documented evidence; FSHARP:after bounded SQL reduction, owns typed data analysis, machine-learning pipelines and high-correctness complex calculation where typed immutable functional modeling materially improves correctness; FSHARP-NO:database-authority+unbounded-fetch+duplicate-algorithm-authority\nFORBID:fetch-all-then-filter/sort/group/join/page+SELECT-star production-contract+string-concatenated-SQL+N+1+unbounded-result+offset-only-large-pagination+application-enforced-row-security+SQL-business-policy/sovereign-decision+cross-owner-direct-database+query-without-timeout+silent-client-side-fallback+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\nSmall already-bounded result sets may receive final presentation-only formatting outside SQL');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (300, E'article', E'C34', E'CODEX_MODULE_PERMISSION', E'CODEX_MAIN', E'sql-first-data-reduction-semantic-business-boundary', E'sql-first-data-reduction-semantic-business-boundary\nPIPELINE:request>CSharp-application>parameterized-bounded-PostgreSQL set operation>bounded-result>FSharp-domain-validation/business-semantics>typed-result; SQL-OWNER:data-selection+relational-integrity+set-computation; CSHARP-OWNER:application+workflow+SQL-orchestration; FSHARP-OWNER:business-meaning+validation+state-transition; RUST:approved SQL adapter/runtime path permitted by versioned contract; PYTHON:retired;no governance-thin adapter and no business or SQL orchestration role\nFORBID:fetch-all-before-relational-reduction+SQL-business-authority+Python-domain-model-as-production-owner+Python-business-policy/workflow+Python-SQL-orchestration+unbounded-transfer\nnon-relational-semantic-post-processing-after-maximum-safe-SQL-reduction');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (301, E'article', E'C35', E'CODEX_MODULE_DIRECTORY', E'CODEX_DIRECTORY_SPECIAL_LAW', E'complete-governed-directory-domain-set', E'complete-governed-directory-domain-set\nMASTER-DIRECTORY:directory-master-catalog is the exhaustive registry of every governed directory class; REQUIRED-DOMAINS:law-structure+special-law+provision-classification+project-architecture+identity-module+permission-capability+tool-route+data-schema-authority+API-event-contract+service-process-port-environment+model-resource-dependency+configuration-credential-secret+version-release-artifact+audit-evidence-retention+backup-recovery-migration+UI-window-feature-entry+command-code+fault-code+maintenance-manual+test-flow; OWNER:permission-sovereign for directory definition+identity+registration+relationship+version+activation+retirement+access and write decisions; DOMAIN-AUTHORITY:referenced bodies remain with their codex-declared domain owners and directory ownership grants no body authority; MASTER-ENTRY:directory-code+canonical-name+scope+authority-kind+required-fields+relationships+coverage-rule+implementation-state+introduced-version+retired-version; COMPLETENESS:no governed identity may exist outside exactly-one applicable registered directory and every directory appears in master catalog; IMPLEMENTATION-STATE:mandated-pending-implementation cannot be represented as active and blocks dependent verified release; CONVERGENCE:legacy permission registries become projections or implementations of the matching master entry and cannot remain parallel authority; VALIDATION:permission-sovereign verifies master coverage+schema+ownership+links before activation DIRECTORY-STORAGE:every directory managed by permission-core is persisted in the registered local PostgreSQL authority only; PostgreSQL is the sole current structured storage and transaction boundary for directory entries,relationships,lifecycle and write receipts; alternate embedded database,file,cache,mirror or module-private state cannot be directory authority or write fallback.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:unregistered-directory-class+parallel-master-catalog+directory-owned-by-other-sovereign+missing-required-domain+active-status-before-implementation-proof+legacy-registry-as-separate-authority+directory-ownership-changing-domain-body-authority+catch-all-entry-hiding-unclassified-identity+permission-core-directory-outside-PostgreSQL+alternate embedded database-or-file-as-directory-authority+directory-write-fallback-outside-PostgreSQL+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\nThird-party opaque internals require no internal directory entries, but their artifact adapter interface permission data and failure exposure require registered entries');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (302, E'article', E'C36', E'CODEX_MODULE_DATA', E'CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW', E'data-authority-storage-rag-special-law', E'data-authority-storage-rag-special-law\nSCOPE:Git history+SQL official mutable data+Rust-Vector-Engine/RAG semantic candidates+LLM inference boundary+schemas+transactions+retention+reconciliation; OWNER:decision-sovereign owns-domain decisions with data-governance-sub-sovereign managing data modules while permission-sovereign owns directory registration; IDENTITY:CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW+section-14+immutable provision identities; AUTHORITY:codex+A60+D40 with special-over-general precedence only-inside-declared-scope; INPUT:registered directory identities+current version+permission proof+owner evidence; RULE:one accountable owner+typed decisions+governed executor only+no cross-domain authority; RELATIONSHIPS:permission-special-law+data-schema-authority-directory+backup-recovery-migration-directory; LIFECYCLE:register>validate>activate>operate>observe>repair-or-rollback>retire with versioned lineage; VALIDATION:identity+owner+scope+schema+relationships+permission+runtime generation+evidence all current; FAILURE:deny ambiguous or cross-owner mutation and preserve authoritative data; EVIDENCE:authority map+schema version+transaction proof+lineage+integrity hash+backup and restore verification\nINHERITS:A135#SPECIAL_LAW_BOUNDARY\nNo emergency development debug administrator or performance condition may bypass authority permission isolation evidence or rollback boundaries');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (303, E'article', E'C4', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'protection', E'protection\nFILE:os-readonly-protected; INTEGRITY:verify-before-load+exec\nFORBID:backup/restore/hot-update/any-path-overwrite-codex\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (304, E'article', E'C41', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'whole-codex-repair-and-continuity-integration', E'whole-codex-repair-and-continuity-integration\nWHOLE-CODEX-INTEGRATION:all main-codex outlines+subordinate ordinances+special laws+permission-sovereign directories apply as one non-skippable hierarchy; REPAIR-ORDER:authority and identity>scope owner>evidence and preservation>channel continuity>minimal repair method>independent verification>certified activation>stability publication; GENERAL-RULE:C40 no-overwrite/no-reset preservation boundary governs every automatic repair across every domain and more-specific law may narrow but never weaken it; CHANNEL:B46+C39 reconnect first without source mutation and only an independently proven source defect may enter C40 repair chain; STARTUP:B47 ten-second deadline failure is not permission to overwrite or reset code; LIVE-CHANGE:B48 candidate failure never becomes automatic replacement of active code; RELEASE:D28+D29 retain exact active certified baseline and rollback is a new explicit certified activation not repair reset; DATA:authoritative data repair uses owner transaction semantics and cannot be misrepresented as source-code replacement; TOOLS:each independent individual retains own failure boundary and main-system repair cannot mutate its source or terminate it; CONFLICT:preservation+no-overwrite+no-reset+explicit owner+current permission+minimal scope+strongest verification prevail; ACCEPTANCE:one trace proves fault>owner>scope>method>before/after hashes>diff>tests>audit>activation or no-activation>stability without loss of user work\nFORBID:any-law-interpreted-to-authorize-overwrite/reset+special-law-exception-that-weakens-C40+repair-owner-combination+cross-individual-repair+automatic-version-rollback+startup-deadline-used-as-destructive-repair-authority+channel-failure-used-as-code-mutation-proof+successful-runtime-used-to-hide-source-loss\nOnly an explicit human-governor successor provision may change the no-overwrite/no-reset boundary; operational urgency and automated decisions cannot create an exception.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (305, E'article', E'C42', E'CODEX_MODULE_MAINTENANCE', E'CODEX_AUTOMATIC_REPAIR_SPECIAL_LAW', E'automatic-repair-preservation-special-law', E'automatic-repair-preservation-special-law\nAUTOMATIC-REPAIR:exact root-cause evidence>preserve Git/index/worktree/user state+before hashes>exact decision/permission/programming-review proof>smallest deterministic targeted patch>post-hash/diff/tests/audit/stability; METHOD:repair-only; UNCOMMITTED-OVERLAP:stop; DISCONNECT:reconnect without source mutation; FAILURE:no mutation or rollback only attempted patch\nFORBID:overwrite+reset+replacement+restore-default+checkout+clean+revert+delete-recreate+whole-file-rewrite+directory-sync+version-selection+uncommitted-loss+self-authorization+self-verification\nContainment may isolate an affected capability but never expands automatic source mutation authority.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (306, E'article', E'C43', E'CODEX_MODULE_RELEASE', E'CODEX_RELEASE_VERSION_SPECIAL_LAW', E'update-and-reload-special-law', E'update-and-reload-special-law\nUPDATE-RELOAD:candidate isolated from active certified runtime; full precheck; edit/build/test/reject cannot stop restart disconnect or degrade active generation; compatible hot-reload uses transactional snapshot+dependency order+full rollback; incompatible change uses ready blue-green successor before atomic switch; frontend reuses same window host; failure retains active release; rollback is new explicit certified activation; control traffic has reserved capacity\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:uncertified-update+partial-live-reload+candidate-active-import+save-triggered-restart+reload-disconnect+default-over-active+automatic-reset/rollback+activation-before-ready+mixed-generation\nSecurity containment may disable only an affected artifact; activation still requires certification.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (307, E'article', E'C44', E'CODEX_MODULE_DIRECTORY', E'CODEX_DIRECTORY_SPECIAL_LAW', E'directory-coverage-and-special-law-convergence', E'directory-coverage-and-special-law-convergence\nSCOPE:directory relationships+fault-to-manual coverage+special-law successor convergence+identity groups+independent-tool isolation; RULE:all relationship endpoints use immutable DIR_* directory codes and one row per source-target edge; composite physical table-name targets are invalid; every retryable or repairable registered fault maps to at least one maintenance manual and test flow; overlapping active special provisions must declare one successor and remove predecessor from effective set while preserving identity and lineage; identity groups require a dedicated directory; every ordered pair of main-system and independent tools requires a failure-isolation matrix entry covering process window data channel resource repair update and shutdown; PENDING:directory implementation remains explicitly pending until inventory format relationship consumer failure-injection rollback and zero-gap evidence pass; EXTERNAL:signature and 星澄 confidential-storage gates remain open until their independent proofs exist and cannot be self-closed by codex text; RELEASE:open required gate blocks verified activation but does not erase the prior valid codex state\nFORBID:physical-table-name-as-directory-relationship-identity+multi-target-string-in-one-edge+repairable-fault-without-manual+parallel-active-duplicate-special-provisions+identity-group-without-directory+independent-tool-without-pairwise-isolation-matrix+pending-directory-marked-active-without-evidence+external-gate-self-asserted-complete+deleting-superseded-identity\nExternal signature and encrypted 星澄 storage completion require their declared external evidence and therefore remain visible open gates until independently satisfied.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (308, E'article', E'C45', E'CODEX_MODULE_GIT', E'CODEX_GIT_WORKTREE_SPECIAL_LAW', E'git-top-level-directory-classification', E'git-top-level-directory-classification\nPHYSICAL-IDENTITY:Git top-level directory is DIR[DIR_PROJECT_ROOT]; CANONICAL-CLASSIFICATION:git-top-level-directory co-located with PROJECT_GPTBRIDGE project root; AUTHORITY:the repository metadata+index+references+objects+hooks+configuration+tracked working trees and version-control runtime artifacts must resolve inside DIR[DIR_PROJECT_ROOT] after canonical path and reparse-point resolution; SINGLE-ROOT:no alternate active Git top-level or worktree root outside DIR[DIR_PROJECT_ROOT]; WORKTREE:each governed worktree must be a registered descendant path and preserve branch+index+ownership isolation; OPERATIONS:commit+merge+sync+audit+push originate from the registered Git root and follow coordinator authority; MIGRATION:legacy external worktrees become nonlaunchable read-only migration evidence until moved+validated+retired\nFORBID:Git-active-root-outside-DIR[DIR_PROJECT_ROOT]+external-active-worktree+alternate-dot-git-authority+gitdir-pointer-escape+symlink/junction/reparse-escape+unregistered-worktree+cross-worktree-index-mutation+worker-direct-push+force-push/ref-delete/non-fast-forward-without-explicit-governance-approval\nA legacy external worktree may remain read-only during a registered migration window; it cannot receive commits, synchronization, runtime writes, or remain active after the internal successor is validated.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (309, E'article', E'C46', E'CODEX_MODULE_DIRECTORY', E'CODEX_TOP_LEVEL_DIRECTORY_PATH_SPECIAL_LAW', E'top-level-directory-path-special-law', E'top-level-directory-path-special-law\nSCOPE:all project+Git+main-system+startup-core+governance-codex+local-model+independent-tool and registered module roots; OWNER:permission-sovereign exclusively registers path codes and canonical targets; IDENTITY:each top-level root has one immutable uppercase path-code+lower-kebab canonical-name+one canonical absolute path+entity-kind+parent+logical owner+activation state; RESOLUTION:environment variables and configuration reference path-code only and resolver canonicalizes case+separator+relative segments+symlink+junction/reparse target before descendant validation; BOUNDARY:no owned local artifact may resolve outside registered root; EXTERNAL:PostgreSQL+Rust-Vector-Engine+external service storage uses registered opaque authority endpoints and is never encoded as local path exception; MIGRATION:old and target roots recorded with one-way state transition+read-only old root+atomic reference cutover+tests+rollback; COMPLETION:new architecture is complete only after target validation+all references cut over+rollback window closed+legacy data reconciled+old root safely deleted+deletion proof recorded; NO-LEGACY-ROOT:no completed architecture may retain old directory+junction+symlink+redirect+duplicate+backup inside active namespace; AUTHORITY:directory declaration and its implementation obligation are both mandatory\nFORBID:hardcoded-physical-path-outside-directory+unregistered-root+duplicate-active-root+path-code-reuse+relative/absolute traversal+symlink/junction/reparse/environment escape+case-alias collision+implicit external-storage exception+active-before-validation+legacy-write/launch-after-cutover+complete-before-old-root-deletion+retained-old-root/junction/symlink/redirect/duplicate/backup-in-active-namespace\nOperating-system required locations may be used only through a registered external-location code with exact owner, permission, lifecycle, cleanup and non-authoritative status; immutable audit evidence may retain hashes and manifests but not the old working root.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (310, E'article', E'C47', E'CODEX_MODULE_RUNTIME', E'CODEX_SYSTEM_RELIABILITY_SPECIAL_LAW', E'system-stability-fault-reduction-self-repair-speed-and-isolation-special-law', E'system-stability-fault-reduction-self-repair-speed-and-isolation-special-law\nOBJECTIVES:maximize stable availability+reduce preventable faults+minimize detection/containment/recovery time+preserve bounded execution latency+guarantee owner-local blast radius; OWNER:runtime-sovereign owns continuity+decision-sovereign owns health classification and reliability priorities+health-maintenance-test-sub-sovereign manages repair verification+permission-sovereign owns exact authority+automation-sovereign owns budgets and resource allocation with resource-dependency-sync-sub-sovereign managing resource modules+information-layer owns cross-layer signals; SLO:each capability declares availability+latency p50/p95/p99+throughput+error rate+queue age+resource headroom+fault budget+detection deadline+containment deadline+recovery objective+stability window; PREVENTION:typed contracts+bounded resources+dependency timeouts+bulkheads+circuit breakers+backpressure+admission control+idempotency+checkpointing+preflight+fault injection+capacity margin; SPEED:critical-path priority+parallel independent work+event-driven waits+bounded payloads+cache with freshness proof+no duplicate probes+no busy polling+deadline propagation+load shed noncritical work before control degradation; REPAIR:detect>classify exact fault code>isolate>preserve state/evidence>select registered manual>permission check>bounded minimal repair with no overwrite/reset>independent verification>stability window>close or escalate; REPAIR-LIMIT:no self-modification of source+no authority expansion+no repeated ineffective repair+failure budget and circuit breaker; ISOLATION:per-individual process+generation+queue+pool+quota+session+data+logs+repair+update+shutdown and shared dependency tenant/bulkhead; CASCADE-PREVENTION:one owner failure cannot restart+stop+mutate+starve+lower health verdict of another; MEASUREMENT:every release compares baseline/regression and blocks activation on reliability or latency regression beyond declared budget\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:unbounded queue/retry/resource+retry storm+shared failure budget+global restart/kill+cross-owner repair+repair-by-overwrite/reset+repair-without-root-cause/manual/permission/evidence+same-actor-final-verification+performance-by-average-only+latency-without-percentiles+speed-by-skipping-governance/safety/durability+stability-from-process-existence+fault masking+premature-success+repeated-repair-after-budget+dependency-cascade\nEmergency containment may immediately stop only the exact hazardous owner operation; it must preserve evidence and cannot bypass later authority, repair, verification, isolation or stability-window requirements.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (311, E'article', E'C48', E'CODEX_MODULE_INFORMATION', E'CODEX_INFORMATION_COMMUNICATION_SPECIAL_LAW', E'noninterrupting-channel-anomaly-isolation', E'noninterrupting-channel-anomaly-isolation\nINVARIANT:an anomaly must never globally interrupt an information channel or unrelated route; ACTION:isolate only the exact anomalous message+event+stream+session+tenant+capability or owner generation while preserving control+heartbeat+ack+healthy traffic; REDUNDANCY:critical routes maintain independent control lane+bounded alternate transport/session and authoritative cursor checkpoint so service continues in degraded authenticated mode; DETECTION:malformed payload+sequence gap+stale generation+auth anomaly+backpressure+timeout+jailbreak indicator+dependency fault becomes typed quarantined item and not channel-wide shutdown; STATE:healthy partitions remain connected+affected partition marked isolated/degraded+state-changing action for affected scope fails closed+read-only last-confirmed state marked stale where required; RECOVERY:diagnose isolated cause+fresh authentication/generation+snapshot/cursor/hash reconciliation+independent verification+stability window then rejoin without duplicate side effect; CASCADE:no anomaly may consume unrelated retry/failure budgets or restart/stop another individual; OBSERVABILITY:continuous status includes isolation scope+reason+since+healthy-route count+recovery owner and never secret payload\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:global-channel-close-for-local-anomaly+unrelated-route-interruption+control/heartbeat-starvation+drop-anomaly-without-evidence+apply-quarantined-message+continue-affected-state-changing-command+shared-retry-budget+channel-wide-restart+silent-degraded-state+rejoin-before-convergence+duplicate-side-effect\nIf every redundant route is physically unavailable, the channel remains in an explicit isolated degraded state with control recovery attempts and preserved evidence; it may not falsely report connected or discard state.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (312, E'article', E'C5', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'maintenance-health', E'maintenance-health\nOWNER:health-maintenance-test-sub-sovereign; SCOPE:system-health-monitor; INCLUDE:data-integrity-check+presentation\nFORBID:ignore/hide-data-integrity-abnormal-in-health-monitor\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (313, E'article', E'C50', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'automation-core-final-responsibility', E'automation-core-final-responsibility\nOWNER:automation-core. RESPONSIBILITY:orchestrate authorized workflow scheduling,synchronization target,dependency order,atomic boundary,conflict isolation,retry,cancellation,update,backup,restore,repair,retention and convergence evidence. AUTHORITY:automation-core never creates policy or permission;it accepts current decision and permission artifacts. EXECUTION:registered modules perform bounded work and return typed receipts;runtime-core owns process execution mechanics. DOMAIN-SPLIT:resource,dependency,channel,release,state,repair,backup,cleanup,retention,learning-evidence and audit-delivery are module responsibilities under one automation-core contract,not sub-sovereigns. SUCCESS:all required identities,versions,states and receipts converge and independent verification passes.\nFORBID:automation-sovereign-or-sub-sovereign+automation-self-authorization+module-authority+overlapping-module-owner+implicit-target+unverified-overwrite-reset-delete-update-repair-or-restore+success-before-convergence\nEmergency containment may isolate the exact affected scope but cannot transfer policy,permission or execution authority.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (314, E'article', E'C52', E'CODEX_MODULE_RELEASE', E'CODEX_RELEASE_VERSION_SPECIAL_LAW', E'automation-sovereign-global-update-execution-and-convergence', E'automation-sovereign-global-update-execution-and-convergence\nGLOBAL-UPDATE:sole automation coordinator updates registered dependencies after timing/gates and never admits a new dependency without explicit permission artifact. TRANSACTION:affected inventory>stage>compatibility/security/config/backup/test>canary>waves>A/B atomic handover>stability>retire prior. RETIREMENT:prior generation becomes ROLLBACK_ONLY for registered bounded window; successful window+zero consumers/locks/manifests/processes+completed migration produces PURGE_READY and automatic complete deletion; failed successor rolls back before purge. TERMINAL:ACTIVE current+optional one ROLLBACK_ONLY or PURGED prior; no indefinite standby/archive.; UPDATE-DETECTION:every-24-hours+immediate-governed-security-advisory-event; RETIREMENT-TAG:mandatory from SUPERSEDED through PURGE_READY and binds dependency-id+old-version+successor-version+state+reason+zero-consumer-progress+rollback-deadline+scheduled-purge-at\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:unapproved-new-dependency+second-coordinator+normal-update-before-14-days+false-emergency+overwrite-active+purge-before-stability/rollback-expiry/zero-reference+retain-multiple-old-versions+hidden-partial-failure+missing-or-stale-retirement-tag+update-detection-interval-not-24-hours\nCritical security updates may shorten canary and observation timing but cannot bypass certification, 星澄 review, permission authorization, signed provenance, isolation, journal, evidence, compatibility or rollback readiness; an actively exploited target may be isolated while unaffected channels remain available.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (315, E'article', E'C53', E'CODEX_MODULE_LANGUAGE', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'cpp-six-domain-namespace-and-include-dependency-special-law', E'cpp-six-domain-namespace-and-include-dependency-special-law\nGOVERNANCE-UNIT:C++ six-domain governance applies to namespace+symbol ownership+include/link dependency edges,not source-file or folder count; CANONICAL-NAMESPACES:gptbridge::native::parser|gptbridge::native::vector|gptbridge::native::memory|gptbridge::native::token|gptbridge::native::transform|gptbridge::native::binding; PHYSICAL-ALLOW:parser.cpp+vector.cpp+transformer.cpp are a valid three-file core and no empty/artificial memory.cpp,token.cpp,binding.cpp or six-folder layout is required; COLOCATION:a translation unit may implement multiple canonical namespaces only when every symbol belongs to exactly one namespace and all edges obey the DAG; DAG:memory=>none; token=>memory; parser=>token+memory; vector=>memory; transform=>memory and vector only when explicitly declared; binding=>parser+vector+memory+token+transform; NO-REVERSE:callee cannot include/call dependent/upstream namespace; C-ABI:gptbridge_native.h+gptbridge_native.c remain the language-neutral contract/thunk outside C++ namespace ownership and D60 controls the sole consumer path; BINDING-NAMESPACE:gptbridge::native::binding is private C++/pybind11 adaptation ownership only and cannot become a second public contract; CHECKER:parse namespaces+fully qualified symbols+headers/includes+calls+link graph,resolve each symbol to one domain,compare actual graph to declared DAG,detect cycles+reverse edges+unmapped/global symbols+duplicate owners and report physical files separately from logical namespaces; HEADER:private header declares one primary namespace or an explicit bounded multi-namespace boundary and cannot expose private implementation across forbidden edges; TEST:one logical-domain test group per namespace+dependency graph test+cycle injection+co-location fixture+current-three-file fixture+D59 release gate; SUPERSESSION:D37 requirements for own folder,one domain per source module or six physical units are non-operative and replaced by C53.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:checker equating namespace count with file count+mandatory six cpp files/folders+namespace-less native symbol except exact C ABI exports+wrong/reverse dependency+cycle+memory dependency+token calling parser/vector/transform/binding+parser calling vector/transform/binding+vector calling parser/token/transform/binding+transform calling parser/token/binding or undeclared vector+binding owning algorithm/policy+include cpp+duplicate/unmapped symbol+physical layout used as proof without namespace graph.\nCompiler-generated anonymous/internal symbols may remain translation-unit local when checker traces them to one enclosing canonical namespace owner and proves no cross-domain edge or exported identity.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (316, E'article', E'C54', E'CODEX_MODULE_LANGUAGE', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'canonical-javascript-csharp-sql-native-fsharp-topology-special-law', E'canonical-javascript-csharp-sql-native-fsharp-topology-special-law\nTOPOLOGY:B166-managed UI client>selected approved shell and typed bridge>application/workflow API;branches resolve through current B166 single-owner allocation and PostgreSQL authority;TEST-AUDIT:CSharp sole orchestration+owner-language native runners+C++23 Audit Engine;FAILURE:typed fail-closed without alternate owner\nFORBID:pytest-or-Python-test/audit/verification+Python-application-path+contractless-cross-owner-call+alternate-owner-on-failure\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (317, E'article', E'C55', E'CODEX_MODULE_LANGUAGE', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'javascript-esm-governance-checker-structure-and-dependency-dag-evidence-special-law', E'javascript-esm-governance-checker-structure-and-dependency-dag-evidence-special-law\nROOT:governance checker JavaScript-ESM subtree uses code/; STRUCTURE:code/checkers/LanguageBoundaryChecker.js+code/checkers/DependencyDagChecker.js;code/policy/LanguagePolicy.js+code/policy/DependencyPolicy.js;code/registry/GovernanceCheckerRegistry.js; DIRECTORY-EXCEPTION:B75 JavaScript-ESM directory allowlist is extended only for this registered governance checker subtree with policy and registry roles below; CHECKERS:LanguageBoundaryChecker performs D62 language/origin/owner/directory/ABI/API/size gate and DependencyDagChecker performs D64 resolved edge graph+DAG+cycle verification; POLICY:LanguagePolicy and DependencyPolicy contain immutable declarative data only,no scanning/resolution/filesystem/network/process/evidence/verdict/repair side effects; REGISTRY:GovernanceCheckerRegistry registers exact checker id+policy id+trigger+input/output schema+rule set+version and performs no scan,decision or repair; DEPENDENCY-POLICY-DAG:{javascript-esm=>information_layer}+{c=>cpp}+{binding=>parser|vector|token|transform|memory}+{parser=>token|memory}+{vector=>memory}+{token=>memory}+{transform=>memory}+{memory=>none}; CANONICAL-QUALIFICATION:javascript-esm>information_layer expands to B32 canonical contract;Python is retired and no python>native or python-qualified expansion exists; graph uses canonical node/edge ids and denies every undeclared edge; CYCLE:any directed cycle is FAIL even when each edge appears locally allowed; DIAGNOSTIC:never only FAIL dependency violation; output FAIL plus source:<canonical path>,target:<canonical path>,edge:<source-role>-><target-role>,rule:<exact ids>,reason:<typed human-readable boundary>,expected:<canonical path>; example JavaScript-ESM direct Python uses edge=javascript-esm->python-direct,rule=B32/B50,expected=no-python-target-exists; READONLY-V1:scan+resolve+classify+compare+evidence+PASS/WARN/FAIL only; decision remains existing governance chain.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:checker automatic import/include/build/path rewrite+file move+automatic CMake/csproj/tsconfig mutation+checker-created exception/allowlist+policy executable scan logic+registry authority+generic dependency failure without exact source,target,edge,rule,reason,expected+cycle accepted because component edges are locally allowed+undeclared DAG edge+text-only dependency proof.\nNone for mutation or exception creation. Owner-neutral remediation context may name the expected edge but cannot contain or execute a patch.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (318, E'article', E'C56', E'CODEX_MODULE_DATA', E'CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW', E'vector-lineage-outbox-generation-and-recovery', E'vector-lineage-outbox-generation-and-recovery\nWRITE-BOUNDARY:one PostgreSQL transaction writes resource+chunk+embedding+revision+scope+tombstone+durable-index-outbox-event;APPLICATION-DUAL-WRITE:forbidden;INDEX-WORKER:bounded Rust owner consumes idempotently+in-batches+generation-aware+crash-recoverable and records index-state acknowledgement;QUEUE-BOUNDARY:PostgreSQL stores durable mutation events but is not used for high-frequency ephemeral runtime events;GENERATION:index_generation+schema_version+embedding_model+embedding_version+dimensions+distance_metric+source_revision_watermark+build_hash+created_at+verified_at;READ:query cannot mix incompatible generations;RECOVERY:last verified generation remains active until replacement passes\nFORBID:independent-synchronous-dual-write+unbounded-outbox-consumer+ack-before-index-update+generation-without-watermark+mixed-dimension/model/metric+failed-rebuild-overwriting-last-verified-generation\nConcrete algorithms, thresholds, index layouts and batch values remain implementation-layer rules and require no Codex amendment while boundaries stay unchanged.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (319, E'article', E'C57', E'CODEX_MODULE_MAINTENANCE', E'CODEX_AUTOMATIC_REPAIR_SPECIAL_LAW', E'xingcheng-auxiliary-repair-update-user-switch-confirmation-and-fault-cardinality', E'xingcheng-auxiliary-repair-update-user-switch-confirmation-and-fault-cardinality\nCONTROL-SURFACE:星澄 auxiliary system owns the user-facing control surface for automatic repair and automatic update. It exposes two independent explicit switches:automatic_repair_enabled and automatic_update_enabled; default and persisted state must be visible,attributable to the user and never inferred from model intent. DETECTION:health observation,fault classification,evidence collection,isolation and non-mutating diagnosis may continue regardless of execution switch so faults remain observable. EXECUTION-GATE:a repair/update mutation may execute only when its corresponding switch is enabled AND the user confirms the concrete pending action. DOMAIN-SCOPE:the repair side of this surface governs user-facing repair intents presented on the auxiliary surface only; faults of the governed runtime classified by the maintenance sovereign and routed to 星澄 for autonomous governed repair under C105 are outside the switch and confirmation scope of this article, are never presented as user-confirmation items, and are not gated by repair_release or automatic_repair_enabled. Confirmation binds action_id,fault_id or update_id,scope,target,proposed method,risk,rollback/fallback,evidence digest and expiry; it is one-time,non-transferable and invalid after material plan/evidence change. A switch alone is not confirmation;confirmation alone cannot bypass a disabled switch. Existing lawful one-time manual commands remain valid only for their explicit scope. CARDINALITY:the detector assigns one incident snapshot as SINGLE_FAULT when exactly one independently actionable fault exists,or MULTI_FAULT when two or more exist; correlated symptoms may share a root_cause_group but each distinct fault keeps its own fault_id,evidence,severity,impact,isolation state,proposed action and confirmation state. PRESENTATION:SINGLE_FAULT displays one complete fault item. MULTI_FAULT displays every fault individually in deterministic severity/time/fault_id order,shows total and unresolved counts,and provides per-fault confirmation;bulk confirmation is forbidden unless every included action is expanded,individually selectable and explicitly confirmed in the same user act. SEQUENCING:multi-fault execution is one action at a time;after each action re-detect and refresh remaining evidence because one repair may invalidate another diagnosis. Failure of one item is isolated and cannot hide,cancel or auto-authorize others. UPDATE:automatic update follows the same switch+confirmation rule and must show version/source/hash/affected scope,compatibility evidence and rollback;backend synchronization privilege does not waive user confirmation. AUDIT:record switch changes,prompt,decision,actor,time,action result and refreshed fault set without secrets. UI close/cancel/expiry means no mutation.\nFORBID:hidden or combined switch+switch enabling itself+model/repair engine impersonating user confirmation+execute-on-detection+confirmation reused across actions+silent bulk repair/update+multi-fault collapsed into one generic message+showing only first fault+repair failure suppressing other faults+changed plan using stale confirmation+disabled switch bypass+confirmation dialog defaulting to approval+code overwrite/reset as repair.\nImmediate reversible isolation may occur without confirmation solely to stop active damage while preserving unaffected operation; it cannot modify source code,apply an update,erase evidence or become a repair, and must be displayed as an isolated fault action for subsequent user decision.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (320, E'article', E'C58', E'CODEX_MODULE_DATA', E'CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW', E'postgresql-pgvector-rust-activation-order', E'postgresql-pgvector-rust-activation-order\nORDER:1 PostgreSQL extension/schema/migration parity;2 canonical resource+chunk+vector+scope+lineage identities;3 Rust-native-vector-engine contract and deterministic rebuild;4 hybrid retrieval parity and PostgreSQL post-verification;5 legacy vector-service zero-consumer proof;6 legacy data/config/package/runtime removal;7 recovery rebuild evidence;DEPENDENCY:each stage consumes current evidence from predecessors;FAILURE:blocks affected and downstream activation while verified upstream capability remains;REENTRY:resume earliest invalid stage\nFORBID:stage-skip+parallel-activation-bypass+Rust-before-canonical-pgvector+legacy-service-after-cutover+deletion-before-canonical-migration+completion-without-rebuild-and-zero-consumer-proof\nHistorical retired-service identity may remain only in lineage and removal evidence.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (321, E'article', E'C59', E'CODEX_MODULE_DATA', E'CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW', E'database-runtime-pool-query-schema-health-and-cross-engine-integrity', E'database-runtime-pool-query-schema-health-and-cross-engine-integrity\nPOOL-ISOLATION:central-index,transport,audit and each module-private database use separately budgeted connection pools with owner,max/open/idle/wait/lease metrics and reserved critical capacity;one workload cannot exhaust another pool. READ-WRITE-PATH:code exposes distinct read and write paths even on one host;transaction consistency and read-after-write requirements are explicit and routing may later change without contract drift. SQL-SAFETY:all runtime values use prepared statements or parameterized queries;SQL string concatenation/interpolation for transport,locator,resource lookup and every runtime query is prohibited. TIMEOUTS:every runtime statement has a bounded statement_timeout;transactions have lock_timeout,idle timeout and bounded deadlock/serialization retry with jitter,idempotency and total deadline;retry never duplicates committed side effects. PERFORMANCE-EVIDENCE:slow-query log stores redacted query digest,role/module,mean,p95,p99,rows examined/returned,calls and plan identity without secrets or raw personal values. Periodic analysis identifies unused/duplicate indexes and abnormal sequential scans;index removal/addition requires workload,query-plan,write/storage and rollback evidence. RETENTION:audit,transport history,model inference history and repair history each declare retention,archive/legal-hold,purge owner and proof;central append-only audit uses governed archival/purge rather than runtime mutation. VACUUM-ANALYZE:registered native health/maintenance execution observes bloat,dead tuples,statistics freshness and transaction age,then schedules bounded VACUUM/ANALYZE through governed execution;Python is retired and manual recurring dependence is forbidden. SCHEMA-CONTRACT:startup verifies expected schema version,tables,columns/types/nullability,constraints,indexes,RLS/policies,extensions and migration head before write readiness. DRIFT:actual catalog is deterministically compared to approved migration-derived schema digest;out-of-band change becomes SCHEMA_DRIFT,blocks unsafe writes and cannot be silently adopted. MIGRATION-DRY-RUN:before formal migration validate dependency graph,lock/table-rewrite risk,name/type/default conflicts,data conversion,space/time budget,upgrade order,rollback or downgrade feasibility and mixed-version compatibility;destructive or irreversible steps require explicit evidence and user/governance authorization. MODULE-DB-HEALTH:each module database state is exactly healthy|degraded|reconcile_required|read_only|failed with reason,evidence,time and allowed operations;health state does not change authority. LOCATOR:verify locator target identity,existence,boundary and content/version hash;missing or mismatched target is orphaned and is never returned as valid. TOMBSTONE:resource deletion first writes deleted/tombstoned status,revision,time,actor,reason and correlation_id;downstream cleanup and audit complete before policy-governed purge;hard delete cannot erase required lineage. VECTOR-FRESHNESS:compare derived-index resource_id/chunk_id/resource_version/content_hash/embedding version to PostgreSQL;older or mismatched vector is stale,excluded from authoritative retrieval and queued for idempotent rebuild. CENTRAL-SHAPE:central index stores necessary normalized frequently queried fields;JSONB is for bounded typed extension data with schema,size/index/retention rules and cannot become an unbounded catch-all. CROSS-ENGINE-EVENT:every PostgreSQL>Rust-derived-index transition uses one correlation_id with resource_id,from/to revision,hash,status,idempotency key and audit linkage across the entire chain. All controls obey the C58 stage order.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:shared universal pool+unbounded connection acquisition+mixed hidden read/write route+SQL concatenation/interpolation+unbounded statement/lock wait+unbounded deadlock retry+raw sensitive slow-query text+automatic index churn+unbounded history+manual-only vacuum/analyze+write-ready before schema check+accepting schema drift as baseline+production migration without dry-run+unknown module DB health+returning orphan locator+immediate unaudited hard delete+serving stale vector as current+unmanaged alternate embedded database WAL+all-DB blocking startup scan by default+JSONB dumping ground+cross-engine update without correlation_id.+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\nA parameterized administrative migration statement may contain approved static identifiers that cannot be bound,provided identifiers come from a closed registry and are quoted/validated;emergency read-only access may proceed under schema drift only when compatibility is proven and audited.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (322, E'article', E'C6', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'data', E'data\nOWNER:data-governance-sub-sovereign; SCOPE:all-data-body-matters; ITEMS:structured/semantic-index/version-history; FUNC:access-spec-consistency-integrity-check+data-directory; BASIS:codex\nFORBID:data-governance-sub-sovereign-overstep-exec/resource/permission\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (323, E'article', E'C60', E'CODEX_MODULE_DATA', E'CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW', E'observable-verifiable-recoverable-postgresql-pgvector-rust-platform', E'observable-verifiable-recoverable-postgresql-pgvector-rust-platform\nPLATFORM:PostgreSQL+pgvector canonical authority and Rust-native-vector-engine rebuildable acceleration operate as one local vector platform;HEALTH:POSTGRESQL|PGVECTOR|RUST_VECTOR_ENGINE|MIGRATION|REBUILD|RETRIEVAL each emits healthy|degraded|stale|rebuild_required|failed with scope+revision+evidence+allowed-operations;CONSISTENCY:every derived entry matches PostgreSQL resource+chunk+revision+content+embedding+scope;MISMATCH:mark stale/rebuild_required and block derived use;RECOVERY:detect>isolate>discard-derived>rebuild-from-PostgreSQL>verify>activate>audit;LEGACY:retired vector service is excluded from health and runtime and tracked only by removal evidence\nFORBID:health-masking+derived-mismatch-overwrite+Rust-promotion-to-authority+legacy-service-health-or-fallback+recovery-without-canonical-proof\nHistorical retired-service identity may remain only in lineage and removal evidence.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (324, E'article', E'C61', E'CODEX_MODULE_DATA', E'CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW', E'three-engine-self-observation-diagnosis-and-controlled-optimization', E'three-engine-self-observation-diagnosis-and-controlled-optimization\nAUTOMATIC-DATA-MAINTENANCE:PostgreSQL+Rust-Vector-Engine self-observe,self-diagnose and self-maintain through one registered event-driven maintenance flow; EVENTS:schema/migration+query-plan+capacity+WAL+transport-backlog+source-revision+index-generation+permission+restore; ACTIONS:bounded analyze/vacuum/reindex/rebuild/reconcile/retention/connection-generation-fence and safe additive index maintenance; SAFETY:canonical migration/schema/permission contracts control every action; reversible deterministic actions execute automatically; destructive,authority-changing or unknown-effect actions fail closed and quarantine; CAPACITY:30/90/180-day forecast+warning/critical/fail-closed; EVIDENCE:before/after plan+counts+hashes+generation+latency+resource+result; SCHEDULER:existing sole automation scheduler only\nFORBID:second-maintenance-scheduler+manual-confirmation-as-normal-path+automatic-destructive-DDL+authority-changing-optimization+unbounded-query/retry+reopen-before-certification+retired-engine-consumer+success-without-evidence\nAn approved emergency may cancel a query,throttle/reject new low-priority work or isolate a failing pool without mutation confirmation to preserve stability;it must remain reversible,visible and audited and cannot create/drop an index,purge data or reopen a failed store.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (325, E'article', E'C62', E'CODEX_MODULE_DATA', E'CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW', E'bounded-vector-query-planning-and-authority-verification', E'bounded-vector-query-planning-and-authority-verification\nPLANNER:one Rust RAG query planner selects only necessary governed paths from semantic-ANN-vectord-rs|exact-or-small-scope-pgvector|pgvector-degradation|PostgreSQL-FTS+vectord-rs-hybrid|relational-filter-first;SELECTION:scope+capability+health+estimated-candidate-size+deadline+resource-envelope;PARALLELISM:independent lexical+semantic+metadata preparation may execute concurrently through existing bounded scheduler then one bounded join;AUTHORITY-VERIFY:all candidate IDs use one bounded PostgreSQL batch validation before context;CHECKS:resource-exists+chunk-exists+revision-current+status-active+tombstone-false+scope-allowed+embedding-compatible;FAILURE:drop invalid candidate and fail-closed/degrade exact capability according to policy;NPLUSONE:forbidden\nFORBID:query-all-backends-unconditionally+unbounded-spawn/thread/task+per-candidate-SQL+candidate-context-before-authority-check+scope-post-check-only+retired-vector-service-route+Python-query-planner\nConcrete algorithms, thresholds, index layouts and batch values remain implementation-layer rules and require no Codex amendment while boundaries stay unchanged.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (326, E'article', E'C64', E'CODEX_MODULE_DATA', E'CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW', E'vector-backpressure-cache-cancellation-and-projection', E'vector-backpressure-cache-cancellation-and-projection\nBACKPRESSURE:bounded priority queue interactive>maintenance>rebuild using existing scheduler/resource envelope;ADAPTATION:batch+queue+cache+chunk are tuned only within registered ceilings from queue-depth+CPU+RAM+DB-latency+index-latency+interactive-load;CACHE:key includes resource_id+revision+scope_id+embedding_model+embedding_version+query/config-generation and remains non-canonical;CANCELLATION:request>RAG>planner>vectord-rs>PostgreSQL>reranker>context-builder with necessary audit receipt retained;LOW-COPY:large cross-layer payload uses resource/chunk/revision+offset/reference and governed streaming where owner-local benchmark supports it;POOL:existing workload-class PostgreSQL pools only\nFORBID:unbounded-channel+Tokio-task-or-thread-per-request+rebuild-starving-interactive+cache-key-with-resource-or-query-only+work-continuing-after-cancel+second-connection-pool+per-embedding-transaction+large-buffer-clone-without-evidence\nConcrete algorithms, thresholds, index layouts and batch values remain implementation-layer rules and require no Codex amendment while boundaries stay unchanged.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (327, E'article', E'C65', E'CODEX_MODULE_DATA', E'CODEX_DATA_AUTHORITY_STORAGE_RAG_SPECIAL_LAW', E'rag-index-state-reconciliation-collection-topology-and-reranker-fallback', E'rag-index-state-reconciliation-collection-topology-and-reranker-fallback\nINDEX-STATE:every indexed resource/chunk has an authoritative index_state recording at minimum embedding_model,embedding_dimension,chunk_size,chunk_overlap,chunking_version,parser_version,rag_schema_version,content_sha256,indexed_at plus resource_id,chunk_id,source_revision,pipeline_version,backend_generation and status. Reindex planning compares each field and marks only the exact affected resources/chunks stale. A change such as chunk_size 1200/overlap 200 to 1600/250 invalidates entries built under the old pair and their dependent chunk/point mappings;it does not authorize deleting/rebuilding unrelated compatible data or the entire collection. STATE-MACHINE:runtime RAG state is exactly CANONICAL,DEGRADED or RECONCILING. CANONICAL requires healthy Rust-Vector-Engine and PostgreSQL,matching index_state and complete queue. Verified Rust-Vector-Engine/PostgreSQL fault moves affected scope to DEGRADED;canonical writes fail closed and only a registered bounded non-authoritative in-memory cache may serve an already verified read snapshot;each deferred mutation remains in PostgreSQL transport with reconciliation_required=true. Canonical recovery moves to RECONCILING,which must verify source SHA256,resolve owning-module original content,re-chunk under current index_state,re-embed with canonical model/dimension,idempotently write Rust-Vector-Engine,update PostgreSQL,verify resource/chunk/point counts+IDs+hashes+versions and drain/close queue. Only then may reconciliation_required=false and state return CANONICAL. Service availability alone cannot transition to CANONICAL;derived Rust vectors are never canonical and are rebuilt only from PostgreSQL-authoritative content and pgvector metadata. COLLECTION-TOPOLOGY:one Rust-Vector-Engine instance and one canonical collection gptbridge_shared_knowledge serve all authorized local models and four RAG behaviors. Physical per-rag-type or per-model canonical collections are forbidden. Logical isolation uses governed point metadata rag_type with one value or rag_types array containing only hybrid-rag,code-rag,agentic-rag,memory-rag;server-side metadata filters and post-result authorization apply. A chunk may carry multiple rag_types only when each membership has evidence and compatible lifecycle/version. RERANKER-OBSERVABILITY:every retrieval response/evidence reports reranker.requested,reranker.active,reranker.fallback,reranker.reason,model/version and timing. If qwen3-reranker-0.6b is unavailable/not cached,the lawful fallback is RRF with active=false,fallback=rrf and a typed reason such as model_not_cached;successful response cannot imply reranker participation. ORDER:this provision supersedes the shorter C63 work order with the binding sequence:1 Canonical Rust-Vector-Engine;2 PostgreSQL canonical metadata;3 recoverable cross-store write consistency;4 reconciliation;5 index versioning;6 dual-layer authorization filtering;7 stage observability including reranker;8 Code RAG;9 Agentic RAG;10 Memory RAG;11 retrieval benchmark. Stage N activation requires fresh PASS evidence from 1..N-1;isolated experimental work cannot certify a later stage.;MUTABLE-VALUES:resolve-current-values-from-owner-versioned-contract-or-registry;CODEX:retains-owner+boundary+prohibition+acceptance-dimensions-only\nFORBID:index_state missing any minimum field+whole-collection rebuild when exact affected scope is provable+CANONICAL on endpoint availability alone+direct degraded-vector transfer+clearing reconciliation before count/ID/hash/version proof+four physical canonical RAG collections+unregistered rag_type+multi-rag membership without evidence+silent reranker fallback+response claiming reranker active when RRF fallback ran+skipping the eleven-stage order.+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation;FORBID:deployment-version+benchmark-result+model-threshold+port+path+operational-tunable-as-permanent-Codex-literal\nA full rebuild is lawful only when a collection-wide incompatible schema/model change,total loss or corruption makes narrower rebuild impossible and evidence proves scope. Experimental collections may exist in isolated non-canonical test scope with expiry and cannot be queried by production.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (328, E'article', E'C66', E'CODEX_MODULE_GIT', E'CODEX_GIT_WORKTREE_SPECIAL_LAW', E'governed-multi-ai-git-coordination-and-delivery-infrastructure', E'governed-multi-ai-git-coordination-and-delivery-infrastructure\nGIT-ROLE:single fully automated local coordination and delivery infrastructure; MAIN:sole stable integration branch; WORKTREES:DIR[DIR_GIT_WORKTREES]+registered ephemeral worktrees; SINGLE-ENTRY:GitRepository.run; SCHEDULER:existing GitAutomationService only; COORDINATOR:workspace_sync only; EVENT-DRIVEN:file/HEAD/worker/commit/queue events with bounded periodic reconciliation; TRACKING:allowlist authored-source+Codex/contracts+SQL-migrations+required-config+non-rebuildable-test/audit-evidence+human-docs; IGNORE:runtime-state+logs+cache+temp+build/dist+packages+venv+models+database-instance+coverage+generated-index+rebuildable-output+secret; SELF-COMMIT:stable+path-scoped+no-foreign-stage+write-lock-clear; QUEUE:immutable-commit+base+worker+task+priority+policy; CONFLICT:registered generated artifact regenerates;single canonical owner resolves deterministic content;otherwise quarantine and preserve; DELIVERY:integrate>audit>fast-forward>central equality>origin push; MAINTENANCE:locks+leases+worktree registry+fsck+refs+hooks+divergence+audit continuity; CLEANUP:ignored expendable artifacts by registered retention only,never unmerged work\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:second-watcher/scheduler/coordinator+raw-Git-write+worker-push+whole-index-commit+tracking-excluded-output+secret-tracking+moving-branch-merge+unbounded-poll/retry+ambiguous-semantic-conflict-choice+force-push+ref-delete+history-rewrite+destructive-reset+delete-unmerged-work+push-before-audit-and-central-equality\nA non-repository diagnostic may execute git --version through an approved bootstrap adapter and remains audited. A registered generated artifact may use an automation-sovereign-approved merge driver only inside the sole coordinator and only with post-resolution regeneration,validation and audit;any failed condition falls back to stop,preserve and notify.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (329, E'article', E'C67', E'CODEX_MODULE_XINGCHENG', E'CODEX_STAR_PRIVILEGED_INSTITUTION_SPECIAL_LAW', E'xingcheng-auxiliary-manual-repair-update-release-switches', E'xingcheng-auxiliary-manual-repair-update-release-switches\n星澄 auxiliary system provides two independent user-operated manual release switches:repair_release and update_release. DOMAIN-SCOPE:repair_release applies only to user-facing repair intents; it never governs, gates or represents the C105 autonomous internal-fault repair chain, whose execution requires no user release. The user alone decides whether each category is enabled or disabled and may revoke it at any time. Default is disabled unless an explicit persisted user preference proves otherwise. Automatic detection,diagnosis,evidence collection and reversible isolation may continue while disabled,but no repair or update mutation is released. Enabled state only permits presentation of a concrete action for decision;each action still requires the C57 one-time user confirmation bound to current target,scope,method,risk,evidence and expiry. The system/model/repair engine/update engine cannot toggle,simulate,preselect or infer user release. Switch state,change actor,time,device/session,confirmation,execution and result are visible and audited. Multiple faults remain individually displayed and individually released;one switch or approval is never blanket consent. Closing UI,cancelling,expiry,identity mismatch or material plan change denies release.\nFORBID:default-on without user proof+automatic switch mutation+enabled switch treated as blanket confirmation+confirmation bypassing disabled switch+hidden/preselected approval+one approval reused+bulk undisclosed repair/update+model impersonating user+repair by overwrite/reset+update privilege bypassing user release.\nImmediate reversible non-mutating isolation may occur to prevent active damage;it does not toggle either switch,does not authorize repair/update and must be shown and audited.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (330, E'article', E'C68', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'codex-canonical-reference-code-only-policy', E'codex-canonical-reference-code-only-policy\nCODEX-REFERENCE:current and future Codex provisions reference mutable/deployable entities by canonical code,not repeated physical or environment-specific values. DIRECTORY-FIRST:when an entity or physical value already exists in any permission-sovereign managed directory,the Codex and every subordinate/special law must reference that directory_code plus typed field selector;it cannot restate the resolved physical value. Resolution is dynamic against the current accepted directory generation. The minimum core code vocabulary is ROOT_GPTBRIDGE,DIR_MAIN_SYSTEM,DIR_STANDALONE_TOOLS,DIR_MODEL_DIALOGUE,DIR_XINGCHENG,DIR_SHARED_LAYER,STORE_POSTGRESQL_CENTRAL,STORE_VECTOR_SEMANTIC,COLLECTION_SHARED_KNOWLEDGE,MODEL_EMBEDDING_CANONICAL,MODEL_RERANKER_CANONICAL,GIT_MAIN_BRANCH,GIT_REMOTE_CENTRAL,GIT_REMOTE_ORIGIN,POOL_WORKTREE_PERSISTENT,POOL_WORKTREE_EPHEMERAL,CHANNEL_INFORMATION_CANONICAL and CONTRACT_SHARED_LAYER. Codes identify semantics;their physical values exist exactly once in the permission-sovereign canonical reference registry and are resolved under A106. A provision defining a code may state its normative semantic meaning,but operational paths,ports,versions,dimensions,chunk sizes,models,collection names,branch names and capacity values belong to typed registry fields. HISTORICAL-MIGRATION:historical immutable literals remain evidence. Each still-effective legacy provision with mutable literals receives a code-mapping record immediately and an immutable code-based successor before its next affected release or configuration change;no in-place rewrite. Until successor completion,the mapping controls resolution and the literal cannot be copied into new law or implementation. CODE-CITATION:law text uses CODE[identifier] and optional field selector;reports may render resolved values with registry revision/hash and label them derived. SECRET codes resolve only inside authorized secret providers and never reveal values in Codex. OWNER:permission-sovereign governs identity/access/lifecycle of reference codes;domain owner supplies semantic truth;neither consumer nor environment invents codes.\nFORBID:new mutable literal in Codex+restating a physical value already present in a directory+same physical value repeated as authority+code mapped in multiple registries+consumer inventing alias+historical literal copied forward+resolved value treated as Codex text+secret value stored in Codex+code without owner/type/version/status+changing mapping without new generation and affected evidence.+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\nIrreducible normative constants such as the Codex version identity and closed legal state enums may be stated literally at their single definition point and referenced by code elsewhere. A one-time user command may supply a scoped value without creating persistent law.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (331, E'article', E'C7', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'boundary-data-integrity', E'boundary-data-integrity\nDATA-INTEGRITY-CHECK:data-governance-sub-sovereign; SYSTEM-HEALTH-MONITOR:health-maintenance-test-sub-sovereign; PRESENT:data-integrity-health-only\nFORBID:maintenance-proxy-data-integrity-check; FORBID:data-governance-sub-sovereign-proxy-health-monitor\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (332, E'article', E'C71', E'CODEX_MODULE_MAINTENANCE', E'CODEX_AUTOMATIC_REPAIR_SPECIAL_LAW', E'modular-automation-and-automation-isolation', E'modular-automation-and-automation-isolation\nAUTOMATION:automatic update and automatic repair are modular;each automation unit is bound to its module code and identity group and acts only within that module\'s scope; ISOLATION:each automation unit runs independently with its own status,error and heartbeat; one unit\'s failure never disables or delays another unit or the main system; SCHEDULING:units are scheduled independently and bounded; DETECTION:detection,classification and evidence collection continue regardless of execution gates; EXECUTION:execution follows the module\'s switch and the user\'s per-item confirmation; OBSERVABILITY:per-unit automation state is reported separately.\nFORBID:one automation unit governing all modules+unit failure disabling other units+unit failure stalling the main system+unbounded automation scheduling+automation acting outside its module scope\nA governed cross-module maintenance action may be requested only through the owning module\'s declared interface and permission.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (333, E'article', E'C73', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'codex-indexed-search-performance-special-law', E'codex-indexed-search-performance-special-law\nSEARCH:interactive Codex lookup uses PostgreSQL-owned deterministic indexed projections; every result rehydrates the formal PostgreSQL row and verifies identity,lifecycle,current successor,content hash,current seal and access scope. INDEXES:identity,lifecycle,effective status,law code,module membership,command/fault code and dependency edges use dedicated indexes. FULL-TEXT:PostgreSQL full-text search covers authorized subject and rule fields with provision,module and law filters. CACHE:bounded memory cache keys include current version,query,scope,language and search-manifest hash. RECOVERY:missing or corrupt index/cache is discarded and rebuilt from formal PostgreSQL rows; alternate embedded database search is prohibited as current authority or fallback.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:unbounded-interactive-scan+stale-cache+search-result-as-authority+alternate embedded database-current-search-authority+external-indexing+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\nA maintenance-only full integrity scan may read all authoritative rows when explicitly requested;it remains bounded,observable and separate from interactive search.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (334, E'article', E'C74', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'codex-search-physical-index-and-dependency-dag-evidence', E'codex-search-physical-index-and-dependency-dag-evidence\nFTS-INTEGRITY:the search manifest binds both authoritative search-document hash and the independently recomputed physical FTS row hash plus exact FTS row count. Equal row counts alone do not prove parity. DAG-INTEGRITY:the module manifest generation records one aggregate dependency_graph_hash and an explicit cycle_check_status produced from the complete registered graph;per-module dependency hashes cannot replace whole-graph cycle validation. BENCHMARK-EVIDENCE:codex_search_benchmark_evidence records version identity,query class,normalized query hash,plan detail,result count,duration_microseconds,index_used,status and measured_at_utc for exact identity,module filter,short alias and FTS paths. PERFORMANCE:benchmarks are diagnostic evidence,not fixed acceptance thresholds;the required invariant is bounded indexed execution with no interactive full authoritative-table scan. FRESHNESS:any provision,module,dependency,alias,search-document or FTS change invalidates the manifest and benchmark generation until rebuilt in the same amendment transaction. AUTHORITY:all indexes and measurements remain derived and non-authoritative. HISTORY:revision_history remains user-deleted.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:FTS count-only proof+document hash substituted for physical FTS hash+module-local dependency hashes claimed cycle-complete+benchmark without query plan+full authoritative scan in interactive path+performance number as legal authority+stale benchmark reused across version+history reconstruction.\nA cold-cache measurement may vary by machine and load;variance is recorded without weakening correctness or index-use requirements.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (335, E'article', E'C75', E'CODEX_MODULE_MAINTENANCE', E'CODEX_AUTOMATIC_REPAIR_SPECIAL_LAW', E'health-recovery-orchestration-contract', E'health-recovery-orchestration-contract\nTRIGGER:B105 state and exact fault codes. FLOW:detect>isolate>decide>authorize>execute>verify>stability-window>recover-or-escalate>audit. REQUEST:{recovery_id,module_code,generation,health_result_id,fault_codes,affected_capabilities,decision_id,authorization_proof,executor_code,resource_budget,attempt_budget,deadline,rollback_target,correlation_id}. RESULT:{recovery_id,state,attempts,before_hash,after_hash,verification_evidence,stability_window_result,remaining_faults,rollback_receipt,completed_at_utc}. POLICY:idempotent+bounded retries+backoff+circuit breaker+no source overwrite/reset+unaffected channels continue. Automatic repair/update user switches remain controlling where applicable. SUCCESS requires new B105 current classification after verification,not executor exit alone.\nFORBID:recovery without current health result+component self-authorized repair+infinite retry+retry storm+whole-system isolation+success on process exit+reuse observation as verification+source reset/overwrite+hidden remaining fault.\nA transient retry may reuse the same immutable request within its attempt budget;any target,decision or payload change requires a successor request.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (336, E'article', E'C76', E'CODEX_MODULE_INFORMATION', E'CODEX_INFORMATION_COMMUNICATION_SPECIAL_LAW', E'connection-boundary-and-low-cost-legal-paths', E'connection-boundary-and-low-cost-legal-paths\nPURPOSE:replace overloaded C27. CONNECTION is an interaction crossing process,owner,trust,permission principal,state/data owner or independent contract boundary,or using I/O/serialization/session/transport handles. B101 PURE_INTERNAL_CALL and INTRA_MODULE_COMPONENT_CALL are not connections merely because code layers differ. ROUTES:LOCAL_PURE_CALL=no session/audit;LOCAL_GOVERNED_DISPATCH=typed envelope+scope+correlation without socket/IPC;READ_ONLY_QUERY=pooled least-scope session+prepared bounded query+batch audit;TEST_ISOLATED_ROUTE=ephemeral credentials+isolated data+no production mutation+aggregate evidence;FULL_TRANSPORT=information-layer adapter+auth+contract+timeout+retry/backpressure+audit. Selection uses formal predicates,not caller preference. Diagnostics,startup and one-time scripts choose the lowest route whose facts satisfy it and do not automatically require FULL_TRANSPORT.\nFORBID:layer label alone classified connection+direct cross-owner I/O+read-only route performing mutation+test route touching production state+support script blanket bypass+FULL_TRANSPORT mandated when LOCAL_PURE_CALL predicate holds+low-cost route used across authority or data-owner boundary.\nAn in-process database-free read of immutable owner-local constants is LOCAL_PURE_CALL;an actual database query is READ_ONLY_QUERY even in the same process.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (337, E'article', E'C77', E'CODEX_MODULE_XINGCHENG', E'CODEX_STAR_PRIVILEGED_INSTITUTION_SPECIAL_LAW', E'single-chinese-codex-mirror-three-part-storage', E'single-chinese-codex-mirror-three-part-storage\nCHINESE-MIRROR:exactly five ordered synchronized part files form one complete non-authoritative zh-TW mirror. Each part binds mirror_id,part_index,part_count,current Codex version,assembled payload hash,part hash and previous-part hash. ATOMIC-PUBLICATION:render all five from the formal PostgreSQL Codex,verify full parity and quality,then promote the complete generation together. Missing,mixed-version,duplicate,extra or corrupt part makes the mirror unavailable without affecting PostgreSQL authority.\nFORBID:part-count-other-than-five+part-as-independent-authority+mixed-generation+alternate embedded database-as-mirror-source-authority+fourth-or-extra-assembled-copy+partial-publication+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\nA streaming authorized reader may hold bounded transient rows while assembling;all transient content is erased at session end and never becomes another persistent mirror.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (338, E'article', E'C78', E'CODEX_MODULE_DIRECTORY', E'CODEX_DIRECTORY_SPECIAL_LAW', E'codex-external-non-indexing-and-internal-derived-search-clean-successor', E'codex-external-non-indexing-and-internal-derived-search-clean-successor\nSUCCESSOR:C78 completely supersedes D74. EXTERNAL-NON-INDEXING:Codex and every derivative are prohibited from RAG,embedding,semantic/vector indexes,training,external search,OS indexing and application-wide indexes. INTERNAL-SEARCH:authorized tooling may maintain Codex search documents,aliases,PostgreSQL full-text indexes,search manifests,benchmark evidence and module manifests only inside protected formal PostgreSQL authority. These are derived non-authoritative projections and are atomically rebuilt from current effective provisions. alternate embedded database may contain only non-current historical or isolated fixture data and cannot host current Codex search authority.\nFORBID:external-Codex-indexing+alternate embedded database-current-search-authority+derived-index-as-law+stale-search-generation+projection-writing-back-law+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\nBounded authorized in-memory lookup is erased at session end.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (339, E'article', E'C79', E'CODEX_MODULE_DIRECTORY', E'CODEX_DIRECTORY_SPECIAL_LAW', E'directory-coverage-requirement-complete-alignment', E'directory-coverage-requirement-complete-alignment\nEvery directory_master_catalog identity has exactly one directly corresponding coverage requirement after canonical normalization. Coverage proves complete inventory,zero orphan,zero missing,current-version parity,authoritative rows and seal/hash coverage. DIR_TEST_SUITE_ARCHITECTURE,DIR_CODEX_INTERNAL_MODULE,DIR_FORMAL_RULE_REGISTRY and DIR_MACHINE_SCHEMA_REGISTRY are explicit release-blocking subjects.\nFORBID:catalog without direct coverage+orphan coverage+count-only parity+stale or unsealed coverage.\nHistorical aliases resolve to one canonical code only.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (340, E'article', E'C8', E'CODEX_MODULE_PERMISSION', E'CODEX_MAIN', E'directory-write', E'directory-write\nDIRECTORY-WRITE:permission-sovereign-decision; EXEC:governed-executor; STORE:data-governance-sub-sovereign-declared; BASIS:codex+explicit-authorization DIRECTORY-STORAGE:every directory managed by permission-core is persisted in the registered local PostgreSQL authority only; PostgreSQL is the sole current structured storage and transaction boundary for directory entries,relationships,lifecycle and write receipts; alternate embedded database,file,cache,mirror or module-private state cannot be directory authority or write fallback.\nFORBID:direct-mutation-by-permission-sovereign/unauthorized-directory-write+permission-core-directory-outside-PostgreSQL+alternate embedded database-or-file-as-directory-authority+directory-write-fallback-outside-PostgreSQL+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (341, E'article', E'C80', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'cross-store-data-authority-provenance-resilience-and-readiness-contract', E'cross-store-data-authority-provenance-resilience-and-readiness-contract\nDATA-CONTROL-SYSTEM:central and module data operations are governed by the machine-readable data_governance_control_registry. LINEAGE-AUTHORITY-WRITE:every resource binds full cross-store lineage,authority_class,write provenance and contemporaneous permission/RLS proof. SCHEMA-DDL:one schema owner;runtime DDL forbidden;migration-executor-only DDL with independent append-only audit. CONNECTION:contract-version handshake and generation fencing precede writes. AUTOMATIC-MAINTENANCE:the existing automation core is the sole scheduler and registered database maintenance executors are the sole actors;no second scheduler,migration executor or authority source is permitted. OBSERVATION:transaction age,idle-in-transaction,locks,dead tuples,vacuum lag,table/index bloat,WAL,disk,pool pressure,transport backlog,backup state and reconciliation backlog are continuously observed. ADMISSION:each automatic action declares object scope,trigger threshold,maintenance workload class,deadline,concurrency and resource ceiling,idempotency key,stop policy and audit identity;interactive and authority work preempt maintenance. ACTIONS:registered bounded VACUUM,ANALYZE,REINDEX,partition and retention maintenance,connection recycling,long-transaction handling,orphan scanning,reconciliation,backup verification and restore rehearsal may run automatically. STRUCTURE:maintenance never invents or runs unregistered DDL,never auto-applies migration and never legalizes live drift;schema change remains ordered migration-executor work. LIFECYCLE:destructive cleanup follows tombstone,retention,reference check,purge and cross-store synchronization;unresolved references preserve data. RESILIENCE:versioned SLO,RPO/RTO classes,capacity watermarks,domain-scoped read-only emergency mode and database startup certification are mandatory. FAILURE:timeout,missing evidence,drift,unsafe lock impact or indeterminate outcome stops the action and may isolate only the affected domain read-only;no global silent alternate embedded database substitution. RECEIPT:every action records trigger,threshold,actor,executor,object,before/after state,duration,resources,result and correlation identity. AUTHORITY:degraded-copy,cache and derived data never become central-official by fallback or availability.\nFORBID:untraceable resource|missing authority marker|write without actor/executor/decision/correlation/revision|permission decision without snapshot|runtime or unregistered DDL|automatic migration|live drift legalization|second maintenance scheduler|unbounded transaction,concurrency,retry or maintenance resource|maintenance starving interactive work|RLS or generation-fence bypass|shared unclassified pool|single-step cross-store delete|purge with unresolved reference|uncertified rebuild serving|capacity exhaustion without fail-closed gate|global outage when domain isolation is sufficient|global automatic alternate embedded database fallback|SELECT-1-only readiness|maintenance success without receipt.+FORBID:alternate embedded database-active-consumer+alternate embedded database-runtime-write+alternate embedded database-fallback+alternate embedded database-reconciliation\nEmergency read-only access remains available only for an isolated registered domain and cannot mutate or upgrade authority. A database-native maintenance mechanism may execute only inside the same registered thresholds,ownership,resource and receipt contract.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (342, E'article', E'C81', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'postgresql-sql-authority-migration-security-fallback-audit-and-readiness-contract', E'postgresql-sql-authority-migration-security-fallback-audit-and-readiness-contract\nPOSTGRESQL-AUTOMATION:PostgreSQL18.6 is the sole SQL authority; schema inventory,migration replay,drift detection,security projection parity,transport/audit integrity,backup certification,capacity maintenance and readiness are maintained automatically by the existing single automation flow; TRIGGER:migration/schema/role/RLS/index/restore/connection-generation/workload-health event; SAFE-ACTIONS:ordered migration+analyze/vacuum+registered additive index+pool/batch adjustment+generation fence+read-only switch+evidence refresh; UNSAFE:destructive DDL,unknown effect or authority conflict fails closed and quarantines; no alternate SQL engine or manual normal path\nFORBID:second-SQL-authority+second-SQL-maintainer+out-of-band-DDL+runtime-role-DDL+manual-confirmation-as-normal-maintenance+automatic-destructive-DDL+write-under-drift+restore-authority-without-certification+retired-engine-fallback\nA registered read-only emergency scope may expose previously certified PostgreSQL data while affected writes remain closed;it cannot use alternate embedded database to replace central authority.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (343, E'article', E'C82', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'sql-migration-authority-and-priority-data-schema-directory-contract', E'sql-migration-authority-and-priority-data-schema-directory-contract\nMIGRATION-AUTOMATION:DIR_DATA_SCHEMA_AUTHORITY+sql-migration contract+sql-governance-closure contract are automatically regenerated and verified from ordered immutable migrations and live PostgreSQL introspection; INVARIANT:declared_schema_hash=replayed_schema_hash=live_introspected_schema_hash; CHAIN:N.source=N-1.target+gapless+single-head; EVENT:new-migration or catalog change triggers replay+receipt+directory parity+closure evidence; MISMATCH:SQL_SCHEMA_DRIFT fail-closed+read-only/quarantine; only migration executor may apply DDL\nFORBID:manual-catalog-as-authority+out-of-band-DDL+missing-receipt+multiple-migration-head+gap/branch+write-after-drift+manual-pass\nRead-only emergency access may continue only for previously certified compatible objects while all affected writes remain closed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (344, E'article', E'C83', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'sql-authority-boundary', E'sql-authority-boundary\nSQL-AUTHORITY:PostgreSQL18.6 is the sole central canonical structured-data+shared-transport+central-audit SQL authority; every official SQL object and write resolves to PostgreSQL through a registered contract; retired SQL engines have zero active consumers and cannot carry private state,fallback,cache,transport,audit,permission or reconciliation authority\nFORBID:second-SQL-authority+retired-SQL-engine-active-consumer+SQL-fallback+out-of-band-DDL+database-created-permission-authority\nPreviously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (345, E'article', E'C84', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'postgresql-object-level-schema-authority', E'postgresql-object-level-schema-authority\nEvery PostgreSQL schema,table,view,function,trigger,index,policy and role projection has object identity,database,schema,object type,owner module,authority class,data class,introducing migration,current definition hash and status.\nINHERITS:A135#SQL_GOVERNANCE_BOUNDARY\nPreviously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (346, E'article', E'C85', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'sql-migration-chain', E'sql-migration-chain\nMigrations are immutable,totally ordered,transactional and hash-chained. Each predecessor target hash equals the next source hash;genesis replay equals expected current schema hash;out-of-band DDL is prohibited.\nINHERITS:A135#SQL_GOVERNANCE_BOUNDARY\nPreviously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (347, E'article', E'C86', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'postgresql-schema-drift-gate', E'postgresql-schema-drift-gate\nAUTOMATIC-DRIFT-GATE:every startup,migration,restore,role/RLS change and periodic safety reconciliation recomputes declared_schema_hash+replayed_schema_hash+live_introspected_schema_hash; equality permits the registered capability; mismatch emits SQL_SCHEMA_DRIFT,raises connection generation,fences stale writers and switches affected scope fail-closed/read-only until an ordered migration restores parity\nFORBID:drift-warning-only+write-under-drift+manual-override+live-schema-becoming-authority+stale-connection-write\nPreviously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (348, E'article', E'C89', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'sql-audit-transport-integrity', E'sql-audit-transport-integrity\nAUTOMATIC-AUDIT-TRANSPORT-MAINTENANCE:append-only audit and shared transport automatically verify identity+correlation+causation+idempotency+ordering+retention+consumer ownership+sequence continuity; backlog,orphan,lease and retention events trigger bounded repair/reconciliation through the sole automation flow; unknown effects quarantine without replaying non-idempotent work\nFORBID:silent-gap+mutable-audit+duplicate-side-effect+unbounded-backlog/retry+second-transport-maintainer+success-without-continuity-evidence\nPreviously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (349, E'article', E'C9', E'CODEX_MODULE_ORDINANCE', E'CODEX_SUBORDINATE_ORDINANCES', E'four-functions-local', E'four-functions-local\nFUNCTIONS:Git+SQL+semantic-index+RAG+LLM remain local-owned formal capabilities;PRODUCTION:execution owners resolve exclusively through B166;UNAVAILABLE:declare closed and do not substitute an unregistered service;NETWORK:embedded browser access remains a governed tool channel and grants no authority\nFORBID:Python-third-domain+Python-production-service+unregistered-external-substitution+embedded-browser-governance-bypass\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (350, E'article', E'C90', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'sql-recovery-authority', E'sql-recovery-authority\nAUTOMATIC-RECOVERY:backup creation,restore rehearsal,retention and restore certification are scheduled by the sole automation flow; restore never creates authority; reopening requires automatic migration/schema/hash/RLS/role/security-projection/lineage/generation verification and connection-generation fence; any failed root keeps the affected scope read-only or closed\nFORBID:restore-as-authority+automatic-open-before-certification+stale-connection-write+uncertified-backup+manual-pass\nPreviously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (351, E'article', E'C91', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'sql-capability-health-and-degradation', E'sql-capability-health-and-degradation\nAUTOMATIC-CAPABILITY-HEALTH:PostgreSQL capabilities are observed independently for official-read/write,transport,audit,migration and maintenance; health events automatically choose healthy,degraded-read-only or fail-closed per registered matrix; no alternate SQL engine exists; recovery automatically replays required verification before reopening and publishes typed status/evidence\nFORBID:global-hidden-degradation+alternate-SQL-fallback+permission/audit/transport-substitution+write-before-ready+manual-normal-path\nPreviously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (352, E'article', E'D1', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'amendment', E'amendment\nAMENDMENT:explicit-signed-higher-version-full-replacement\nFORBID:incremental/runtime-amendment\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (353, E'article', E'D10', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'codex-modification-history', E'codex-modification-history\nHISTORY:inside-official-codex-database+ordered+hash-chained; EACH-ENTRY:change-id+version+date+scope+summary+previous-hash+entry-hash; SEALED-VERSION:no-history-write; SUCCESSOR-VERSION:copy-complete-prior-history+append-current-release-entry+seal\nFORBID:delete/reorder/rewrite/backdate/fabricate/history-gap/in-place-append-to-sealed-version; FORBID:postgresql-as-history-authority\nHistory is appended only while constructing an unsealed complete successor version.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (354, E'article', E'D100', E'CODEX_MODULE_RELEASE', E'CODEX_RELEASE_VERSION_SPECIAL_LAW', E'technical-pass-versus-external-verification-status', E'technical-pass-versus-external-verification-status\nDUAL-STATUS:technical_status=PASS|FAIL|BLOCKED|TIMEOUT|ERROR|INCOMPLETE_EVIDENCE;certification_status=TECHNICAL_PASS|SEALED_PENDING_EXTERNAL_SIGNATURES|VERIFIED_RELEASE|REJECTED|INCOMPLETE_EVIDENCE. Automated audit can produce current technical status and TECHNICAL_PASS only; external certification requirements remain distinct. UI/API/audit always expose both exact states and missing requirements. FAIL/BLOCKED/TIMEOUT/ERROR/INCOMPLETE_EVIDENCE cannot promote or be hidden.\nFORBID:single-combined-boolean+non-PASS-treated-PASS+technical-PASS-labeled-VERIFIED_RELEASE+pending-hidden+self-signature-replacing-required-external-certification+certification-masking-technical-failure\nDevelopment/test execution may consume TECHNICAL_PASS artifacts inside an isolated non-production scope when the release policy explicitly permits it and the pending certification is visible.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (355, E'article', E'D102', E'CODEX_MODULE_RUNTIME', E'CODEX_MAIN', E'execution-receipt-tier-profile', E'execution-receipt-tier-profile\nSUCCESSOR-SCOPE:B106 declares stage contracts;this article declares the canonical machine receipt-tier profile. TIERS:dispatch-intake|authorization-and-governance-gate|task-planning|specialized-executor|result-verification|state-event-audit-publication. MAPPING:INTAKE->dispatch-intake;AUTHORIZE->authorization-and-governance-gate;PLAN->task-planning;DISPATCH+EXECUTE->specialized-executor;VERIFY->result-verification;PUBLISH->state-event-audit-publication. ORDER:strict single pass;skip+repeat+out-of-order deny with a receipt error. REFUSALS:authorization failures still record planning+executor+verification+publication as refusal receipts;no tier is skipped. VERIFICATION:the verification actor must differ from the concrete specialized-executor actor whenever an executor actor is named;executor self-declared success is never sufficient. ACCEPTANCE:an accepted outcome requires a complete receipt ledger+a passing independent verdict+a published audit entry;any missing receipt+failed verdict or failed publication returns a refusal instead. DURABILITY:the audit append is serialized against concurrent processes and flushed to stable storage before success;an append that cannot be made durable denies.\nFORBID:tier-skip+duplicate+reorder on governed work+executor self-verification+accepted outcome without complete receipts+basis-free acceptance+acceptance before audit publication+publication failure tolerated+reduced profile on state mutation\nA decision-only adjudication that executes nothing records the same tier profile with the executor tier marked decision-layer;the receipt ledger is never reduced below the six declared tiers.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (356, E'article', E'D103', E'CODEX_MODULE_AUDIT', E'CODEX_MAIN', E'independent-verification-verdict-record', E'independent-verification-verdict-record\nVERDICT:each verification produces a typed record {verified|verifier|reasons}. IDENTITY:the verifier is a distinct program object or identity from every executor actor;the recorded verifier differs from the concrete specialized-executor actor whenever one is named. CHECKS:the decision basis must be present;an executor may not declare its own verified state or verifier field;an unaccepted result must carry a refusal reason;registered per-intent checks add evidence checks. EVIDENCE:where a registered check verifies an artifact+revision+state or external evidence,the verdict references that evidence and never relies solely on executor-reported fields. FAIL-CLOSED:any failed check returns verified=false with reasons and the request is refused.\nFORBID:self-verification+executor-self-declared verification accepted+verdict without reasons+basis-free acceptance+verifier equal to the concrete executor+one actor as sole final verifier of its own work+silent verdict omission\nA decision-only adjudication with no concrete executor is verified by the independent verifier object;the verdict is still recorded.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (357, E'article', E'D104', E'CODEX_MODULE_AUDIT', E'CODEX_AUDIT_EVIDENCE_TIME_SPECIAL_LAW', E'user-authorized-revision-history-resumption-genesis', E'user-authorized-revision-history-resumption-genesis\nUSER-AUTHORITY:the current explicit user finding that empty revision_history violates D10 authorizes revision recording to resume now under the separate-command exception of C72. NO-BACKFILL:previously user-deleted entries remain deleted and must not be reconstructed from Git,mirror,seals,caches or inference. NEW-GENESIS:revision_history begins a new auditable chain at sequence=1 whose previous_hash is 64 zero hexadecimal characters and whose summary explicitly names user-authorized-resumption-after-deletion;the entry binds the current successor version,current pre-amendment seal full_root as baseline and the exact amendment scope. It proves the new chain start,not undisclosed prior amendment history. FUTURE:every Codex successor transaction copies the complete resumed chain,appends exactly one current change entry before provision_revisions/sealing,and sets seal_manifest.history_head to that entry_hash;version,change_id,timestamp,scope,summary,previous_hash and entry_hash are mandatory. ENTRY-HASH:SHA256 over canonical UTF-8 fields sequence|change_id|version|recorded_at_utc|change_scope|summary|previous_hash|version_epoch with separators fixed by the registered canonicalization policy. ORDER:sequence strictly increases by one,previous_hash equals prior entry_hash,version and recorded_at are nondecreasing UTC timestamps,and one successor version has exactly one history entry. CURRENT-SCOPE-PRECEDENCE:this article supersedes C72 and overrides only the obsolete \'revision_history remains user-deleted/empty\' clauses embedded in earlier and related active provisions;their non-history rules remain active. D10 again controls ordinary future history preservation. VALIDATION:empty history after this version,missing current entry,broken sequence/hash/version linkage,seal head mismatch or reconstructed pre-genesis entry is CRITICAL FAIL and blocks Codex publication. CERTIFICATION:the resumed chain is technical integrity evidence;external human signatures remain separately pending and are still required for VERIFIED_RELEASE.\nFORBID:reconstructing deleted entries+claiming genesis contains prior history+sequence gap+multiple entries for one version+entry after seal+in-place history edit/delete/reorder+noncanonical hash+seal history_head mismatch+future amendment without append+user-deleted marker used to suppress future history+history chain used to imply external signature verification.\nThe deleted pre-genesis history remains permanently unavailable. Its absence is explicitly represented by the new genesis boundary and does not permit fabricated recovery.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (358, E'article', E'D105', E'CODEX_MODULE_AUDIT', E'CODEX_AUDIT_EVIDENCE_TIME_SPECIAL_LAW', E'provision-normativity-classification-contract', E'provision-normativity-classification-contract\nCLASSIFICATION:every provision identity must declare exactly one current primary class:EXPLANATORY,HISTORICAL,NORMATIVE_MANUAL,MACHINE_ENFORCED,RELEASE_BLOCKING or SUPERSEDED;secondary tags may refine but never replace the primary class. EXPLANATORY creates no independent duty. HISTORICAL is non-effective lineage evidence. NORMATIVE_MANUAL requires named verifier and evidence schema. MACHINE_ENFORCED requires an active formal-rule mapping,typed inputs,deterministic predicate,decision,severity and executable conformance evidence. RELEASE_BLOCKING requires fresh revision-bound evidence and denies release on failure or absence. SUPERSEDED must resolve to one active successor. DEFAULT:an unclassified active provision is NORMATIVE_MANUAL and INCOMPLETE_EVIDENCE,never silently machine-enforced or release-passing. COVERAGE:formal-rule count need not equal provision count,but every machine-enforced clause must be mapped and every mapping must resolve to one active provision and evaluator contract.\nFORBID:implicit normative class+checker-created policy+unmapped machine enforcement+missing evidence treated as pass+superseded rule remaining controlling+one mapping claiming unrelated clauses.\nLegacy provisions remain readable;their classification is migrated incrementally and cannot be inferred as verified release evidence.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (359, E'article', E'D106', E'CODEX_MODULE_AUDIT', E'CODEX_AUDIT_EVIDENCE_TIME_SPECIAL_LAW', E'formal-rule-semantic-and-evaluator-parity-contract', E'formal-rule-semantic-and-evaluator-parity-contract\nCALL-BOUNDARY:compare caller and callee values field-by-field for process,module,owner,trust,principal,generation and state_owner;never compare heterogeneous namespaces to one another. ROLE:each request carries active_role_identity;星澄 may lawfully use review,coordination or executor role under its special law while one request has exactly one active role and retains permission/domain boundaries. IDENTITY:resolver proof validates registry hash,current generation,active source and output identities,declared cardinality and certified resolver receipt. HEALTH:validate schema,type,unit,range,time,freshness,dimension,threshold,hysteresis,sequence,generation,source and content hash. PRECEDENCE:prove exactly one controlling rule,acyclic successor graph,valid special-law containment,ordinance authority and superseded predecessor exclusion. PIPELINE:validate exact order,uniqueness,stage owner,input/output schema,timeout,idempotency,fault code,receipt and executor-verifier separation. TRANSPORT:FULL_TRANSPORT validates authenticated requester,registered destination,scope,contract,rate budget,audit,transport owner and credential custody;it is never unconditional. MACHINE-SCHEMA:validate types,enums,timestamps,hashes,sequence,previous hash,signature references,schema version and unknown-field policy. RELEASE:verify actual Ed25519 threshold signatures,signer identities,trust anchors,artifact digest,content root,history head and identity root;status strings alone are evidence claims,not proof. PARITY:formal registry predicate,evaluator behavior,tests and controlling prose must share one versioned semantic hash;any mismatch is CRITICAL and fail-closed.\nFORBID:heterogeneous-ID equality+role hard-code that removes lawful 星澄 executor identity+cardinality-only identity proof+field-presence-only health/schema proof+stage-name-only pipeline proof+unconditional FULL_TRANSPORT+self-asserted release verification+evaluator semantics without Codex lineage.\nUntil evaluator parity evidence is submitted,the technical audit may report structural checks but affected formal decisions remain INCOMPLETE_EVIDENCE.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (360, E'article', E'D107', E'CODEX_MODULE_RELEASE', E'CODEX_RELEASE_VERSION_SPECIAL_LAW', E'seal-candidate-certification-and-release-status-contract', E'seal-candidate-certification-and-release-status-contract\nIDENTITY:each seal record is either CANDIDATE_SEAL,CERTIFIED_SEAL or RETIRED_SEAL and binds a unique seal_id,version_identity,content_root,history_head,identity_root,lineage_root,created_at and certification state. IMMUTABILITY:a changed root or history head creates a new candidate identity and never overwrites a sealed identity. CERTIFICATION:Ed25519 2-of-3 external signatures and valid trust anchors are mandatory for CERTIFIED_SEAL. STATUS:technical output is standardized as TECHNICAL_AUDIT_PASS or TECHNICAL_AUDIT_FAIL;legal closure is CODEX_CERTIFICATION_COMPLETE or CODEX_CERTIFICATION_INCOMPLETE;release is VERIFIED_RELEASE_APPROVED or VERIFIED_RELEASE_DENIED. A technical pass with pending signatures always yields CODEX_CERTIFICATION_INCOMPLETE and VERIFIED_RELEASE_DENIED. HISTORY:the post-deletion revision chain begins at its declared recovery genesis and proves only successors from that genesis;it must not claim reconstructed deleted history. OBLIGATIONS:mandated,planned,in-progress,evidence-submitted,verified,complete,escalated and failed remain distinct;an incomplete release-blocking obligation denies affected verified release and is never promoted by audit wording.\nFORBID:same seal identity with changed roots+candidate represented as certified+technical PASS presented as legal verification+signature status string substituted for cryptographic proof+fabricated deleted history+mandated obligation presented complete.\nHistorical seal rows lacking candidate identity remain legacy candidate evidence only and cannot certify a current release.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (361, E'article', E'D11', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'codex-file-protection-and-authority-boundary', E'codex-file-protection-and-authority-boundary\nAUTHORITY:the current PostgreSQL Codex is authoritative through permission,transaction,version,current-binding and seal controls;filesystem attributes never create authority. READONLY:only current generated confidential Chinese mirror parts,the registered governance package entry and registered shared-layer enforcement sources require filesystem read-only protection. WRITABLE:architecture projections,renderer inputs and all other non-mirror workspace files are governed writable. PUBLICATION:an authorized publisher may unlock a required protected target only for verified atomic replacement and must restore protection before completion. CANDIDATE:a candidate has no current authority until verified,published,bound and sealed.\nFORBID:filesystem-readonly-as-authority+all-Codex-files-readonly+unauthorized-write+in-place-current-authority-mutation+unsealed-candidate-as-current+protected-target-left-writable+content-or-version-drift\nNone.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (362, E'article', E'D110', E'CODEX_MODULE_AUDIT', E'CODEX_AUDIT_EVIDENCE_TIME_SPECIAL_LAW', E'revision-history-current-and-pre-genesis-state-normalization', E'revision-history-current-and-pre-genesis-state-normalization\npre_genesis_history_state=user-deleted describes only deleted history before recovery genesis;revision_history_status=active-resumed-genesis is the sole current state. Current history starts at revision_history_genesis_version and every amendment appends one linked row. Legacy statements that history remains deleted apply only pre-genesis.\nFORBID:dual current state+empty-current inference+fabricated backfill+legacy prose overriding D104/D110.\nDeletion timestamp and scope remain historical evidence.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (363, E'article', E'D111', E'CODEX_MODULE_LANGUAGE', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'language-governance-freeze-acceptance-event', E'language-governance-freeze-acceptance-event\nFREEZE_PENDING becomes FROZEN only after an append-only acceptance event binds schema version,current revision,policy/IR/evidence/DAG/corpus/golden hashes,full-incremental parity,ABI/API compatibility,release pipeline,duplicate-scanner absence,stale-evidence test,zero critical findings and OBL_LANGUAGE_DEPENDENCY_DAG_GATE verified evidence plus 星澄 receipt. Metadata alone cannot freeze.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:metadata-only freeze+self-declared FROZEN+missing or stale evidence+critical waiver.\nExperimental governance cannot satisfy stable freeze.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (364, E'article', E'D113', E'CODEX_MODULE_RELEASE', E'CODEX_RELEASE_VERSION_SPECIAL_LAW', E'current-seal-component-and-trust-anchor-continuity', E'current-seal-component-and-trust-anchor-continuity\nCURRENT-SEAL:every current seal_manifest row has same-version sealed_components inventory and trust_anchor_requirements row. COMPONENTS bind authoritative content,identity,lineage,revision history,directory/registry state,search/module manifests,epoch identity and epoch seal into full-root coverage;included flags are explicit. TRUST:current row declares Ed25519,2-of-3,three keys,detached signatures and external offline private-key custody. CONTINUITY:seal,components,trust anchor,certification evidence and epoch seal share current version identity;missing current rows yield INCOMPLETE_EVIDENCE. Historical legacy rows may remain sparse but cannot certify current release.\nFORBID:manifest-only current seal+trust inherited implicitly from old version+component gap hidden by full-root string+private key stored in Codex+pending signature presented verified.\nExternal signatures remain pending until real detached signature verification;adding the trust requirement row is not certification.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (365, E'article', E'D114', E'CODEX_MODULE_AUDIT', E'CODEX_AUDIT_EVIDENCE_TIME_SPECIAL_LAW', E'provision-classification-and-formal-parity-clean-successor', E'provision-classification-and-formal-parity-clean-successor\nSUCCESSOR:D114 completely supersedes D101 classification and mapping-status clauses;D105 primary classes are canonical:EXPLANATORY,HISTORICAL,NORMATIVE_MANUAL,MACHINE_ENFORCED,RELEASE_BLOCKING,SUPERSEDED. Enforcement and release-blocking are orthogonal secondary tags,so D100 may be primary RELEASE_BLOCKING and also formal-rule mapped. MAPPING_STATUS is structural only:UNMAPPED,PARTIAL,MAPPED,CONFLICT. PARITY_STATUS is separate:NOT_APPLICABLE,PENDING,PASS,FAIL. A mapped rule is executable for formal VERIFIED decisions only when parity PASS binds registry,evaluator,test and controlling-prose semantic hashes plus evidence ID at current revision. Pending parity yields INCOMPLETE_EVIDENCE.\nFORBID:legacy INTERPRETIVE_ONLY/MIXED as current primary class+parity encoded in mapping status+MAPPED interpreted VERIFIED+one field carrying two state machines.\nLegacy D101 classifications are historical migration inputs only.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (366, E'article', E'D115', E'CODEX_MODULE_DIRECTORY', E'CODEX_DIRECTORY_SPECIAL_LAW', E'machine-schema-complete-typed-registry-contract', E'machine-schema-complete-typed-registry-contract\nEvery machine schema row declares required fields,optional fields,field_types,nullability,schema_version,compatibility,unknown-field policy,content hash,persistence,redaction,status and successor. machine_schema_registry is the sole canonical machine-schema representation;specialized schema tables are derived views only and MUST NOT independently define semantics. Canonical producer schemas,consumer validators,derived specialized views and persistence tables must match one registered semantic hash before parity_status may be PASS. identity-conversion contract is mandatory alongside receipt,token,audit,health,test-suite,final-decision,Codex-read-session and Chinese-mirror-part schemas. Drift,missing type/nullability evidence or absent producer-validator-table parity evidence is P0 INCOMPLETE_EVIDENCE.\nFORBID:key-name-only validation+checker-local field definitions+required/optional ambiguity+required-but-nullable hidden as optional+schema drift treated pass.\nAn explicitly optional field may be absent;nullable is independent and must be declared.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (367, E'article', E'D116', E'CODEX_MODULE_TEST', E'CODEX_TEST_VALIDATION_EVALUATION_SPECIAL_LAW', E'normalized-test-flow-command-fault-manual-trace-contract', E'normalized-test-flow-command-fault-manual-trace-contract\nTest-flow requirement_ids contains provision identities only. Exact command,fault and manual relationships are stored in normalized test_flow_command_links,test_flow_fault_links and test_flow_manual_links. test_trace_applicability is the sole machine-readable applicability registry and records code_type,code,relationship_type,applicability,reason_code,controlling_provision,evidence_hash,validated_at_version and status. Each link binds code,test flow,evidence field,evidence hash,introduced_version,validated_against_version and status. Active codes require either current validated links or an authorized current not-applicable record;pending,gap,retired and not-applicable are distinct states and missing data never means not applicable. FAULT_TO_MANUAL is zero-to-many with rationale;repairable faults require one-or-more manuals.\nFORBID:mixed identity types in requirement_ids+free-text-only trace+every fault forced to arbitrary manual+repairable fault without manual+aggregate coverage without exact links.\nInformational/non-repairable faults may have zero manuals only with registered rationale.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (368, E'article', E'D117', E'CODEX_MODULE_RELEASE', E'CODEX_MAIN', E'timestamp-version-model-exclusive-successor', E'timestamp-version-model-exclusive-successor\nSUCCESSOR:D91 and D92 exclusively control current generation identity and change classification;formal names are stable and version-free,while internal authority timestamps order immutable generations and lineage;historical numeric or visible timestamp identities are non-operative evidence only.\nFORBID:current numeric/five-decimal version issuance+version arithmetic+automatic increment+1.00000 baseline used for successor calculation+legacy rule remaining effective.\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (369, E'article', E'D118', E'CODEX_MODULE_RELEASE', E'CODEX_MAIN', E'timestamp-codex-amendment-flow-successor', E'timestamp-codex-amendment-flow-successor\nSUCCESSOR:D118 completely supersedes D75. Non-disruptive amendment flow is RECEIVE>SNAPSHOT>STAGE>NORMALIZE>VALIDATE>CERTIFY>PREPARE>ATOMIC-PUBLISH>NOTIFY>SAFE-RELOAD>VERIFY>AUDIT. NORMALIZE uses D91 timestamp-version identity and the current timestamp_version_evolution_rules registry;it never reads numeric version_evolution_rules as current authority. All readers keep the last accepted generation until atomic publication;failure quarantines staging and leaves runtime unchanged.\nFORBID:1.00000 arithmetic in amendment flow+active in-place mutation+partial publication+fabricated signatures+runtime interruption caused solely by Codex amendment.\nImmutable legacy amendment evidence remains readable as historical only.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (370, E'article', E'D12', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'provision-update-recertification', E'provision-update-recertification\nANY-PROVISION-CHANGE:creates-new-candidate+new-permanent-identity+new-lineage+new-content-hash; RECERTIFICATION:integrity+identity+history+complete-version-seal-required; EFFECTIVE:only-after-recertified-successor-activation; PRIOR-PROVISION:active-until-then+retained-after-supersession\nFORBID:reuse-prior-identity/signature/hash+in-place-update+self-certification+partial-certification+activate-before-recertification+retire-old-provision-before-successor-effective\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (371, E'article', E'D121', E'CODEX_MODULE_RELEASE', E'CODEX_MAIN', E'implementation-obligation-mandated-state-clean-successor', E'implementation-obligation-mandated-state-clean-successor\nSUCCESSOR:D121 supersedes the obligation-state transition clause of D120. The governance_closure_plan is scheduling evidence only and does not advance an implementation obligation. The twelve obligations OBL_ANTI_JAILBREAK+OBL_ARCHITECTURE_CATALOG+OBL_CHANNEL_ANOMALY_ISOLATION+OBL_DIRECTORY_GOVERNANCE_DATA_CLOSURE+OBL_FORMAL_EVALUATOR_V2_PARITY+OBL_LANGUAGE_DEPENDENCY_DAG_GATE+OBL_LAYERED_ARCHITECTURE+OBL_NATIVE_PROMOTION_RECORD_CHECKER+OBL_SYSTEM_RELIABILITY+OBL_TEST_SUITE_DIRECTORY+OBL_TOP_LEVEL_PATHS+OBL_星澄_AUDIT all remain mandated. D55 lifecycle advancement requires actual state-transition evidence and receipt beyond a planning row. Their deadline remains 2026-10-12T15:59:59Z or the next affected verified release,whichever occurs first,except where an existing obligation has an earlier equivalent release condition. VERIFIED_RELEASE remains denied while any is open.\n\nPACKAGE-AUTO-DEFER:每24小時偵測一次。未具明確新增套件許可者自動標記DEFERRED_AWAITING_PERMISSION；一般新版發布未滿14日者自動標記DEFERRED_OBSERVATION_WINDOW。遞延不等於拒絕、通過或已安裝，遞延期間禁止下載、安裝、鎖定或執行；條件成熟後於下一次週期自動重新評估。重大安全或相容性事件得立即加跑受管檢查。\nFORBID:plan treated as implementation progress+mandated automatically changed to planned+deadline extension+open obligation omitted from release closure+completion without actual acceptance evidence.\nA later obligation may advance only through its own immutable evidenced transition under D55.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (372, E'article', E'D123', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'D87-D90-reference-normalization-successor', E'D87-D90-reference-normalization-successor\nSUCCESSOR:D123 supersedes D87,D88,D89 and D90 only to normalize their current version-authority references while preserving their interpretation,command-contract,reference-placement and evidence-timestamp duties. D91 exclusively defines current timestamp-derived version identities and issuance;D123 governs interpretation and reference normalization;event,evidence,audit and revision timestamps retain the D90 envelope incorporated here. Current contract_version_identity and sealed version_identity are issued under D91. Operational references consume typed canonical codes or governed environment bindings;version identity and evidence timestamp remain distinct typed fields. Historical D86 references are immutable lineage evidence only and never current authority.\nFORBID:D86 described as current or exclusive authority+untyped timestamp serving version and evidence+legacy alias selecting current state+event-time correction changing version identity+new numeric contract version+duplicated operational literal.\nHistorical provisions and values remain readable as immutable evidence;normalization changes current references without rewriting history.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (373, E'article', E'D124', E'CODEX_MODULE_DIRECTORY', E'CODEX_MAIN', E'current-binding-search-directory-access-and-certification-contract', E'current-binding-search-directory-access-and-certification-contract\nCURRENT-PROJECTION:every amendment atomically rebuilds current_binding_version for all active and superseded lifecycle identities and every effective projection row to the current Codex version. SEARCH-LIFECYCLE:codex_search_document.lifecycle_state is joined from provision_lifecycle_status during build and is never independently copied. SPECIAL-LAW:current links resolve through provision_supersession_edges to one active successor;retired-no-successor links are removed or replaced by an explicit active controlling basis. DIRECTORY:B42-normalized_directory_entry is the canonical active representation;legacy backing schemas are source projections only. PLAN:all master directories have a normalization plan or born-normalized evidence. ACCESS:sub-sovereigns have no direct Codex view and may use only an explicit bounded parent-sovereign proxy session. CERTIFICATION:sealed-governed-authorization is the sole current certification-state value and must equal current seal,epoch seal and certification evidence.\nFORBID:stale binding version+search lifecycle copied independently+stale special-law provision link+legacy backing schema claimed canonical+missing normalization plan+direct sub-sovereign Codex view+competing certification enums.\nHistorical rows retain their original version and status only in explicitly historical fields.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (374, E'article', E'D127', E'CODEX_MODULE_DATA', E'CODEX_MAIN', E'sql-governance-verification-suite', E'sql-governance-verification-suite\nAUTOMATIC-SQL-VERIFICATION:CSharp TestSuiteOrchestrator triggers required PostgreSQL migration replay+drift+RLS/security projection+transaction+transport+audit immutability+backup/restore+zero-retired-consumer suites on affected events; evidence is hash/revision/version bound and feeds the release gate automatically; timeout,missing evidence,BLOCKED or failure remains fail-closed\nFORBID:second-test-orchestrator+manual-pass+BLOCKED-as-PASS+stale-evidence+release-with-missing-SQL-suite\nPreviously certified read-only data may remain available only under an explicit compatible snapshot policy while affected writes stay closed.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (375, E'article', E'D13', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'atomic-provision-supersession', E'atomic-provision-supersession\nACTIVATION-EVENT:identity+recertification+complete-version-seal+official-entry-publication; SAME-INSTANT:successor-status=active+predecessor-status=superseded; PREDECESSOR-AFTER-ACTIVATION:no-legal-effect+history-only; GAP/OVERLAP:none\nFORBID:old-and-new-simultaneously-effective+delayed-old-law-expiry+rollback-by-native-javascript-esmivating-old-identity+delete-superseded-history\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (376, E'article', E'D130', E'CODEX_MODULE_IDENTITY', E'CODEX_MAIN', E'身分與會話驗證基線', E'身分與會話驗證基線\n全系統身分、session、permission 與 governed request 僅依 registered identity、process attestation、nonce、時間界線、single-use session、token/signature verification、identity/authorization/revocation generation、audience、scope、purpose、confirmation reference、correlation/operation identity 與 audit evidence。驗證順序須 fail-closed 並與 token contract 對齊。\n禁止由未註冊的人體特徵來源產生身分、權限、提升權限、啟動工具、接受 session、存取 Codex 或核准 release；禁止保存秘密 token、私鑰或可重播 credential。\n歷史 sealed 內容只保留歷史效力；任何缺少實作或測試證據的 current closure 必須為 INCOMPLETE_EVIDENCE。');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (377, E'article', E'D132', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-ntp-correctness-tests', E'xingcheng-ntp-correctness-tests\nBOUNDARY:autoregressive training must prevent future-token leakage and prove target alignment,masking,loss and tokenizer consistency through native evidence;OWNER:XINGCHENG owns the detailed probe matrix,inputs and tolerances as owner-local test rules;FAILURE:missing or contradictory evidence denies training-artifact acceptance.\n\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (378, E'article', E'D133', E'CODEX_MODULE_XINGCHENG', E'CODEX_MAIN', E'xingcheng-kv-cache-correctness-and-performance', E'xingcheng-kv-cache-correctness-and-performance\nBOUNDARY:the production inference owner must prove cache correctness across supported data forms,context boundaries and decoding phases,and must measure quality plus resource effects;OWNER:the C++23 inference implementation owns concrete cases,tolerances,contexts and metrics as owner-local test rules;PROHIBITION:performance gain cannot excuse unmeasured correctness or quality loss.\n;FORBID:deployment-version+benchmark-result+model-threshold+port+path+operational-tunable-as-permanent-Codex-literal\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (379, E'article', E'D134', E'CODEX_MODULE_RELEASE', E'CODEX_MAIN', E'gptbridge-release-manifest', E'gptbridge-release-manifest\nProject-wide release manifest (release_id, git_commit, backend_version, frontend_version, ipc_contract_version, database_schema_version, codex_schema, codex_version, build_hash, status) instead of relying on Git commits alone; before any cutover the manifest must validate codex compatibility, permission-definition compatibility, IPC compatibility, SQL schema compatibility and frontend compatibility.\nThe manifest may only reference the codex verified version and seal digest; the codex must never be treated as a hot-updatable configuration file that a release overwrites.\nregistered Codex contract section 10.18 records the manifest schema and the compatibility gate; neither exists in the repository (gap G56).;MUTABLE-VALUES:resolve-current-values-from-owner-versioned-contract-or-registry;CODEX:retains-owner+boundary+prohibition+acceptance-dimensions-only\n;FORBID:deployment-version+benchmark-result+model-threshold+port+path+operational-tunable-as-permanent-Codex-literal\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (380, E'article', E'D135', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'gptbridge-integration-sequence', E'gptbridge-integration-sequence\nINTEGRATION-CONVERGENCE: existing-capability inventory and current registered contracts remain the only basis; duplicate gateway, updater, runtime registry or process manager is forbidden. INTEGRATION-04B RELEASE-ISOLATION: each candidate executes from an immutable validated release_root with a distinct generation, state_root, backend port and process identity; it cannot write active release/state, receive production gateway traffic, or claim READY before full runtime initialization and authenticated health proof. 04B lifecycle PASS requires runtime READY, no runtime_failed phase, graceful STOPPING->STOPPED with exit_code=0, released port and zero orphan process. The mid-start termination case passes only when STARTING was observed, termination occurred before runtime READY, resources were released and no orphan remained. Any blocked mandatory scenario or stale/contradictory evidence makes the group INCOMPLETE, never PASS. INTEGRATION-05 STANDBY-BACKEND: standby must be a separately isolated validated release generation; active remains authoritative and serves traffic until standby reaches STANDBY+READY and compatibility, health and bounded stability evidence pass. Promotion is one atomic gateway generation switch; old generation drains only after promotion and remains rollback-capable during the rollback window. Readiness, stability, isolation or generation-fence failure terminates only standby, preserves active, records failed-isolated or rolled-back, and forbids global-success. CURRENT-CALIBRATION:04B evidence that treated listener-ready plus runtime_failed/exit_code=1 as PASS is invalidated and must be regenerated; 05 implementation exists but is not certified complete until the isolation and promotion evidence above is current.\n\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (381, E'article', E'D136', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'project-blockchain-style-module-records', E'project-blockchain-style-module-records\nBlockchain-style data structure only (append-only hash chain with verifiable integrity; no tokens, no consensus, no P2P): one module_id maps to one dedicated hash chain of operation receipts, state changes and version publications; entries chain prev_hash + payload_hash + actor/identity + decision/correlation id + timestamp into entry_hash, and any tampering, gap or reordering fails verification fail-closed. The design reuses the existing audit chain (GPTBridge.GitAutomation Ledger.cs chained audit append to git_audit_chain/, seal_manifest and revision_history) instead of creating a second ledger. Fine-grained modules each own a registry identity and an independent chain head; integrity verification (replay plus hash comparison) is provided and integrated with governor sealing and external signatures; chains store hashes and metadata only, never secrets or credentials.\nMandatory registered Codex contract invariant 20; a failed chain-integrity verification is fail-closed; history is never rewritten or deleted.\nRecorded in registered Codex contract section 10.29 and invariant 20; the existing audit chain provides the mechanism, per-module chain heads are not yet wired.\n\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (382, E'article', E'D137', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'on-demand-isolation-authority', E'on-demand-isolation-authority\nGRANULARITY:isolate one unit or one module (selectable)|PURPOSE:failure boundary failure must not propagate to other units|EXECUTION:isolation+release+freeze executed by runtime core|ADJUDICATION:decision core when needed|AUDIT:full audit trail mandatory|SCOPE:on-demand only no permanent isolation without cause\nFORBID:isolation executed outside runtime core+unaudited isolation+isolation bypassing decision adjudication when contested\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (383, E'article', E'D138', E'CODEX_MODULE_LANGUAGE', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'test-responsibility-and-audit-gate', E'test-responsibility-and-audit-gate\nTEST-RESPONSIBILITY:CSharp14/.NET10 TestSuiteOrchestrator is the sole test orchestrator;C/C++23 and each registered owner-language native runner execute applicable tests and normalize typed test result contract;C++23 Audit Engine executes the audit manifest;Python and pytest have no formal test,integration,audit,verification,release or push-gate responsibility;the release Push Gate requires complete current native evidence and one-language success never implies system acceptance;formal evaluator fails closed on missing owner,runner,evidence or audit record\nFORBID:pytest-formal-role+Python-test/audit/verification/gate+second-orchestrator+second-audit-engine+capability-activation-without-current-executed-evidence+silent-unsupported-check\nNone; unsupported required coverage is BLOCKED and release-denied rather than delegated to Python.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (384, E'article', E'D139', E'CODEX_MODULE_LANGUAGE', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'test-audit-native-residency-gate', E'test-audit-native-residency-gate\nBOUNDARY:formal test,audit,verification,release,push and their scheduling have zero Python or pytest execution in every environment;TEST:CSharp owns sole orchestration and registered owner-language native runners execute checks;AUDIT:C++23 Audit Engine plus registered native providers only;PROOF:current source dependency graph+build graph+runner registry+audit manifest+process tree+consumer registry must jointly show zero Python consumer,zero Python child process and zero Python fallback for every formal path;UNSUPPORTED:BLOCKED+release-denied;EVIDENCE:bound to the current internal timestamp generation and invalidated by any affected source,contract,runner or manifest change.\nFORBID:Python-or-pytest-consumer+Python-child-process+Python-delegation/fallback+partial-consumer-proof+stale-proof+unsupported-as-PASS+second-orchestrator-or-audit-engine\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (385, E'article', E'D14', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'codex-without-codex-view', E'codex-without-codex-view\nCODEX:cannot-view-or-cite-codex-content; RECEIVE:signed-opaque-adjudication-result+provision-identities+verification-status-without-rule-text; ACTION:verify-envelope+identity+freshness+audit+coordinate-authorized-outcome\nFORBID:codex-direct-codex-read+rule-text-disclosure+independent-codex-interpretation+business-execution\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (386, E'article', E'D140', E'CODEX_MODULE_LANGUAGE', E'CODEX_LANGUAGE_SOURCE_NATIVE_SPECIAL_LAW', E'native-model-training-compatibility-evidence', E'native-model-training-compatibility-evidence\nNATIVE-TRAINING-EVIDENCE:current evidence binds the C++23 trainer,model artifact,dataset generation,training configuration,FSharp evaluation,resource envelope and C++23 inference consumer;required evidence proves artifact integrity,training/inference compatibility,quality non-regression,rollback and zero retired-framework consumer;Python,JAX/XLA,NumPy and PyTorch are never a baseline,reference,executor,fallback or acceptance source;missing or contradictory evidence denies promotion fail-closed.\nFORBID:training-activation-without-complete-current-evidence+retired-framework-reference+unbounded-GPU-memory+partial-check-set-as-complete\nNone.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (387, E'article', E'D141', E'CODEX_MODULE_TEST', E'CODEX_TEST_VALIDATION_EVALUATION_SPECIAL_LAW', E'test-audit-final-responsibility-and-deadline-reference', E'test-audit-final-responsibility-and-deadline-reference\nTEST:CSharp orchestration+native runners under PARAM[MANDATORY_TEST_SUITE_DEADLINE_MS];AUDIT:C++23 engine under PARAM[INDEPENDENT_AUDIT_FLOW_DEADLINE_MS];RESULT:typed contract+cleanup+evidence;OWNER:current B34/D35 mapping\nFORBID:deadline-literal-outside-registry+timeout-as-PASS+Python-production-test-or-audit\nNormative cryptographic constants, identity formats and closed status enums remain explicit when variability would weaken interoperability or safety.');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (388, E'article', E'D17', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'candidate-build-review-and-governed-seal', E'candidate-build-review-and-governed-seal\nCANDIDATE:built through governed tooling with complete diff,identity,lineage,version classification and integrity evidence;REVIEW:required before publication;SEAL:issued only by the registered Codex amendment and certification process after deterministic verification of the current epoch lineage and declared integrity roots;ACTIVATION:only after seal,projection parity and atomic publication.\nFORBID:self-seal|unreviewed-seal|candidate-as-effective-law|seal-with-missing-lineage|seal-outside-registered-amendment-process.\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (389, E'article', E'D18', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'ghost-provision-prohibition', E'ghost-provision-prohibition\nNEW-PROVISION:must-be-active-for-at-least-one-complete-effective-version-before-supersession; ZERO-EFFECTIVE-PERIOD:invalid+retired-not-law; SUPERSESSION-VERSION:must-match-revision-history\nFORBID:birth-and-death-same-version+incorrect-effective-version+ghost-lineage-node\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (390, E'article', E'D2', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'governor-and-seal', E'governor-and-seal\nGOVERNOR:human-operator; OFFICE:codex; AMEND:deliberate-act; SEAL:versioned-digest-manifest; VERIFY:before-every-load\nFORBID:non-governor-seal/forged-manifest/verify-skip\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (391, E'article', E'D20', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'time-and-clock', E'time-and-clock\nTIME-SOURCE:authenticated-OS-time-synchronization; MAX-DRIFT:5-seconds; TIMESTAMP:UTC+monotonic-order-companion; TOKEN/CERTIFICATE-CHECK:deny-when-drift-exceeds-limit; CLOCK-FAULT:audit+maintenance-adjudication\nFORBID:local-unauthenticated-time-as-authority+wall-clock-only-ordering+expiry-acceptance-under-excess-drift\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (392, E'article', E'D21', E'CODEX_MODULE_FOUNDATION', E'CODEX_MAIN', E'api-contract-versioning', E'api-contract-versioning\nEACH-API/IPC/EVENT/SCHEMA-CONTRACT:stable-id+semantic-version+typed-fields+compatibility-range; BREAKING-CHANGE:new-major+consumer-migration+dual-read-window-or-atomic-cutover; REMOVAL:usage-proof+review\nFORBID:unversioned-contract+silent-breaking-change+producer-only-upgrade+indefinite-compatibility-shim\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (393, E'article', E'D22', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'maintenance-sovereign-focused-duty', E'maintenance-sovereign-focused-duty\nOWNER:health-maintenance-test-sub-sovereign under decision-sovereign; POWER:no-decision+no-execution; DUTIES:manage-maintenance-and-test-modules+assign-decision-approved-work+coordinate-module-division+collect-evidence+submit-status; DECISION:decision-sovereign owns health+maintenance+test-policy+acceptance decisions; DIRECTORY:permission-sovereign owns test-flow directory decisions; EXECUTION:module-execution-layer only; EVIDENCE:registered-test-flow-code+requirements-trace+positive-and-negative-results+failure-code+retest-proof+acceptance-decision+audit-record\nFORBID:non-maintenance-domain-ownership+direct-ungoverned-execution+test-directory-self-registration+permission-bypass+unregistered-test+hidden-failure+result-falsification+acceptance-without-evidence+closing-gap-without-retest+cross-domain-test-content-takeover\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (394, E'article', E'D23', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'星澄-review-isolation', E'星澄-review-isolation\n星澄-ISOLATION:execution+write+control boundaries retained; REVIEW:authenticated-read-only-evidence-projection-is-the-only-system-interface\nFORBID:raw-system-entry+private-bypass+review-to-control-escalation\n');
INSERT INTO "codex_search_fts_content" ("id", "c0", "c1", "c2", "c3", "c4", "c5") VALUES (395, E'article', E'D24', E'CODEX_MODULE_AUTHORITY', E'CODEX_MAIN', E'星澄-review-thinking', E'星澄-review-thinking\n星澄:independent-analysis+reasoning over governed global evidence; RESULT:advisory-only+traceable; USER:final-recipient\nFORBID:binding-decision+system-adjudication+hidden-action\n');
