INSERT INTO "preamble" ("id", "title", "authority_rank", "issuance", "binding_scope") VALUES (1, E'GPTBridge Governance Codex', E'highest-normative-authority', E'published-as-immutable-adjudication-source', E'all-modules-and-all-execution');
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (1, E'P1', E'MANDATE:governance-rule; LAYER:highest; STORAGE:independent; FLAG:forbid-arbitrary-amendment', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (2, E'P2', E'FORM:pure-declaration; ENFORCEMENT:none; REPRESENTATION:frozen-schema-construction+read-only-export; EXEC:delegated-to-governed-executor', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (3, E'P3', E'MUTATION:frozen; AMENDMENT:full-versioned-replacement-only', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (4, E'P4', E'OWNER:permission-sovereign; SCOPE:all-permission-matters; ACTIONS:manage-issue-terminate-supervise; EXEC:delegated', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (5, E'P5', E'POWERS:decision/execution/governance; PRINCIPLE:separate; FORBID:merger-of-powers', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (6, E'P6', E'MODE:deny-by-default+explicit-allowlist; REQUIRES:explicit-auditable-grant', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (7, E'P7', E'SYSTEMS:git/postgresql/qdrant/rag/llm; PRINCIPLE:separation; FORMAL-ROLES:postgresql-central-structured-data/qdrant-canonical-semantic-index/git-version-history/rag-retrieval/llm-reasoning; DEPENDENCIES:governance-approved-inventory-only; FALLBACK:bounded+declared+reconciled; FORBID:role-substitution', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (8, E'P8', E'ADJUDICATION-SOURCE:codex; APPLIES:all-system-sovereigns; 星澄:outside-decision-chain', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (9, E'P9', E'CODEX:immutable-sole-sovereign-adjudication-basis; POWER:none; EXEC:none', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (10, E'P10', E'星澄:local-native-model; AUTHORITY:complete-owned-domain; ISOLATION:system-detached; SYSTEM-PARTICIPATION:none', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (11, E'P12', E'GOVERNANCE-AUTHORITY:operational-authority; BASIS:codex; CODEX-POWER:none', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (12, E'P13', E'SYSTEM-RESOURCE-SUB-SOVEREIGN:own-resource-matters; SCOPE:state-monitor-provision-delegate-release; EXEC:delegated', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (13, E'P14', E'SYSTEM-DATA-SUB-SOVEREIGN:own-data-matters; SCOPE:access-spec-consistency-integrity-check; EXEC:delegated', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (14, E'P15', E'SYSTEM-INTEGRATION-SUB-SOVEREIGN:own-cross-sovereign-module-interface; SCOPE:coordinate-sync-bus; EXEC:delegated', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (15, E'P16', E'STACK:python+typescript+cpp+c+csharp+sql-hybrid; MANDATORY:true; LANGUAGES:only-python-typescript-cpp-c-csharp-sql; FORMAL-TOOLS:postgresql,qdrant,git,rag', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (16, E'P18', E'CODE-ORIGIN:local-owned-application-code;STACK:c+cpp+csharp+fsharp+rust+go+python-bounded+javascript-esm+julia+sql;DEPENDENCIES:explicit-inventory+version+license+security-review+local-execution;EXTERNAL-SERVICE:governed-network-capability-only', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (17, E'P19', E'CODEX-LANGUAGE:programming-language; CHINESE:reserved-to-chinese-codex; BASIS:backup-only-none', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (18, E'P20', E'INTERFACE-LAYER:presentation-of-decisions-state;AUTHORITY:no-decide-no-exec;STACK:Rust/Tauri+Native-JavaScript-ESM+JSDoc+GPUI+egui;BIND:all-modules-and-all-execution', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (19, E'P21', E'AUDIT:mandatory-ledger; WRITE:governed-executor; OWN:system-data-sub-sovereign; RETENTION:by-governance-policy; READ:governance-authority+maintenance-analysis', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (20, E'P22', E'VIOLATION:stop-record-adjudicate; STOP:deny-fail-closed; ADJUDICATE:governance-authority-final; FORBID:continued-execution-on-violation', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (21, E'P23', E'FORMAL-TOOLS:postgresql+git+rag+c+cpp+csharp+fsharp+rust+go+python-bounded+javascript-esm+julia+sql+tauri+gpui+egui+esbuild+swc;GOVERNANCE:governed-by-codex;FORBID:non-formal-substitution', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (22, E'P24', E'星澄-NATIVE-MODEL:exclusive-programming-language-review; SCOPE:conformance-acceptance-migration+code-authoring; EXEC:governed-native-capability', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (23, E'P27', E'SOURCE-STRUCTURE:module-primary-responsibility=1+public-entrypoints<=3+authored-functions-and-classes<=12+module<=600-effective-lines+function<=60-effective-lines; EXCEPTION:auto-generated/pure-data-table/registry/explicitly-registered-exception-file-only', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (24, E'P28', E'CODEX-CITATION:single-entry=governance-codex://official; PROVISION:identified-by-explicit-id; ALTERNATE-ENTRY:none', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (25, E'P29', E'CODEX-DIRECTION:codex>postgresql-reference-and-audit-only; POSTGRESQL>codex-mutation:none', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (26, E'P30', E'CODEX-AVAILABILITY:independent-of-postgresql+qdrant+network+runtime-services; GOVERNANCE-ADJUDICATION-BASIS:locally-readable-during-external-data-failure', 1);
INSERT INTO "principles" ("position", "provision_id", "statement", "binding") VALUES (27, E'P31', E'SEALED-CODEX:immutable-by-every-actor+system+service+tool+database+runtime; EXISTING-VERSION-MUTATION:none; REVISION:new-complete-version-only', 1);
